import { useState, useEffect } from "react";
import { useTranslation } from "@/lib/i18n";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
  DialogFooter,
} from "@/components/ui/dialog";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { EntityCombobox } from "./EntityCombobox";
import type { ComboboxOption } from "./EntityCombobox";
import { api } from "@/lib/api";
import { useToast } from "@/hooks/use-toast";
import type { BulkEditFieldConfig, BulkEditFieldType } from "@/lib/types/bulk-edit.types";

/**
 * Универсальный компонент массового редактирования записей
 * 
 * @example
 * ```tsx
 * <BulkEditDialog
 *   open={bulkEditOpen}
 *   onOpenChange={setBulkEditOpen}
 *   onConfirm={(field, value) => handleBulkUpdate(field, value)}
 *   count={selectedIds.size}
 *   moduleId="contractors"
 * />
 * ```
 */
export interface BulkEditDialogProps {
  /** Открыто ли диалоговое окно */
  open: boolean;
  /** Callback изменения состояния открытия */
  onOpenChange: (open: boolean) => void;
  /** Callback подтверждения изменений (поле, значение) */
  onConfirm: (field: string, value: string) => void;
  /** Количество выбранных записей */
  count: number;
  /** ID модуля для загрузки настроек */
  moduleId: string;
  /** Поля для редактирования (если не переданы, загружаются из API) */
  fields?: BulkEditFieldConfig[];
  /** Заголовок диалога (опционально, по умолчанию из i18n) */
  title?: string;
  /** Описание диалога (опционально, по умолчанию из i18n) */
  description?: string;
  /** Дополнительные данные для полей (статусы, приоритеты и т.д.) */
  referenceData?: Record<string, Array<{ id: string; name: string }>>;
}

export function BulkEditDialog({
  open,
  onOpenChange,
  onConfirm,
  count,
  moduleId,
  fields: propFields,
  title,
  description,
  referenceData = {},
}: BulkEditDialogProps) {
  const { t } = useTranslation();
  const { toast } = useToast();
  const [selectedField, setSelectedField] = useState<string>('');
  const [selectedValue, setSelectedValue] = useState<string>('');
  const [fields, setFields] = useState<BulkEditFieldConfig[]>([]);
  const [loading, setLoading] = useState(false);
  const [creating, setCreating] = useState(false);

  // Загружаем настройки полей из API если не переданы в props
  useEffect(() => {
    if (open && !propFields) {
      setLoading(true);
      api.get(`/module-settings/${moduleId}/bulk-edit/enabled`)
        .then((data) => {
          if (data.fields && Array.isArray(data.fields)) {
            setFields(data.fields);
            if (data.fields.length > 0) {
              setSelectedField(data.fields[0].id);
            }
          }
        })
        .catch(console.error)
        .finally(() => setLoading(false));
    } else if (propFields) {
      setFields(propFields);
      if (propFields.length > 0) {
        setSelectedField(propFields[0].id);
      }
    }
  }, [open, propFields, moduleId]);

  // Сбрасываем выбранное значение при изменении поля
  useEffect(() => {
    setSelectedValue('');
  }, [selectedField]);

  // Сбрасываем состояние при закрытии
  useEffect(() => {
    if (!open) {
      const firstField = fields[0];
      setSelectedField(firstField?.id || '');
      setSelectedValue('');
    }
  }, [open, fields]);

  const handleSave = () => {
    if (selectedField && selectedValue) {
      onConfirm(selectedField, selectedValue);
      onOpenChange(false);
    }
  };

  const handleCancel = () => {
    onOpenChange(false);
    const firstField = fields[0];
    setSelectedField(firstField?.id || '');
    setSelectedValue('');
  };

  const currentField = fields.find(f => f.id === selectedField);

  // Получаем опции для текущего поля
  const getFieldOptions = () => {
    if (!currentField) return [];

    // Если есть dataSource, пытаемся получить данные из referenceData
    if (currentField.dataSource) {
      // Пробуем разные варианты ключей
      const keysToTry = [
        currentField.dataSource,  // 'projects', 'tasks', 'tags'
        `${currentField.dataSourceModule}_${currentField.dataSource}`,  // 'finance_projects'
        currentField.dataSourceModule,  // 'finance'
        currentField.id.replace('_id', 's'),  // 'project_id' -> 'projects'
        currentField.id,  // 'tags'
      ];

      for (const key of keysToTry) {
        if (key && referenceData[key] && Array.isArray(referenceData[key])) {
          return referenceData[key];
        }
      }

      // Если не нашли, пробуем найти по частичному совпадению
      const foundKey = Object.keys(referenceData).find(
        k => k.toLowerCase().includes((currentField.dataSource || '').toLowerCase())
      );
      if (foundKey && referenceData[foundKey]) {
        return referenceData[foundKey];
      }
    }

    return [];
  };

  const fieldOptions = getFieldOptions();

  // Проверяем что это за поле для правильного отображения
  const isComboboxField = currentField?.type === 'combobox' ||
                          ['project_id', 'task_id', 'contractor_id', 'lawyer_user_id', 'assignee', 'client_id', 'client', 'manager', 'court_id'].includes(currentField?.id || '');
  const isTagsField = currentField?.type === 'tags' || currentField?.id === 'tags';

  // Функция создания новой записи
  const handleCreate = async (name: string) => {
    if (!currentField) return null;

    setCreating(true);
    try {
      let newId: string | number | null = null;

      // Определяем какой endpoint использовать для создания
      if (currentField.dataSource === 'projects') {
        const res = await api.post('/projects', { name });
        newId = res.data.id;
      } else if (currentField.dataSource === 'tasks') {
        const res = await api.post('/tasks', { title: name });
        newId = res.data.id;
      } else if (currentField.dataSource === 'contractors') {
        const res = await api.post('/contractors', { name });
        newId = res.data.id;
      } else if (currentField.dataSource === 'tags') {
        const res = await api.post('/tags', { name, color: '#000000' });
        newId = res.data.id;
      }

      if (newId) {
        toast({
          title: 'Создано',
          description: `Запись "${name}" создана`,
        });
      }

      return newId;
    } catch (error: any) {
      toast({
        title: 'Ошибка',
        description: error?.message || 'Не удалось создать запись',
        variant: 'destructive',
      });
      return null;
    } finally {
      setCreating(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-lg">
        <DialogHeader>
          <DialogTitle>
            {title || t('common.bulk_edit.title')} ({count})
          </DialogTitle>
          <DialogDescription>
            {description || t('common.bulk_edit.description')}
          </DialogDescription>
        </DialogHeader>

        {loading ? (
          <div className="py-8 text-center text-muted-foreground">
            Загрузка настроек...
          </div>
        ) : fields.length === 0 ? (
          <div className="py-8 text-center text-muted-foreground">
            Нет доступных полей для редактирования
          </div>
        ) : (
          <div className="grid gap-4 py-4">
            {/* Выбор поля */}
            <div className="grid gap-2">
              <Label>{t('common.bulk_edit.field')}</Label>
              <Select value={selectedField} onValueChange={setSelectedField}>
                <SelectTrigger>
                  <SelectValue placeholder={t('common.bulk_edit.select_field')} />
                </SelectTrigger>
                <SelectContent>
                  {fields.map(field => (
                    <SelectItem key={field.id} value={field.id}>
                      {field.label}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            {/* Выбор значения */}
            <div className="grid gap-2">
              <Label>{t('common.bulk_edit.value')}</Label>
              {currentField?.type === 'select' && (
                <Select value={selectedValue} onValueChange={setSelectedValue}>
                  <SelectTrigger>
                    <SelectValue placeholder={t('common.bulk_edit.select_value')} />
                  </SelectTrigger>
                  <SelectContent>
                    {fieldOptions.map(option => (
                      <SelectItem key={option.id} value={option.id}>
                        {option.name}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              )}
              {(isComboboxField || isTagsField) && (
                <EntityCombobox
                  value={selectedValue}
                  onChange={(id) => setSelectedValue(typeof id === 'string' ? id : String(id))}
                  options={fieldOptions.map(o => ({ id: o.id, label: o.name }) as ComboboxOption)}
                  placeholder={isTagsField ? 'Выберите теги' : t('common.bulk_edit.select_value')}
                  disabled={fieldOptions.length === 0 && !handleCreate}
                  onCreate={handleCreate}
                  createLabel="Создать:"
                />
              )}
              {currentField?.type === 'text' && (
                <input
                  type="text"
                  className="flex h-10 w-full rounded-md border border-input bg-background px-3 py-2 text-sm ring-offset-background placeholder:text-muted-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2"
                  value={selectedValue}
                  onChange={(e) => setSelectedValue(e.target.value)}
                  placeholder="Введите значение"
                />
              )}
              {currentField?.type === 'number' && (
                <input
                  type="number"
                  className="flex h-10 w-full rounded-md border border-input bg-background px-3 py-2 text-sm ring-offset-background placeholder:text-muted-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2"
                  value={selectedValue}
                  onChange={(e) => setSelectedValue(e.target.value)}
                  placeholder="Введите число"
                />
              )}
              {currentField?.type === 'date' && (
                <input
                  type="date"
                  className="flex h-10 w-full rounded-md border border-input bg-background px-3 py-2 text-sm ring-offset-background placeholder:text-muted-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2"
                  value={selectedValue}
                  onChange={(e) => setSelectedValue(e.target.value)}
                />
              )}
              {currentField?.type === 'boolean' && (
                <Select value={selectedValue} onValueChange={setSelectedValue}>
                  <SelectTrigger>
                    <SelectValue placeholder={t('common.bulk_edit.select_value')} />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="true">Да</SelectItem>
                    <SelectItem value="false">Нет</SelectItem>
                  </SelectContent>
                </Select>
              )}
              {currentField?.type === 'tags' && (
                <EntityCombobox
                  value={selectedValue}
                  onChange={(id) => setSelectedValue(typeof id === 'string' ? id : String(id))}
                  options={fieldOptions.map(o => ({ id: o.id, label: o.name } as ComboboxOption))}
                  placeholder="Выберите теги"
                />
              )}
            </div>
          </div>
        )}

        <DialogFooter>
          <Button variant="outline" onClick={handleCancel}>
            {t('common.cancel')}
          </Button>
          <Button onClick={handleSave} disabled={!selectedValue || loading}>
            {t('common.save')}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

import { toast } from "sonner";
import { AlertCircle } from "lucide-react";

export interface ValidationField {
  name: string;
  label: string;
  value?: unknown;
}

export interface ValidationError {
  field: string;
  message: string;
}

/**
 * Hook to show validation errors in toast with list of required fields
 * Usage:
 * const { showValidationError, validateFields } = useValidationToast();
 * 
 * const errors = validateFields([
 *   { name: 'title', label: 'Название', value: formData.title },
 *   { name: 'type', label: 'Тип', value: formData.type },
 * ]);
 * 
 * if (errors.length > 0) {
 *   showValidationError(errors, 'Заполните обязательные поля');
 *   return;
 * }
 */

export const useValidationToast = () => {
  /**
   * Validate array of fields and return list of missing/empty fields
   */
  const validateFields = (fields: ValidationField[]): ValidationError[] => {
    return fields
      .filter(field => !field.value || (typeof field.value === 'string' && !field.value.trim()))
      .map(field => ({
        field: field.name,
        message: field.label,
      }));
  };

  /**
   * Show validation error toast with list of required fields
   */
  const showValidationError = (errors: ValidationError[], title = 'Заполните обязательные поля') => {
    const errorList = errors.map(e => e.message).join(', ');

    toast.error(
      <div className="flex flex-col gap-2">
        <div className="flex items-center gap-2">
          <AlertCircle className="w-4 h-4 flex-shrink-0" />
          <span className="font-medium">{title}</span>
        </div>
        <div className="text-sm text-muted-foreground pl-6">
          {errorList}
        </div>
      </div>,
      {
        duration: 4000,
        className: 'max-w-md',
      }
    );
  };

  /**
   * Shorthand: validate fields and show error if any missing
   * Returns true if validation passed (no errors)
   */
  const validate = (fields: ValidationField[], title?: string): boolean => {
    const errors = validateFields(fields);
    if (errors.length > 0) {
      showValidationError(errors, title);
      return false;
    }
    return true;
  };

  return {
    validateFields,
    showValidationError,
    validate,
  };
};

/**
 * Component that displays validation errors as JSX for custom toast layouts
 */
export function ValidationErrorContent({
  errors,
  title = 'Заполните обязательные поля',
}: {
  errors: ValidationError[];
  title?: string;
}) {
  if (errors.length === 0) return null;

  const errorList = errors.map(e => e.message).join(', ');

  return (
    <div className="flex flex-col gap-2">
      <div className="flex items-center gap-2">
        <AlertCircle className="w-4 h-4 flex-shrink-0" />
        <span className="font-medium">{title}</span>
      </div>
      <div className="text-sm text-muted-foreground pl-6">
        {errorList}
      </div>
    </div>
  );
}

/**
 * Компонент поиска организаций через DaData Suggestions
 * Используется для быстрого создания контрагентов по ИНН или названию
 */

import React, { useState, useEffect, useRef } from 'react';
import { Search, Building2, Check, Loader2, AlertCircle } from 'lucide-react';
import { Input } from '@/components/ui/input';
import { Button } from '@/components/ui/button';
import { ScrollArea } from '@/components/ui/scroll-area';
import { cn } from '@/lib/utils';
import { api } from '@/lib/api';

export interface DadataSuggestion {
  value: string;
  unrestricted_value: string;
  data: {
    inn: string;
    kpp?: string;
    ogrn: string;
    type: 'LEGAL' | 'INDIVIDUAL';
    name: {
      full_with_opf: string;
      short_with_opf: string;
      full?: string;
      short?: string;
    };
    fio?: {
      surname: string;
      name: string;
      patronymic?: string;
    };
    management?: {
      name: string;
      post: string;
    };
    address: {
      value: string;
      unrestricted_value: string;
    };
    state: {
      status: 'ACTIVE' | 'LIQUIDATING' | 'LIQUIDATED' | 'BANKRUPT' | 'REORGANIZING';
      actuality_date?: string;
    };
    okved?: string;
    okved_type?: string;
    branch_type?: 'MAIN' | 'BRANCH';
    branch_count?: number;
    hid?: string;
    ogrn_date?: string;
    opf?: {
      code: string;
      full?: string;
      short?: string;
    };
    okpo?: string;
    capital?: {
      value: number;
      currency?: string;
    };
    phones?: Array<{
      source?: string;
      value?: string;
    }>;
    emails?: string[];
  };
}

interface DadataSuggestionsInputProps {
  value?: string;
  onChange?: (value: string, suggestion?: DadataSuggestion) => void;
  onSelect?: (suggestion: DadataSuggestion) => void;
  placeholder?: string;
  className?: string;
  disabled?: boolean;
  filters?: {
    type?: 'LEGAL' | 'INDIVIDUAL';
    status?: Array<'ACTIVE' | 'LIQUIDATING' | 'LIQUIDATED'>;
    locations?: Array<{ kladr_id?: string; city?: string }>;
  };
}

export function DadataSuggestionsInput({
  value = '',
  onChange,
  onSelect,
  placeholder = 'Введите ИНН, название или адрес...',
  className,
  disabled = false,
  filters,
}: DadataSuggestionsInputProps) {
  const [suggestions, setSuggestions] = useState<DadataSuggestion[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [isOpen, setIsOpen] = useState(false);
  const [selectedIndex, setSelectedIndex] = useState(-1);

  const inputRef = useRef<HTMLInputElement>(null);
  const suggestionsRef = useRef<HTMLDivElement>(null);

  // Поиск по кнопке
  const handleSearch = async () => {
    if (!value || value.length < 2) {
      setError('Введите минимум 2 символа');
      return;
    }

    setLoading(true);
    setError(null);

    try {
      const response = await api.post('/dadata/suggest/party', {
        query: value,
        count: 10,
        filters: filters || {},
      });

      setSuggestions(response.suggestions || []);
      setIsOpen(true);
    } catch (err: any) {
      setError(err.message || 'Ошибка поиска');
      setSuggestions([]);
    } finally {
      setLoading(false);
    }
  };

  // Закрытие при клике вне
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (
        suggestionsRef.current &&
        !suggestionsRef.current.contains(event.target as Node) &&
        !inputRef.current?.contains(event.target as Node)
      ) {
        setIsOpen(false);
      }
    };

    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  // Выбор организации
  const handleSelect = (suggestion: DadataSuggestion) => {
    setIsOpen(false);
    setSuggestions([]);

    if (onSelect) {
      onSelect(suggestion);
    }

    if (onChange) {
      onChange(suggestion.value, suggestion);
    }
  };

  // Навигация клавиатурой
  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (!isOpen || suggestions.length === 0) return;

    switch (e.key) {
      case 'ArrowDown':
        e.preventDefault();
        setSelectedIndex(prev => Math.min(prev + 1, suggestions.length - 1));
        break;
      case 'ArrowUp':
        e.preventDefault();
        setSelectedIndex(prev => Math.max(prev - 1, 0));
        break;
      case 'Enter':
        e.preventDefault();
        if (selectedIndex >= 0 && suggestions[selectedIndex]) {
          handleSelect(suggestions[selectedIndex]);
        }
        break;
      case 'Escape':
        setIsOpen(false);
        break;
    }
  };

  // Форматирование типа организации
  const getOrganizationType = (type: string, branchType?: string) => {
    if (branchType === 'BRANCH') return 'Филиал';
    if (type === 'INDIVIDUAL') return 'ИП';
    return 'ООО/АО';
  };

  // Статус организации
  const getStatusColor = (status: string) => {
    switch (status) {
      case 'ACTIVE': return 'bg-emerald-100 text-emerald-700';
      case 'LIQUIDATING': return 'bg-amber-100 text-amber-700';
      case 'LIQUIDATED':
      case 'BANKRUPT': return 'bg-red-100 text-red-700';
      default: return 'bg-gray-100 text-gray-700';
    }
  };

  return (
    <div className={cn("relative space-y-2", className)}>
      <div className="flex gap-2">
        <div className="relative flex-1">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
          <Input
            ref={inputRef}
            value={value}
            onChange={(e) => {
              onChange?.(e.target.value);
              setIsOpen(false);
            }}
            onKeyDown={(e) => {
              if (e.key === 'Enter') {
                handleSearch();
              }
              handleKeyDown(e);
            }}
            placeholder={placeholder}
            className="pl-9 pr-8"
            disabled={disabled}
          />
          {loading && (
            <Loader2 className="absolute right-3 top-1/2 -translate-y-1/2 w-4 h-4 animate-spin text-muted-foreground" />
          )}
        </div>
        <Button 
          onClick={handleSearch} 
          disabled={loading || !value || value.length < 2}
          type="button"
        >
          {loading ? <Loader2 className="w-4 h-4 animate-spin" /> : 'Найти'}
        </Button>
      </div>

      {error && (
        <div className="absolute top-full left-0 right-0 mt-1 p-2 text-xs text-destructive bg-destructive/10 rounded border border-destructive/20">
          <AlertCircle className="w-3 h-3 inline mr-1" />
          {error}
        </div>
      )}

      {isOpen && suggestions.length > 0 && (
        <div
          ref={suggestionsRef}
          className="absolute top-full left-0 right-0 mt-1 bg-background border rounded-lg shadow-lg z-50 max-h-[400px] overflow-hidden"
        >
          <ScrollArea className="h-full">
            {suggestions.map((suggestion, index) => (
              <div
                key={suggestion.data.hid || index}
                className={cn(
                  "p-3 cursor-pointer hover:bg-muted/50 transition-colors border-b last:border-b-0",
                  index === selectedIndex && "bg-muted"
                )}
                onClick={() => handleSelect(suggestion)}
              >
                <div className="flex items-start justify-between gap-2">
                  <div className="flex-1 min-w-0">
                    <div className="flex items-center gap-2 mb-1">
                      <Building2 className="w-4 h-4 text-muted-foreground shrink-0" />
                      <span className="font-medium text-sm truncate">
                        {suggestion.value}
                      </span>
                    </div>

                    {suggestion.data.inn && (
                      <div className="text-xs text-muted-foreground space-y-0.5">
                        <div>
                          ИНН: <span className="font-mono">{suggestion.data.inn}</span>
                          {suggestion.data.kpp && (
                            <span className="ml-2">КПП: <span className="font-mono">{suggestion.data.kpp}</span></span>
                          )}
                        </div>
                        {suggestion.data.ogrn && (
                          <div>ОГРН: <span className="font-mono">{suggestion.data.ogrn}</span></div>
                        )}
                        {suggestion.data.address?.value && (
                          <div className="truncate">📍 {suggestion.data.address.value}</div>
                        )}
                      </div>
                    )}
                  </div>

                  <div className="flex flex-col items-end gap-1 shrink-0">
                    <span className={cn(
                      "text-[10px] px-1.5 py-0.5 rounded font-medium",
                      getStatusColor(suggestion.data.state?.status || 'ACTIVE')
                    )}>
                      {suggestion.data.state?.status === 'ACTIVE' ? 'Действующая' :
                       suggestion.data.state?.status === 'LIQUIDATING' ? 'Ликвидируется' :
                       suggestion.data.state?.status === 'LIQUIDATED' ? 'Ликвидирована' :
                       suggestion.data.state?.status || '—'}
                    </span>
                    <span className="text-[10px] text-muted-foreground">
                      {getOrganizationType(suggestion.data.type, suggestion.data.branch_type)}
                    </span>
                  </div>
                </div>
              </div>
            ))}
          </ScrollArea>
          <div className="p-2 text-xs text-muted-foreground text-center border-t bg-muted/30">
            Найдено: {suggestions.length} из 10 макс.
          </div>
        </div>
      )}

      {isOpen && value && value.length >= 2 && suggestions.length === 0 && !loading && !error && (
        <div className="absolute top-full left-0 right-0 mt-1 p-4 text-center text-sm text-muted-foreground bg-background border rounded-lg shadow-lg">
          Ничего не найдено по запросу "{value}"
        </div>
      )}
    </div>
  );
}

