export interface FileUploaderWithCheckProps extends Omit<React.ComponentProps<typeof FileUploader>, 'onSuccess'> {
  /** API endpoint для проверки существования */
  checkEndpoint: string;

  /** Поле имени файла в запросе проверки */
  fileNameField?: string;

  /** Поле хэша файла в запросе проверки */
  fileHashField?: string;

  /** Вычислять хэш файла (по умолчанию true) */
  computeHash?: boolean;

  /** Callback при успешной загрузке (с результатом проверки) */
  onSuccess?: (upload: any, checkResult?: any) => void;

  /** Callback при использовании существующего файла */
  onUseExisting?: (existingFile: any) => void;
}

/**
 * FileUploader с проверкой на дубликаты
 * 
 * @example
 * ```tsx
 * <FileUploaderWithCheck
 *   uploadUrl="/api/upload"
 *   checkEndpoint="/api/documents/check-exists"
 *   computeHash={true}
 *   onSuccess={(upload, checkResult) => {
 *     if (checkResult?.exists) {
 *       console.log('Использован существующий файл');
 *     } else {
 *       console.log('Загружен новый файл');
 *     }
 *   }}
 * />
 * ```
 */
export function FileUploaderWithCheck({
  checkEndpoint,
  fileNameField = 'fileName',
  fileHashField = 'fileHash',
  computeHash = true,
  onSuccess,
  onUseExisting,
  ...fileUploaderProps
}: FileUploaderWithCheckProps) {
  const [showDuplicateDialog, setShowDuplicateDialog] = useState(false);
  const [pendingFile, setPendingFile] = useState<any>(null);
  const [checkResult, setCheckResult] = useState<any>(null);

  const { checkFile, isChecking } = useFileExistsCheck({
    checkEndpoint,
    fileNameField,
    fileHashField,
    computeHash,
    onDuplicateFound: (result) => {
      setCheckResult(result);
      setShowDuplicateDialog(true);
    },
  });

  const handleUploadWithCheck = async (upload: any) => {
    // Сначала проверяем файл
    if (pendingFile) {
      try {
        const result = await checkFile(pendingFile);

        if (!result.exists) {
          // Файл не существует - продолжаем загрузку
          onSuccess?.(upload, result);
        }
        // Если файл существует, диалог уже показан в onDuplicateFound
      } catch (error) {
        console.error('File check error:', error);
        // При ошибке проверки всё равно загружаем
        onSuccess?.(upload, null);
      }
    } else {
      onSuccess?.(upload, checkResult);
    }
  };

  const handleConfirmUploadNew = () => {
    // Пользователь решил загрузить новый файл несмотря на дубликат
    setShowDuplicateDialog(false);
    if (pendingFile) {
      // Загружаем файл (FileUploader уже начал загрузку)
      onSuccess?.(pendingFile, checkResult);
    }
    setPendingFile(null);
    setCheckResult(null);
  };

  const handleConfirmUseExisting = () => {
    // Пользователь решил использовать существующий файл
    setShowDuplicateDialog(false);
    onUseExisting?.(checkResult);
    setPendingFile(null);
    setCheckResult(null);
  };

  const handleViewExisting = () => {
    if (checkResult?.existingFile?.url) {
      window.open(checkResult.existingFile.url, '_blank');
    }
  };

  return (
    <>
      <FileUploader
        {...fileUploaderProps}
        onSuccess={handleUploadWithCheck}
        disabled={isChecking || fileUploaderProps.disabled}
      />

      <FileExistsDialog
        open={showDuplicateDialog}
        onOpenChange={setShowDuplicateDialog}
        fileName={pendingFile?.name || checkResult?.fileName || 'Файл'}
        existingFile={checkResult}
        onUploadNew={handleConfirmUploadNew}
        onUseExisting={onUseExisting ? handleConfirmUseExisting : undefined}
        onViewExisting={handleViewExisting}
      />
    </>
  );
}

import * as React from "react";
import { Input } from "@/components/ui/input";
import { cn } from "@/lib/utils";

interface MoneyInputProps extends Omit<React.InputHTMLAttributes<HTMLInputElement>, "onChange" | "value"> {
  value: number | undefined;
  onValueChange: (value: number) => void;
  currency?: string;
}

export const MoneyInput = React.forwardRef<HTMLInputElement, MoneyInputProps>(
  ({ className, value, onValueChange, currency, ...props }, ref) => {
    // Internal string state to handle user typing "100." before "100.5"
    const [displayValue, setDisplayValue] = React.useState("");

    // Format number to "1 234 567,89"
    const formatValue = (val: number | undefined) => {
      if (val === undefined || val === null || isNaN(val)) return "";
      return new Intl.NumberFormat("ru-RU", {
        minimumFractionDigits: 2,
        maximumFractionDigits: 2,
      }).format(val);
    };

    // Update display value when prop value changes externally
    React.useEffect(() => {
      // Only update if the parsed display value is different to avoid cursor jumps on simple re-renders
      // or if the field is not currently focused (simplified approach)
      const parsedDisplay = parseFloat(displayValue.replace(/\s/g, "").replace(",", "."));
      if (value !== parsedDisplay) {
         setDisplayValue(formatValue(value));
      }
    }, [value]);

    const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      const inputValue = e.target.value;
      
      // Allow only numbers, spaces, commas, dots
      if (!/^[\d\s,.]*$/.test(inputValue)) return;

      setDisplayValue(inputValue);

      // Normalize for parsing: remove spaces, replace comma with dot
      const normalized = inputValue.replace(/\s/g, "").replace(",", ".");
      const numericValue = parseFloat(normalized);

      if (!isNaN(numericValue)) {
        onValueChange(numericValue);
      } else if (normalized === "") {
        onValueChange(0);
      }
    };

    const handleBlur = () => {
      // On blur, enforce the strict formatting
      if (value !== undefined) {
        setDisplayValue(formatValue(value));
      }
    };

    const handleFocus = (e: React.FocusEvent<HTMLInputElement>) => {
        // Optional: Remove formatting on focus to make editing easier? 
        // For now, let's keep it simple, user can edit the string.
        // Or strip formatting:
        const raw = value?.toString().replace('.', ',') || "";
        setDisplayValue(raw);
        e.target.select();
    };

    return (
      <Input
        ref={ref}
        type="text"
        inputMode="decimal"
        value={displayValue}
        onChange={handleChange}
        onBlur={handleBlur}
        onFocus={handleFocus}
        className={cn("text-right font-mono", className)}
        {...props}
      />
    );
  }
);

MoneyInput.displayName = "MoneyInput";

/**
 * QuickActionsMenu - универсальное выпадающее меню быстрых действий
 * Объединяет быстрые действия (из БД) и обычные действия (просмотр, редактирование, удаление)
 */
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
