  },

  // Бэкапы
  backups: {
    read: perm(RESOURCES.BACKUPS, ACTIONS.READ),
    write: perm(RESOURCES.BACKUPS, ACTIONS.WRITE),
    delete: perm(RESOURCES.BACKUPS, ACTIONS.DELETE),
  },
} as const;

/**
 * Тип всех прав доступа
 */
export type PermissionId = typeof PERMISSIONS[keyof typeof PERMISSIONS][keyof typeof PERMISSIONS[keyof typeof PERMISSIONS]];

/**
 * Получение всех ID прав как массив строк
 */
export const getAllPermissionIds = (): string[] => {
  return Object.values(PERMISSIONS).flatMap(resource =>
    Object.values(resource)
  );
};

/**
 * Получение прав для конкретного ресурса
 */
export const getResourcePermissions = (resource: string): string[] => {
  const resourcePerms = (PERMISSIONS as any)[resource];
  if (!resourcePerms) return [];
  return Object.values(resourcePerms);
};

import { describe, it, expect, beforeEach, vi } from 'vitest';
import { renderHook, act, waitFor } from '@testing-library/react';
import { useDataTable } from '../useDataTable';
import { api } from '@/lib/api';
import { List } from 'lucide-react';

// Mock API
vi.mock('@/lib/api', () => ({
  api: {
    get: vi.fn(),
    post: vi.fn(),
  },
}));

interface MockItem {
  id: number;
  name: string;
  status: string;
}

const mockInitialData: MockItem[] = [
  { id: 1, name: 'Item 1', status: 'active' },
  { id: 2, name: 'Item 2', status: 'inactive' },
  { id: 3, name: 'Item 3', status: 'active' },
];

const mockColumns = {
  name: true,
  status: true,
  actions: true,
};

const mockTabs = [
  { id: 'list', label: 'List', icon: List, visible: true },
  { id: 'board', label: 'Board', icon: List, visible: false },
];

describe('useDataTable', () => {
  beforeEach(() => {
    vi.clearAllMocks();
    (api.get as any).mockResolvedValue(null);
    (api.post as any).mockResolvedValue({});
  });

  describe('Initial state', () => {
    it('should initialize with default values', () => {
      const { result } = renderHook(() =>
        useDataTable({
          initialData: mockInitialData,
          initialColumns: mockColumns,
        })
      );

      expect(result.current.searchQuery).toBe('');
      expect(result.current.selectedIds.size).toBe(0);
      expect(result.current.rowsPerPage).toBe('25');
      expect(result.current.currentPage).toBe(1);
      expect(result.current.visibleColumns).toEqual(mockColumns);
    });

    it('should accept custom rows per page', () => {
      const { result } = renderHook(() =>
        useDataTable({
          initialData: mockInitialData,
          initialColumns: mockColumns,
          defaultRowsPerPage: '50',
        })
      );

      expect(result.current.rowsPerPage).toBe('50');
    });
  });

  describe('Search', () => {
    it('should update search query', () => {
      const { result } = renderHook(() =>
        useDataTable({
          initialData: mockInitialData,
          initialColumns: mockColumns,
        })
      );

      act(() => {
        result.current.setSearchQuery('test');
      });

      expect(result.current.searchQuery).toBe('test');
    });
  });

  describe('Selection', () => {
    it('should toggle item selection', () => {
      const { result } = renderHook(() =>
        useDataTable({
          initialData: mockInitialData,
          initialColumns: mockColumns,
        })
      );

      act(() => {
        result.current.toggleSelection(1);
      });

