      });

      expect(result.current.columnOrder).toEqual(['col2', 'col1', 'col3']);
    });

    it('should reorder column to new position', () => {
      const { result } = renderHook(() =>
        useDataTable({
          initialData: mockInitialData,
          initialColumns: {
            col1: true,
            col2: true,
            col3: true,
          },
        })
      );

      act(() => {
        result.current.reorderColumn('col1', 'col3');
