import * as React from "react";

const MOBILE_BREAKPOINT = 768;
const TABLET_BREAKPOINT = 1024;

export function useIsMobile() {
  const [isMobile, setIsMobile] = React.useState<boolean | undefined>(undefined);

  React.useEffect(() => {
    const mql = window.matchMedia(`(max-width: ${MOBILE_BREAKPOINT - 1}px)`);
    const onChange = () => {
      setIsMobile(window.innerWidth < MOBILE_BREAKPOINT);
    };
    mql.addEventListener("change", onChange);
    setIsMobile(window.innerWidth < MOBILE_BREAKPOINT);
    return () => mql.removeEventListener("change", onChange);
  }, []);

  return !!isMobile;
}

/** Returns true for screens between 768px and 1024px (tablet range) */
export function useIsTablet() {
  const [isTablet, setIsTablet] = React.useState<boolean>(false);

  React.useEffect(() => {
    const check = () => {
      const w = window.innerWidth;
      setIsTablet(w >= MOBILE_BREAKPOINT && w < TABLET_BREAKPOINT);
    };
    window.addEventListener("resize", check);
    check();
    return () => window.removeEventListener("resize", check);
  }, []);

  return isTablet;
}

import { useTranslation } from '@/lib/i18n';

import { useState, useEffect, useRef, useCallback } from 'react';
import {
  StatusItem,
  TagItem,
  PriorityItem,
  QuickAction,
  RelationshipTypeItem,
  defaultStatuses,
  defaultTags,
  defaultPriorities,
  defaultQuickActions,
  defaultRelationshipTypes,
  accentColors,
} from '@/lib/settings-data';
import { api } from '@/lib/api';
import { toast } from 'sonner';

const STORAGE_KEYS = {
  theme: 'titan_theme',
  accentColor: 'titan_accent_color',
  sidebarCollapsed: 'titan_sidebar_collapsed',
};

// Кэширование для предотвращения множественных запросов
let referencesCache: any = null;
let referencesCacheTime: number = 0;
const CACHE_TTL = 5 * 60 * 1000; // 5 минут

type ReferenceCrudType = 'status' | 'tag' | 'priority' | 'relationshipType';
type ReferenceCrudItem = StatusItem | TagItem | PriorityItem | RelationshipTypeItem;

interface ContractorTypeItem {
  id: string;
  name: string;
}

interface LegalFormItem {
  id: string;
  name: string;
  color?: string;
  showAsTab?: boolean;
}

// Mapping from (module, type) -> Database Table Name
const getTableName = (module: string, type: 'status' | 'tag' | 'priority' | 'relationshipType'): string | null => {
    if (type === 'tag') return 'defined_tags';
    if (type === 'priority') return 'priority';
    if (type === 'relationshipType') return 'relationship_type';

    const statusMap: Record<string, string> = {
        'contractors': 'contractor_status',
        'projects': 'project_status',
        'tasks': 'task_status',
        'lawyers': 'lawyer_status',
        'cases': 'case_status'
    };
    return statusMap[module] || null;
};

// Флаг для предотвращения параллельных запросов
let isLoadingReferences = false;
const pendingCallbacks: Array<() => void> = [];

export function useSettings() {
  const { t } = useTranslation();
  const [statuses, setStatuses] = useState<StatusItem[]>([]);
  const [tags, setTags] = useState<TagItem[]>([]);
  const [priorities, setPriorities] = useState<PriorityItem[]>([]);
  const [quickActions, setQuickActions] = useState<QuickAction[]>([]);
  const [relationshipTypes, setRelationshipTypes] = useState<RelationshipTypeItem[]>([]);
  const [contractorTypes, setContractorTypes] = useState<ContractorTypeItem[]>([]);
  const [legalForms, setLegalForms] = useState<LegalFormItem[]>([]);

  // Initialize from localStorage synchronously to prevent flash of content
  const [theme, setThemeState] = useState<'light' | 'dark'>(() => 
    (localStorage.getItem(STORAGE_KEYS.theme) as 'light' | 'dark') || 'light'
  );
  const [accentColor, setAccentColorState] = useState<string>(() => 
    localStorage.getItem(STORAGE_KEYS.accentColor) || 'blue'
  );

  // CRITICAL FIX: Read sidebar state immediately to prevent "breathing" sidebar on navigation
  const [sidebarCollapsed, setSidebarCollapsedState] = useState(() => {
      const saved = localStorage.getItem(STORAGE_KEYS.sidebarCollapsed);
      return saved === 'true';
  });

  const [loading, setLoading] = useState(true);

  // Sync state to DOM and localStorage
  const setTheme = (newTheme: 'light' | 'dark') => {
      setThemeState(newTheme);
      document.documentElement.classList.toggle('dark', newTheme === 'dark');
      localStorage.setItem(STORAGE_KEYS.theme, newTheme);
      // Persist to DB
      api.post('/user-settings', { key: STORAGE_KEYS.theme, value: newTheme }).catch(console.error);
  };

  const setAccentColor = (newColor: string) => {
      setAccentColorState(newColor);
      const colorConfig = accentColors.find(c => c.id === newColor);
      if (colorConfig) {
        document.documentElement.style.setProperty('--primary', colorConfig.primary);
        document.documentElement.style.setProperty('--accent', colorConfig.primary);
        document.documentElement.style.setProperty('--ring', colorConfig.primary);
        document.documentElement.style.setProperty('--sidebar-primary', colorConfig.primary);
        document.documentElement.style.setProperty('--sidebar-ring', colorConfig.primary);
        localStorage.setItem(STORAGE_KEYS.accentColor, newColor);
        // Persist to DB
        api.post('/user-settings', { key: STORAGE_KEYS.accentColor, value: newColor }).catch(console.error);
      }
  };

  const setSidebarCollapsed = (collapsed: boolean) => {
      setSidebarCollapsedState(collapsed);
      localStorage.setItem(STORAGE_KEYS.sidebarCollapsed, String(collapsed));
      // Persist to DB
      api.post('/user-settings', { key: STORAGE_KEYS.sidebarCollapsed, value: collapsed }).catch(console.error);
  };

  const loadData = useCallback(async (forceRefresh = false) => {
    try {
      setLoading(true);

      // Загружаем ВСЁ параллельно
      const [references, dbTheme, dbAccent, dbCollapsed, legalFormsWithGroups, apiQuickActions] = await Promise.all([
          api.get('/references'),
          api.get(`/user-settings/${STORAGE_KEYS.theme}`),
          api.get(`/user-settings/${STORAGE_KEYS.accentColor}`),
          api.get(`/user-settings/${STORAGE_KEYS.sidebarCollapsed}`),
          api.get('/references/legal_forms').catch(() => []),
          api.get('/quick-actions').catch(() => []),
      ]);

      // Конвертируем быстрые действия
      const convertedActions: QuickAction[] = Array.isArray(apiQuickActions)
        ? apiQuickActions.map((action: any) => ({
            id: action.id,
            name: action.name,
            icon: action.icon,
            action: action.action,
            module: action.module,
          }))
        : [];

      const legalFormsData = Array.isArray(legalFormsWithGroups)
        ? legalFormsWithGroups
        : (legalFormsWithGroups?.rows || references.legalForms || []);

      // Сохраняем в кэш
      referencesCache = {
        statuses: references.statuses || [],
        tags: references.tags || [],
        relationshipTypes: references.relationshipTypes || [],
        contractorTypes: references.contractorTypes || [],
        legalForms: legalFormsData,
        prioritySettings: references.prioritySettings,
        quickActions: convertedActions,
      };
      referencesCacheTime = Date.now();

      // Устанавливаем всё
      setStatuses(references.statuses || []);
      setTags(references.tags || []);
      setRelationshipTypes(references.relationshipTypes || []);
      setContractorTypes(references.contractorTypes || []);
      setLegalForms(legalFormsData);
      setQuickActions(convertedActions);

      if (references.prioritySettings) {
        setPriorities(references.prioritySettings);
      }

      console.log('[use-settings] Loaded', {
        statuses: (references.statuses || []).length,
        tags: (references.tags || []).length,
        quickActions: convertedActions.length,
      });

      // Apply DB settings if they exist (override localStorage default)
      if (dbTheme) {
          setThemeState(dbTheme);
          document.documentElement.classList.toggle('dark', dbTheme === 'dark');
          localStorage.setItem(STORAGE_KEYS.theme, dbTheme);
      }

      if (dbAccent) {
          const colorConfig = accentColors.find(c => c.id === dbAccent);
          if (colorConfig) {
              setAccentColorState(dbAccent);
              document.documentElement.style.setProperty('--primary', colorConfig.primary);
              document.documentElement.style.setProperty('--accent', colorConfig.primary);
              document.documentElement.style.setProperty('--ring', colorConfig.primary);
              document.documentElement.style.setProperty('--sidebar-primary', colorConfig.primary);
              document.documentElement.style.setProperty('--sidebar-ring', colorConfig.primary);
              localStorage.setItem(STORAGE_KEYS.accentColor, dbAccent);
          }
      }

      if (dbCollapsed !== null) {
          setSidebarCollapsedState(Boolean(dbCollapsed));
          localStorage.setItem(STORAGE_KEYS.sidebarCollapsed, String(dbCollapsed));
      }

      // Notify other parts of the app that references were reloaded
      try {
        window.dispatchEvent(new CustomEvent('references:updated', { detail: references }));
      } catch (e) {
        // ignore in non-browser environments
      }

    } catch (apiError) {
      console.error('[use-settings] Error loading data:', apiError);
      setStatuses(defaultStatuses);
      setTags(defaultTags);
      setPriorities(defaultPriorities);
      setQuickActions([]);
      setRelationshipTypes(defaultRelationshipTypes);
    } finally {
      setLoading(false);
      isLoadingReferences = false;

      // Выполняем ожидающие callback'и
      const callbacks = [...pendingCallbacks];
      pendingCallbacks.length = 0;
      callbacks.forEach(cb => cb());
    }
  }, []);

  useEffect(() => {
    // Apply initial styles from localStorage immediately to avoid flash
    const loadedTheme = localStorage.getItem(STORAGE_KEYS.theme);
    const loadedAccentColor = localStorage.getItem(STORAGE_KEYS.accentColor);

    // NOTE: sidebarCollapsed is handled in useState initializer above to prevent jump

    if (loadedTheme) {
        document.documentElement.classList.toggle('dark', loadedTheme === 'dark');
    }

    if (loadedAccentColor) {
        const colorConfig = accentColors.find(c => c.id === loadedAccentColor);
        if (colorConfig) {
            document.documentElement.style.setProperty('--primary', colorConfig.primary);
            document.documentElement.style.setProperty('--accent', colorConfig.primary);
            document.documentElement.style.setProperty('--ring', colorConfig.primary);
            document.documentElement.style.setProperty('--sidebar-primary', colorConfig.primary);
            document.documentElement.style.setProperty('--sidebar-ring', colorConfig.primary);
        }
    }

    // Then load from DB to sync
    loadData();
  }, []);

  // --- CRUD Operations ---

  const addItem = async (type: ReferenceCrudType, item: ReferenceCrudItem) => {
      try {
          const table = getTableName(item.module, type);
          if (!table) throw new Error("Unknown module or type");

          const payload: any = { ...item };
          if (type === 'status') {
              const existing = statuses.filter(s => s.module === item.module);
              (payload as any).displayOrder = existing.length + 1;
          }

          await api.post(`/references/${table}`, payload);
          toast.success(t('generated.zapis_dobavlena'));
          await loadData();
      } catch (e) {
          console.error('Error adding item:', e);
          toast.error(t('generated.oshibka_dobavleniya') + (e instanceof Error ? e.message : String(e)));
      }
  };

  const updateItem = async (type: ReferenceCrudType, item: ReferenceCrudItem) => {
      try {
          const table = getTableName(item.module, type);
          if (!table) throw new Error("Unknown module or type");

          await api.put(`/references/${table}/${item.id}`, item);
          toast.success(t('generated.zapis_obnovlena'));
          await loadData();
      } catch (e) {
          console.error('Error updating item:', e);
          toast.error(t('generated.oshibka_obnovleniya') + (e instanceof Error ? e.message : String(e)));
      }
  };

  const deleteItem = async (type: 'status' | 'tag' | 'priority' | 'relationshipType', id: string, module: string) => {
      try {
          const table = getTableName(module, type);
          if (!table) throw new Error("Unknown module or type");

          await api.delete(`/references/${table}/${id}`);
          toast.success(t('generated.zapis_udalena'));
          await loadData();
      } catch (e) {
          console.error('Error deleting item:', e);
          toast.error(t('generated.oshibka_udaleniya') + (e instanceof Error ? e.message : String(e)));
      }
  };

  // ─── Legal Form CRUD ─────────────────────────────────────────────────────────
  const addLegalForm = async (item: LegalFormItem) => {
      try {
          const finalId = item.id || `lf-${Date.now()}`;
          await api.post('/references/legal_forms', { ...item, id: finalId });
          toast.success(t('generated.zapis_dobavlena'));
          await loadData();
      } catch (e) {
          console.error('Error adding legal form:', e);
          toast.error(t('generated.oshibka_dobavleniya') + (e instanceof Error ? e.message : String(e)));
      }
  };

  const updateLegalForm = async (item: LegalFormItem) => {
      try {
          await api.put(`/references/legal_forms/${item.id}`, item);
          toast.success(t('generated.zapis_obnovlena'));
          await loadData();
      } catch (e) {
          console.error('Error updating legal form:', e);
          toast.error(t('generated.oshibka_obnovleniya') + (e instanceof Error ? e.message : String(e)));
      }
  };

  const deleteLegalForm = async (id: string) => {
      try {
          await api.delete(`/references/legal_forms/${id}`);
          toast.success(t('generated.zapis_udalena'));
          await loadData();
      } catch (e) {
          console.error('Error deleting legal form:', e);
          toast.error(t('generated.oshibka_udaleniya') + (e instanceof Error ? e.message : String(e)));
      }
  };

  const saveQuickActions = async (items: QuickAction[]) => {
    try {
        const reorderPayload = items.map((item, index) => ({
            id: item.id,
            displayOrder: index + 1
        }));
        await api.post('/quick-actions/reorder', { items: reorderPayload });
        toast.success(t('generated.bystrye_deystviya_sohraneny'));
        await loadData();
    } catch(e) {
        console.error('Error saving quick actions:', e);
        toast.error(t('generated.oshibka_sohraneniya') + (e instanceof Error ? e.message : String(e)));
    }
  };

  const getStatusesByModule = (module: string) => statuses.filter(s => s.module === module);
  const getTagsByModule = (module: string) => tags.filter(t => t.module === module);
  const getPrioritiesByModule = (module: string) => priorities.filter(p => p.module === module);
  const getQuickActionsByModule = (module: string) => quickActions.filter(q => q.module === module);
  const getRelationshipTypesByModule = (module: string) => relationshipTypes.filter(rt => rt.module === module);
  const getContractorTypesByModule = (_module: string = 'contractors') => contractorTypes;

  const getLegalFormsByModule = (_module: string = 'contractors') => {
    // Legal forms don't have a module field yet, they're global
    return legalForms;
  };

  return {
    statuses,
    tags,
    priorities,
    quickActions,
    relationshipTypes,
    contractorTypes,
    legalForms,
    theme,
    accentColor,

    addItem,
    updateItem,
    deleteItem,
    addLegalForm,
    updateLegalForm,
    deleteLegalForm,

    saveStatuses: () => {},
    saveTags: () => {},
    savePriorities: () => {},

    saveQuickActions,
    setTheme,
    setAccentColor,
    getStatusesByModule,
    getTagsByModule,
    getPrioritiesByModule,
    getQuickActionsByModule,
    getRelationshipTypesByModule,
    getContractorTypesByModule,
    getLegalFormsByModule,
    sidebarCollapsed,
    setSidebarCollapsed,
    refresh: loadData
  };
}

import { useState, useMemo } from "react";

export interface UseBulkSelectionOptions<T> {
  /** Все данные (весь массив) */
  allData: T[];
  /** Данные на текущей странице */
  pageData: T[];
  /** ID выбранных записей */
  selectedIds: Set<string | number>;
  /** Установить выбранные ID */
  setSelectedIds: (ids: Set<string | number>) => void;
  /** Ключ для получения ID из записи */
  getId?: (item: T) => string | number;
}

export interface UseBulkSelectionReturn {
  /** Выбранные ID */
  selectedIds: Set<string | number>;
  /** Установить выбранные ID */
  setSelectedIds: (ids: Set<string | number>) => void;
  /** Выбраны ли все записи на текущей странице */
  isCurrentPageSelected: boolean;
  /** Выбраны ли все записи (все страницы) */
  isAllSelected: boolean;
  /** Выбраны ли некоторые записи на текущей странице */
  isSomeSelected: boolean;
  /** Переключить выбор текущей страницы */
  toggleCurrentPage: () => void;
  /** Переключить выбор всех страниц */
  toggleAllPages: () => void;
  /** Переключить выбор отдельной записи */
  toggleOne: (id: string | number) => void;
  /** Очистить выбор */
  clearSelection: () => void;
  /** Выбрать только текущую страницу */
  selectCurrentPageOnly: () => void;
  /** Количество выбранных записей */
  selectedCount: number;
  /** Количество записей на текущей странице */
  currentPageCount: number;
  /** Общее количество записей */
  totalCount: number;
}

/**
 * Хук для управления множественным выбором с поддержкой "выбора всех страниц"
 * 
 * @example
 * ```tsx
 * const {
 *   isCurrentPageSelected,
 *   isAllSelected,
 *   isSomeSelected,
 *   toggleCurrentPage,
 *   toggleAllPages,
 *   toggleOne,
 *   clearSelection,
 *   selectedCount,
 * } = useBulkSelection({
 *   allData: allContractors,
 *   pageData: paginatedContractors,
 *   selectedIds,
 *   setSelectedIds,
 * });
 * ```
 */
export function useBulkSelection<T>({
  allData,
  pageData,
  selectedIds,
  setSelectedIds,
  getId = (item: any) => item.id,
}: UseBulkSelectionOptions<T>): UseBulkSelectionReturn {
  const [selectAllMode, setSelectAllMode] = useState(false);

  // Получаем все ID (с защитой от undefined)
  const allIds = useMemo(() => {
    if (!allData || !Array.isArray(allData)) return new Set<string | number>();
    return new Set(allData.map(getId));
  }, [allData, getId]);

  const currentPageIds = useMemo(() => {
    if (!pageData || !Array.isArray(pageData)) return new Set<string | number>();
    return new Set(pageData.map(getId));
  }, [pageData, getId]);

  // Проверяем состояния выбора
  const isCurrentPageSelected = useMemo(() => {
    if (currentPageIds.size === 0) return false;
    return Array.from(currentPageIds).every(id => selectedIds.has(id));
  }, [selectedIds, currentPageIds]);

  const isAllSelected = useMemo(() => {
    if (allIds.size === 0) return false;
    return allIds.size === selectedIds.size;
  }, [selectedIds, allIds]);

  const isSomeSelected = useMemo(() => {
    return selectedIds.size > 0 && !isAllSelected;
  }, [selectedIds.size, isAllSelected]);

  const selectedCount = selectedIds.size;
  const currentPageCount = pageData.length;
  const totalCount = allData.length;

  // Переключить выбор текущей страницы
  const toggleCurrentPage = () => {
    const newSelected = new Set(selectedIds);
    if (isCurrentPageSelected) {
      // Снять выделение со всех на текущей странице
      currentPageIds.forEach(id => newSelected.delete(id));
    } else {
      // Выделить все на текущей странице
      currentPageIds.forEach(id => newSelected.add(id));
    }
    setSelectedIds(newSelected);
    setSelectAllMode(false);
  };

  // Переключить выбор всех страниц
  const toggleAllPages = () => {
    if (isAllSelected) {
      // Снять выделение со всех
      setSelectedIds(new Set());
      setSelectAllMode(false);
    } else {
      // Выделить все
      setSelectedIds(allIds);
      setSelectAllMode(true);
    }
  };

  // Переключить выбор отдельной записи
  const toggleOne = (id: string | number) => {
    const newSelected = new Set(selectedIds);
    if (newSelected.has(id)) {
      newSelected.delete(id);
    } else {
      newSelected.add(id);
    }
    setSelectedIds(newSelected);
    setSelectAllMode(false);
  };

  // Очистить выбор
  const clearSelection = () => {
    setSelectedIds(new Set());
    setSelectAllMode(false);
  };

  // Выбрать только текущую страницу
  const selectCurrentPageOnly = () => {
    setSelectedIds(currentPageIds);
    setSelectAllMode(false);
  };

  return {
    selectedIds,
    setSelectedIds,
    isCurrentPageSelected,
    isAllSelected,
    isSomeSelected,
    toggleCurrentPage,
    toggleAllPages,
    toggleOne,
    clearSelection,
    selectCurrentPageOnly,
    selectedCount,
    currentPageCount,
    totalCount,
  };
}

import { useState, useEffect, useRef } from "react";
import { LucideIcon } from "lucide-react";
import { api } from "@/lib/api";

export interface TabConfig {
  id: string;
  label: string;
  icon: LucideIcon;
  visible: boolean;
}

export interface SortConfig<T> {
  key: keyof T;
  direction: 'asc' | 'desc';
}

interface UseDataTableProps<T> {
  initialData: T[];
  initialColumns: Record<string, boolean>;
  initialTabs?: TabConfig[];
  storageKey?: string; // New prop for persistence
  defaultRowsPerPage?: string;
  defaultColumnWidths?: Record<string, number>;
}

interface SavedTabConfig {
  id: string;
  visible: boolean;
}

export function useDataTable<T extends { id: string | number }>({
  initialData,
  initialColumns,
  initialTabs = [],
  storageKey,
  defaultRowsPerPage = "25",
  defaultColumnWidths = {},
}: UseDataTableProps<T>) {
  const initialColumnsRef = useRef<Record<string, boolean>>(initialColumns);
  const initialTabsRef = useRef<TabConfig[]>(initialTabs);

  // Update refs when props change
  useEffect(() => {
    initialColumnsRef.current = initialColumns;
  }, [initialColumns]);

  useEffect(() => {
    initialTabsRef.current = initialTabs;
  }, [initialTabs]);

  const lastSavedColumnsRef = useRef<string | null>(null);
  const lastSavedTabsRef = useRef<string | null>(null);
  const lastSavedOrderRef = useRef<string | null>(null);
  const lastSavedPaginationRef = useRef<string | null>(null);
  const lastSavedWidthsRef = useRef<string | null>(null);
  // Map of tabId → saved visible value, for dynamic tabs loaded after initial API fetch
  const savedTabVisibilityRef = useRef<Record<string, boolean>>({});

  // Search & Filter Basics
  const [searchQuery, setSearchQuery] = useState("");

  // Selection
  const [selectedIds, setSelectedIds] = useState<Set<string | number>>(new Set());

  // Sorting
  const [sortConfig, setSortConfig] = useState<SortConfig<T> | null>(null);

  // Visibility & Config state
  const [visibleColumns, setVisibleColumns] = useState(initialColumns);
  const [columnOrder, setColumnOrder] = useState<string[]>(Object.keys(initialColumns));
  const [tabsConfig, setTabsConfig] = useState<TabConfig[]>(initialTabs);
  const [columnWidths, setColumnWidths] = useState<Record<string, number>>(defaultColumnWidths);

  // Pagination
  const [rowsPerPage, setRowsPerPage] = useState<string>(defaultRowsPerPage);
  const [currentPage, setCurrentPage] = useState<number>(1);

  // Initialize as "loaded" if no storageKey (no async loading needed)
  const [isLoaded, setIsLoaded] = useState(!storageKey);

  // Load Settings from API
  useEffect(() => {
    if (storageKey) {
        const loadSettings = async () => {
            try {
                // Load Columns
                const savedCols = await api.get(`/user-settings/${storageKey}-columns`);
                if (savedCols) {
                  setVisibleColumns({ ...initialColumnsRef.current, ...savedCols });
                  lastSavedColumnsRef.current = JSON.stringify({ ...initialColumnsRef.current, ...savedCols });
                } else {
                  lastSavedColumnsRef.current = JSON.stringify(initialColumnsRef.current);
                }

                // Load Column Order
                const savedOrder = await api.get(`/user-settings/${storageKey}-column-order`);
                if (savedOrder && Array.isArray(savedOrder)) {
                  const initialKeys = Object.keys(initialColumnsRef.current || {});
                  // Keep saved order, append any new keys not in saved order
                  const merged = [
                    ...(savedOrder as string[]).filter(k => initialKeys.includes(k)),
                    ...initialKeys.filter(k => !(savedOrder as string[]).includes(k)),
                  ];
                  setColumnOrder(merged);
                  lastSavedOrderRef.current = JSON.stringify(merged);
                } else {
                  lastSavedOrderRef.current = JSON.stringify(Object.keys(initialColumnsRef.current || {}));
                }

                // Load Tabs
                if (initialTabsRef.current && initialTabsRef.current.length > 0) {
                    const savedTabs = await api.get(`/user-settings/${storageKey}-tabs`);
                    if (savedTabs && Array.isArray(savedTabs)) {
                      // Store all saved visibility in ref so dynamic tabs added later can use it
                      const visMap: Record<string, boolean> = {};
                      (savedTabs as SavedTabConfig[]).forEach((s) => { visMap[s.id] = s.visible; });
                      savedTabVisibilityRef.current = visMap;
                      // Reconstruct tabs in saved order, preserving visibility; append new tabs not in saved data
                      setTabsConfig(prev => {
                        const savedOrder = (savedTabs as SavedTabConfig[]).map(s => s.id);
                        return [
                          ...savedOrder
                            .map(id => prev.find(t => t.id === id))
                            .filter((t): t is TabConfig => !!t)
                            .map(tab => ({ ...tab, visible: visMap[tab.id] ?? tab.visible })),
                          ...prev.filter(t => !savedOrder.includes(t.id)),
                        ];
                      });
                      lastSavedTabsRef.current = JSON.stringify(
                        (savedTabs as SavedTabConfig[]).map(({ id, visible }) => ({ id, visible }))
                      );
                    } else {
                      lastSavedTabsRef.current = JSON.stringify((initialTabsRef.current || []).map(({ id, visible }) => ({ id, visible })));
                    }
                }

                // Load Pagination (rowsPerPage preference)
                const savedPagination = await api.get(`/user-settings/${storageKey}-pagination`);
                if (savedPagination && typeof savedPagination === 'object' && 'rowsPerPage' in savedPagination) {
                  setRowsPerPage((savedPagination as { rowsPerPage: string }).rowsPerPage);
                  lastSavedPaginationRef.current = JSON.stringify({ rowsPerPage: (savedPagination as { rowsPerPage: string }).rowsPerPage });
                } else {
                  lastSavedPaginationRef.current = JSON.stringify({ rowsPerPage: defaultRowsPerPage });
                }

                // Load Column Widths
                const savedWidths = await api.get(`/user-settings/${storageKey}-column-widths`);
                if (savedWidths && typeof savedWidths === 'object') {
                  setColumnWidths({ ...defaultColumnWidths, ...savedWidths });
                  lastSavedWidthsRef.current = JSON.stringify({ ...defaultColumnWidths, ...savedWidths });
                } else {
                  lastSavedWidthsRef.current = JSON.stringify(defaultColumnWidths);
                }
            } catch (e) {
                console.error("Failed to load table settings", e);
                lastSavedColumnsRef.current = JSON.stringify(initialColumnsRef.current || {});
                lastSavedOrderRef.current = JSON.stringify(Object.keys(initialColumnsRef.current || {}));
                lastSavedTabsRef.current = JSON.stringify((initialTabsRef.current || []).map(({ id, visible }) => ({ id, visible })));
                lastSavedPaginationRef.current = JSON.stringify({ rowsPerPage: defaultRowsPerPage });
                lastSavedWidthsRef.current = JSON.stringify(defaultColumnWidths);
            } finally {
                // Defer state update to avoid immediate setState in finally block
                setTimeout(() => setIsLoaded(true), 0);
            }
        };
        loadSettings();
    }
  }, [storageKey]);

  // Persist Columns
  useEffect(() => {
    if (storageKey && isLoaded) {
        const serialized = JSON.stringify(visibleColumns);

        if (serialized === lastSavedColumnsRef.current) {
            return;
        }

        api.post('/user-settings', {
            key: `${storageKey}-columns`,
            value: visibleColumns
        })
          .then(() => {
            lastSavedColumnsRef.current = serialized;
          })
          .catch(console.error);
    }
  }, [visibleColumns, storageKey, isLoaded]);

  // Persist Column Order
  useEffect(() => {
    if (storageKey && isLoaded) {
      const serialized = JSON.stringify(columnOrder);
      if (serialized === lastSavedOrderRef.current) return;
      api.post('/user-settings', { key: `${storageKey}-column-order`, value: columnOrder })
        .then(() => { lastSavedOrderRef.current = serialized; })
        .catch(console.error);
    }
  }, [columnOrder, storageKey, isLoaded]);

  // Persist Tabs
  useEffect(() => {
    if (storageKey && isLoaded) {
        const toSave = tabsConfig.map(({ id, visible }) => ({ id, visible }));
        const serialized = JSON.stringify(toSave);

        if (serialized === lastSavedTabsRef.current) {
            return;
        }

        api.post('/user-settings', {
            key: `${storageKey}-tabs`,
            value: toSave
        })
          .then(() => {
            lastSavedTabsRef.current = serialized;
          })
          .catch(console.error);
    }
  }, [tabsConfig, storageKey, isLoaded]);

  // Persist Pagination (rowsPerPage only)
  useEffect(() => {
    if (storageKey && isLoaded) {
      const toSave = { rowsPerPage };
      const serialized = JSON.stringify(toSave);
      if (serialized === lastSavedPaginationRef.current) return;
      api.post('/user-settings', { key: `${storageKey}-pagination`, value: toSave })
        .then(() => { lastSavedPaginationRef.current = serialized; })
        .catch(console.error);
    }
  }, [rowsPerPage, storageKey, isLoaded]);

  // Persist Column Widths
  useEffect(() => {
    if (storageKey && isLoaded) {
      const serialized = JSON.stringify(columnWidths);
      if (serialized === lastSavedWidthsRef.current) return;
      api.post('/user-settings', { key: `${storageKey}-column-widths`, value: columnWidths })
        .then(() => { lastSavedWidthsRef.current = serialized; })
        .catch(console.error);
    }
  }, [columnWidths, storageKey, isLoaded]);

  // Handlers
  const handleSort = (key: keyof T) => {
    let direction: 'asc' | 'desc' = 'asc';
    if (sortConfig && sortConfig.key === key && sortConfig.direction === 'asc') {
      direction = 'desc';
    }
    setSortConfig({ key, direction });
  };

  const toggleSelection = (id: string | number) => {
    setSelectedIds(prev => {
      const newSet = new Set(prev);
      if (newSet.has(id)) newSet.delete(id);
      else newSet.add(id);
      return newSet;
    });
  };

  const toggleAllSelection = (items: T[]) => {
    if (selectedIds.size === items.length && items.length > 0) {
      setSelectedIds(new Set());
    } else {
      setSelectedIds(new Set(items.map(i => i.id)));
    }
  };

  const clearSelection = () => setSelectedIds(new Set());

  // Tab Management
  const moveTab = (index: number, direction: 'up' | 'down') => {
    const newConfig = [...tabsConfig];
    if (direction === 'up' && index > 0) {
        [newConfig[index], newConfig[index - 1]] = [newConfig[index - 1], newConfig[index]];
    } else if (direction === 'down' && index < newConfig.length - 1) {
        [newConfig[index], newConfig[index + 1]] = [newConfig[index + 1], newConfig[index]];
    }
    setTabsConfig(newConfig);
  };

  const toggleTabVisibility = (id: string, checked: boolean) => {
    setTabsConfig(prev => {
      const newConfig = prev.map(tab =>
          tab.id === id ? { ...tab, visible: checked } : tab
      );

      // Обновляем savedTabVisibilityRef
      savedTabVisibilityRef.current[id] = checked;

      // Сохраняем в API
      if (storageKey) {
        const toSave = newConfig.map(({ id, visible }) => ({ id, visible }));
        api.post('/user-settings', {
          key: `${storageKey}-tabs`,
          value: toSave
        }).catch(console.error);
      }

      return newConfig;
    });
  };

  const toggleColumnVisibility = (column: string, checked: boolean) => {
    setVisibleColumns(prev => ({ ...prev, [column]: checked }));
  };

  const setColumnWidth = (key: string, width: number) => {
    setColumnWidths(prev => ({ ...prev, [key]: width }));
  };

  const moveColumn = (key: string, direction: 'up' | 'down') => {
    setColumnOrder(prev => {
      const idx = prev.indexOf(key);
      if (idx === -1) return prev;
      const next = [...prev];
      if (direction === 'up' && idx > 0)
        [next[idx], next[idx - 1]] = [next[idx - 1], next[idx]];
      else if (direction === 'down' && idx < next.length - 1)
        [next[idx], next[idx + 1]] = [next[idx + 1], next[idx]];
      return next;
    });
  };

  const reorderColumn = (fromKey: string, toKey: string) => {
    setColumnOrder(prev => {
      const fromIdx = prev.indexOf(fromKey);
      const toIdx = prev.indexOf(toKey);
      if (fromIdx === -1 || toIdx === -1 || fromIdx === toIdx) return prev;
      const next = [...prev];
      next.splice(fromIdx, 1);
      next.splice(toIdx, 0, fromKey);
      return next;
    });
  };

  /** Drag-to-reorder вкладок: меняет местами вкладки по id */
  const reorderTab = (fromId: string, toId: string) => {
    setTabsConfig(prev => {
      const fromIdx = prev.findIndex(t => t.id === fromId);
      const toIdx = prev.findIndex(t => t.id === toId);
      if (fromIdx === -1 || toIdx === -1 || fromIdx === toIdx) return prev;
      const next = [...prev];
      next.splice(fromIdx, 1);
      next.splice(toIdx, 0, prev[fromIdx]);
      return next;
    });
  };

  return {
    searchQuery,
