/**
 * WebSocket Hook для React
 * Подключение к WebSocket серверу и обработка событий
 */

import { useEffect, useRef, useCallback, useState } from 'react';
import { toast } from 'sonner';

interface WebSocketMessage {
  type: string;
  data: any;
  timestamp: string;
}

interface UseWebSocketOptions {
  userId?: string;
  onNewMail?: (mail: any) => void;
  onSyncStatus?: (status: any) => void;
  onMailSent?: (mail: any) => void;
  autoReconnect?: boolean;
  reconnectInterval?: number;
}

export function useWebSocket(options: UseWebSocketOptions = {}) {
  const {
    userId,
    onNewMail,
    onSyncStatus,
    onMailSent,
    autoReconnect = true,
    reconnectInterval = 5000
  } = options;

  const wsRef = useRef<WebSocket | null>(null);
  const reconnectTimeoutRef = useRef<NodeJS.Timeout>();
  const [isConnected, setIsConnected] = useState(false);
  const [lastMessage, setLastMessage] = useState<WebSocketMessage | null>(null);
  const [syncStatus, setSyncStatus] = useState<any>(null);

  // Подключение к WebSocket
  const connect = useCallback(() => {
    if (!userId) {
      console.log('[WebSocket] No userId, skipping connection');
      return;
    }

    try {
      // Закрываем старое соединение если есть
      if (wsRef.current) {
        wsRef.current.close();
      }

      // Создаём новое соединение
      const protocol = window.location.protocol === 'https:' ? 'wss:' : 'ws:';
      const wsUrl = `${protocol}//${window.location.host}/ws?userId=${userId}`;

      console.log('[WebSocket] Connecting to:', wsUrl);

      const ws = new WebSocket(wsUrl);
      wsRef.current = ws;

      ws.onopen = () => {
        console.log('[WebSocket] Connected');
        setIsConnected(true);

        // Отправляем ping для проверки
        ws.send(JSON.stringify({ type: 'ping' }));
      };

      ws.onmessage = (event) => {
        try {
          const message: WebSocketMessage = JSON.parse(event.data);
          console.log('[WebSocket] Message received:', message);

          setLastMessage(message);

          // Обрабатываем разные типы сообщений
          switch (message.type) {
            case 'connected':
              console.log('[WebSocket] Server acknowledged connection');
              break;

            case 'pong':
              console.log('[WebSocket] Pong received');
              break;

            case 'new_mail':
              console.log('[WebSocket] New mail notification');
              onNewMail?.(message.data);
              toast.info(`📧 Новое письмо от ${message.data.mail?.sender || 'Неизвестный'}`);
              break;

            case 'sync_status':
              console.log('[WebSocket] Sync status:', message.data.status);
              setSyncStatus(message.data);
              onSyncStatus?.(message.data);

              if (message.data.status === 'completed') {
                toast.success(`✅ ${message.data.message}`);
              } else if (message.data.status === 'error') {
                toast.error(`❌ ${message.data.message}`);
              }
              // progress и counting — обрабатываются через syncStatus state
              break;

            case 'mail_sent':
              console.log('[WebSocket] Mail sent notification');
              onMailSent?.(message.data);
              toast.success('✅ Письмо отправлено');
              break;

            default:
              console.warn('[WebSocket] Unknown message type:', message.type);
          }
        } catch (error) {
          console.error('[WebSocket] Error parsing message:', error);
        }
      };

      ws.onclose = () => {
        console.log('[WebSocket] Disconnected');
        setIsConnected(false);
        wsRef.current = null;

        // Автоматическое переподключение
        if (autoReconnect) {
          console.log(`[WebSocket] Will reconnect in ${reconnectInterval}ms`);
          reconnectTimeoutRef.current = setTimeout(connect, reconnectInterval);
        }
      };

      ws.onerror = (error) => {
        console.error('[WebSocket] Error:', error);
      };
    } catch (error) {
      console.error('[WebSocket] Connection error:', error);

      if (autoReconnect) {
        reconnectTimeoutRef.current = setTimeout(connect, reconnectInterval);
      }
    }
  }, [userId, autoReconnect, reconnectInterval, onNewMail, onSyncStatus, onMailSent]);

  // Отправка сообщения
  const sendMessage = useCallback((type: string, data: any = {}) => {
    if (wsRef.current && wsRef.current.readyState === WebSocket.OPEN) {
      wsRef.current.send(JSON.stringify({ type, data }));
    } else {
      console.warn('[WebSocket] Cannot send message - not connected');
    }
  }, []);

  // Подписка на события
  const subscribe = useCallback((events: string[]) => {
    sendMessage('subscribe', { events });
  }, [sendMessage]);

  // Отписка от событий
  const unsubscribe = useCallback((events: string[]) => {
    sendMessage('unsubscribe', { events });
  }, [sendMessage]);

  // Отключение
  const disconnect = useCallback(() => {
    if (reconnectTimeoutRef.current) {
      clearTimeout(reconnectTimeoutRef.current);
    }
    if (wsRef.current) {
      wsRef.current.close();
      wsRef.current = null;
    }
    setIsConnected(false);
  }, []);

  // Подключение при монтировании
  useEffect(() => {
    if (userId) {
      connect();
    }

    return () => {
      disconnect();
    };
  }, [userId]);

  return {
    isConnected,
    lastMessage,
    syncStatus,
    sendMessage,
    subscribe,
    unsubscribe,
    disconnect,
    connect
  };
}

// Используем относительные пути, так как прокси настроен на /api -> localhost:5001
const API_URL = import.meta.env.VITE_API_URL || '/api';

// Получаем ID текущего пользователя из локального хранилища
const getCurrentUserId = () => {
    return localStorage.getItem('titan_user_id') || '2';
};

// Получаем JWT токен из локального хранилища
const getAuthToken = () => {
    return localStorage.getItem('titan_token');
};

// Стандартные заголовки для всех запросов
const getHeaders = (extraHeaders?: HeadersInit) => {
    const headers: HeadersInit = {
        'x-user-id': getCurrentUserId(),
    };

    // Добавляем JWT токен если есть
    const token = getAuthToken();
    if (token) {
        headers['Authorization'] = `Bearer ${token}`;
    }

    return { ...headers, ...extraHeaders };
};

export const api = {
  get: async (endpoint: string, options?: { responseType?: 'json' | 'blob', params?: Record<string, any> }) => {
    // Добавляем query параметры если есть
    let url = `${API_URL}${endpoint}`;
    if (options?.params) {
      const queryParams = new URLSearchParams();
      Object.entries(options.params).forEach(([key, value]) => {
        if (value !== undefined && value !== null) {
          queryParams.append(key, String(value));
        }
      });
      const queryString = queryParams.toString();
      if (queryString) {
        url += `?${queryString}`;
      }
    }

    const response = await fetch(url, {
        headers: getHeaders()
    });

    // Если токен истёк (401), перенаправляем на логин
    if (response.status === 401) {
        localStorage.removeItem('titan_token');
        localStorage.removeItem('titan_user_id');
        localStorage.removeItem('titan_user_role');
        window.location.href = '/login';
        throw new Error('Срок действия сессии истёк');
    }

    if (!response.ok) {
      if (response.status === 403) throw new Error("Нет прав доступа (403)");
      const body = await response.json().catch(() => ({}));
      const err = Object.assign(new Error(body.error ?? `API Error: ${response.statusText}`), body, { status: response.status });
      throw err;
    }
    if (options?.responseType === 'blob') {
      return response.blob();
    }

    // Handle empty responses
    const contentType = response.headers.get('content-type');
    if (!contentType || !contentType.includes('application/json')) {
      return null;
    }

    return response.json();
  },
  post: async (endpoint: string, data: unknown, options?: RequestInit) => {
