        throw err;
    }

    // Handle empty responses
    const contentType = response.headers.get('content-type');
    if (!contentType || !contentType.includes('application/json')) {
      return null;
    }

    return response.json();
  },
  put: async (endpoint: string, data: unknown) => {
    const response = await fetch(`${API_URL}${endpoint}`, {
      method: 'PUT',
      headers: getHeaders({ 'Content-Type': 'application/json' }),
      body: JSON.stringify(data),
    });

    // Если токен истёк (401), перенаправляем на логин
    if (response.status === 401) {
        localStorage.removeItem('titan_token');
        localStorage.removeItem('titan_user_id');
        localStorage.removeItem('titan_user_role');
        window.location.href = '/login';
        throw new Error('Срок действия сессии истёк');
    }

    if (!response.ok) {
        if (response.status === 403) throw new Error("Нет прав доступа (403)");
        throw new Error(`API Error: ${response.statusText}`);
    }

    // Handle empty responses
    const contentType = response.headers.get('content-type');
    if (!contentType || !contentType.includes('application/json')) {
      return null;
    }

    return response.json();
  },
  patch: async (endpoint: string, data: unknown) => {
    const response = await fetch(`${API_URL}${endpoint}`, {
      method: 'PATCH',
      headers: getHeaders({ 'Content-Type': 'application/json' }),
      body: JSON.stringify(data),
    });

    // Если токен истёк (401), перенаправляем на логин
    if (response.status === 401) {
        localStorage.removeItem('titan_token');
        localStorage.removeItem('titan_user_id');
        localStorage.removeItem('titan_user_role');
        window.location.href = '/login';
        throw new Error('Срок действия сессии истёк');
    }

    if (!response.ok) {
        if (response.status === 403) throw new Error("Нет прав доступа (403)");
        throw new Error(`API Error: ${response.statusText}`);
    }

    // Handle empty responses
    const contentType = response.headers.get('content-type');
    if (!contentType || !contentType.includes('application/json')) {
      return null;
    }

    return response.json();
  },
  delete: async (endpoint: string) => {
    const response = await fetch(`${API_URL}${endpoint}`, {
      method: 'DELETE',
      headers: getHeaders()
    });

    // Если токен истёк (401), перенаправляем на логин
    if (response.status === 401) {
        localStorage.removeItem('titan_token');
        localStorage.removeItem('titan_user_id');
        localStorage.removeItem('titan_user_role');
        window.location.href = '/login';
        throw new Error('Срок действия сессии истёк');
    }

    if (!response.ok) {
        if (response.status === 403) throw new Error("Нет прав доступа (403)");
        throw new Error(`API Error: ${response.statusText}`);
    }

    // Handle empty responses (common for DELETE)
    const contentType = response.headers.get('content-type');
    if (!contentType || !contentType.includes('application/json')) {
      return null;
    }

    return response.json();
  }
};

import React, { createContext, useContext, useState } from 'react';
import * as locales from './locales/ru/index';

// Список модулей, которые содержат внутри себя другие неймспейсы и не должны использоваться как префикс
// Например, business.ts содержит contractors: {...}, поэтому ключ будет contractors.title, а не business.contractors.title
const CONTAINER_MODULES = ['business', 'legal', 'office', 'layout'];

type TranslationTree = Record<string, unknown>;

// Рекурсивная функция для сплющивания объекта
const flattenObject = (obj: TranslationTree, prefix = ''): Record<string, string> => {
  return Object.keys(obj).reduce<Record<string, string>>((acc, k) => {
    const pre = prefix.length ? prefix + '.' : '';
    if (typeof obj[k] === 'object' && obj[k] !== null && !Array.isArray(obj[k])) {
      Object.assign(acc, flattenObject(obj[k] as TranslationTree, pre + k));
    } else {
      acc[pre + k] = String(obj[k]);
    }
    return acc;
  }, {});
};

// Сборка всех переводов в один плоский объект
const translations = Object.entries(locales).reduce((acc, [key, module]) => {
  // key - это имя экспорта (например, "common", "business")
  const isContainer = CONTAINER_MODULES.includes(key);
  
  if (isContainer) {
    // Для контейнеров (business, legal...) мы берем ключи внутри как корневые
    // { business: { contractors: ... } } -> contractors.title
    return { ...acc, ...flattenObject(module) };
  } else {
    // Для обычных модулей (common, auth...) используем имя файла как префикс
    // { common: { search: ... } } -> common.search
    return { ...acc, ...flattenObject(module, key) };
  }
}, {} as Record<string, string>);

// Создаём алиасы `generated.<key>` для ключей из `lost` и `general.generated`
// (используется старый префикс в коде)
if (translations) {
  // Сначала алиасы из lost.* (приоритет выше)
  Object.keys(translations).forEach(k => {
    if (k.startsWith('lost.')) {
      const short = k.replace(/^lost\./, '');
      const genKey = `generated.${short}`;
      if (!translations[genKey]) {
        translations[genKey] = translations[k];
      }
    }
  });
  // Затем алиасы из general.generated.* (заполняет пробелы)
  Object.keys(translations).forEach(k => {
    if (k.startsWith('general.generated.')) {
      const short = k.replace(/^general\.generated\./, '');
      const genKey = `generated.${short}`;
      if (!translations[genKey]) {
        translations[genKey] = translations[k];
      }
    }
  });
}

type InterpolationParams = Record<string, string | number> | Array<string | number>;

const I18nContext = createContext<{
  t: (key: string, params?: InterpolationParams) => string;
  locale: string;
  setLocale: (locale: string) => void;
} | null>(null);

export const I18nProvider = ({ children }: { children: React.ReactNode }) => {
  const [locale, setLocale] = useState('ru');

  const t = (key: string, params?: InterpolationParams): string => {
    let str = translations[key] ?? key;
    if (params) {
      if (Array.isArray(params)) {
        params.forEach((value, index) => {
          str = str.replace(new RegExp(`\\{${index}\\}`, 'g'), String(value));
        });
      } else {
        Object.entries(params).forEach(([k, v]) => {
          str = str.replace(new RegExp(`\\{${k}\\}`, 'g'), String(v));
        });
      }
    }
    return str;
  };

  return (
    <I18nContext.Provider value={{ t, locale, setLocale }}>
      {children}
    </I18nContext.Provider>
  );
};

export const useTranslation = () => {
  const context = useContext(I18nContext);
  if (!context) {
    throw new Error('useTranslation must be used within an I18nProvider');
  }
  return context;
};

/**
 * Utility for rendering text with clickable links
 * Converts URLs in plain text to clickable <a> elements
 */

import React from 'react';

/**
 * Regex pattern to match URLs including very long ones
 * Matches:
 * - http:// and https:// protocols
 * - www. prefixes
 * - Various domain extensions
 * - Query parameters and fragments (including very long ones like the Nalog.ru example)
 */
const URL_REGEX = /https?:\/\/[^\s<>[\]{}|"'()]*[^\s<>[\]{}|"'().,:;!?]/gi;

interface RenderLinkOptions {
  target?: string;
  rel?: string;
  className?: string;
}

/**
 * Parse text and convert URLs to clickable links
 * Handles very long URLs like https://service.nalog.ru/ri-repl.do?t=58A29C7C02057E68543FAEB3F0B60E9DACA57FCC277CB8AA7E59F5934CF2D2F6
 * 
 * @param text - Plain text that may contain URLs
 * @param options - Options for link rendering
 * @returns Array of React elements (text nodes and link elements)
 */
export function renderTextWithLinks(
  text: string,
  options: RenderLinkOptions = {}
): React.ReactElement[] {
  const {
    target = '_blank',
    rel = 'noopener noreferrer',
    className = 'text-blue-600 hover:text-blue-700 hover:underline cursor-pointer'
  } = options;

  if (!text) return [];

  const parts: React.ReactElement[] = [];
  let lastIndex = 0;
  let linkCount = 0;

  // Find all URLs in the text
  let match;
  const matches: Array<{ url: string; start: number; end: number }> = [];

  while ((match = URL_REGEX.exec(text)) !== null) {
    matches.push({
      url: match[0],
      start: match.index,
      end: match.index + match[0].length
    });
  }

  // Build parts array
  matches.forEach((urlMatch) => {
    // Add text before the URL
    if (urlMatch.start > lastIndex) {
      parts.push(
        React.createElement(
          React.Fragment,
          { key: `text-${lastIndex}` },
          text.substring(lastIndex, urlMatch.start)
        )
      );
    }

    // Add the clickable link
    parts.push(
      React.createElement(
        'a',
        {
          key: `link-${linkCount}`,
          href: urlMatch.url,
          target,
          rel,
          className,
          title: urlMatch.url,
          onClick: (e: React.MouseEvent) => {
            // Allow opening in new tab/window
            if (!e.ctrlKey && !e.metaKey && !e.shiftKey) {
              e.preventDefault();
              window.open(urlMatch.url, target);
            }
          }
        },
        // Display truncated URL if very long
        urlMatch.url.length > 60
          ? `${urlMatch.url.substring(0, 57)}...`
          : urlMatch.url
      )
    );

    linkCount++;
    lastIndex = urlMatch.end;
  });

  // Add remaining text after last URL
  if (lastIndex < text.length) {
    parts.push(
      React.createElement(
        React.Fragment,
        { key: `text-end-${lastIndex}` },
        text.substring(lastIndex)
      )
    );
  }

  // If no URLs found, return original text in array
  if (parts.length === 0) {
    return [React.createElement(React.Fragment, { key: 'text-only' }, text)];
  }

  return parts;
}

/**
 * Component that wraps text and converts URLs to clickable links
 */
export interface TextWithLinksProps {
  text: string;
  className?: string;
  linkClassName?: string;
  target?: string;
  rel?: string;
  as?: React.ElementType;
}

export const TextWithLinks: React.FC<TextWithLinksProps> = ({
  text,
  className,
  linkClassName,
  target = '_blank',
  rel = 'noopener noreferrer',
  as: Component = 'p'
}) => {
  const links = renderTextWithLinks(text, {
    target,
    rel,
    className: linkClassName
  });

  return React.createElement(
    Component,
    { className },
    ...links
  );
};

export default TextWithLinks;

/**
 * Типы для настроек полей массового редактирования (Bulk Edit)
 */

/** Тип поля для массового редактирования */
export type BulkEditFieldType = 
  | 'select'           // Выпадающий список (статусы, приоритеты и т.д.)
  | 'combobox'         // Combobox с поиском (контрагенты, пользователи)
  | 'text'             // Текстовое поле
  | 'number'           // Числовое поле
  | 'date'             // Дата
  | 'boolean'          // Булево значение
  | 'tags';            // Теги

/** Конфигурация поля для массового редактирования */
export interface BulkEditFieldConfig {
  /** Уникальный идентификатор поля (ключ в объекте записи) */
  id: string;
  /** Отображаемое название поля */
  label: string;
  /** Тип редактора */
  type: BulkEditFieldType;
  /** Источник данных для select/combobox (опционально) */
  dataSource?: string;  // Например: 'statuses', 'priorities', 'users', 'contractors'
  /** Модуль для данных (опционально) */
  dataSourceModule?: string;  // Например: 'contractors', 'lawyers'
  /** Порядок отображения */
  order: number;
  /** Включено ли поле */
  enabled: boolean;
  /** Обязательно ли поле для заполнения */
  required?: boolean;
  /** Описание поля (подсказка) */
  description?: string;
  /** Дополнительные параметры */
  params?: Record<string, any>;
}

/** Настройки массового редактирования для модуля */
export interface ModuleBulkEditSettings {
  /** ID модуля (например: 'contractors', 'projects', 'cases') */
  moduleId: string;
  /** Название модуля */
  moduleName: string;
  /** Поля для массового редактирования */
  fields: BulkEditFieldConfig[];
  /** Включено ли массовое редактирование для модуля */
  enabled: boolean;
  /** Дата последнего обновления */
  updatedAt?: string;
}

/** Пропсы для компонента настройки полей BulkEdit */
export interface BulkEditSettingsEditorProps {
  /** ID модуля */
  moduleId: string;
  /** Название модуля */
