import type { CalendarEvent, CalendarNotification, EventType } from "../types";
import type { Contractor } from "@/modules/contractors";
import {
  calendarEventReducer, createInitialFormState,
  setField, setForm, resetForm,
} from "../store/calendarEventSlice";
import { CalendarParticipantNotify } from "./CalendarParticipantNotify";
import { CalendarReminderSection } from "./CalendarReminderSection";

interface CalendarEventSheetProps {
  event: CalendarEvent | null;
  selectedDate: Date | null;
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onSave: (event: CalendarEvent) => void;
  onDelete: (id: string) => void;
}

export function CalendarEventSheet({
  event, selectedDate, open, onOpenChange, onSave, onDelete,
}: CalendarEventSheetProps) {
  const { t } = useTranslation();
  const { toast } = useToast();
  const { contractors, createContractor } = useContractors();

  // Управление ContractorSheet
  const [contractorSheetOpen, setContractorSheetOpen] = React.useState(false);
  const [pendingContractorName, setPendingContractorName] = React.useState<string>("");
  const contractorResolverRef = React.useRef<{ resolve: (id: number) => void; reject: () => void } | null>(null);

  const [state, dispatch] = useReducer(calendarEventReducer, createInitialFormState(event, selectedDate));
  const { formData, isCustomReminderOpen, customReminderType, customVal, customUnit, customDate, customTime } = state;

  useEffect(() => {
    if (open) {
      if (event) dispatch(setForm({ ...event, notifications: event.notifications || [] }));
      else dispatch(resetForm(selectedDate || null));
    }
  }, [open, event, selectedDate]);

  const handleChange = (field: keyof CalendarEvent, value: any) => dispatch(setField(field, value));

  const availableClientContacts = useMemo(() => {
    if (!formData.client) return [];
    const contractor = contractors.find((c) => c.name === formData.client);
    if (!contractor) return [];
    const contacts: { label: string; value: string; type: "phone" | "email" }[] = [];
    if (contractor.phone && contractor.phone !== "—") {
      contacts.push({ label: `Офис: ${contractor.name}`, value: contractor.phone, type: "phone" });
    }
    contractor.contacts?.forEach((c) => {
      if (c.phone) contacts.push({ label: `${c.name} (${c.position || t("calendar.contact_type")})`, value: c.phone, type: "phone" });
      if (c.email) contacts.push({ label: `${c.name} (${c.position || t("calendar.contact_type")})`, value: c.email, type: "email" });
    });
    return contacts;
  }, [formData.client, contractors, t]);

  const filteredClientTargets = useMemo(() => {
    const ch = formData.clientNotifyChannel;
    if (ch === "email") return availableClientContacts.filter((c) => c.type === "email");
    if (ch === "sms" || ch === "whatsapp") return availableClientContacts.filter((c) => c.type === "phone");
    return availableClientContacts;
  }, [availableClientContacts, formData.clientNotifyChannel]);

  const formatNotification = (n: CalendarNotification) => {
    if (n.type === "relative") {
      const unitLabel = n.unit === "minutes" ? "мин." : n.unit === "hours" ? "ч." : n.unit === "days" ? "дн." : "нед.";
      return `За ${n.value} ${unitLabel}`;
    }
    try {
      const [d, time] = (n.value as string).split("T");
      return `${d} в ${time}`;
    } catch { return String(n.value); }
  };

  const handleSave = () => {
    if (!formData.title?.trim()) {
      toast({
        variant: "destructive",
        title: t("calendar.validation.title_required"),
      });
      return;
    }

    if (!formData.date) {
      toast({
        variant: "destructive",
        title: t("calendar.validation.date_required"),
      });
      return;
    }

    if (!formData.allDay) {
      const startTime = formData.time || "10:00";
      const endTime = formData.endTime || "11:00";
      if (startTime >= endTime) {
        toast({
          variant: "destructive",
          title: t("calendar.validation.end_time_before_start"),
        });
        return;
      }
    }

    onSave(formData as CalendarEvent);
    onOpenChange(false);
  };

  const handleCreateContractor = (name: string) =>
    new Promise<number>((resolve, reject) => {
      contractorResolverRef.current = { resolve, reject };
      setPendingContractorName(name);
      setContractorSheetOpen(true);
    });

  const handleContractorSheetClose = (isOpen: boolean) => {
    if (!isOpen) {
      contractorResolverRef.current?.reject();
      contractorResolverRef.current = null;
      setContractorSheetOpen(false);
    }
  };

  const handleContractorSheetSave = async (contractor: Partial<Contractor>) => {
    const newContractor = await createContractor(contractor);
    if (newContractor && contractorResolverRef.current) {
      contractorResolverRef.current.resolve(newContractor.id);
      toast({
        title: t("calendar.contractor_created"),
      });
    } else {
      contractorResolverRef.current?.reject();
    }
    contractorResolverRef.current = null;
    setContractorSheetOpen(false);
  };

  return (
    <>
      <ResizableSheet
      open={open}
      onOpenChange={onOpenChange}
      onSave={handleSave}
      onDelete={event ? () => onDelete(formData.id!) : undefined}
      title={event ? t("calendar.edit_event_form") : t("calendar.new_event")}
      description={formData.title || t("calendar.event")}
      moduleKey="calendar-event"
      defaultWidth="md"
      showDeleteButton={!!event}
      saveButtonLabel="common.save"
      cancelButtonLabel="common.cancel"
    >
      <div className="space-y-6">
        {/* Title */}
        <Input
          placeholder={t("calendar.add_event_title")}
          className="text-xl font-semibold border-0 border-b rounded-none px-0 focus-visible:ring-0 shadow-none h-auto py-2"
          value={formData.title || ""}
          onChange={(e) => handleChange("title", e.target.value)}
          autoFocus={!event}
        />

        {/* Event type */}
        <div className="flex items-center gap-4">
          <div className="w-5 flex justify-center text-muted-foreground">
            <div className={`w-3 h-3 rounded-full ${
              formData.type === "meeting" ? "bg-blue-500" :
              formData.type === "task"    ? "bg-green-500" :
              formData.type === "court"   ? "bg-red-500" :
              formData.type === "project" ? "bg-orange-500" :
              formData.type === "reminder"? "bg-pink-500" : "bg-slate-500"
            }`} />
          </div>
          <Select value={formData.type} onValueChange={(v: EventType) => handleChange("type", v)}>
            <SelectTrigger className="flex w-full items-center justify-between rounded-md border border-input bg-background hover:bg-accent hover:text-accent-foreground px-3 py-2 h-9 text-sm font-normal ring-offset-background focus:outline-none focus:ring-2 focus:ring-ring focus:ring-offset-2 disabled:cursor-not-allowed disabled:opacity-50"><SelectValue placeholder={t("calendar.event_type")} /></SelectTrigger>
            <SelectContent>
              <SelectItem value="meeting">{t("calendar.event_types.meeting")}</SelectItem>
              <SelectItem value="task">{t("calendar.event_types.task")}</SelectItem>
              <SelectItem value="call">{t("calendar.event_types.call")}</SelectItem>
              <SelectItem value="court">{t("calendar.event_types.court")}</SelectItem>
              <SelectItem value="project">{t("calendar.event_types.project")}</SelectItem>
              <SelectItem value="reminder">{t("calendar.event_types.reminder")}</SelectItem>
              <SelectItem value="personal">{t("calendar.event_types.personal")}</SelectItem>
            </SelectContent>
          </Select>
        </div>

        {/* Date/Time */}
        <div className="flex items-start gap-4">
          <Clock className="w-5 h-5 text-muted-foreground mt-2" />
          <div className="flex-1 space-y-3">
            <div className="flex items-center justify-between">
              <Label htmlFor="all-day" className="font-normal text-muted-foreground">{t("calendar.all_day_event")}</Label>
              <Switch id="all-day" checked={formData.allDay} onCheckedChange={(c) => handleChange("allDay", c)} />
            </div>
            <div className="flex flex-col gap-2">
              <div className="flex gap-2 items-center">
                <DatePicker
                  value={formData.date ? format(formData.date, "dd.MM.yyyy") : ""}
                  onChange={(d) => {
                    const [day, month, year] = d.split(".").map(Number);
                    handleChange("date", new Date(year, month - 1, day));
                  }}
                  className="flex-1"
                />
                {!formData.allDay && (
                  <Input type="time" className="w-24" value={formData.time || "10:00"} onChange={(e) => handleChange("time", e.target.value)} />
                )}
              </div>
              {!formData.allDay && (
                <div className="flex gap-2 items-center text-muted-foreground text-sm">
                  <span className="w-full text-center">{t("calendar.until_text")}</span>
                  <Input type="time" className="w-24" value={formData.endTime || "11:00"} onChange={(e) => handleChange("endTime", e.target.value)} />
                </div>
              )}
            </div>
          </div>
        </div>

        {/* Participants */}
        <div className="flex items-start gap-4">
          <div className="w-5 flex justify-center mt-2">👥</div>
          <div className="flex-1 grid grid-cols-1 sm:grid-cols-2 gap-x-6 gap-y-4">
            <div className="space-y-1.5">
              <Label className="text-xs text-muted-foreground">{t("calendar.event_client")}</Label>
              <EntityCombobox
                value={formData.client}
                onChange={(v) => { 
                  handleChange("client", v ? String(v) : ""); 
                  handleChange("clientNotifyTarget", ""); 
                }}
                options={(contractors ?? []).map((c) => ({
                  id: c.name,
                  label: c.name,
                }))}
                placeholder={t("calendar.select_client")}
                onCreate={handleCreateContractor}
                className="h-9 text-sm"
              />
              <CalendarParticipantNotify
                label={t("calendar.notify_client")}
                checked={formData.notifyClient || false}
                onCheckedChange={(v) => handleChange("notifyClient", v)}
                channel={formData.clientNotifyChannel || "email"}
                onChannelChange={(c) => { handleChange("clientNotifyChannel", c); handleChange("clientNotifyTarget", ""); }}
                target={formData.clientNotifyTarget}
                onTargetChange={(v) => handleChange("clientNotifyTarget", v)}
                availableTargets={filteredClientTargets}
                showTaskToggle
                taskChecked={formData.createFollowUpTask}
                onTaskCheckedChange={(v) => handleChange("createFollowUpTask", v)}
                disabled={!formData.client}
              />
            </div>
            <div className="space-y-1.5">
              <Label className="text-xs text-muted-foreground">{t("calendar.event_assignee")}</Label>
              <UserSelect value={formData.assignee || ""} onValueChange={(v) => handleChange("assignee", v)} placeholder={t("calendar.assign_user")} className="h-9 text-sm" />
              <CalendarParticipantNotify
                label={t("calendar.notify_client")}
                checked={formData.notifyAssignee || false}
                onCheckedChange={(v) => handleChange("notifyAssignee", v)}
                channel={formData.assigneeNotifyChannel || "app"}
                onChannelChange={(c) => handleChange("assigneeNotifyChannel", c)}
                target={formData.assigneeNotifyTarget}
                onTargetChange={(v) => handleChange("assigneeNotifyTarget", v)}
                availableTargets={[]}
                disabled={!formData.assignee}
              />
            </div>
          </div>
        </div>

        {/* Reminders */}
        <CalendarReminderSection
          notifications={formData.notifications || []}
          isCustomReminderOpen={isCustomReminderOpen}
          customReminderType={customReminderType}
          customVal={customVal}
          customUnit={customUnit}
          customDate={customDate}
          customTime={customTime}
          formatNotification={formatNotification}
          dispatch={dispatch}
        />

        {/* Location */}
        <div className="flex items-center gap-4">
          <MapPin className="w-5 h-5 text-muted-foreground" />
          <Input placeholder={t("calendar.add_location")} value={formData.location || ""} onChange={(e) => handleChange("location", e.target.value)} className="bg-transparent" />
        </div>

        {/* Description */}
        <div className="flex items-start gap-4">
          <AlignLeft className="w-5 h-5 text-muted-foreground mt-2" />
          <Textarea placeholder={t("calendar.add_description")} rows={5} value={formData.description || ""} onChange={(e) => handleChange("description", e.target.value)} className="resize-none" />
        </div>
      </div>
    </ResizableSheet>

      {/* Contractor Creation Sheet */}
      <ContractorSheet
        contractor={null}
        open={contractorSheetOpen}
        onOpenChange={handleContractorSheetClose}
        onSave={handleContractorSheetSave}
        defaultContractorName={pendingContractorName}
      />
    </>
  );
}

