import { useState, useEffect } from "react";
import { Tabs, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { useTranslation } from "@/lib/i18n";
import { 
  CircleDot, 
  Activity, 
  Users, 
  FileText,
  Building2,
} from "lucide-react";
import { Contractor } from "../types/contractor.types";
import { ContractorOverviewTab } from "./tabs/ContractorOverviewTab";
import { ContractorRequisitesTab } from "./tabs/ContractorRequisitesTab";
import { ContractorContactsTab } from "./tabs/ContractorContactsTab";
import { useSheetTabs } from "@/hooks/useSheetTabs";
import { SheetTabSettings, ResizableSheet } from "@/components/shared";
import { useContractorForm } from "../hooks";

interface ContractorSheetProps {
  contractor: Contractor | null;
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onSave?: (contractor: Contractor) => void;
  onDelete?: (id: number) => void;
  initialName?: string;
  defaultContractorName?: string;
}

export function ContractorSheet({ 
  contractor, 
  open, 
  onOpenChange,
  onSave,
  onDelete,
  initialName,
}: ContractorSheetProps) {
  const { t } = useTranslation();
  const [referencesUpdateTrigger, setReferencesUpdateTrigger] = useState(0);
  
  // Form management
  const { formData, handleChange, handleSubmit, isValid } = useContractorForm({
    initialContractor: contractor,
    initialName: contractor ? undefined : initialName,
    onSave,
  });
  
  // Tab Management
  const { tabs, toggleTab, moveTab } = useSheetTabs([
    { id: "overview", label: "sheet.tabs.overview", icon: CircleDot, visible: true },
    { id: "requisites", label: "sheet.tabs.requisites", icon: FileText, visible: true },
    { id: "contacts", label: "sheet.tabs.contacts", icon: Users, visible: true },
    { id: "activity", label: "sheet.tabs.activity", icon: Activity, visible: true },
  ]);
  
  const [activeTab, setActiveTab] = useState("overview");
  // Ensure active tab is visible when opening or changing configuration
  useEffect(() => {
      const currentTab = tabs.find(t => t.id === activeTab);
      if (currentTab && !currentTab.visible) {
          const firstVisible = tabs.find(t => t.visible);
          if (firstVisible) setActiveTab(firstVisible.id);
      }
  }, [tabs, activeTab]);

  // Listen for references updates from Settings
  useEffect(() => {
    const onReferencesUpdated = () => {
      // Trigger a re-render to pick up new references from parent
      setReferencesUpdateTrigger(prev => prev + 1);
    };
    window.addEventListener('references:updated', onReferencesUpdated);
    return () => window.removeEventListener('references:updated', onReferencesUpdated);
  }, []);

  const handleSave = () => {
    const savedContractor = handleSubmit();
    onOpenChange(false);
  };

  const handleDelete = () => {
    if (contractor && onDelete) {
      onDelete(contractor.id);
    }
    onOpenChange(false);
  };

  return (
    <ResizableSheet
      open={open}
      onOpenChange={onOpenChange}
      onSave={handleSave}
      onDelete={contractor ? handleDelete : undefined}
      title={contractor ? contractor.name : t('contractors.add_button')}
      description={formData.name || t('contractor_sheet.title_new')}
      moduleKey="contractor-sheet"
      defaultWidth="xl"
      showDeleteButton={!!contractor}
      saveButtonLabel="contractor_sheet.action.save"
      cancelButtonLabel="contractor_sheet.action.cancel"
    >
      <div className="space-y-6">
        <div className="flex items-center gap-2">
          <Tabs value={activeTab} onValueChange={setActiveTab} className="w-full">
            <TabsList className="w-full justify-start overflow-x-auto">
              {tabs.map(tab => {
                if (!tab.visible) return null;
                const Icon = tab.icon;
                return (
                  <TabsTrigger key={tab.id} value={tab.id} className="gap-1.5 text-xs">
                    <Icon className="w-3.5 h-3.5" />
                    {t(tab.label)}
                  </TabsTrigger>
                );
              })}
            </TabsList>
          </Tabs>
          
          <SheetTabSettings 
            tabs={tabs} 
            onToggle={toggleTab} 
            onMove={moveTab} 
          />
        </div>

        {activeTab === "overview" && (
          <ContractorOverviewTab 
            formData={formData} 
            handleChange={handleChange} 
            _triggerUpdate={referencesUpdateTrigger}
          />
        )}

        {activeTab === "requisites" && (
          <ContractorRequisitesTab formData={formData} handleChange={handleChange} />
        )}

        {activeTab === "contacts" && (
          <ContractorContactsTab formData={formData} handleChange={handleChange} />
        )}

        {activeTab === "activity" && (
          <div className="text-center text-muted-foreground py-8">
            {t('contractor_sheet.placeholder.activity')}
          </div>
        )}
      </div>
    </ResizableSheet>
  );
}

import { useTranslation } from '@/lib/i18n';
/**
 * EnrichLookupPanel — поиск контрагента в реестре по любому запросу
 * (ИНН, ОГРН, название) и заполнение полей формы из найденных данных.
 */
import { useState } from 'react';
import { Search, ChevronDown, ChevronUp, Sparkles, RefreshCw, Check } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Checkbox } from '@/components/ui/checkbox';
import { Badge } from '@/components/ui/badge';
import { toast } from 'sonner';
import { api } from '@/lib/api';
import { Contractor } from '../types/contractor.types';

interface EnrichLookupPanelProps {
  formData: Partial<Contractor>;
  handleChange: (field: keyof Contractor, value: unknown) => void;
}

type RawData = Record<string, string | null>;

interface FieldRow {
  field: keyof Contractor;
  label: string;
  current: string | null;
  fetched: string;
  changed: boolean;
}

// Поля которые показываем в диффе (в том же порядке что и в форме)
const FIELD_META: { field: keyof Contractor; label: string }[] = [
  { field: 'name',             label: 'Краткое наименование' },
  { field: 'fullName',         label: 'Полное наименование'  },
  { field: 'inn',              label: 'ИНН'                  },
  { field: 'ogrn',             label: 'ОГРН'                 },
  { field: 'kpp',              label: 'КПП'                  },
  { field: 'legalAddress',     label: 'Юридический адрес'    },
  { field: 'director',         label: 'Руководитель (ФИО)'   },
  { field: 'directorPosition', label: 'Должность'            },
  { field: 'registrationDate', label: 'Дата регистрации'     },
  { field: 'legalForm',        label: 'Правовая форма'       },
];

export function EnrichLookupPanel({ formData, handleChange }: EnrichLookupPanelProps) {
  const { t } = useTranslation();
  const [open, setOpen]         = useState(false);
  const [query, setQuery]       = useState('');
  const [loading, setLoading]   = useState(false);
  const [source, setSource]     = useState<string | null>(null);
  const [rows, setRows]         = useState<FieldRow[]>([]);
  const [selected, setSelected] = useState<Set<keyof Contractor>>(new Set());

  // Предзаполнение запроса при открытии панели
  const handleOpen = () => {
    if (!open && !query) {
      setQuery(formData.inn || formData.ogrn || formData.name || '');
    }
    setOpen(v => !v);
  };

  const doSearch = async () => {
    if (!query.trim()) { toast.error(t('generated.vvedite_zapros')); return; }
    setLoading(true);
    setRows([]);
    setSelected(new Set());
    try {
      const result: { source: string; data: RawData } = await api.post('/enrichment/search', { query: query.trim() });
      const { source: src, data } = result;
      setSource(src);

      const newRows: FieldRow[] = [];
      for (const { field, label } of FIELD_META) {
        const fetched = data[field as string];
        if (!fetched) continue;
        const current = (formData[field] as string | null | undefined) ?? null;
        const changed = String(fetched).trim() !== String(current ?? '').trim();
        newRows.push({ field, label, current: current || null, fetched, changed });
      }

      setRows(newRows);
      // Автоматически выбираем поля которых нет или которые изменились
      setSelected(new Set(newRows.filter(r => r.changed).map(r => r.field)));

      if (!newRows.length) toast.info(t('generated.dannye_sovpadayut_ili_istochnik_nichego_'));
    } catch (e: unknown) {
      toast.error(t('generated.oshibka_poiska') + (e instanceof Error ? e.message : String(e)));
    } finally {
      setLoading(false);
    }
  };

  const toggle = (field: keyof Contractor) => {
    setSelected(prev => {
      const next = new Set(prev);
      next.has(field) ? next.delete(field) : next.add(field);
      return next;
    });
  };

  const applySelected = () => {
    let count = 0;
    for (const row of rows) {
      if (!selected.has(row.field)) continue;
      // registrationDate: конвертируем из YYYY-MM-DD если нужно
      handleChange(row.field, row.fetched);
      count++;
    }
    if (count) {
      toast.success(`Заполнено ${count} ${count === 1 ? 'поле' : count < 5 ? 'поля' : 'полей'}. Нажмите «Сохранить» чтобы применить.`);
      setRows([]);
      setSelected(new Set());
      setSource(null);
    }
  };

  const changedCount  = rows.filter(r => r.changed).length;
  const selectedCount = selected.size;

  return (
    <div className="rounded-lg border border-border overflow-hidden">
      {/* Заголовок-кнопка */}
      <button
        type="button"
        onClick={handleOpen}
        className="w-full flex items-center justify-between px-4 py-2.5 text-sm font-medium text-foreground hover:bg-muted/50 transition-colors"
      >
        <span className="flex items-center gap-2">
          <Sparkles className="w-4 h-4 text-emerald-500" />
          {t('generated.nayti_v_reestre_rusprofile_ru')}
        </span>
        {open ? <ChevronUp className="w-4 h-4 text-muted-foreground" /> : <ChevronDown className="w-4 h-4 text-muted-foreground" />}
      </button>

      {open && (
        <div className="border-t border-border p-4 space-y-4 bg-muted/20">
          {/* Строка поиска */}
          <div className="flex gap-2">
            <div className="relative flex-1">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
              <Input
                value={query}
                onChange={e => setQuery(e.target.value)}
                placeholder={t('generated.inn_ogrn_ili_nazvanie_kompanii')}
                className="pl-9"
                onKeyDown={e => e.key === 'Enter' && doSearch()}
              />
            </div>
            <Button onClick={doSearch} disabled={loading} className="shrink-0 gap-2">
              {loading ? <RefreshCw className="w-4 h-4 animate-spin" /> : <Search className="w-4 h-4" />}
              Найти
            </Button>
          </div>

          {/* Результаты */}
          {rows.length > 0 && (
            <div className="space-y-3">
              <div className="flex items-center justify-between">
                <span className="text-xs text-muted-foreground">
                  {t('generated.istochnik')} <Badge variant="outline" className="text-xs ml-1">{source}</Badge>
                  {changedCount > 0 && <span className="ml-2 text-emerald-600">· {changedCount} отличий</span>}
                </span>
                <Button
                  size="sm"
                  onClick={applySelected}
                  disabled={selectedCount === 0}
                  className="gap-1.5 bg-emerald-600 hover:bg-emerald-700 text-white h-7 text-xs"
                >
                  <Check className="w-3.5 h-3.5" />
                  Заполнить выбранные ({selectedCount})
                </Button>
              </div>

              <div className="rounded-md border border-border overflow-hidden">
                <table className="w-full text-xs">
                  <thead>
                    <tr className="border-b border-border bg-muted/40">
                      <th className="w-8 px-3 py-2"></th>
                      <th className="px-3 py-2 text-left text-muted-foreground font-medium">{t('generated.pole')}</th>
                      <th className="px-3 py-2 text-left text-muted-foreground font-medium">{t('generated.seychas')}</th>
                      <th className="px-3 py-2 text-left text-muted-foreground font-medium">{t('generated.naydeno')}</th>
                    </tr>
                  </thead>
                  <tbody>
                    {rows.map(row => (
                      <tr
                        key={String(row.field)}
                        className={`border-b border-border last:border-0 cursor-pointer hover:bg-muted/30 transition-colors ${selected.has(row.field) ? 'bg-emerald-500/5' : ''}`}
                        onClick={() => toggle(row.field)}
                      >
                        <td className="px-3 py-2" onClick={e => e.stopPropagation()}>
                          <Checkbox
                            checked={selected.has(row.field)}
                            onCheckedChange={() => toggle(row.field)}
                          />
                        </td>
                        <td className="px-3 py-2 font-medium text-muted-foreground whitespace-nowrap">{row.label}</td>
                        <td className="px-3 py-2 text-muted-foreground/60 max-w-[120px] truncate">
                          {row.current || <span className="italic">{t('generated.pusto')}</span>}
                        </td>
                        <td className={`px-3 py-2 max-w-[160px] truncate font-medium ${row.changed ? 'text-emerald-600' : 'text-foreground'}`}>
                          {row.fetched}
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </div>
          )}
        </div>
      )}
    </div>
  );
}

