/**
 * Quick action sheets for contractors
 * Sheet for creating Task, Claim, Project from contractor page
 */
import { useState, useEffect } from "react";
import { useTranslation } from "@/lib/i18n";
import { Sheet, SheetContent, SheetHeader, SheetTitle, SheetFooter } from "@/components/ui/sheet";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { toast } from "sonner";
import { api } from "@/lib/api";

interface QuickSheetProps {
  type: 'task' | 'claim' | 'project';
  open: boolean;
  onOpenChange: (open: boolean) => void;
  contractorName: string;
  contractorId?: number | string;
  statuses?: Array<{ id: string; name: string }>;
  priorities?: Array<{ id: string; name: string }>;
  projectTypes?: Array<{ id: string; name: string }>;
  caseTypes?: Array<{ id: string; name: string }>;
}

export function QuickActionSheet({
  type,
  open,
  onOpenChange,
  contractorName,
  contractorId,
  statuses = [],
  priorities = [],
  projectTypes = [],
  caseTypes = [],
}: QuickSheetProps) {
  const { t } = useTranslation();
  const [title, setTitle] = useState('');
  const [description, setDescription] = useState('');
  const [status, setStatus] = useState('');
  const [priority, setPriority] = useState('');
  const [typeValue, setTypeValue] = useState('');
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    if (open) {
      setTitle(`${type === 'task' ? 'Задача' : type === 'claim' ? 'Претензия' : 'Проект'} для ${contractorName}`);
      setDescription('');
      setStatus('');
      setPriority('');
      setTypeValue('');
    }
  }, [open, type, contractorName]);

  const handleSave = async () => {
    if (!title.trim()) {
      toast.error(t('generated.zapolnite_nazvanie'));
      return;
    }

    setSaving(true);
    try {
      if (type === 'task') {
        await api.post('/tasks', {
          title,
          description,
          status: status || 'To Do',
          priority: priority || 'Medium',
          contractorId,
          contractorName,
          assignee: '',
          dueDate: '',
        });
        toast.success(t('generated.zadacha_sozdana'));
      } else if (type === 'claim') {
        await api.post('/legal-cases', {
          title,
          description,
          type: typeValue || 'claim',
          status: status || 'new',
          contractorId,
          contractorName,
          lawyerUserId: '',
          outcome: '',
        });
        toast.success(t('generated.pretenziya_sozdana'));
      } else {
        await api.post('/projects', {
          name: title,
          description,
          status: status || 'active',
          priority: priority || 'Medium',
          type: typeValue,
          contractorId,
          contractorName,
          manager: '',
          budget: 0,
        });
        toast.success(t('generated.proekt_sozdan'));
      }
      onOpenChange(false);
    } catch (error) {
      console.error(`Error creating ${type}:`, error);
      toast.error(t('generated.oshibka_sozdaniya'));
    } finally {
      setSaving(false);
    }
  };

  const sheetTitle = type === 'task'
    ? 'Создать задачу'
    : type === 'claim'
    ? 'Создать претензию'
    : 'Создать проект';

  return (
    <Sheet open={open} onOpenChange={onOpenChange}>
      <SheetContent className="sm:max-w-md">
        <SheetHeader>
          <SheetTitle>{sheetTitle}</SheetTitle>
        </SheetHeader>
        <div className="space-y-4 py-4">
          <div className="space-y-2">
            <Label>{t('generated.nazvanie')}</Label>
            <Input
              value={title}
              onChange={(e) => setTitle(e.target.value)}
              placeholder={contractorName}
            />
          </div>

          <div className="space-y-2">
            <Label>{t('generated.opisanie')}</Label>
            <Textarea
              value={description}
              onChange={(e) => setDescription(e.target.value)}
              rows={3}
            />
          </div>

          {(type === 'task' || type === 'project') && priorities.length > 0 && (
            <div className="space-y-2">
              <Label>{t('generated.prioritet')}</Label>
              <Select value={priority} onValueChange={setPriority}>
                <SelectTrigger>
                  <SelectValue placeholder="Выберите приоритет" />
                </SelectTrigger>
                <SelectContent>
                  {priorities.map(p => (
                    <SelectItem key={p.id} value={p.id}>{p.name}</SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
          )}

          {statuses.length > 0 && (
            <div className="space-y-2">
              <Label>{t('generated.status')}</Label>
              <Select value={status} onValueChange={setStatus}>
                <SelectTrigger>
                  <SelectValue placeholder="Выберите статус" />
                </SelectTrigger>
                <SelectContent>
                  {statuses.map(s => (
                    <SelectItem key={s.id} value={s.id}>{s.name}</SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
          )}

          {type === 'claim' && caseTypes.length > 0 && (
            <div className="space-y-2">
              <Label>Тип дела</Label>
              <Select value={typeValue} onValueChange={setTypeValue}>
                <SelectTrigger>
                  <SelectValue placeholder="Выберите тип" />
                </SelectTrigger>
                <SelectContent>
                  {caseTypes.map(ct => (
                    <SelectItem key={ct.id} value={ct.id}>{ct.name}</SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
          )}

          {type === 'project' && projectTypes.length > 0 && (
            <div className="space-y-2">
              <Label>Тип проекта</Label>
              <Select value={typeValue} onValueChange={setTypeValue}>
                <SelectTrigger>
                  <SelectValue placeholder="Выберите тип" />
                </SelectTrigger>
                <SelectContent>
                  {projectTypes.map(pt => (
                    <SelectItem key={pt.id} value={pt.id}>{pt.name}</SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
          )}
        </div>

        <SheetFooter>
          <Button variant="outline" onClick={() => onOpenChange(false)}>
            {t('generated.otmena')}
          </Button>
          <Button onClick={handleSave} disabled={saving}>
            {saving ? t('generated.sohranenie') : t('generated.sozdat')}
          </Button>
        </SheetFooter>
      </SheetContent>
    </Sheet>
  );
}

