import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { UserSelect } from "@/components/shared";
import { Button } from "@/components/ui/button";
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";
import {
  Command,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
  CommandSeparator,
} from "@/components/ui/command";
import { CircleDot, Tag, FileText, Building2, Phone, ChevronsUpDown, PlusCircle, Search, RefreshCw, Undo2 } from "lucide-react";
import { useTranslation } from "@/lib/i18n";
import { Contractor } from "../../types/contractor.types";
import { MaskedInput } from "@/components/ui/MaskedInput";
import { useSettings } from "@/hooks/use-settings";
import { useCurrencies } from "@/hooks/useCurrencies";
import { Tag as TagComponent } from "@/components/ui/Tag";
import { useState, useEffect } from "react";
import { getTagColor } from "@/components/ui/color-utils";
import { DadataSuggestionsInput, type DadataSuggestion } from "@/components/ui/DadataSuggestionsInput";
import { cn } from "@/lib/utils";

interface ContractorOverviewTabProps {
  formData: Partial<Contractor>;
  handleChange: (field: keyof Contractor, value: unknown) => void;
  references?: unknown;
  _triggerUpdate?: number;
}

interface ReferenceOption {
  id: string;
  name: string;
  color?: string;
}

export function ContractorOverviewTab({ formData, handleChange, references, _triggerUpdate }: ContractorOverviewTabProps) {
  const { t } = useTranslation();
  const { data: currencies = [] } = useCurrencies();
  const { getStatusesByModule, getTagsByModule, getRelationshipTypesByModule, getContractorTypesByModule, getLegalFormsByModule } = useSettings();

  const [statuses, setStatuses] = useState<ReferenceOption[]>([]);
  const [availableTags, setAvailableTags] = useState<ReferenceOption[]>([]);
  const [relationshipTypes, setRelationshipTypes] = useState<ReferenceOption[]>([]);
  const [contractorTypesList, setContractorTypesList] = useState<ReferenceOption[]>([]);
  const [legalFormsList, setLegalFormsList] = useState<ReferenceOption[]>([]);
  const [tagComboOpen, setTagComboOpen] = useState(false);
  const [tagQuery, setTagQuery] = useState('');
  const [dadataQuery, setDadataQuery] = useState('');

  // Для режима редактирования - храним оригинальные данные
  const [originalData, setOriginalData] = useState<Partial<Contractor> | null>(null);
  const [isRefreshing, setIsRefreshing] = useState(false);
  const [hasChanges, setHasChanges] = useState(false);

  // Определяем, редактируем ли мы существующего контрагента
  const isEditMode = formData.id !== undefined && formData.id !== null && formData.id !== 0;

  // Сохраняем оригинальные данные при монтировании (для редактирования)
  useEffect(() => {
    if (isEditMode && !originalData) {
      setOriginalData({ ...formData });
    }
  }, [isEditMode, formData.id]); // eslint-disable-line react-hooks/exhaustive-deps

  // Обновление данных из ЕГРЮЛ по ИНН
  const handleRefreshFromEgrul = async () => {
    if (!formData.inn || formData.inn.length < 10) {
      alert('⚠️ Сначала введите ИНН организации (минимум 10 цифр)');
      return;
    }

    if (!confirm('🔄 Обновить данные из ЕГРЮЛ?\n\nТекущие данные будут заменены на актуальные из налоговой.\nВы сможете отменить изменения до сохранения.')) {
      return;
    }

    setIsRefreshing(true);

    try {
      const response = await fetch('http://localhost:5001/api/dadata/suggest/party', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ query: formData.inn, count: 1 }),
      });

      const result = await response.json();

      if (!result.suggestions || result.suggestions.length === 0) {
        alert('❌ Организация с ИНН ' + formData.inn + ' не найдена в ЕГРЮЛ');
        return;
      }

      const suggestion = result.suggestions[0];
      const data = suggestion.data;

      console.log('🔄 Обновление данных из ЕГРЮЛ:', suggestion.value);
      console.log('📋 Данные DaData:', data);

      // Сохраняем текущие данные перед обновлением (если ещё не сохранены)
      if (!hasChanges && originalData) {
        setOriginalData({ ...originalData });
      }

      // Заполняем все поля
      handleChange('name', suggestion.value);
      handleChange('fullName', data.name.full_with_opf);
      handleChange('inn', data.inn);
      handleChange('kpp', data.kpp || '');
      handleChange('ogrn', data.ogrn);

      if (data.ogrn_date) {
        handleChange('registrationDate', new Date(data.ogrn_date).toISOString().split('T')[0]);
      }

      handleChange('legalAddress', data.address?.unrestricted_value || data.address?.value || '');

      if (data.type === 'LEGAL' && data.management) {
        handleChange('director', data.management.name);
        handleChange('directorPosition', data.management.post || 'Руководитель');
      } else if (data.type === 'INDIVIDUAL' && data.fio) {
        const fio = `${data.fio.surname || ''} ${data.fio.name || ''}${data.fio.patronymic ? ' ' + data.fio.patronymic : ''}`.trim();
        handleChange('director', fio);
        handleChange('directorPosition', 'Индивидуальный предприниматель');
      }

      if (data.okved) handleChange('okved', data.okved);

      if (data.type === 'INDIVIDUAL') {
        handleChange('legalForm', 'ip');
        handleChange('type', 'individual');
      } else {
        handleChange('type', 'legal');
        if (data.opf?.code) {
          const opfCode = data.opf.code;
          if (opfCode.startsWith('6') || opfCode.startsWith('1')) handleChange('legalForm', 'ooo');
          else if (opfCode.startsWith('7')) handleChange('legalForm', 'ip');
        }
      }

      if (data.state?.status === 'ACTIVE') {
        handleChange('status', 'active');
        handleChange('isActive', true);
      } else if (data.state?.status === 'LIQUIDATED') {
        handleChange('status', 'inactive');
        handleChange('isActive', false);
      }

      if (data.capital?.value) {
        handleChange('authorizedCapital', data.capital.value);
      }

      if (data.emails && data.emails.length > 0) {
        handleChange('email', data.emails[0]);
      }

      setHasChanges(true);
      alert('✅ Данные обновлены из ЕГРЮЛ!\n\nОрганизация: ' + suggestion.value + '\n\nНажмите "Отменить" если нужно вернуть старые данные.');

    } catch (err: any) {
      console.error('❌ Ошибка обновления:', err);
      alert('❌ Ошибка при обновлении: ' + (err.message || 'Неизвестная ошибка'));
    } finally {
      setIsRefreshing(false);
    }
  };

  // Отмена изменений (возврат к оригинальным данным)
  const handleRevertChanges = () => {
    if (!originalData) return;

    if (!confirm('↩️ Отменить все изменения?\n\nДанные будут возвращены к состоянию до обновления.')) {
      return;
    }

    // Восстанавливаем все поля из оригинальных данных
    Object.keys(originalData).forEach(key => {
      handleChange(key as keyof Contractor, originalData[key as keyof Contractor]);
    });

    setHasChanges(false);
    console.log('✅ Данные возвращены к оригинальным');
  };

  // Re-calculate when references update trigger changes
  useEffect(() => {
    setStatuses(getStatusesByModule('contractors'));
    setAvailableTags(getTagsByModule('contractors'));
    setRelationshipTypes(getRelationshipTypesByModule('contractors'));
    setContractorTypesList(getContractorTypesByModule('contractors'));
    setLegalFormsList(getLegalFormsByModule('contractors'));
  }, [getStatusesByModule, getTagsByModule, getRelationshipTypesByModule, getContractorTypesByModule, getLegalFormsByModule, _triggerUpdate]);

  // Обработка выбора организации из DaData
  const handleDadataSelect = (suggestion: DadataSuggestion) => {
    const data = suggestion.data;

    console.log('🎯 Выбрана организация:', suggestion.value);
    console.log('📋 Полные данные DaData:', data);

    // === Основные поля ===
    handleChange('name', suggestion.value);
    handleChange('fullName', data.name.full_with_opf);

    // === Реквизиты ===
    if (data.inn) handleChange('inn', data.inn);
    if (data.kpp) handleChange('kpp', data.kpp);
    if (data.ogrn) handleChange('ogrn', data.ogrn);

    // Дата регистрации (из ОГРН)
    if (data.ogrn_date) {
      const regDate = new Date(data.ogrn_date).toISOString().split('T')[0];
      handleChange('registrationDate', regDate);
    }

    // === Адрес ===
    handleChange('legalAddress', data.address?.unrestricted_value || data.address?.value || '');

    // === Руководитель ===
    console.log('👤 Проверка руководителя:');
    console.log('  - data.type:', data.type);
    console.log('  - data.management:', data.management);
    console.log('  - data.fio:', data.fio);

    if (data.type === 'LEGAL') {
      if (data.management && data.management.name) {
        handleChange('director', data.management.name);
        handleChange('directorPosition', data.management.post || 'Руководитель');
        console.log('  ✅ Заполнено из data.management:', data.management.name);
      } else {
        console.log('  ⚠️ data.management отсутствует или пустой');
      }
    } else if (data.type === 'INDIVIDUAL') {
      if (data.fio) {
        const fio = `${data.fio.surname || ''} ${data.fio.name || ''}${data.fio.patronymic ? ' ' + data.fio.patronymic : ''}`.trim();
        handleChange('director', fio);
        handleChange('directorPosition', 'Индивидуальный предприниматель');
        console.log('  ✅ Заполнено из data.fio:', fio);
      } else {
        console.log('  ⚠️ data.fio отсутствует');
      }
    } else {
      console.log('  ⚠️ Неизвестный тип организации:', data.type);
    }

    // === ОКВЭД ===
    if (data.okved) handleChange('okved', data.okved);

    // === Тип и правовая форма ===
    if (data.type === 'INDIVIDUAL') {
      handleChange('legalForm', 'ip');
      handleChange('type', 'individual');
    } else {
      handleChange('type', 'legal');
      // Определяем правовую форму по ОКОПФ
      if (data.opf?.code) {
        const opfCode = data.opf.code;
        if (opfCode.startsWith('6')) handleChange('legalForm', 'ooo'); // ООО
        else if (opfCode.startsWith('1')) handleChange('legalForm', 'ooo'); // АО
        else if (opfCode.startsWith('7')) handleChange('legalForm', 'ip'); // ИП
      }
    }

    // === Статус ===
    if (data.state?.status === 'ACTIVE') {
      handleChange('status', 'active');
      handleChange('isActive', true);
    } else if (data.state?.status === 'LIQUIDATED') {
      handleChange('status', 'inactive');
      handleChange('isActive', false);
    } else if (data.state?.status === 'BANKRUPT') {
      handleChange('status', 'paused');
      handleChange('isActive', false);
    }

    // === Дополнительные поля (если есть в модели) ===
    // ОКПО
    if (data.okpo) {
      console.log('ℹ️ ОКПО:', data.okpo, '(нет поля в модели)');
    }

    // Уставной капитал
    if (data.capital?.value) {
      handleChange('authorizedCapital', data.capital.value);
      console.log('💰 Уставной капитал:', data.capital.value);
    }

    // Телефоны компании
    if (data.phones && data.phones.length > 0) {
      const phone = data.phones[0];
      const phoneValue = phone.source || phone.value || '';
      handleChange('phone', phoneValue);
      console.log('📞 Телефон компании:', phoneValue);
    } else {
      handleChange('phone', '');
      console.log('⚠️ Телефон не предоставлен');
    }

    // Email компании
    if (data.emails && data.emails.length > 0) {
      handleChange('email', data.emails[0]);
      console.log('📧 Email компании:', data.emails[0]);
    }

    // === Создаем контакт с руководителем ===
    const contactPerson: any = {
      id: `contact_${Date.now()}`,
      isPrimary: true,
    };

    let hasContactData = false;

    // ФИО и должность руководителя
    if (data.type === 'LEGAL' && data.management?.name) {
      contactPerson.name = data.management.name;
      contactPerson.position = data.management.post || 'Руководитель';
      hasContactData = true;
      console.log('👤 Руководитель:', contactPerson.name);
    } else if (data.type === 'INDIVIDUAL' && data.fio) {
      contactPerson.name = `${data.fio.surname || ''} ${data.fio.name || ''}${data.fio.patronymic ? ' ' + data.fio.patronymic : ''}`.trim();
      contactPerson.position = 'Индивидуальный предприниматель';
      hasContactData = true;
      console.log('👤 ИП:', contactPerson.name);
    }

    // Телефон контакта
    if (data.phones && data.phones.length > 0) {
      contactPerson.phone = data.phones[0].source || data.phones[0].value || '';
      hasContactData = true;
    }

    // Email контакта
    if (data.emails && data.emails.length > 0) {
      contactPerson.email = data.emails[0];
      hasContactData = true;
    }

    // Добавляем контакт, если есть данные и контакт с таким именем ещё не существует
    if (hasContactData && contactPerson.name) {
      const currentContacts = formData.contacts || [];
      const existingContact = currentContacts?.find(c => c?.name === contactPerson.name);
      if (!existingContact) {
        handleChange('contacts', [...currentContacts, contactPerson]);
        console.log('✅ Контакт добавлен:', contactPerson);
      } else {
        console.log('ℹ️ Контакт уже существует:', contactPerson.name);
      }
    }

    console.log('✅ Заполнение завершено!');
  };

  const handleAddTag = (tagId: string) => {
    const tag = availableTags.find(t => t.id === tagId);
    if (tag) {
        const currentTags = formData.tags || [];
        if (!currentTags.includes(tag.name)) {
            handleChange("tags", [...currentTags, tag.name]);
        }
    }
  };

  const handleAddCustomTag = (tagName: string) => {
    const currentTags = formData.tags || [];
    if (tagName && !currentTags.includes(tagName)) {
      handleChange("tags", [...currentTags, tagName]);
    }
  };

  const handleRemoveTag = (tagName: string) => {
      const currentTags = formData.tags || [];
      handleChange("tags", currentTags.filter(t => t !== tagName));
  };

  const filteredAvailableTags = availableTags.filter(
    tag => !(formData.tags || []).includes(tag.name)
  );

  return (
    <div className="space-y-6">
      {/* Поиск по DaData - ТОЛЬКО для новых контрагентов */}
      {!isEditMode && (
        <div className="rounded-lg border bg-gradient-to-r from-blue-50 to-indigo-50 p-4 space-y-3">
          <div className="flex items-center gap-2 text-sm font-medium text-foreground">
            <Search className="w-4 h-4 text-blue-600" />
            Быстрый поиск организации
          </div>
          <DadataSuggestionsInput
            value={dadataQuery}
            onChange={(v) => setDadataQuery(v)}
            onSelect={handleDadataSelect}
            placeholder="Введите ИНН, название или адрес организации..."
            filters={{
              status: ['ACTIVE'],
            }}
          />
          <p className="text-xs text-muted-foreground">
            💡 Введите ИНН или название — данные заполнятся автоматически из ЕГРЮЛ
          </p>
        </div>
      )}

      {/* Кнопки обновления - ТОЛЬКО для редактирования */}
      {isEditMode && (
        <div className="flex items-center gap-2 p-3 rounded-lg border bg-muted/30">
          <Button
            variant="outline"
            size="sm"
            onClick={handleRefreshFromEgrul}
            disabled={isRefreshing || !formData.inn}
            className="gap-1"
          >
            <RefreshCw className={cn("w-4 h-4", isRefreshing && "animate-spin")} />
            {isRefreshing ? 'Обновление...' : 'Обновить из ЕГРЮЛ'}
          </Button>

          {hasChanges && (
            <Button
              variant="outline"
              size="sm"
              onClick={handleRevertChanges}
              className="gap-1 text-amber-600 hover:text-amber-700"
            >
              <Undo2 className="w-4 h-4" />
              Отменить изменения
            </Button>
          )}

          <span className="text-xs text-muted-foreground ml-auto">
            {formData.inn ? `ИНН: ${formData.inn}` : '⚠️ Введите ИНН для обновления'}
          </span>
        </div>
      )}

      {/* Общая информация */}
      <div className="space-y-4">
        <div className="flex items-center gap-2 text-sm font-medium text-foreground">
          <CircleDot className="w-4 h-4 text-primary" />
          {t('contractor_sheet.section.general')}
        </div>

        <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
