              {t('contractor_sheet.field.status')}
            </Label>
            <Select 
              value={formData.status ?? ''} 
              onValueChange={(v) => handleChange("status", v)}
            >
              <SelectTrigger>
                <SelectValue placeholder={t('generated.vyberite_status')} />
              </SelectTrigger>
              <SelectContent>
                {statuses.length > 0 ? (
                    statuses.map(status => (
                        <SelectItem key={status.id} value={status.id}>
