            <div className="flex flex-wrap gap-2 mb-2">
                {formData.tags?.map(tagName => {
                    const color = getTagColor(tagName, availableTags);
                    return (
                        <TagComponent
                            key={tagName}
                            color={color}
                            clickable={true}
                            onClick={() => handleRemoveTag(tagName)}
                            className="hover:bg-destructive/10 hover:text-destructive"
                        >
                            {tagName} ×
                        </TagComponent>
                    );
                })}
            </div>

            <Popover open={tagComboOpen} onOpenChange={setTagComboOpen}>
              <PopoverTrigger asChild>
                <Button
                  variant="outline"
                  role="combobox"
                  aria-expanded={tagComboOpen}
                  className="w-full justify-between font-normal h-9 text-muted-foreground"
                >
                  <span className="truncate">{t('contractor_sheet.placeholder.add_tag')}</span>
                  <ChevronsUpDown className="ml-2 h-4 w-4 shrink-0 opacity-50" />
                </Button>
              </PopoverTrigger>
              <PopoverContent className="w-[--radix-popover-trigger-width] p-0" align="start">
                <Command>
                  <CommandInput
                    placeholder={t('contractor_sheet.placeholder.search_tag')}
                    value={tagQuery}
                    onValueChange={setTagQuery}
                  />
                  <CommandList>
                    <CommandEmpty className="py-2 text-sm text-muted-foreground text-center">
                      {t('contractor_sheet.placeholder.no_tags_found')}
                    </CommandEmpty>
                    <CommandGroup>
                      {filteredAvailableTags
                        .filter(tag =>
                          !tagQuery.trim() ||
                          tag.name.toLowerCase().includes(tagQuery.toLowerCase())
                        )
                        .map(tag => (
                          <CommandItem
                            key={tag.id}
                            value={tag.name}
                            onSelect={() => {
                              handleAddTag(tag.id);
                              setTagComboOpen(false);
                              setTagQuery('');
                            }}
                          >
                            <div
                              className="w-2 h-2 rounded-full mr-2 flex-shrink-0"
                              style={{ backgroundColor: getTagColor(tag.name, availableTags) }}
                            />
                            {tag.name}
                          </CommandItem>
                        ))
                      }
                    </CommandGroup>
                    {tagQuery.trim() &&
                      !availableTags.some(
                        t => t.name.toLowerCase() === tagQuery.trim().toLowerCase()
                      ) && (
                      <>
                        <CommandSeparator />
                        <CommandGroup>
                          <CommandItem
                            value={`__create__${tagQuery}`}
                            onSelect={() => {
                              handleAddCustomTag(tagQuery.trim());
                              setTagComboOpen(false);
                              setTagQuery('');
                            }}
                          >
                            <PlusCircle className="w-4 h-4 mr-2 text-muted-foreground" />
                            {t('contractor_sheet.action.add_custom_tag', { tag: tagQuery.trim() })}
                          </CommandItem>
                        </CommandGroup>
                      </>
                    )}
                  </CommandList>
                </Command>
              </PopoverContent>
            </Popover>
          </div>

          <div className="space-y-2">
            <div className="flex items-center gap-2 text-sm font-medium text-foreground">
              <FileText className="w-4 h-4 text-primary" />
              {t('contractor_sheet.section.notes')}
            </div>
            <Textarea 
              placeholder={t('contractor_sheet.placeholder.notes')}
              value={formData.notes || ""}
              onChange={(e) => handleChange("notes", e.target.value)}
              rows={3}
            />
          </div>
        </div>
      </div>
    </div>
  );
}

import { useState, useMemo, useCallback } from "react";
import { usePersistedTab } from "@/hooks/usePersistedTab";
import { Contractor, LegalForm } from "../types/contractor.types";

interface UseContractorFiltersReturn {
  activeTab: string;
  setActiveTab: (tab: string) => void;
  statusFilter: string;
  setStatusFilter: (status: string) => void;
  searchQuery: string;
  setSearchQuery: (query: string) => void;
  filteredContractors: Contractor[];
  resetFilters: () => void;
}

interface UseContractorFiltersProps {
  contractors: Contractor[];
  initialTab?: string;
  initialStatus?: string;
}

export function useContractorFilters({
  contractors,
  initialTab = "all",
  initialStatus = "all",
}: UseContractorFiltersProps): UseContractorFiltersReturn {
  const [activeTab, setActiveTab] = usePersistedTab("tab:contractorFilters", initialTab);
  const [statusFilter, setStatusFilter] = useState(initialStatus);
  const [searchQuery, setSearchQuery] = useState("");

  const filteredContractors = useMemo(() => {
    return contractors.filter((contractor) => {
      const matchesSearch = contractor.name
        .toLowerCase()
        .includes(searchQuery.toLowerCase());
      const matchesStatus =
        statusFilter === "all" || contractor.status === statusFilter;

      let matchesType = true;
      if (activeTab !== "all") {
        matchesType = contractor.legalForm === (activeTab as LegalForm);
      }

      return matchesSearch && matchesStatus && matchesType;
    });
  }, [contractors, searchQuery, statusFilter, activeTab]);

  const resetFilters = useCallback(() => {
    setActiveTab(initialTab);
    setStatusFilter(initialStatus);
    setSearchQuery("");
  }, [initialTab, initialStatus]);

  return {
    activeTab,
    setActiveTab,
    statusFilter,
    setStatusFilter,
    searchQuery,
    setSearchQuery,
    filteredContractors,
    resetFilters,
  };
}

import { useState, useCallback, useEffect } from "react";
import { Contractor } from "../types/contractor.types";

interface UseContractorFormProps {
  initialContractor?: Contractor | null;
  initialName?: string;
  onSave?: (contractor: Contractor) => void;
}

interface UseContractorFormReturn {
  formData: Partial<Contractor>;
  setFormData: React.Dispatch<React.SetStateAction<Partial<Contractor>>>;
  handleChange: (field: keyof Contractor, value: unknown) => void;
  handleSubmit: () => Contractor;
  isValid: boolean;
}

const isContractorStatus = (value: unknown): value is Contractor["status"] => {
  return value === "active" || value === "pending" || value === "vip" || value === "paused";
};

export function useContractorForm({
  initialContractor,
  initialName,
  onSave,
}: UseContractorFormProps = {}): UseContractorFormReturn {
  const [formData, setFormData] = useState<Partial<Contractor>>({
    status: "active",
    type: "client",
    currency: "RUB",
    legalForm: "ooo",
    bankAccounts: [],
    contacts: [],
    tags: [],
  });

  useEffect(() => {
    if (initialContractor) {
      // При редактировании сохраняем ВСЕ существующие поля
      setFormData({
        ...initialContractor,
        // Убеждаемся, что обязательные поля имеют значения
        status: initialContractor.status || "active",
        tags: initialContractor.tags || [],
        bankAccounts: initialContractor.bankAccounts || [],
        contacts: initialContractor.contacts || [],
      });
    } else {
      // При создании нового контрагента используем значения по умолчанию
      setFormData({
        name: initialName ?? '',
        status: "active",
        type: "client",
        currency: "RUB",
        legalForm: "ooo",
        bankAccounts: [],
        contacts: [],
        tags: [],
      });
    }
  }, [initialContractor, initialName]);

  const handleChange = useCallback((field: keyof Contractor, value: unknown) => {
    setFormData((prev) => { 
      const newData = { ...prev, [field]: value };

      // Автоматически заполняем legalEntityType на основе legalForm
      if (field === 'legalForm') {
        const lf = String(value);
        if (lf === 'ip') newData.legalEntityType = 'individual';
        else if (lf === 'self' || lf === 'private') newData.legalEntityType = 'private';
        else if (lf === 'foreign') newData.legalEntityType = 'foreign';
        else newData.legalEntityType = 'legal'; // ooo, pao, ao, ano, np, gup, mup и т.д.
      }

      return newData;
    });
  }, []);

  const handleSubmit = useCallback((): Contractor => {
    const contractor: Contractor = {
      ...formData,
      id: initialContractor?.id || Math.floor(Math.random() * 10000),
      name: formData.name || "",
      tags: formData.tags || [],
      status: isContractorStatus(formData.status) ? formData.status : "active",
      phone: formData.phone || "—",
      manager: formData.manager || "",
    } as Contractor;

    if (onSave) {
      onSave(contractor);
    }

    return contractor;
  }, [formData, initialContractor, onSave]);

  const isValid = Boolean(formData.name && formData.name.trim() !== "");

  return {
    formData,
    setFormData,
    handleChange,
    handleSubmit,
    isValid,
  };
}

