import { useState, useEffect, useCallback } from "react";
import { toast } from "sonner";
import { useTranslation } from "@/lib/i18n";
import { Contractor, ReferenceData } from "../types/contractor.types";
import { CreateContractorRequest } from "../types/api.types";
import { contractorService } from "../api/contractorService";

interface UseContractorsReturn {
  contractors: Contractor[];
  loading: boolean;
  error: Error | null;
  fetchContractors: () => Promise<void>;
  createContractor: (data: Partial<Contractor>) => Promise<Contractor | null>;
  updateContractor: (id: number, data: Partial<Contractor>) => Promise<Contractor | null>;
  deleteContractor: (id: number) => Promise<boolean>;
  deleteContractors: (ids: number[]) => Promise<boolean>;
}

export function useContractors(): UseContractorsReturn {
  const { t } = useTranslation();
  const [contractors, setContractors] = useState<Contractor[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<Error | null>(null);

  const fetchContractors = useCallback(async () => {
    try {
      setLoading(true);
      const data = await contractorService.getAll();
      setContractors(data);
      setError(null);
    } catch (err) {
      setError(err instanceof Error ? err : new Error(String(err)));
      toast.error(t("general.toast.error.contractor_load"));
    } finally {
      setLoading(false);
    }
  }, [t]);

  const createContractor = useCallback(
    async (data: Partial<Contractor>): Promise<Contractor | null> => {
      try {
        const newContractor = await contractorService.create(data as unknown as CreateContractorRequest);
        setContractors((prev) => [newContractor, ...prev]);
        toast.success(t("general.toast.success.contractor_created"));
        return newContractor;
      } catch (err) {
        toast.error(t("general.toast.error.contractor_save"));
        return null;
      }
    },
    [t]
  );

  const updateContractor = useCallback(
    async (id: number, data: Partial<Contractor>): Promise<Contractor | null> => {
      try {
        const updatedContractor = await contractorService.update(id, { id, ...data } as unknown as import('../types/api.types').UpdateContractorRequest);
        setContractors((prev) =>
          prev.map((c) => (c.id === id ? updatedContractor : c))
        );
        toast.success(t("general.toast.success.contractor_updated"));
        return updatedContractor;
      } catch (err) {
        toast.error(t("general.toast.error.contractor_save"));
        return null;
      }
    },
    [t]
  );

  const deleteContractor = useCallback(
    async (id: number): Promise<boolean> => {
      try {
        await contractorService.delete(id);
        setContractors((prev) => prev.filter((c) => c.id !== id));
        toast.success(t("general.toast.success.contractor_deleted"));
        return true;
      } catch (err) {
        toast.error(t("general.toast.error.contractor_delete"));
        return false;
      }
    },
    [t]
  );

  const deleteContractors = useCallback(
    async (ids: number[]): Promise<boolean> => {
      try {
        const promises = ids.map((id) => contractorService.delete(id));
        await Promise.all(promises);
        setContractors((prev) => prev.filter((c) => !ids.includes(c.id)));
        toast.success(
          t("general.toast.success.contractors_deleted").replace("{0}", ids.length.toString())
        );
        return true;
      } catch (err) {
        toast.error(t("general.toast.error.contractors_bulk_delete"));
        return false;
      }
    },
    [t]
  );

  useEffect(() => {
    fetchContractors();
  }, [fetchContractors]);

  return {
    contractors,
    loading,
    error,
    fetchContractors,
    createContractor,
    updateContractor,
    deleteContractor,
    deleteContractors,
  };
}

interface UseContractorReferencesReturn {
  references: ReferenceData;
  loading: boolean;
  error: Error | null;
  refreshReferences: () => Promise<void>;
}

export function useContractorReferences(): UseContractorReferencesReturn {
  const [references, setReferences] = useState<ReferenceData>({
    projectStatuses: [],
    priorities: [],
    managers: [],
    contractorTypes: [],
    legalForms: [],
  });
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<Error | null>(null);

  const refreshReferences = useCallback(async () => {
    try {
      setLoading(true);
      const data = await contractorService.getReferences();
      setReferences(data);
      setError(null);
    } catch (err) {
      setError(err instanceof Error ? err : new Error(String(err)));
    } finally {
      setLoading(false);
    }
  }, []);

