import { useState, useEffect, useCallback } from "react";
import { toast } from "sonner";
import { useTranslation } from "@/lib/i18n";
import { Contractor, ReferenceData } from "../types/contractor.types";
import { CreateContractorRequest } from "../types/api.types";
import { contractorService } from "../api/contractorService";

interface UseContractorsDataReturn {
  contractors: Contractor[];
  references: ReferenceData;
  loading: boolean;
  error: Error | null;
  refreshData: () => Promise<void>;
  createContractor: (data: Partial<Contractor>) => Promise<Contractor | null>;
  updateContractor: (id: number, data: Partial<Contractor>) => Promise<Contractor | null>;
  deleteContractor: (id: number) => Promise<boolean>;
  deleteContractors: (ids: number[]) => Promise<boolean>;
}

export function useContractorsData(): UseContractorsDataReturn {
  const { t } = useTranslation();
  const [contractors, setContractors] = useState<Contractor[]>([]);
  const [references, setReferences] = useState<ReferenceData>({
    projectStatuses: [],
    priorities: [],
    managers: [],
    contractorTypes: [],
    legalForms: [],
  });
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<Error | null>(null);

  const refreshData = useCallback(async () => {
    try {
      setLoading(true);
      const [contractorsData, referencesData] = await Promise.all([
        contractorService.getAll(),
        contractorService.getReferences(),
      ]);
      setContractors(contractorsData);
      setReferences(referencesData);
      setError(null);
    } catch (err) {
      setError(err instanceof Error ? err : new Error(String(err)));
      toast.error(t("general.toast.error.contractor_load"));
    } finally {
      setLoading(false);
    }
  }, [t]);

  const createContractor = useCallback(
    async (data: Partial<Contractor>): Promise<Contractor | null> => {
      try {
        const newContractor = await contractorService.create(data as unknown as CreateContractorRequest);
        setContractors((prev) => [newContractor, ...prev]);
        toast.success(t("general.toast.success.contractor_created"));
        return newContractor;
      } catch (err) {
        toast.error(t("general.toast.error.contractor_save"));
        return null;
      }
    },
    [t]
  );

  const updateContractor = useCallback(
    async (id: number, data: Partial<Contractor>): Promise<Contractor | null> => {
      try {
        const updatedContractor = await contractorService.update(id, { id, ...data } as unknown as import('../types/api.types').UpdateContractorRequest);
        setContractors((prev) =>
          prev.map((c) => (c.id === id ? updatedContractor : c))
        );
        toast.success(t("general.toast.success.contractor_updated"));
        return updatedContractor;
      } catch (err) {
        toast.error(t("general.toast.error.contractor_save"));
        return null;
      }
    },
    [t]
  );

  const deleteContractor = useCallback(
    async (id: number): Promise<boolean> => {
      try {
        await contractorService.delete(id);
        setContractors((prev) => prev.filter((c) => c.id !== id));
        toast.success(t("general.toast.success.contractor_deleted"));
        return true;
      } catch (err) {
        toast.error(t("general.toast.error.contractor_delete"));
        return false;
      }
    },
    [t]
  );

  const deleteContractors = useCallback(
    async (ids: number[]): Promise<boolean> => {
      try {
        const promises = ids.map((id) => contractorService.delete(id));
        await Promise.all(promises);
        setContractors((prev) => prev.filter((c) => !ids.includes(c.id)));
        toast.success(
          t("general.toast.success.contractors_deleted").replace("{0}", ids.length.toString())
        );
        return true;
      } catch (err) {
        toast.error(t("general.toast.error.contractors_bulk_delete"));
        return false;
      }
    },
    [t]
  );

  useEffect(() => {
    refreshData();

    const onRefs = (e: Event) => {
      const detail = (e as CustomEvent<ReferenceData>).detail;
      if (detail) setReferences(detail);
    };
    window.addEventListener("references:updated", onRefs);
    return () => window.removeEventListener("references:updated", onRefs);
  }, [refreshData]);

  return {
    contractors,
    references,
    loading,
    error,
    refreshData,
    createContractor,
    updateContractor,
    deleteContractor,
    deleteContractors,
  };
}

import { useState, useMemo, useCallback, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import { toast } from "sonner";
import { useValidationToast } from "@/components/shared";
import {
  Users, Building2, UserCheck,
} from "lucide-react";
import { api } from "@/lib/api";
import { parseRowsPerPage } from "@/lib/utils";
import { useTranslation } from "@/lib/i18n";
import { useSettings } from "@/hooks/use-settings";
import { useDataTable } from "@/hooks/useDataTable";
import { usePersistedTab } from "@/hooks/usePersistedTab";
import { useContractorsData, useContractorActions } from "../hooks";
import { Contractor } from "../types/contractor.types";
import type { TaskReference, LegalCaseReference, ProjectReference } from "@/lib/types";
import { useBulkSelection } from "@/hooks/useBulkSelection";

export interface QuickSheetState {
  isOpen: boolean;
  contractorName: string;
  contractorId?: number | string;
}

const initialSheetState: QuickSheetState = {
  isOpen: false,
  contractorName: "",
  contractorId: undefined,
};

export function useContractorsPage() {
  const { t } = useTranslation();
  const { getStatusesByModule, getTagsByModule, legalForms, getRelationshipTypesByModule, relationshipTypes } = useSettings();
  const { validate } = useValidationToast();
  const navigate = useNavigate();

  // Quick action sheets state
  const [taskSheet, setTaskSheet] = useState<QuickSheetState>(initialSheetState);
  const [claimSheet, setClaimSheet] = useState<QuickSheetState>(initialSheetState);
  const [projectSheet, setProjectSheet] = useState<QuickSheetState>(initialSheetState);
  const [allContractors, setAllContractors] = useState<Contractor[]>([]);

  const loadContractors = useCallback(async () => {
    try {
      const data = await api.get("/contractors");
      setAllContractors(data || []);
    } catch {
      setAllContractors([]);
    }
  }, []);

  useEffect(() => {
    loadContractors();
  }, [loadContractors]);

  // Quick action save handlers
  const handleSaveQuickTask = async (task: TaskReference, contractorName: string): Promise<boolean> => {
    try {
      // Validate required title
      if (!validate([{ name: 'title', label: t('common.name'), value: task.title }])) {
        return false;
      }

      // Check if meeting requires date
      if (task.title.includes(t('contractors.messages.meeting_keyword')) || task.description?.includes(t('contractors.messages.meeting_keyword'))) {
        if (!validate([{ name: 'dueDate', label: t('common.date'), value: task.dueDate }])) {
          return false;
        }
      }
      await api.post("/tasks", { ...task, project: task.project || "General" });
      toast.success(t("general.toast.success.task_created"));
      setTaskSheet(initialSheetState);
      return true;
    } catch {
      toast.error(t("general.toast.error.task_save"));
      return false;
    }
  };

  const handleSaveClaim = async (claim: LegalCaseReference, contractorName: string): Promise<boolean> => {
    try {
      if (!validate([{ name: 'title', label: t('common.name'), value: claim.title }])) {
        return false;
      }
      await api.post("/legal-cases", { ...claim, type: "claim", status: "claim_draft" });
      toast.success(t("general.toast.success.claim_created", [contractorName]));
      setClaimSheet(initialSheetState);
      return true;
    } catch {
      toast.error(t("general.toast.error.claim_create"));
      return false;
    }
  };

  const handleSaveProject = async (project: ProjectReference, contractorName: string): Promise<boolean> => {
    try {
      if (!validate([{ name: 'name', label: t('common.name'), value: project.name }])) {
        return false;
      }
      await api.post("/projects", { ...project, status: "new" });
      toast.success(t("general.toast.success.project_created"));
      setProjectSheet(initialSheetState);
      return true;
    } catch {
      toast.error(t("general.toast.error.project_save"));
      return false;
    }
  };

  // Data management
  const {
    contractors,
    references,
    loading,
    createContractor,
    updateContractor,
    deleteContractor,
    deleteContractors,
    refreshData,
  } = useContractorsData();

  // Contractor sheet
  const [contractorSheet, setContractorSheet] = useState<{
    isOpen: boolean;
    contractorId?: number | null;
  }>({ isOpen: false, contractorId: null });

  const openContractorSheet = (contractorId?: number | null) =>
    setContractorSheet({ isOpen: true, contractorId: contractorId ?? null });
  const closeContractorSheet = () =>
    setContractorSheet({ isOpen: false, contractorId: null });

  // Quick actions
  const { handleQuickAction } = useContractorActions({
    contractors,
    onCreateTask: (contractorName, contractorId) => {
      setTaskSheet({ isOpen: true, contractorName, contractorId });
    },
    onCreateClaim: (contractorName, contractorId) => {
      setClaimSheet({ isOpen: true, contractorName, contractorId });
    },
    onCreateProject: (contractorName, contractorId) => {
      setProjectSheet({ isOpen: true, contractorName, contractorId });
    },
  });

  // Table configuration
  const {
    sortConfig,
    visibleColumns,
    columnOrder,
    tabsConfig,
    setTabsConfig,
    savedTabVisibilityRef,
    handleSort,
    toggleSelection,
    toggleAllSelection,
    clearSelection: clearTableSelection,
    moveTab,
    moveColumn,
    reorderColumn,
    reorderTab,
    toggleColumnVisibility,
    rowsPerPage,
    setRowsPerPage,
    currentPage,
    setCurrentPage,
    columnWidths,
    setColumnWidth,
  } = useDataTable<Contractor>({
    initialData: [],
    initialColumns: {
      name: true,
      tags: true,
      type: true,
      status: true,
      phone: true,
      manager: true,
    },
    initialTabs: [
      { id: "all", label: "contractors.tabs.all", icon: Users, visible: true },
    ],
    storageKey: "contractors-table",
  });

  // Build dynamic tabs from legal form groups
  useEffect(() => {
    console.log('🔍 legalForms:', legalForms);
    console.log('🔍 legalForms length:', legalForms.length);
    console.log('🔍 relationshipTypes:', relationshipTypes);

    // Создаём вкладки из ГРУПП правовых форм (только если showAsTab = true)
    // legalForms теперь содержит groupName и groupShowAsTab из БД (после camelCase преобразования)
    const groupTabs: Array<{ id: string; label: string; icon: any; visible: boolean }> = [];
    const processedGroups = new Map<string, { name: string; showAsTab: boolean }>(); // group_id -> { name, showAsTab }

    legalForms.forEach((form: any) => {
      console.log('  📋 Form:', form.id, 'groupId:', form.groupId, 'groupName:', form.groupName, 'groupShowAsTab:', form.groupShowAsTab);
      if (form.groupId && !processedGroups.has(form.groupId)) {
        // groupShowAsTab может быть null, true, false. По умолчанию true.
        const showAsTab = form.groupShowAsTab !== false; // если false, то не показывать
        processedGroups.set(form.groupId, {
          name: form.groupName || form.groupId,
          showAsTab
        });
      }
    });

    console.log('📊 Processed groups:', Object.fromEntries(processedGroups));

    // Создаём вкладки для групп, у которых showAsTab !== false
    processedGroups.forEach((group, groupId) => {
      if (group.showAsTab) {
        groupTabs.push({
          id: groupId,
          label: group.name,
          icon: Building2,
          visible: true,
        });
      }
    });

    console.log('📑 groupTabs:', groupTabs);

    const contractorRelTypes = relationshipTypes.filter(rt => rt.module === 'contractors');
    const rtTabs = contractorRelTypes
      .filter(rt => rt.showAsTab)  // ТОЛЬКО если showAsTab = true в настройках
      .map(rt => ({
        id: rt.id,
        label: rt.name,
        icon: UserCheck,
        visible: true,
      }));

    setTabsConfig(prev => {
      const allTab = prev.find(t => t.id === 'all') ?? { id: 'all', label: 'contractors.tabs.all', icon: Users, visible: true };
      const visMap = savedTabVisibilityRef.current;

      const applyVisibility = (tab: typeof groupTabs[0]) => {
        const existing = prev.find(p => p.id === tab.id);
        if (existing) {
          return { ...tab, visible: existing.visible };
        }
        if (tab.id in visMap) {
          return { ...tab, visible: visMap[tab.id] };
        }
        return tab;
      };

      return [allTab, ...groupTabs.map(applyVisibility), ...rtTabs.map(applyVisibility)];
    });
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [legalForms, relationshipTypes]);

  // Filters
  const [searchQuery, setSearchQuery] = useState("");
  const [statusFilter, setStatusFilter] = useState<string>("all");
  const [activeTab, setActiveTab] = usePersistedTab<string>("tab:contractors", "all");
  const [bulkEditOpen, setBulkEditOpen] = useState(false);

  // Reset page when filters change
  useEffect(() => { setCurrentPage(1); }, [searchQuery, statusFilter, activeTab, setCurrentPage]);

  const handleBulkUpdate = async (field: string, value: string) => {
    try {
      const ids = Array.from(selectedIds).filter((id): id is number => typeof id === 'number');
      if (ids.length === 0) return;
      const updates = { [field]: value };
      await api.post('/contractors/bulk-update', { ids, updates });
      toast.success(t('generated.zapis_obnovlen'));
      clearSelection();
      // Обновляем данные через refreshData из useContractorsData
      await refreshData();
      await loadContractors();
    } catch (e) {
      console.error(e);
      toast.error(t('generated.oshibka_sohraneniya'));
    }
  };

  const filteredContractors = useMemo(() => {
    // Создаём карту legalForm -> groupId на основе legalForms
    const legalFormToGroup = new Map<string, string>();
    legalForms.forEach((form: any) => {
      if (form.groupId) {
        legalFormToGroup.set(form.id, form.groupId);
      }
    });

    return contractors.filter((contractor) => {
      const matchesSearch = contractor.name
        .toLowerCase()
        .includes(searchQuery.toLowerCase());
      const matchesStatus =
        statusFilter === "all" || contractor.status === statusFilter;
      let matchesType = true;
      if (activeTab !== "all") {
        const contractorRelTypes = relationshipTypes.filter(rt => rt.module === 'contractors');
        const isRelationshipTypeTab = contractorRelTypes.some(rt => rt.id === activeTab);
        if (isRelationshipTypeTab) {
          matchesType = contractor.type === activeTab;
        } else if (activeTab === 'employee') {
          // Вкладка "Сотрудник"
          matchesType = contractor.isEmployee === true;
        } else {
          // Вкладки по ГРУППЕ правовой формы
          // Определяем группу контрагента по его legalForm
          const contractorGroupId = contractor.legalForm ? legalFormToGroup.get(contractor.legalForm) : undefined;
          matchesType = contractorGroupId === activeTab;
        }
      }
      return matchesSearch && matchesStatus && matchesType;
    });
  }, [contractors, searchQuery, statusFilter, activeTab, relationshipTypes, legalForms]);

  const sortedContractors = useMemo(() => {
    if (!sortConfig) return filteredContractors;
    const getSortableValue = (
      c: Contractor,
      key: keyof Contractor,
    ): string | number => {
      if (key === "tags") return (c.tags || []).join(", ").toLowerCase();
      if (
        key === "name" ||
        key === "status" ||
        key === "phone" ||
        key === "manager"
      )
        return String(c[key] ?? "").toLowerCase();
      return String(c[key] ?? "");
    };
    return [...filteredContractors].sort((a, b) => {
      const aValue = getSortableValue(a, sortConfig.key);
      const bValue = getSortableValue(b, sortConfig.key);
      if (aValue < bValue) return sortConfig.direction === "asc" ? -1 : 1;
      if (aValue > bValue) return sortConfig.direction === "asc" ? 1 : -1;
      return 0;
    });
  }, [filteredContractors, sortConfig]);

  const paginatedContractors = sortedContractors.slice(
    (currentPage - 1) * parseRowsPerPage(rowsPerPage),
    currentPage * parseRowsPerPage(rowsPerPage),
  );

  // Внутренний state для selectedIds
  const [selectedIdsInternal, setSelectedIdsInternal] = useState<Set<string | number>>(new Set());

  // Используем useBulkSelection для управления множественным выбором
  const {
    selectedIds,
    setSelectedIds,
    toggleOne,
    toggleCurrentPage,
    toggleAllPages,
    clearSelection,
    selectCurrentPageOnly,
    isCurrentPageSelected,
    isAllSelected,
    isSomeSelected,
    selectedCount,
  } = useBulkSelection({
    allData: sortedContractors,
    pageData: paginatedContractors,
    selectedIds: selectedIdsInternal,
    setSelectedIds: setSelectedIdsInternal,
    getId: (c) => c.id,
  });

  const handleBulkDelete = async () => {
    if (!confirm(t('generated.podtverdite_udalenie'))) return;
    try {
      const ids = Array.from(selectedIds).filter((id): id is number => typeof id === 'number');
      if (ids.length === 0) return;
      await deleteContractors(ids);
      clearSelection();
      toast.success(t('generated.zapisi_udaleny'));
    } catch {
      toast.error(t('generated.oshibka_udaleniya'));
    }
  };

  const handleToggleTab = (tabId: string) => {
    setTabsConfig(prev => prev.map(tab =>
      tab.id === tabId ? { ...tab, visible: !tab.visible } : tab
    ));
  };

  const handleToggleColumn = (column: string) => {
    toggleColumnVisibility(column, !visibleColumns[column]);
  };

  return {
    t,
    getStatusesByModule,
    initialSheetState,
    allContractors,
    loadContractors,
    handleSaveQuickTask,
    handleSaveClaim,
    handleSaveProject,
    contractors,
    references,
    loading,
    createContractor,
    updateContractor,
    deleteContractor,
    contractorSheet,
    openContractorSheet,
    closeContractorSheet,
    selectedContractor: contractorSheet.contractorId ? contractors.find(c => c.id === contractorSheet.contractorId) || null : null,
    handleContractorQuickAction: handleQuickAction,
    searchQuery,
    setSearchQuery,
    selectedIds,
    setSelectedIds,
    handleBulkUpdate,
    getTagsByModule,
    legalForms,
    relationshipTypes,
    sortConfig,
    visibleColumns,
    columnOrder,
    tabsConfig,
    handleSort,
    toggleSelection: (id: number) => toggleOne(Number(id)),
    toggleAllSelection: toggleCurrentPage,
    clearSelection,
    moveTab,
    moveColumn,
    reorderColumn,
    reorderTab,
    statusFilter,
    setStatusFilter,
    activeTab,
    setActiveTab,
    rowsPerPage,
    setRowsPerPage,
    currentPage,
    setCurrentPage,
    columnWidths,
    setColumnWidth,
    sortedContractors,
    paginatedContractors,
    handleBulkDelete,
    handleToggleTab,
    handleToggleColumn,
    // Новые функции для bulk selection
    toggleCurrentPage,
    toggleAllPages,
    selectCurrentPageOnly,
    isCurrentPageSelected,
    isAllSelected,
    isSomeSelected,
    selectedCount,
    // Bulk edit dialog
    bulkEditOpen,
    setBulkEditOpen,
    // Quick action sheets
    taskSheet,
    setTaskSheet,
    claimSheet,
    setClaimSheet,
    projectSheet,
    setProjectSheet,
  };
}

