    t,
    getStatusesByModule,
    initialSheetState,
    allContractors, loadContractors,
    handleSaveQuickTask, handleSaveClaim, handleSaveProject,
    contractors, references, loading,
    createContractor, updateContractor, deleteContractor,
    contractorSheet, openContractorSheet, closeContractorSheet, selectedContractor,
    handleContractorQuickAction,
    searchQuery, setSearchQuery,
    selectedIds,
    handleBulkUpdate,
    getTagsByModule,
    legalForms,
    relationshipTypes,
    sortConfig, visibleColumns, columnOrder, tabsConfig,
    handleSort, toggleSelection, toggleAllSelection, clearSelection, moveTab, moveColumn, reorderColumn, reorderTab,
    statusFilter, setStatusFilter,
    activeTab, setActiveTab,
    rowsPerPage, setRowsPerPage,
    currentPage, setCurrentPage,
    sortedContractors, paginatedContractors,
    columnWidths, setColumnWidth,
    handleBulkDelete, handleToggleTab, handleToggleColumn,
    // Bulk selection
    toggleCurrentPage,
    toggleAllPages,
    selectCurrentPageOnly,
    isCurrentPageSelected,
    isAllSelected,
    isSomeSelected,
    selectedCount,
    // Bulk edit dialog
    bulkEditOpen,
    setBulkEditOpen,
    // Quick action sheets
    taskSheet, setTaskSheet,
    claimSheet, setClaimSheet,
    projectSheet, setProjectSheet,
  } = useContractorsPage();

  const { dragging, dragOver, onColumnMouseDown, onColumnMouseEnter } = useColumnDrag(reorderColumn);

  const contractorColumnLabels: Record<string, string> = {
    name: t("contractors.table.name"),
    tags: t("contractors.table.tags"),
    type: t("contractors.table.type"),
    status: t("contractors.table.status"),
    phone: t("contractors.table.phone"),
    manager: t("contractors.table.manager"),
  };

  return (
    <AppLayout
      title={t("contractors.title")}
      subtitle={t("contractors.subtitle")}
      breadcrumbs={[{ label: t("contractors.title") }]}
      actions={
        <Button className="gap-2" onClick={() => openContractorSheet(null)}>
          <Plus className="w-4 h-4" />
          {t("contractors.add_button")}
        </Button>
      }
    >
      <ContractorStats contractors={contractors} />

      <Tabs value={activeTab} onValueChange={setActiveTab} className="space-y-4">
        <div className="flex justify-between items-center flex-wrap gap-4">
          <SortableTabsList
            tabsConfig={tabsConfig}
            onReorder={reorderTab}
            t={t}
          />

          <ContractorToolbar
            searchQuery={searchQuery}
            onSearchChange={setSearchQuery}
            selectedCount={selectedCount}
            onCancelSelection={clearSelection}
            onBulkDelete={handleBulkDelete}
            tabsConfig={tabsConfig}
            onMoveTab={moveTab}
            onToggleTab={handleToggleTab}
            visibleColumns={visibleColumns}
            onToggleColumn={handleToggleColumn}
            columnOrder={columnOrder}
            onMoveColumn={moveColumn}
            statusFilter={statusFilter}
            onStatusFilterChange={setStatusFilter}
            statuses={getStatusesByModule("contractors")}
            relationshipTypes={relationshipTypes.filter(rt => rt.module === 'contractors')}
            legalForms={legalForms}
            tags={getTagsByModule('contractors')}
            // Bulk selection props
            isAllSelected={isAllSelected}
            isSomeSelected={isSomeSelected}
            toggleAllPages={toggleAllPages}
            // Bulk edit
            onBulkEditClick={() => setBulkEditOpen(true)}
          />
        </div>

        <TabsContent value={activeTab} className="mt-0">
          <div className="titan-card overflow-x-auto scrollbar-stable">
            <Table>
              <TableHeader>
                <TableRow>
                  <TableUtilityHead className="w-12">
                    <TableHeaderCheckbox
                      isCurrentPageSelected={isCurrentPageSelected}
                      isAllSelected={isAllSelected}
                      isSomeSelected={isSomeSelected}
                      onToggleCurrentPage={toggleCurrentPage}
                      onToggleAllPages={toggleAllPages}
                      onSelectCurrentPageOnly={selectCurrentPageOnly}
                      onClearSelection={clearSelection}
                      selectedCount={selectedCount}
                      currentPageCount={paginatedContractors.length}
                      totalCount={sortedContractors.length}
                      showDropdown={selectedCount > 0}
                    />
                  </TableUtilityHead>
                  {columnOrder.filter(key => visibleColumns[key]).map(key => (
                    <SortableTableHead
                      key={key}
                      label={contractorColumnLabels[key] ?? key}
                      onSort={() => handleSort(key as any)}
                      direction={sortConfig?.key === key ? sortConfig.direction : null}
                      columnKey={key}
                      isDragging={dragging === key}
                      isDragOver={dragOver === key}
                      onColumnMouseDown={onColumnMouseDown}
                      onColumnMouseEnter={onColumnMouseEnter}
                      width={columnWidths?.[key]}
                      onResize={(width) => setColumnWidth(key, width)}
                    />
                  ))}
                  <TableUtilityHead className="w-12" />
                </TableRow>
              </TableHeader>
              <TableBody>
                <ContractorTable
                  contractors={paginatedContractors}
                  selectedIds={selectedIds as Set<number>}
                  visibleColumns={visibleColumns}
                  columnOrder={columnOrder}
                  onToggleSelection={toggleSelection}
                  onToggleAllSelection={toggleAllSelection}
                  onRowClick={(contractor) => openContractorSheet(contractor.id)}
                  onQuickAction={handleContractorQuickAction}
                  loading={loading}
                  relationshipTypes={relationshipTypes.filter(rt => rt.module === 'contractors')}
                  columnWidths={columnWidths}
                />
              </TableBody>
            </Table>

            <TableFooterPagination
              shownCount={paginatedContractors.length}
              totalCount={sortedContractors.length}
              rowsPerPage={rowsPerPage}
              onRowsPerPageChange={setRowsPerPage}
              currentPage={currentPage}
              onPageChange={setCurrentPage}
            />
          </div>
        </TabsContent>
      </Tabs>

      <ContractorSheet
        key={`sheet-${references.contractorTypes?.length || 0}-${references.legalForms?.length || 0}`}
        contractor={selectedContractor}
        open={contractorSheet.isOpen}
        onOpenChange={(open) => { if (!open) closeContractorSheet(); }}
        onSave={async (contractor) => {
          if (selectedContractor) {
            await updateContractor(contractor.id, contractor);
          } else {
            await createContractor(contractor);
          }
        }}
        onDelete={deleteContractor}
      />

      <BulkEditDialog
        moduleId="contractors"
        open={bulkEditOpen}
        onOpenChange={setBulkEditOpen}
        onConfirm={handleBulkUpdate}
        count={selectedCount}
        referenceData={{
          statuses: getStatusesByModule("contractors"),
          relationshipTypes: relationshipTypes.filter(rt => rt.module === 'contractors'),
          legalForms,
          tags: getTagsByModule('contractors'),
          users: references.managers || [],
        }}
      />

      {/* Quick action sheets */}
      <QuickActionSheet
        type="task"
        open={taskSheet.isOpen}
        onOpenChange={(open) => !open && setTaskSheet({ isOpen: false, contractorName: '' })}
        contractorName={taskSheet.contractorName}
        contractorId={taskSheet.contractorId}
        statuses={getStatusesByModule('tasks')}
        priorities={references.priorities || []}
      />
      <QuickActionSheet
        type="claim"
        open={claimSheet.isOpen}
        onOpenChange={(open) => !open && setClaimSheet({ isOpen: false, contractorName: '' })}
        contractorName={claimSheet.contractorName}
        contractorId={claimSheet.contractorId}
        statuses={references.caseStatuses || []}
        caseTypes={references.caseTypes || []}
      />
      <QuickActionSheet
        type="project"
        open={projectSheet.isOpen}
        onOpenChange={(open) => !open && setProjectSheet({ isOpen: false, contractorName: '' })}
        contractorName={projectSheet.contractorName}
        contractorId={projectSheet.contractorId}
        statuses={references.projectStatuses || []}
        priorities={references.priorities || []}
      />
    </AppLayout>
  );
}

