import { useState, useEffect, useCallback } from "react";
import { toast } from "sonner";
import { useTranslation } from "@/lib/i18n";
import { FileItem, FolderStats } from "../types/document.types";
import { documentService } from "../api/documentService";

interface UseDocumentsReturn {
  files: FileItem[];
  stats: FolderStats;
  loading: boolean;
  error: Error | null;
  fetchFiles: (parentId?: string | null) => Promise<void>;
  fetchStats: () => Promise<void>;
  createFolder: (name: string, parentId?: string | null) => Promise<FileItem | null>;
  uploadFile: (file: File, parentId?: string | null) => Promise<FileItem | null>;
  deleteFile: (id: string) => Promise<boolean>;
  toggleStar: (id: string, starred: boolean) => Promise<boolean>;
}

export function useDocuments(): UseDocumentsReturn {
  const { t } = useTranslation();
  const [files, setFiles] = useState<FileItem[]>([]);
  const [stats, setStats] = useState<FolderStats>({
    used: "0 GB",
    total: "10 GB",
    percentage: 0,
    filesCount: 0,
  });
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<Error | null>(null);

  const fetchFiles = useCallback(async (parentId?: string | null) => {
    try {
      setLoading(true);
      const data = await documentService.getAll(parentId);
      setFiles(data);
      setError(null);
    } catch (err) {
      setError(err instanceof Error ? err : new Error(String(err)));
      toast.error(t("general.toast.error.files_load"));
    } finally {
      setLoading(false);
    }
  }, [t]);

  const fetchStats = useCallback(async () => {
    try {
      const data = await documentService.getStats();
      setStats(data);
    } catch (err) {
      console.error("Failed to fetch stats", err);
    }
  }, []);

  const createFolder = useCallback(
    async (name: string, parentId?: string | null): Promise<FileItem | null> => {
      try {
        const newFolder = await documentService.createFolder({ name, parentId });
        setFiles((prev) => [newFolder, ...prev]);
        toast.success(t("general.toast.success.folder_created"));
        return newFolder;
      } catch (err) {
        toast.error(t("general.toast.error.folder_create"));
        return null;
      }
    },
    [t]
  );

  const uploadFile = useCallback(
    async (file: File, parentId?: string | null): Promise<FileItem | null> => {
      try {
        const uploadedFile = await documentService.uploadFile({ file, parentId });
        setFiles((prev) => [uploadedFile, ...prev]);
        toast.success(t("general.toast.success.file_uploaded"));
        return uploadedFile;
      } catch (err) {
        toast.error(t("general.toast.error.file_upload"));
        return null;
      }
    },
    [t]
  );

  const deleteFile = useCallback(
    async (id: string): Promise<boolean> => {
      try {
        await documentService.deleteFile(id);
        setFiles((prev) => prev.filter((f) => f.id !== id));
        toast.success(t("general.toast.success.file_deleted"));
        return true;
      } catch (err) {
        toast.error(t("general.toast.error.file_delete"));
        return false;
      }
    },
    [t]
  );

  const toggleStar = useCallback(
    async (id: string, starred: boolean): Promise<boolean> => {
      try {
        await documentService.toggleStar(id, starred);
        setFiles((prev) =>
          prev.map((f) => (f.id === id ? { ...f, starred } : f))
        );
        return true;
      } catch (err) {
        toast.error(t("general.toast.error.file_update"));
        return false;
      }
    },
    [t]
  );

  useEffect(() => {
    fetchFiles();
    fetchStats();
  }, [fetchFiles, fetchStats]);

  return {
    files,
    stats,
    loading,
    error,
    fetchFiles,
    fetchStats,
    createFolder,
    uploadFile,
    deleteFile,
    toggleStar,
  };
}

// frontend/src/modules/documents/hooks/useDocumentsPage.ts
import { useState, useMemo, useEffect, useRef } from "react";
import { toast } from "sonner";
import { useValidationToast } from "@/components/shared";
import { useTranslation } from "@/lib/i18n";
import { api } from "@/lib/api";
import { parseRowsPerPage } from "@/lib/utils";
import { useDataTable } from "@/hooks/useDataTable";
import { FileItem } from "../types";

export type SortOption =
  | "name-asc"
  | "name-desc"
  | "date-asc"
  | "date-desc"
  | "size-asc"
  | "size-desc"
  | "type";

export function useDocumentsPage() {
  const { t } = useTranslation();
  const { validate } = useValidationToast();

  const [files, setFiles] = useState<FileItem[]>([]);
  const [currentFolderId, setCurrentFolderId] = useState<string | null>(null);
  const [viewMode, setViewMode] = useState<"grid" | "list">("grid");
  const [filter, setFilter] = useState<"all" | "recent" | "starred" | "trash" | "templates">("all");
  
  const [isCreateFolderOpen, setIsCreateFolderOpen] = useState(false);
  const [isUploadOpen, setIsUploadOpen] = useState(false);
  const [newFolderName, setNewFolderName] = useState("");
  const [selectedFiles, setSelectedFiles] = useState<FileList | null>(null);

  const table = useDataTable<FileItem>({
    initialData: [],
    initialColumns: {
      name: true,
      size: true,
      date: true,
    },
    storageKey: "documents-table",
  });

  const refreshFiles = async () => {
    try {
      const data = await api.get("/documents");
      setFiles(data);
    } catch (error) {
      console.error("Failed to fetch documents", error);
      toast.error(t("general.toast.error.documents_load"));
    }
  };

  useEffect(() => {
    refreshFiles();
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const currentFolderName = useMemo(() => {
    if (filter === "templates") return "Шаблоны автоматизации";
    if (!currentFolderId) return t("documents.categories.all");
    const folder = files.find((f) => f.id === currentFolderId);
    return folder ? folder.name : t("documents.categories.all");
  }, [currentFolderId, files, t, filter]);

  const filteredAndSortedFiles = useMemo(() => {
    let result = [...files];

    if (table.searchQuery) {
      result = result.filter((f) =>
        f.name.toLowerCase().includes(table.searchQuery.toLowerCase())
      );
    } else if (filter === "starred") {
      result = result.filter((f) => f.starred);
    } else if (filter === "templates") {
      result = result.filter((f) => f.is_template);
    } else if (filter === "recent") {
      result = result.slice(0, 7);
    } else {
      result = result.filter(
        (f) =>
          f.parentId === currentFolderId ||
          (f.parentId == null && currentFolderId == null)
      );
    }

    result.sort((a, b) => {
      if (!table.sortConfig) return 0;
      const { key, direction } = table.sortConfig;
      let comparison = 0;
      
      switch (key) {
        case "name": comparison = a.name.localeCompare(b.name); break;
        case "date": comparison = new Date(a.date).getTime() - new Date(b.date).getTime(); break;
        case "size": comparison = (a.size || "0").localeCompare(b.size || "0"); break;
        default: break;
      }
      
      return direction === "asc" ? comparison : -comparison;
    });

    return result;
  }, [files, currentFolderId, table.searchQuery, filter, table.sortConfig]);

  // Reset page when search/filter changes
  useEffect(() => { table.setCurrentPage(1); }, [table.searchQuery, filter, currentFolderId, table.sortConfig, table.rowsPerPage]);

  const perPage = parseRowsPerPage(table.rowsPerPage);
  const paginatedFiles = filteredAndSortedFiles.slice((table.currentPage - 1) * perPage, table.currentPage * perPage);

  const handleFileClick = (file: FileItem) => {
    if (file.type === "folder") {
      setCurrentFolderId(file.id);
      setFilter("all");
    } else {
      toast.success(t("general.toast.success.file_opened", [file.name]));
    }
  };

  const handleToggleStar = async (id: string) => {
    try {
      const file = files.find((f) => f.id === id);
      if (!file) return;
      const next = !file.starred;
      setFiles((prev) => prev.map((f) => (f.id === id ? { ...f, starred: next } : f)));
      await api.patch(`/documents/${id}/star`, { starred: next });
      toast.success(
        next
          ? t("general.toast.success.added_to_favorites")
          : t("general.toast.success.removed_from_favorites")
      );
    } catch {
      setFiles((prev) => prev.map((f) => (f.id === id ? { ...f, starred: !f.starred } : f)));
      toast.error(t("generated.oshibka_pri_izmenenii_izbrannogo"));
    }
  };

  const handleToggleTemplate = async (id: string) => {
    try {
      const file = files.find((f) => f.id === id);
      if (!file) return;
      const next = !file.is_template;
      setFiles((prev) => prev.map((f) => (f.id === id ? { ...f, is_template: next } : f)));
      await api.patch(`/documents/${id}/template`, { is_template: next });
      toast.success(
        next
          ? "Добавлено в шаблоны"
          : "Удалено из шаблонов"
      );
    } catch {
      setFiles((prev) => prev.map((f) => (f.id === id ? { ...f, is_template: !f.is_template } : f)));
      toast.error("Ошибка при изменении статуса шаблона");
    }
  };

  const handleNavigateToRoot = () => {
    setCurrentFolderId(null);
    setFilter("all");
  };

  const handleCreateFolder = async () => {
    if (!validate([{ name: 'folderName', label: t('generated.nazvanie_papki'), value: newFolderName }])) {
      return;
    }
    try {
      const newFolder: FileItem = {
        id: `folder-${Date.now()}`,
        name: newFolderName,
        type: "folder" as const,
        size: null,
        date: new Date().toISOString().split("T")[0],
        parentId: currentFolderId,
        starred: false,
      };
      await api.post("/documents/folder", newFolder);
      setFiles((prev) => [...prev, newFolder]);
      setIsCreateFolderOpen(false);
      setNewFolderName("");
      toast.success(t("generated.papka_sozdana"));
    } catch {
      toast.error(t("generated.oshibka_pri_sozdanii_papki"));
    }
  };

  const handleUploadFiles = async () => {
    if (!validate([{ name: 'files', label: t('generated.fayly'), value: selectedFiles?.length }])) {
      return;
    }
    let successCount = 0;
    let failCount = 0;
    for (let i = 0; i < selectedFiles.length; i++) {
      const file = selectedFiles[i];
      const formData = new FormData();
      formData.append("file", file);
      if (currentFolderId) formData.append("folderId", currentFolderId);
      try {
        await api.post("/documents/upload", formData);
        successCount++;
      } catch {
        failCount++;
        toast.error(t("general.toast.error.file_upload_error_name", [file.name]));
      }
    }
    setIsUploadOpen(false);
    setSelectedFiles(null);
    if (successCount > 0) toast.success(t("general.toast.success.files_uploaded", [successCount]));
    if (failCount > 0)    toast.error(t("general.toast.error.files_upload_failed", [failCount]));
    await refreshFiles();
  };

  const handleDeleteFiles = async (ids: string[]) => {
    if (!confirm(t("generated.vy_uvereny_chto_hotite_udalit_vybrannye_"))) return;
    try {
      await api.post("/documents/delete", { ids });
      setFiles((prev) => prev.filter((f) => !ids.includes(f.id)));
      toast.success(t("general.toast.success.files_deleted", [ids.length]));
    } catch {
      toast.error(t("generated.oshibka_pri_udalenii_faylov"));
    }
  };

  const handleDownloadFile = async (file: FileItem) => {
    try {
      const blob = await api.get(`/documents/download/${file.id}`, { responseType: "blob" });
      const url = window.URL.createObjectURL(blob);
      const link = document.createElement("a");
      link.href = url;
      link.setAttribute("download", file.name);
      document.body.appendChild(link);
      link.click();
      link.parentNode?.removeChild(link);
      window.URL.revokeObjectURL(url);
    } catch {
      toast.error(t("generated.oshibka_pri_skachivanii_fayla"));
    }
  };

  const handleShareFile = async (file: FileItem) => {
    try {
      const { shareUrl } = await api.get(`/documents/share/${file.id}`);
      if (navigator.clipboard) {
        await navigator.clipboard.writeText(shareUrl);
        toast.success(t("generated.ssylka_skopirovana"));
      } else {
        window.open(shareUrl, "_blank");
      }
    } catch {
      toast.error(t("generated.oshibka_pri_sozdanii_ssylki"));
    }
  };

  const getSortDirection = (field: string): "asc" | "desc" | null => {
    if (table.sortConfig?.key !== field) return null;
    return table.sortConfig.direction;
  };

  const handleSort = (field: string) => {
    table.handleSort(field as any);
  };

  return {
    // state
    files,
    currentFolderId,
    viewMode,
    setViewMode,
    filter,
    setFilter,
    isCreateFolderOpen,
    setIsCreateFolderOpen,
    isUploadOpen,
    setIsUploadOpen,
    newFolderName,
    setNewFolderName,
    selectedFiles,
    setSelectedFiles,
    // computed
    currentFolderName,
    filteredAndSortedFiles,
    paginatedFiles,
    // handlers
    handleFileClick,
    handleToggleStar,
    handleToggleTemplate,
    handleNavigateToRoot,
    handleCreateFolder,
    handleUploadFiles,
    handleDeleteFiles,
    handleDownloadFile,
    handleShareFile,
    getSortDirection,
    handleSort,
    table,
  };
}

import { api } from '@/lib/api';
import {
  Invoice, Payment, ProjectFinanceSummary, ReceivablesReport, CalendarPayment,
  ExpenseCategory, BankStatement, StatementLine, DdsRow, PLReport, ReconciliationAct,
} from '../types/finance.types';

export const financeApi = {
  // Invoices
  getInvoices: async (filters?: {
    status?: string;
    invoiceType?: 'outgoing' | 'incoming';
    contractorId?: number;
    projectId?: number;
    lawyerId?: number;
    startDate?: string;
    endDate?: string;
    overdueOnly?: boolean;
  }) => {
    const params = new URLSearchParams();
    if (filters?.status) params.set('status', filters.status);
    if (filters?.invoiceType) params.set('invoiceType', filters.invoiceType);
    if (filters?.contractorId) params.set('contractorId', String(filters.contractorId));
    if (filters?.projectId) params.set('projectId', String(filters.projectId));
    if (filters?.lawyerId) params.set('lawyerId', String(filters.lawyerId));
    if (filters?.startDate) params.set('startDate', filters.startDate);
    if (filters?.endDate) params.set('endDate', filters.endDate);
    if (filters?.overdueOnly) params.set('overdueOnly', 'true');

    return api.get(`/finance/invoices?${params.toString()}`) as Promise<Invoice[]>;
  },

  getInvoice: async (id: number) => {
    return api.get(`/finance/invoices/${id}`) as Promise<Invoice>;
  },

  createInvoice: async (data: Partial<Invoice>) => {
    return api.post('/finance/invoices', data) as Promise<Invoice>;
  },

  updateInvoice: async (id: number, data: Partial<Invoice>) => {
    return api.put(`/finance/invoices/${id}`, data) as Promise<Invoice>;
  },

  sendInvoice: async (id: number) => {
    return api.post(`/finance/invoices/${id}/send`, {}) as Promise<Invoice>;
  },

  recalculateInvoiceStatus: async (id: number) => {
    return api.post(`/finance/invoices/${id}/recalculate-status`, {}) as Promise<Invoice>;
  },

  generateInvoiceDocument: async (id: number, data: { documentType: 'act' | 'invoice' }) => {
    return api.post(`/finance/invoices/${id}/generate-document`, data) as Promise<{ documentId: number }>;
  },

  // Payments
  getPayments: async (filters?: {
    kind?: 'income' | 'expense';
    invoiceId?: number;
    projectId?: number;
    taskId?: string;
    contractorId?: number;
    categoryId?: string;
    startDate?: string;
    endDate?: string;
  }) => {
    const params = new URLSearchParams();
    if (filters?.kind) params.set('kind', filters.kind);
    if (filters?.invoiceId) params.set('invoiceId', String(filters.invoiceId));
    if (filters?.projectId) params.set('projectId', String(filters.projectId));
    if (filters?.taskId) params.set('taskId', filters.taskId);
    if (filters?.contractorId) params.set('contractorId', String(filters.contractorId));
    if (filters?.categoryId) params.set('categoryId', filters.categoryId);
    if (filters?.startDate) params.set('startDate', filters.startDate);
    if (filters?.endDate) params.set('endDate', filters.endDate);

    return api.get(`/finance/payments?${params.toString()}`) as Promise<Payment[]>;
  },

  createPayment: async (data: Partial<Payment>) => {
    return api.post('/finance/payments', data) as Promise<Payment>;
  },

  updatePayment: async (id: number, data: Partial<Payment>) => {
    return api.put(`/finance/payments/${id}`, data) as Promise<Payment>;
  },

  deletePayment: async (id: number) => {
    return api.delete(`/finance/payments/${id}`);
  },

  /**
   * Отвязать платеж от счета
   * @param paymentId - ID платежа
   * @returns ID счета для которого был пересчитан статус
   */
  unlinkPaymentFromInvoice: async (id: number) => {
    return api.post(`/finance/payments/${id}/unlink-from-invoice`, {}) as Promise<{
      success: boolean;
      previousInvoiceId?: number | string;
      message: string;
    }>;
  },

  // Expense categories (DDS)
  getCategories: async (kind?: 'income' | 'expense') => {
    const params = kind ? `?kind=${kind}` : '';
    return api.get(`/finance/categories${params}`) as Promise<ExpenseCategory[]>;
  },

  createCategory: async (data: { name: string; kind: 'income' | 'expense'; parentId?: string; color?: string }) => {
    return api.post('/finance/categories', data) as Promise<ExpenseCategory>;
  },

  updateCategory: async (id: string, data: Partial<ExpenseCategory>) => {
    return api.put(`/finance/categories/${id}`, data) as Promise<ExpenseCategory>;
  },

  deleteCategory: async (id: string) => {
    return api.delete(`/finance/categories/${id}`);
  },

  // Bank statements
  getStatements: async () => {
    return api.get('/finance/statements') as Promise<BankStatement[]>;
  },

  getStatementLines: async (id: string) => {
    return api.get(`/finance/statements/${id}/lines`) as Promise<StatementLine[]>;
  },

  importStatement: async (data: {
    content: string;
    fileName: string;
    importType: 'csv' | '1c_txt';
    account?: string;
    draft?: boolean; // Предпросмотр без записи в БД
  }) => {
    return api.post('/finance/statements/import', data) as Promise<{
      mode: 'preview' | 'imported';
      statementId?: string;
      linesCount: number;
      totalCredit: number;
      totalDebit: number;
      contractorsCreated?: number;
      contractorsUpdated?: number;
      newAccountsAdded?: number;
      paymentsCreated?: number;
      duplicatesSkipped?: number;
      warningsCount?: number;
      preview?: {
        fileName: string;
        importType: string;
        account: string | null;
        dateFrom: string | null;
        dateTo: string | null;
        totalCredit: number;
        totalDebit: number;
        linesCount: number;
        lines: any[];
        summary: {
          incomeCount: number;
          expenseCount: number;
          uniqueContractors: number;
        };
      };
      report?: {
        summary: any;
        contractors: any;
        newContractors: any[];
        updatedContractors: any[];
        newAccounts: any[];
        warnings: any[];
        suggestions: string[];
      };
    }>;
  },

  confirmImport: async (data: {
    content: string;
    fileName: string;
    importType: 'csv' | '1c_txt';
    account?: string;
  }) => {
    return api.post('/finance/statements/import', { ...data, draft: false }) as Promise<{
      statementId: string;
      linesCount: number;
      totalCredit: number;
      totalDebit: number;
      contractorsCreated: number;
      contractorsUpdated: number;
      newAccountsAdded: number;
      paymentsCreated: number;
      duplicatesSkipped: number;
      warningsCount: number;
      report: any;
    }>;
  },

  rollbackImport: async (sessionId: string, options?: {
    removeContractors?: boolean;
    reason?: string;
  }) => {
    return api.post('/finance/import/rollback', {
      sessionId,
      ...options,
    }) as Promise<{ success: boolean; steps: string[] }>;
  },

  reconcileStatement: async (id: string, account?: string) => {
    return api.post(`/finance/statements/${id}/reconcile`, { account }) as Promise<{ 
      matched: number; 
      total: number; 
    }>;
  },

  updateStatementLine: async (lineId: string, data: { invoiceId?: string; paymentId?: string; categoryId?: string | null }) => {
    return api.put(`/finance/statements/lines/${lineId}`, data) as Promise<StatementLine>;
  },

  deleteStatement: async (id: string) => {
    return api.delete(`/finance/statements/${id}`);
  },

  // Reports & Analytics
  getProjectSummary: async (projectId: number) => {
    return api.get(`/finance/projects/${projectId}/summary`) as Promise<ProjectFinanceSummary>;
  },

  getReceivablesReport: async (groupBy?: 'contractor' | 'project') => {
    const params = groupBy ? `?groupBy=${groupBy}` : '';
    return api.get(`/finance/reports/receivables${params}`) as Promise<ReceivablesReport[]>;
  },

  getCalendarPayments: async (period?: 'week' | 'month') => {
    const params = period ? `?period=${period}` : '';
    return api.get(`/finance/calendar-payments${params}`) as Promise<CalendarPayment[]>;
  },

  getPLReport: async (filters?: { projectId?: number; dateFrom?: string; dateTo?: string }) => {
    const params = new URLSearchParams();
    if (filters?.projectId) params.set('projectId', String(filters.projectId));
    if (filters?.dateFrom) params.set('dateFrom', filters.dateFrom);
    if (filters?.dateTo) params.set('dateTo', filters.dateTo);
    return api.get(`/finance/reports/pl?${params.toString()}`) as Promise<PLReport>;
  },

  getDDSReport: async (filters?: { dateFrom?: string; dateTo?: string }) => {
    const params = new URLSearchParams();
    if (filters?.dateFrom) params.set('dateFrom', filters.dateFrom);
    if (filters?.dateTo) params.set('dateTo', filters.dateTo);
    return api.get(`/finance/reports/dds?${params.toString()}`) as Promise<DdsRow[]>;
  },

  getPaymentRegister: async (filters?: {
    kind?: 'income' | 'expense';
    projectId?: number;
    contractorId?: number;
    dateFrom?: string;
    dateTo?: string;
  }) => {
    const params = new URLSearchParams();
    if (filters?.kind) params.set('kind', filters.kind);
    if (filters?.projectId) params.set('projectId', String(filters.projectId));
    if (filters?.contractorId) params.set('contractorId', String(filters.contractorId));
    if (filters?.dateFrom) params.set('dateFrom', filters.dateFrom);
    if (filters?.dateTo) params.set('dateTo', filters.dateTo);
    return api.get(`/finance/reports/register?${params.toString()}`) as Promise<Payment[]>;
  },

  getReconciliationAct: async (contractorId: string, filters?: { dateFrom?: string; dateTo?: string }) => {
    const params = new URLSearchParams();
    if (filters?.dateFrom) params.set('dateFrom', filters.dateFrom);
    if (filters?.dateTo) params.set('dateTo', filters.dateTo);
    return api.get(`/finance/reconciliation-act/${contractorId}?${params.toString()}`) as Promise<ReconciliationAct>;
  },
};

import { useState, useRef } from 'react';
import { parseRowsPerPage } from '@/lib/utils';
import { TableFooterPagination } from '@/components/shared';
import { useTranslation } from '@/lib/i18n';
import {
  useStatements,
  useStatementLines,
  useImportStatement,
  useReconcileStatement,
  useUpdateStatementLine,
  useDeleteStatement,
  useCategories,
} from '../hooks/useFinance';
import { useInvoices } from '../hooks/useFinance';
import { BankStatement, StatementLine, ExpenseCategory } from '../types/finance.types';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Skeleton } from '@/components/ui/skeleton';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
  DialogFooter,
} from '@/components/ui/dialog';
import {
  Upload, RefreshCw, Trash2, ChevronDown, ChevronRight,
  CheckCircle, AlertCircle, Link as LinkIcon, Tag,
} from 'lucide-react';
import { toast } from 'sonner';
import { ImportPreviewDialog } from '../components/ImportPreviewDialog';

const fmt = (n: number) =>
  new Intl.NumberFormat('ru-RU', { style: 'currency', currency: 'RUB', minimumFractionDigits: 2, maximumFractionDigits: 2 }).format(n);

// ───────── Line row ─────────
function StatementLineRow({
  line,
  invoices,
  categories,
}: {
  line: StatementLine;
  invoices: Array<{ id: string | number; identifier: string }>;
  categories: ExpenseCategory[];
}) {
  const { t } = useTranslation();
  const updateLine = useUpdateStatementLine();
  const [mode, setMode] = useState<'idle' | 'invoice' | 'category'>('idle');
  const [selectedInvoice, setSelectedInvoice] = useState('');
  const [selectedCategory, setSelectedCategory] = useState('');
  const [showUnlinkConfirm, setShowUnlinkConfirm] = useState(false);
  const [showPurposeDialog, setShowPurposeDialog] = useState(false);

  const handleLinkInvoice = async () => {
    if (!selectedInvoice) {
      toast.error(t('finance.statement.select_invoice_first'));
      return;
    }
    try {
      await updateLine.mutateAsync({ lineId: line.id, data: { invoiceId: selectedInvoice } });
      toast.success(t('finance.statement.invoice_linked'));
      setMode('idle');
    } catch (error: any) {
      toast.error(t('general.toast.error.data_load') + ': ' + error?.message);
    }
  };

  const handleUnlinkInvoice = async () => {
    try {
      await updateLine.mutateAsync({ lineId: line.id, data: { invoiceId: null } });
      toast.success(t('finance.statement.invoice_unlinked'));
      setShowUnlinkConfirm(false);
    } catch (error: any) {
      toast.error(t('general.toast.error.data_load') + ': ' + error?.message);
    }
  };

  const handleLinkCategory = async () => {
    if (!selectedCategory) {
      toast.error(t('finance.statement.select_category_first'));
      return;
    }
    try {
      await updateLine.mutateAsync({ lineId: line.id, data: { categoryId: selectedCategory } });
      toast.success(t('finance.statement.category_linked'));
      setMode('idle');
    } catch (error: any) {
      toast.error(t('general.toast.error.data_load') + ': ' + error?.message);
    }
  };

  const statusColor = {
    unmatched: 'bg-amber-100 text-amber-800 dark:bg-amber-950 dark:text-amber-300',
    auto: 'bg-blue-100 text-blue-800 dark:bg-blue-950 dark:text-blue-300',
    manual: 'bg-green-100 text-green-800 dark:bg-green-950 dark:text-green-300',
  }[line.reconcileStatus] || '';

  const statusLabel = {
    unmatched: t('finance.statement.line_unmatched'),
    auto: t('finance.statement.line_auto'),
    manual: t('finance.statement.line_manual'),
  }[line.reconcileStatus] || line.reconcileStatus;

  const isUnmatched = line.reconcileStatus === 'unmatched';
  const relevantCategories = categories.filter(c =>
    line.direction === 'credit' ? c.kind === 'income' : c.kind === 'expense'
  );

  return (
    <>
      <tr className="border-b hover:bg-muted/30 text-sm">
        <td className="p-2 text-xs text-muted-foreground">{line.lineDate}</td>
        <td className={`p-2 font-medium ${line.direction === 'credit' ? 'text-green-600' : 'text-destructive'}`}>
          {line.direction === 'credit' ? '+' : '-'}{fmt(line.amount)}
        </td>
        <td className="p-2">
          <Badge variant="outline" className={`text-xs ${line.direction === 'credit' ? 'border-green-400' : 'border-red-400'}`}>
            {line.direction === 'credit' ? t('finance.statement.line_credit') : t('finance.statement.line_debit')}
          </Badge>
        </td>
        <td className="p-2 max-w-32 truncate text-muted-foreground">{line.counterparty || '—'}</td>
        <td className="p-2 max-w-64">
          {line.purpose ? (
            <div
              className="text-xs text-muted-foreground line-clamp-2 cursor-pointer hover:text-foreground transition-colors"
              onClick={(e) => {
                e.stopPropagation();
                setShowPurposeDialog(true);
              }}
              title="Нажмите для просмотра полного текста"
            >
              {line.purpose}
            </div>
          ) : (
            <span className="text-xs text-muted-foreground">—</span>
          )}
        </td>
        {/* Номер платежного поручения */}
        <td className="p-2">
          {line.reference ? (
            <span className="font-mono text-xs text-muted-foreground">{line.reference}</span>
          ) : '—'}
        </td>
        {/* Категория */}
        <td className="p-2">
          {line.categoryName ? (
            <span
              className="text-xs px-2 py-0.5 rounded-full font-medium"
              style={{ background: line.categoryColor ? `${line.categoryColor}22` : undefined, color: line.categoryColor || undefined }}
            >
              {line.categoryName}
            </span>
          ) : '—'}
        </td>
        {/* Счёт */}
        <td className="p-2">
          {line.invoiceIdentifier ? (
            <div className="flex items-center gap-1">
              <span className="font-mono text-xs bg-muted px-1 py-0.5 rounded">{line.invoiceIdentifier}</span>
              {/* Кнопка отвязки счета */}
              <Button
                size="sm"
                variant="ghost"
                className="h-5 w-5 p-0 text-muted-foreground hover:text-destructive"
                onClick={(e) => {
                  e.stopPropagation();
                  setShowUnlinkConfirm(true);
                }}
                title={t('finance.statement.unlink_invoice')}
              >
                <Trash2 className="w-3 h-3" />
              </Button>
            </div>
          ) : '—'}
        </td>
        <td className="p-2">
          <span className={`text-xs px-2 py-0.5 rounded-full font-medium ${statusColor}`}>{statusLabel}</span>
        </td>
        {/* Действия */}
        <td className="p-2 min-w-[180px]">
          {isUnmatched && mode === 'idle' && (
            <div className="flex items-center gap-1 flex-wrap">
              {/* Категория — для всех */}
              <Button size="sm" variant="outline" className="h-7 text-xs gap-1" onClick={() => setMode('category')}>
                <Tag className="w-3 h-3" />
                {t('generated.kategoriya')}
              </Button>
              {/* Счёт — только для прихода */}
              {line.direction === 'credit' && (
                <Button size="sm" variant="outline" className="h-7 text-xs gap-1" onClick={() => setMode('invoice')}>
                  <LinkIcon className="w-3 h-3" />
                  {t('finance.statement.assign')}
                </Button>
              )}
            </div>
          )}
          {mode === 'invoice' && (
            <div className="flex items-center gap-1 flex-wrap">
              <Select value={selectedInvoice} onValueChange={setSelectedInvoice}>
                <SelectTrigger className="h-7 w-36 text-xs">
                  <SelectValue placeholder={t('generated.schet')} />
                </SelectTrigger>
                <SelectContent>
                  {invoices.map(inv => (
                    <SelectItem key={inv.id} value={String(inv.id)}>
                      {inv.identifier}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
              <Button size="sm" className="h-7 text-xs px-2" onClick={handleLinkInvoice} disabled={!selectedInvoice || updateLine.isPending}>
                <CheckCircle className="w-3 h-3" />
              </Button>
              <Button size="sm" variant="ghost" className="h-7 text-xs px-2" onClick={() => setMode('idle')}>✕</Button>
            </div>
          )}
          {mode === 'category' && (
            <div className="flex items-center gap-1 flex-wrap">
              <Select value={selectedCategory} onValueChange={setSelectedCategory}>
                <SelectTrigger className="h-7 w-40 text-xs">
                  <SelectValue placeholder={t('generated.kategoriya')} />
                </SelectTrigger>
                <SelectContent>
                  {relevantCategories.map(cat => (
                    <SelectItem key={cat.id} value={cat.id}>
                      {cat.name}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
              <Button size="sm" className="h-7 text-xs px-2" onClick={handleLinkCategory} disabled={!selectedCategory || updateLine.isPending}>
                <CheckCircle className="w-3 h-3" />
              </Button>
              <Button size="sm" variant="ghost" className="h-7 text-xs px-2" onClick={() => setMode('idle')}>✕</Button>
            </div>
          )}
        </td>
      </tr>

      {/* Диалог подтверждения отвязки счета */}
      <Dialog open={showUnlinkConfirm} onOpenChange={setShowUnlinkConfirm}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>{t('finance.statement.unlink_invoice')}</DialogTitle>
            <DialogDescription>
              {t('finance.statement.unlink_invoice_confirm')}
            </DialogDescription>
          </DialogHeader>
          <DialogFooter>
            <Button variant="outline" onClick={() => setShowUnlinkConfirm(false)}>
              {t('generated.otmena')}
            </Button>
            <Button
              variant="destructive"
              onClick={handleUnlinkInvoice}
              disabled={updateLine.isPending}
            >
              {t('generated.udalit')}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* Диалог просмотра назначения платежа */}
      <Dialog open={showPurposeDialog} onOpenChange={setShowPurposeDialog}>
        <DialogContent className="max-w-2xl">
          <DialogHeader>
            <DialogTitle>{t('finance.statement.line_purpose')}</DialogTitle>
          </DialogHeader>
          <div className="mt-4 p-4 bg-muted rounded-lg">
            <p className="text-sm whitespace-pre-wrap">{line.purpose}</p>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setShowPurposeDialog(false)}>
              {t('finance.messages.close')}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </>
  );
}

// ───────── Statement row ─────────
function StatementRow({
  stmt,
  invoices,
}: {
  stmt: BankStatement;
  invoices: Array<{ id: string | number; identifier: string }>;
}) {
  const { t } = useTranslation();
  const [expanded, setExpanded] = useState(false);
  const [linePage, setLinePage] = useState(1);
  const [lineRowsPerPage, setLineRowsPerPage] = useState('25');
  const [showReconcileDialog, setShowReconcileDialog] = useState(false);
  const reconcile = useReconcileStatement();
  const deleteStmt = useDeleteStatement();

  const { data: lines, isLoading: linesLoading } = useStatementLines(expanded ? stmt.id : null);
  const { data: categories = [] } = useCategories();

  const linePerPage = parseRowsPerPage(lineRowsPerPage);
  const paginatedLines = (lines || []).slice((linePage - 1) * linePerPage, linePage * linePerPage);

  const handleReconcile = async (e: React.MouseEvent) => {
    e.stopPropagation();
    // Открываем диалог выбора счёта
    setShowReconcileDialog(true);
  };

  const handleReconcileWithAccount = async (account: string | null) => {
    await reconcile.mutateAsync({ id: stmt.id, account: account || undefined });
    setShowReconcileDialog(false);
  };

  const handleDelete = async (e: React.MouseEvent) => {
    e.stopPropagation();
    if (!confirm(t('finance.statement.delete_confirm'))) return;
    await deleteStmt.mutateAsync(stmt.id);
  };

  return (
    <div className="border rounded-lg overflow-hidden">
      <div
        className="flex flex-wrap items-center justify-between p-4 cursor-pointer hover:bg-muted/40 transition-colors gap-2"
        onClick={() => setExpanded(v => !v)}
      >
        <div className="flex items-center gap-3">
          {expanded ? <ChevronDown className="w-4 h-4" /> : <ChevronRight className="w-4 h-4" />}
          <div>
            <div className="font-medium text-sm">{stmt.fileName || t('finance.messages.import')}</div>
            <div className="text-xs text-muted-foreground">
              {stmt.importType.toUpperCase()} | {stmt.dateFrom} — {stmt.dateTo}
              {stmt.account && ` | ${stmt.account}`}
            </div>
          </div>
        </div>
        <div className="flex items-center gap-4">
          <div className="text-sm">
            <span className="text-green-600 font-medium">+{fmt(stmt.totalCredit)}</span>
            {' / '}
            <span className="text-destructive font-medium">-{fmt(stmt.totalDebit)}</span>
          </div>
          <Badge variant={stmt.status === 'reconciled' ? 'default' : 'secondary'} className="text-xs">
            {stmt.status === 'reconciled'
              ? t('finance.statement.status_reconciled')
              : t('finance.statement.status_pending')}
          </Badge>
          <div className="flex items-center gap-1" onClick={e => e.stopPropagation()}>
            {stmt.status !== 'reconciled' && (
              <Button
                size="sm"
                variant="outline"
                className="h-7 text-xs gap-1"
                onClick={handleReconcile}
                disabled={reconcile.isPending}
              >
                <RefreshCw className={`w-3 h-3 ${reconcile.isPending ? 'animate-spin' : ''}`} />
                {t('finance.statement.reconcile')}
              </Button>
            )}
            <Button size="sm" variant="ghost" className="h-7 w-7 p-0 text-muted-foreground hover:text-destructive" onClick={handleDelete}>
              <Trash2 className="w-3 h-3" />
            </Button>
          </div>
        </div>
      </div>

      {expanded && (
        <div className="border-t">
          {linesLoading ? (
            <div className="p-4 space-y-2">
              {[1, 2, 3].map(i => <Skeleton key={i} className="h-8" />)}
            </div>
          ) : !lines || lines.length === 0 ? (
            <div className="p-4 text-center text-sm text-muted-foreground">{t('generated.net_strok')}</div>
          ) : (
            <div className="overflow-x-auto">
              <table className="w-full">
                <thead className="bg-muted/30">
                  <tr>
                    <th className="text-left p-2 text-xs font-medium">{t('finance.statement.line_date')}</th>
                    <th className="text-left p-2 text-xs font-medium">{t('finance.statement.line_amount')}</th>
                    <th className="text-left p-2 text-xs font-medium">{t('finance.statement.line_direction')}</th>
                    <th className="text-left p-2 text-xs font-medium">{t('finance.statement.line_counterparty')}</th>
                    <th className="text-left p-2 text-xs font-medium">{t('finance.statement.line_purpose')}</th>
                    <th className="text-left p-2 text-xs font-medium">{t('finance.statement.line_reference')}</th>
                    <th className="text-left p-2 text-xs font-medium">{t('generated.kategoriya')}</th>
                    <th className="text-left p-2 text-xs font-medium">{t('finance.statement.line_invoice')}</th>
                    <th className="text-left p-2 text-xs font-medium">{t('finance.statement.line_status')}</th>
                    <th className="text-left p-2 text-xs font-medium" />
                  </tr>
                </thead>
                <tbody>
                  {paginatedLines.map(line => (
                    <StatementLineRow key={line.id} line={line} invoices={invoices as any} categories={categories} />
                  ))}
                </tbody>
              </table>
              <TableFooterPagination
                shownCount={paginatedLines.length}
                totalCount={(lines || []).length}
                rowsPerPage={lineRowsPerPage}
                onRowsPerPageChange={(v) => { setLineRowsPerPage(v); setLinePage(1); }}
                currentPage={linePage}
                onPageChange={setLinePage}
                className="flex items-center justify-between px-3 py-2 border-t border-border"
              />
            </div>
          )}
        </div>
      )}

      {/* Диалог выбора счёта для авто-реконсиляции */}
      {showReconcileDialog && (
        <ReconcileDialog
          open={showReconcileDialog}
          onOpenChange={setShowReconcileDialog}
          onConfirm={handleReconcileWithAccount}
          defaultAccount={stmt.account || undefined}
          isPending={reconcile.isPending}
        />
      )}
    </div>
  );
}

// ───────── Dialog for account selection in auto-reconcile ─────────
function ReconcileDialog({
  open,
  onOpenChange,
  onConfirm,
  defaultAccount,
  isPending,
}: {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onConfirm: (account: string | null) => void;
  defaultAccount?: string;
  isPending: boolean;
}) {
  const { t } = useTranslation();
  const [account, setAccount] = useState(defaultAccount || '');

  const handleStart = () => {
    onConfirm(account || null);
  };

  const handleSkip = () => {
    onConfirm(null); // Без счёта — искать по контрагенту
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-md">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <RefreshCw className="w-5 h-5" />
            {t('finance.statement.reconcile_title') || 'Авто-разноска'}
          </DialogTitle>
          <DialogDescription>
            {t('finance.statement.reconcile_description') || 
              'Выберите счёт для автоматической разноски платежей'}
          </DialogDescription>
        </DialogHeader>

        <div className="space-y-4 py-4">
          <div>
            <label className="text-sm font-medium block mb-2">
              {t('finance.statement.account_number') || 'Номер счёта'}
            </label>
            <input
              className="w-full border rounded-md px-3 py-2 text-sm bg-background"
              placeholder="40702810001990005180"
              value={account}
              onChange={e => setAccount(e.target.value)}
              maxLength={20}
            />
            <p className="text-xs text-muted-foreground mt-1">
              {t('finance.statement.reconcile_hint') || 
                'Оставьте пустым для поиска по контрагенту'}
            </p>
          </div>

          <div className="flex items-center gap-2 p-3 border rounded-lg bg-muted/30">
            <AlertCircle className="w-4 h-4 text-amber-600" />
            <p className="text-sm text-muted-foreground">
              {t('finance.statement.reconcile_info') || 
                'Система автоматически привяжет платежи к счетам по сумме'}
            </p>
          </div>
        </div>

        <DialogFooter className="gap-2">
          <Button variant="outline" onClick={handleSkip} disabled={isPending}>
            {t('generated.bez_scheta') || 'Без счёта'}
          </Button>
          <Button variant="outline" onClick={() => onOpenChange(false)} disabled={isPending}>
            {t('generated.otmena') || 'Отмена'}
          </Button>
          <Button onClick={handleStart} disabled={isPending} className="gap-2">
            {isPending ? (
              <>
                <div className="w-4 h-4 border-2 border-current border-t-transparent rounded-full animate-spin" />
