﻿// frontend/src/modules/finance/components/CreateInvoiceSheet.tsx
import { useState, useEffect } from "react";
import { Trash2, Receipt, ArrowUpRight, ArrowDownLeft } from "lucide-react";
import { useTranslation } from '@/lib/i18n';
import { useToast } from '@/hooks/use-toast';
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { ContractorSheet } from "@/modules/contractors";
import { ResizableSheet } from "@/components/shared";
import type { InvoiceType } from "../types/finance.types";
import type { InvoiceFormValues } from "./invoiceFormSchema";
import { useCreateInvoiceSheet } from "../hooks/useCreateInvoiceSheet";
import { InvoiceFormContent } from "./InvoiceFormContent";
import { ConfirmDialog } from '@/components/shared/ConfirmDialog';

interface CreateInvoiceSheetProps {
  open?: boolean;
  onOpenChange?: (open: boolean) => void;
  invoice?: any | null;
  onSave?: (invoice: any) => Promise<void>;
  onDelete?: (id: string | number) => Promise<void>;
  onRefetch?: () => Promise<void>;
  defaultInvoiceType?: InvoiceType;
}

export function CreateInvoiceSheet(props: CreateInvoiceSheetProps) {
  const {
    t,
    currencies,
    invoiceType, setInvoiceType,
    open, setOpen,
    contractors, projects,
    contractorSheetOpen, pendingContractorName,
    form, watchedCurrency,
    createInvoiceMutation,
    onSubmit,
    handleContractorCreate,
    handleContractorSheetClose,
    handleContractorSheetSave,
    invoiceStatuses,
    updateInvoiceStatus,
    unlinkPaymentFromInvoice,
  } = useCreateInvoiceSheet(props);

  const { toast } = useToast();

  const { invoice: existingInvoice, onDelete } = props;

  // Обновляем статус только при сохранении формы
  const [selectedStatus, setSelectedStatus] = useState<string | undefined>(existingInvoice?.status);

  // Диалог подтверждения отвязки платежа
  const [showUnlinkDialog, setShowUnlinkDialog] = useState(false);
  const [pendingStatus, setPendingStatus] = useState<string | null>(null);
  const [unlinkLoading, setUnlinkLoading] = useState(false);

  // Синхронизируем статус при открытии формы
  useEffect(() => {
    if (existingInvoice?.status) {
      setSelectedStatus(existingInvoice.status);
      form.setValue('status', existingInvoice.status);
    }
  }, [existingInvoice?.status, form]);

  const handleStatusChange = (newStatus: string) => {
    // Если счет был оплачен и мы меняем статус - нужно отвязать платеж
    if (existingInvoice?.status === 'paid' && existingInvoice.paymentId) {
      setPendingStatus(newStatus);
      setShowUnlinkDialog(true);
      return;
    }

    setSelectedStatus(newStatus);
    // Обновляем значение в форме
    form.setValue('status', newStatus);
    // Не вызываем API здесь - статус обновится при сохранении
  };

  const handleUnlinkAndChangeStatus = async () => {
    if (!pendingStatus || !existingInvoice?.paymentId) return;

    setUnlinkLoading(true);
    try {
      await unlinkPaymentFromInvoice(existingInvoice.paymentId);
      toast({
        title: t('finance.statement.invoice_unlinked'),
      });

      // Обновляем статус после отвязки
      setSelectedStatus(pendingStatus);
      form.setValue('status', pendingStatus);
    } catch (error) {
      console.error('Error unlinking payment:', error);
      toast({
        title: t('general.toast.error.payment_unlink'),
        variant: 'destructive',
      });
    } finally {
      setUnlinkLoading(false);
      setShowUnlinkDialog(false);
      setPendingStatus(null);
    }
  };

  const handleSubmit = async (data: InvoiceFormValues) => {
    console.log('handleSubmit called with data:', data);
    console.log('data.status:', data.status);
    console.log('selectedStatus:', selectedStatus);
    // Статус обновляется вместе с формой через onSubmit
    await onSubmit(data);
  };

  return (
    <>
      <ResizableSheet
        open={open}
        onOpenChange={setOpen}
        onSave={form.handleSubmit(handleSubmit)}
        onDelete={existingInvoice && onDelete ? async () => {
          await onDelete(existingInvoice.id);
          setOpen(false);
        } : undefined}
        title={existingInvoice ? t("finance.invoice.edit") : t("finance.invoice.create")}
        description={existingInvoice ? existingInvoice.identifier : t("finance.invoice_type.label")}
        moduleKey="invoice-sheet"
        defaultWidth="lg"
        showDeleteButton={!!(existingInvoice && onDelete)}
        saveButtonLabel={createInvoiceMutation.isPending
          ? (existingInvoice ? t('finance.buttons.saving') : t('finance.buttons.creating'))
          : (existingInvoice ? t("finance.action.save") : t("finance.action.create"))}
        cancelButtonLabel="finance.action.cancel"
        hasUnsavedChanges={form.formState.isDirty}
      >
        <div className="space-y-6">
          {/* Invoice type toggle */}
          <div className="flex gap-2">
            {(["outgoing", "incoming"] as InvoiceType[]).map((type) => (
              <button
                key={type}
                type="button"
                onClick={() => setInvoiceType(type)}
                className={`flex-1 flex items-center justify-center gap-1.5 rounded-md border px-3 py-2 text-sm font-medium transition-colors ${
                  invoiceType === type
                    ? "border-primary bg-primary text-primary-foreground"
                    : "border-border bg-background hover:bg-muted"
                }`}
              >
                {type === "outgoing" ? (
                  <ArrowUpRight className="w-3.5 h-3.5" />
                ) : (
                  <ArrowDownLeft className="w-3.5 h-3.5" />
                )}
                {t(`finance.invoice_type.${type}`)}
              </button>
            ))}
          </div>

          {/* Status badge */}
          {existingInvoice && (
            <div className="flex items-center gap-2">
              <Receipt className="w-4 h-4 text-muted-foreground shrink-0" />
              <Badge variant="outline" className="text-xs">
                {t(`finance.invoice.status.${selectedStatus || existingInvoice.status}`)}
              </Badge>
            </div>
          )}

          {/* Form content */}
          <InvoiceFormContent
            form={form}
            watchedCurrency={watchedCurrency}
            contractors={(contractors ?? []) as { id: number; name: string }[]}
            projects={(projects ?? []) as { id: number; name: string }[]}
            currencies={currencies}
            statuses={invoiceStatuses}
            existingStatus={existingInvoice?.status}
            onStatusChange={handleStatusChange}
            onContractorCreate={handleContractorCreate}
          />
        </div>
      </ResizableSheet>

      <ContractorSheet
        contractor={null}
        initialName={pendingContractorName}
        open={contractorSheetOpen}
        onOpenChange={handleContractorSheetClose}
        onSave={handleContractorSheetSave}
      />

      {/* Dialog подтверждения отвязки платежа */}
      <ConfirmDialog
        open={showUnlinkDialog}
        onOpenChange={setShowUnlinkDialog}
        onConfirm={handleUnlinkAndChangeStatus}
        title={t('finance.statement.unlink_invoice')}
        description={t('finance.statement.unlink_invoice_confirm')}
        confirmText={t('common.confirm')}
        cancelText={t('common.cancel')}
        variant="destructive"
        loading={unlinkLoading}
      />
    </>
  );
}

import { useState, useMemo } from 'react';
