        )}
        {canDelete && (
          <button className="h-5 w-5 rounded hover:bg-red-100 text-destructive flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity" title={t('generated.udalit')} onClick={() => handleDelete(cat)}>
