// ───────── Main Component ─────────
export function DebtsDashboard() {
  const { t } = useTranslation();
  const [actContractorId, setActContractorId] = useState<string | null>(null);
  const [actContractorName, setActContractorName] = useState('');
  const [selectedContractorId, setSelectedContractorId] = useState('all');

  const [debtPage, setDebtPage] = useState(1);
  const [debtRowsPerPage, setDebtRowsPerPage] = useState('25');

  const { data: receivables, isLoading } = useReceivablesReport('contractor');
  const { contractors } = useContractors();

  const overdue = useMemo(
    () => (receivables || []).filter(r => r.maxOverdueDays > 0).sort((a, b) => b.maxOverdueDays - a.maxOverdueDays),
    [receivables]
  );
  const upcoming = useMemo(
    () => (receivables || []).filter(r => r.maxOverdueDays === 0),
    [receivables]
  );

  const filtered = useMemo(() => {
    if (selectedContractorId === 'all') return receivables || [];
    return (receivables || []).filter(r => String(r.contractorId) === selectedContractorId);
  }, [receivables, selectedContractorId]);


  useEffect(() => { setDebtPage(1); }, [selectedContractorId]);

  const debtPerPage = parseRowsPerPage(debtRowsPerPage);
  const paginatedFiltered = filtered.slice((debtPage - 1) * debtPerPage, debtPage * debtPerPage);

  const totalOverdue = overdue.reduce((s, r) => s + r.totalDue, 0);
  const totalUpcoming = upcoming.reduce((s, r) => s + r.totalDue, 0);

  return (
    <div className="space-y-6">
      {/* Summary cards */}
      <div className="grid grid-cols-2 gap-4">
        <div className="titan-card p-4">
          <div className="flex items-center gap-2 mb-1">
            <TrendingDown className="w-4 h-4 text-destructive" />
            <span className="text-sm text-muted-foreground">{t('finance.debts.overdue')}</span>
          </div>
          <div className="text-2xl font-bold text-destructive">{fmt(totalOverdue)}</div>
          <div className="text-xs text-muted-foreground">{overdue.length} контрагентов</div>
        </div>
        <div className="titan-card p-4">
          <div className="flex items-center gap-2 mb-1">
            <TrendingUp className="w-4 h-4 text-amber-500" />
            <span className="text-sm text-muted-foreground">{t('finance.debts.upcoming')}</span>
          </div>
          <div className="text-2xl font-bold text-amber-600">{fmt(totalUpcoming)}</div>
          <div className="text-xs text-muted-foreground">{upcoming.length} контрагентов</div>
        </div>
      </div>

      {/* Filter + act button */}
      <div className="flex items-center gap-3 flex-wrap">
        <Select value={selectedContractorId} onValueChange={setSelectedContractorId}>
          <SelectTrigger className="w-60 h-8">
            <SelectValue placeholder={t('generated.kontragent')} />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="all">{t('generated.vse_kontragenty')}</SelectItem>
            {(contractors || []).map(c => (
              <SelectItem key={c.id} value={String(c.id)}>{c.name}</SelectItem>
            ))}
          </SelectContent>
        </Select>

        {selectedContractorId !== 'all' && (
          <Button
            size="sm"
            variant="outline"
            className="gap-2"
            onClick={() => {
              const c = (contractors || []).find(c => String(c.id) === selectedContractorId);
              setActContractorId(selectedContractorId);
              setActContractorName(c?.name || '');
            }}
          >
            <FileText className="w-4 h-4" />
            {t('finance.debts.generate_act')}
          </Button>
        )}
      </div>

      {/* List */}
      {isLoading ? (
        <div className="space-y-3">
          {[1, 2, 3].map(i => <Skeleton key={i} className="h-16 rounded-lg" />)}
        </div>
      ) : filtered.length === 0 ? (
        <div className="titan-card p-8 text-center text-muted-foreground">
          {t('finance.debts.no_debts')}
        </div>
      ) : (
        <div className="space-y-2">
          {/* Overdue first */}
          {overdue.length > 0 && selectedContractorId === 'all' && (
            <p className="text-xs font-medium text-destructive uppercase tracking-wide px-1">
              Просроченные ({overdue.length})
            </p>
          )}
          {paginatedFiltered.map((item, idx) => (
            <DebtRow key={idx} item={item} />
          ))}
          <TableFooterPagination
            shownCount={paginatedFiltered.length}
            totalCount={filtered.length}
            rowsPerPage={debtRowsPerPage}
            onRowsPerPageChange={(v) => { setDebtRowsPerPage(v); setDebtPage(1); }}
            currentPage={debtPage}
            onPageChange={setDebtPage}
            className="flex items-center justify-between p-2 border border-border rounded-lg mt-2"
          />
        </div>
      )}

      {/* Reconciliation act modal */}
      {actContractorId && (
        <ReconciliationActSheet
          contractorId={actContractorId}
          contractorName={actContractorName}
          onClose={() => setActContractorId(null)}
        />
      )}
    </div>
  );
}

import { Invoice } from '../types/finance.types';
import { useTranslation } from '@/lib/i18n';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table';
import { Checkbox } from '@/components/ui/checkbox';
import { Badge } from '@/components/ui/badge';
import { ArrowUpDown, Eye, Pencil, Trash2 } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { QuickActionsMenu } from '@/components/ui/QuickActionsMenu';
import { QuickAction } from '@/lib/settings-data';
import { SortableTableHead } from '@/components/shared';
import { useColumnDrag } from '@/hooks/useColumnDrag';
import { useCallback } from 'react';

interface InvoicesTableProps {
  invoices: Invoice[];
  visibleColumns: Record<string, boolean>;
  columnOrder?: string[];
  onReorderColumn?: (fromKey: string, toKey: string) => void;
  selectedIds: Set<string | number>;
  toggleSelection: (id: string | number) => void;
  toggleAllSelection: () => void;
  onEdit: (invoice: Invoice) => void;
  quickActions: QuickAction[];
  onQuickAction: (actionType: string, id: string | number) => Promise<void>;
  sortConfig: { key: string; direction: 'asc' | 'desc' } | null;
  onSort: (key: string) => void;
  statuses: Array<{ id: string; name: string; color?: string }>;
  columnWidths?: Record<string, number>;
  onColumnResize?: (key: string, width: number) => void;
}

export function InvoicesTable({
  invoices,
  visibleColumns,
  columnOrder,
  onReorderColumn,
  selectedIds,
  toggleSelection,
  toggleAllSelection,
  onEdit,
  quickActions,
  onQuickAction,
  sortConfig,
  onSort,
  statuses,
  columnWidths,
  onColumnResize,
}: InvoicesTableProps) {
  const { t } = useTranslation();

  const handleReorder = useCallback((from: string, to: string) => {
    onReorderColumn?.(from, to);
  }, [onReorderColumn]);
  const { dragging, dragOver, onColumnMouseDown, onColumnMouseEnter } = useColumnDrag(handleReorder);

  const parseAmount = (value: unknown): number => {
    if (typeof value === 'number') return value;
    if (typeof value !== 'string') return NaN;
    const normalized = value.replace(/\s/g, '').replace(',', '.');
    return Number(normalized);
  };

  const statusMap = statuses.reduce((acc, status) => {
    acc[status.id] = status;
    return acc;
  }, {} as Record<string, { id: string; name: string; color?: string }>);

  const SortHeader = ({ colKey, label, sortKey }: { colKey: string; label: string; sortKey: string }) => (
    <SortableTableHead
      columnKey={colKey}
      label={label}
      onSort={() => onSort(sortKey)}
      direction={sortConfig?.key === sortKey ? sortConfig.direction : null}
      isDragging={dragging === colKey}
      isDragOver={dragOver === colKey}
      onColumnMouseDown={onColumnMouseDown}
      onColumnMouseEnter={onColumnMouseEnter}
      width={columnWidths?.[colKey]}
      onResize={onColumnResize ? (w) => onColumnResize(colKey, w) : undefined}
    />
  );

  const orderedKeys = columnOrder ?? Object.keys(visibleColumns);

  return (
    <div className="titan-card">
      <Table>
        <TableHeader>
          <TableRow>
            <TableHead className="w-12">
              <Checkbox
                checked={invoices.length > 0 && selectedIds.size === invoices.length}
                onCheckedChange={() => toggleAllSelection()}
              />
            </TableHead>
            {orderedKeys.map(key => {
              if (!visibleColumns[key]) return null;
              switch (key) {
                case 'identifier': return <SortHeader key={key} colKey={key} label={t('finance.table.identifier')} sortKey="identifier" />;
                case 'contractor': return <SortHeader key={key} colKey={key} label={t('finance.table.contractor')} sortKey="contractorName" />;
                case 'project':    return <SortHeader key={key} colKey={key} label={t('finance.table.project')} sortKey="projectName" />;
                case 'amount':     return <SortHeader key={key} colKey={key} label={t('finance.table.amount')} sortKey="amount" />;
                case 'status':     return <SortHeader key={key} colKey={key} label={t('finance.table.status')} sortKey="status" />;
                case 'issueDate':  return <SortHeader key={key} colKey={key} label={t('finance.table.issue_date')} sortKey="issueDate" />;
                case 'dueDate':    return <SortHeader key={key} colKey={key} label={t('finance.table.due_date')} sortKey="dueDate" />;
                default:           return null;
              }
            })}
            <TableHead className="w-12" />
          </TableRow>
        </TableHeader>
        <TableBody>
          {invoices.length === 0 ? (
            <TableRow>
              <TableCell colSpan={Object.values(visibleColumns).filter(Boolean).length + 2} className="text-center py-8 text-muted-foreground">
                {t('finance.no_invoices')}
              </TableCell>
            </TableRow>
          ) : (
            invoices.map((invoice) => (
              <TableRow key={invoice.id} className="cursor-pointer hover:bg-muted/50">
                <TableCell onClick={(e) => e.stopPropagation()}>
                  <Checkbox
                    checked={selectedIds.has(invoice.id)}
                    onCheckedChange={() => toggleSelection(invoice.id)}
                  />
                </TableCell>
                {orderedKeys.map(key => {
                  if (!visibleColumns[key]) return null;
                  switch (key) {
                    case 'identifier': return (
                      <TableCell key={key} onClick={() => onEdit(invoice)} className="font-semibold">
                        {invoice.identifier}
                      </TableCell>
                    );
                    case 'contractor': return (
                      <TableCell key={key} onClick={() => onEdit(invoice)}>
                        {invoice.contractorName}
                      </TableCell>
                    );
                    case 'project': return (
                      <TableCell key={key} onClick={() => onEdit(invoice)}>
                        {invoice.projectName || '—'}
                      </TableCell>
                    );
                    case 'amount': return (
                      <TableCell key={key} onClick={() => onEdit(invoice)} className="font-medium">
                        {(() => {
                          const amount = parseAmount((invoice as any).amount ?? invoice.amountTotal);
                          if (!Number.isFinite(amount)) return '—';
                          const currency = (invoice as any).currency || 'RUB';
                          return new Intl.NumberFormat('ru-RU', {
                            style: 'currency',
                            currency: currency,
                            minimumFractionDigits: 2,
                            maximumFractionDigits: 2,
                          }).format(amount);
                        })()}
                      </TableCell>
                    );
                    case 'status': return (
                      <TableCell key={key} onClick={() => onEdit(invoice)}>
                        <Badge variant="outline">
                          {statusMap[invoice.status]?.name || t(`finance.invoice.status.${invoice.status}`) || invoice.status}
                        </Badge>
                      </TableCell>
                    );
                    case 'issueDate': return (
                      <TableCell key={key} onClick={() => onEdit(invoice)}>
                        {new Date(invoice.issueDate).toLocaleDateString('ru-RU')}
                      </TableCell>
                    );
                    case 'dueDate': return (
                      <TableCell key={key} onClick={() => onEdit(invoice)}>
                        <div className="flex flex-col">
                          <span>{invoice.dueDate ? new Date(invoice.dueDate).toLocaleDateString('ru-RU') : '—'}</span>
                          {invoice.status === 'overdue' && invoice.overdueSince && (
                            <span className="text-xs text-destructive">
                              Просрочен с {new Date(invoice.overdueSince).toLocaleDateString('ru-RU')}
                            </span>
                          )}
                        </div>
                      </TableCell>
                    );
                    default: return null;
                  }
                })}
                <TableCell onClick={(e) => e.stopPropagation()} className="w-[40px] shrink-0">
                  <QuickActionsMenu
                    itemId={invoice.id}
                    itemName={invoice.identifier}
                    options={[
                      ...quickActions.map(a => ({
                        label: a.name, action: a.action, icon: a.icon, isQuickAction: true,
                      })),
                      { label: 'Просмотреть', action: 'view', icon: 'Eye', isQuickAction: false },
                      { label: 'Редактировать', action: 'edit', icon: 'Pencil', isQuickAction: false },
                      { label: 'Удалить', action: 'delete', icon: 'Trash2', isQuickAction: false, variant: 'destructive' as const },
                    ]}
                    onAction={(actionType, itemId) => void onQuickAction(actionType, itemId)}
                  />
                </TableCell>
              </TableRow>
            ))
          )}
        </TableBody>
      </Table>
    </div>
  );
}

import { Payment } from '../types/finance.types';
import { useTranslation } from '@/lib/i18n';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table';
import { Checkbox } from '@/components/ui/checkbox';
import { ArrowUpDown, Download, Upload, Eye, Pencil, Trash2 } from 'lucide-react';
