  return useMutation({
    mutationFn: (data: Parameters<typeof financeApi.importStatement>[0]) =>
      financeApi.importStatement(data),
    onSuccess: (result) => {
      queryClient.invalidateQueries({ queryKey: ['bankStatements'] });
      queryClient.invalidateQueries({ queryKey: ['contractors'] });
      queryClient.invalidateQueries({ queryKey: ['payments'] });
      queryClient.invalidateQueries({ queryKey: ['ddsReport'] });

      const parts: string[] = [];
      parts.push(`✅ Импортировано ${result.linesCount} строк`);

      if (result.contractorsCreated > 0) {
        parts.push(`👥 Создано контрагентов: ${result.contractorsCreated}`);
      }
      if (result.paymentsCreated > 0) {
        parts.push(`💰 Создано платежей: ${result.paymentsCreated}`);
      }
      if (result.duplicatesSkipped > 0) {
        parts.push(`⚠️ Пропущено дубликатов: ${result.duplicatesSkipped}`);
      }

      // Новые поля (если бэкенд их возвращает)
      if ('contractorsUpdated' in result && result.contractorsUpdated > 0) {
        parts.push(`🔄 Обновлено контрагентов: ${result.contractorsUpdated}`);
      }
      if ('newAccountsAdded' in result && result.newAccountsAdded > 0) {
        parts.push(`🏦 Добавлено счетов: ${result.newAccountsAdded}`);
      }
      if ('warningsCount' in result && result.warningsCount > 0) {
        parts.push(`❗ Предупреждений: ${result.warningsCount}`);
      }

      const title = result.duplicatesSkipped > 0 || result.warningsCount > 0
        ? 'Импорт завершён с предупреждениями'
        : 'Импорт успешно завершён';

      toast({ 
        title, 
        description: parts.join('. ') + '.',
        variant: result.duplicatesSkipped > 0 || result.warningsCount > 0 ? 'default' : 'default',
      });
    },
    onError: (error: any) => {
      toast({ title: t('general.toast.error.data_load'), description: error?.message, variant: 'destructive' });
