      { id: "outgoing",   label: "finance.tabs.invoices_outgoing", icon: ArrowUpFromLine, visible: true },
      { id: "incoming",   label: "finance.tabs.invoices_incoming", icon: ArrowDownToLine, visible: true },
      { id: "payments",   label: "finance.tabs.payments",          icon: DollarSign,      visible: true },
      { id: "statements", label: "finance.tabs.statements",        icon: Landmark,        visible: true },
      { id: "debts",      label: "finance.tabs.debts",             icon: CreditCard,      visible: true },
      { id: "dds",        label: "finance.tabs.dds",               icon: BarChart3,       visible: true },
      { id: "reports",    label: "finance.tabs.reports",           icon: BookOpen,        visible: true },
    ],
  });

  // ── Derived lists ─────────────────────────────────────────────
  const invoiceStatuses = useMemo(() => [
    { id: "draft",        name: t("finance.invoice.status.draft") },
    { id: "sent",         name: t("finance.invoice.status.sent") },
    { id: "partial_paid", name: t("finance.invoice.status.partial_paid") },
    { id: "paid",         name: t("finance.invoice.status.paid") },
    { id: "overdue",      name: t("finance.invoice.status.overdue") },
  ], [t]);

  const financeQuickActions = getQuickActionsByModule("finance");

  const outgoingInvoices = useFilteredInvoices({
    invoices,
    invoiceType: "outgoing",
    searchQuery: outgoingTable.searchQuery,
    sortConfig: outgoingTable.sortConfig,
    statusFilter,
    contractorFilter,
    periodRange,
  });

  const incomingInvoices = useFilteredInvoices({
    invoices,
    invoiceType: "incoming",
    searchQuery: incomingTable.searchQuery,
    sortConfig: null,
    statusFilter,
    contractorFilter,
    periodRange,
  });

  const filteredPayments = useFilteredPayments({
    payments,
    invoices,
    searchQuery: paymentsTable.searchQuery,
    sortConfig: paymentsTable.sortConfig,
    paymentKindFilter,
    periodRange,
    paymentContractorFilter,
    amountFrom,
    amountTo,
    debtorOnly,
  });

  // ── Effects ───────────────────────────────────────────────────
  // Auto-switch to first visible tab when active tab becomes hidden
  useEffect(() => {
    const visible = financeTabsTable.tabsConfig.filter((tab) => tab.visible);
    if (visible.length > 0 && !visible.find((tab) => tab.id === activeTab)) {
      setActiveTab(visible[0].id as ActiveTab);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [financeTabsTable.tabsConfig]);

  // Page resets on filter / page-size changes
  // eslint-disable-next-line react-hooks/exhaustive-deps
  useEffect(() => { outgoingTable.setCurrentPage(1); }, [statusFilter, contractorFilter, outgoingTable.rowsPerPage]);
  // eslint-disable-next-line react-hooks/exhaustive-deps
  useEffect(() => { incomingTable.setCurrentPage(1); }, [statusFilter, contractorFilter, incomingTable.rowsPerPage]);
  // eslint-disable-next-line react-hooks/exhaustive-deps
  useEffect(() => { paymentsTable.setCurrentPage(1); }, [paymentKindFilter, paymentContractorFilter, amountFrom, amountTo, paymentsTable.rowsPerPage]);

  // ── Pagination ────────────────────────────────────────────────
  const outgoingPerPage = parseRowsPerPage(outgoingTable.rowsPerPage);
  const incomingPerPage = parseRowsPerPage(incomingTable.rowsPerPage);
  const paymentsPerPage = parseRowsPerPage(paymentsTable.rowsPerPage);

  const paginatedOutgoing = outgoingInvoices.slice(
    (outgoingTable.currentPage - 1) * outgoingPerPage,
    outgoingTable.currentPage * outgoingPerPage,
  );
  const paginatedIncoming = incomingInvoices.slice(
    (incomingTable.currentPage - 1) * incomingPerPage,
    incomingTable.currentPage * incomingPerPage,
  );
  const paginatedPayments = filteredPayments.slice(
    (paymentsTable.currentPage - 1) * paymentsPerPage,
    paymentsTable.currentPage * paymentsPerPage,
  );

  // ── Stats ─────────────────────────────────────────────────────
  const totalReceivables = useMemo(
    () => (receivablesReport || []).reduce((s, r) => s + r.totalDue, 0),
    [receivablesReport],
  );
  const overdueCount = useMemo(
    () => (receivablesReport || []).filter((r) => r.maxOverdueDays > 0).length,
    [receivablesReport],
  );
  const paidCount = useMemo(
    () => (invoices || []).filter((i) => i.status === "paid").length,
    [invoices],
  );

  // ── Column labels ─────────────────────────────────────────────
  const invoiceColumnLabels = {
    identifier:  t("finance.table.identifier"),
    contractor:  t("finance.table.contractor"),
    project:     t("finance.table.project"),
    amount:      t("finance.table.amount"),
    status:      t("finance.table.status"),
    issueDate:   t("finance.table.issue_date"),
    dueDate:     t("finance.table.due_date"),
  };

  const paymentColumnLabels = {
    kind:              t("finance.table.kind"),
    description:       t("finance.table.description"),
    amount:            t("finance.table.amount"),
    invoiceIdentifier: t("finance.table.invoice"),
    contractorName:    t("finance.table.payer"),
    projectName:       t("finance.table.project"),
    taskTitle:         t("finance.table.task"),
    paymentDate:       t("finance.table.payment_date"),
    paymentMethod:     t("finance.table.payment_method"),
  };

  // ── CRUD handlers ─────────────────────────────────────────────
  const handleBulkDeleteInvoices = async (table: typeof outgoingTable) => {
    if (!confirm(t('finance.confirm.delete_invoices', { count: table.selectedIds.size }))) return;
    try {
      await Promise.all(Array.from(table.selectedIds).map((id) => api.delete(`/finance/invoices/${id}`)));
      await refetchInvoices();
      toast.success(t("general.toast.success.invoices_deleted", [table.selectedIds.size]));
      table.clearSelection();
    } catch {
      toast.error(t("generated.oshibka_pri_udalenii_schetov"));
    }
  };

  const handleBulkDeletePayments = async () => {
    if (!confirm(t('finance.confirm.delete_payments', { count: paymentsTable.selectedIds.size }))) return;
    try {
      await Promise.all(
        Array.from(paymentsTable.selectedIds).map((id) => api.delete(`/finance/payments/${id}`)),
      );
      await refetchPayments();
      toast.success(t("general.toast.success.payments_deleted", [paymentsTable.selectedIds.size]));
      paymentsTable.clearSelection();
    } catch {
      toast.error(t("generated.oshibka_pri_udalenii_platezhey"));
    }
  };

  const handleBulkUpdateInvoices = async (field: string, value: string) => {
    if (!outgoingTable.selectedIds.size && !incomingTable.selectedIds.size) return;

    const selectedIds = activeTab === 'outgoing' 
      ? Array.from(outgoingTable.selectedIds) 
      : Array.from(incomingTable.selectedIds);

    try {
      const updates = { [field]: value };
      await api.post('/finance/invoices/bulk-update', { ids: selectedIds, updates });
      await refetchInvoices();
      toast.success(t('generated.zapis_obnovlen'));
      activeInvoiceTable.clearSelection();
    } catch (e) {
      console.error(e);
      toast.error(t('generated.oshibka_sohraneniya'));
    }
  };

  const handleBulkUpdatePayments = async (field: string, value: string) => {
    if (!paymentsTable.selectedIds.size) return;

    try {
      const updates = { [field]: value };
      await api.post('/finance/payments/bulk-update', { 
        ids: Array.from(paymentsTable.selectedIds), 
        updates 
      });
      await refetchPayments();
      toast.success(t('generated.zapis_obnovlen'));
      paymentsTable.clearSelection();
    } catch (e) {
      console.error(e);
      toast.error(t('generated.oshibka_sohraneniya'));
    }
  };

  const handleDeleteInvoice = async (id: string | number) => {
    if (!confirm(t("generated.udalit_schet"))) return;
    await api.delete(`/finance/invoices/${id}`);
    await refetchInvoices();
    toast.success(t("generated.schet_udalen"));
  };

  const handleDeletePayment = async (id: string | number) => {
    if (!confirm(t("generated.udalit_platezh"))) return;
    await api.delete(`/finance/payments/${id}`);
    await refetchPayments();
    toast.success(t("generated.platezh_udalen"));
  };

  const handleSaveInvoice = async (invoice: any) => {
    if (invoice.id) {
      await api.put(`/finance/invoices/${invoice.id}`, invoice);
      toast.success(t("generated.schet_obnovlen"));
    }
    setSelectedInvoice(null);
    await refetchInvoices();
  };

  const handleSavePayment = async (payment: any) => {
    if (payment.id) {
      await api.put(`/finance/payments/${payment.id}`, payment);
      toast.success(t("generated.platezh_obnovlen"));
    }
    setSelectedPayment(null);
    await refetchPayments();
  };

  const handleInvoiceQuickAction = async (actionType: string, id: string | number) => {
    const inv = (invoices || []).find((i) => String(i.id) === String(id));
    const norm = actionType.toLowerCase();

    // Create invoice (global action)
    if (norm === 'create_invoice' || norm === 'create') {
      setCreateInvoiceOpen(true);
      return;
    }

    if (norm.includes("edit") || norm.includes("open")) {
      if (inv) setSelectedInvoice(inv as any);
      return;
    }
    if (norm.includes("delete")) { await handleDeleteInvoice(id); return; }
    if (norm.includes("send")) {
      await api.post(`/finance/invoices/${id}/send`, {});
      await refetchInvoices();
      toast.success(t("generated.schet_otpravlen"));
      return;
    }
    if (norm.includes("paid") || norm.includes("mark_paid")) {
      await api.put(`/finance/invoices/${id}`, { status: "paid", amountPaid: inv?.amountTotal, amountDue: 0 });
      await refetchInvoices();
      toast.success(t("generated.schet_otmechen_oplachennym"));
      return;
    }
    if (norm.includes("generate") || norm.includes("document")) {
      await api.post(`/finance/invoices/${id}/generate-document`, { documentType: "act" });
      toast.success(t("generated.dokument_sozdan"));
      return;
    }
    if (norm.includes("payment") || norm.includes("record")) {
      setPrefillPaymentInvoiceId(id);
      setActiveTab("payments");
      setCreatePaymentOpen(true);
      return;
    }
    if (norm.includes("recalculate")) {
      await api.post(`/finance/invoices/${id}/recalculate-status`, {});
      await refetchInvoices();
      return;
    }
    toast.info(actionType);
  };

  const handlePaymentQuickAction = async (actionType: string, id: string | number) => {
    const norm = actionType.toLowerCase();
    const pay = (payments || []).find((p) => String(p.id) === String(id));
    if (norm.includes("edit") || norm.includes("open")) {
      if (pay) setSelectedPayment(pay as any);
      return;
    }
    if (norm.includes("delete")) { await handleDeletePayment(id); return; }
    toast.info(actionType);
  };

  // ── Derived helpers ───────────────────────────────────────────
  const isLoading = invoicesLoading || paymentsLoading;
  const isInvoiceTab = activeTab === "outgoing" || activeTab === "incoming";
  const activeInvoiceTable = activeTab === "outgoing" ? outgoingTable : incomingTable;
  const activeInvoiceList  = activeTab === "outgoing" ? outgoingInvoices : incomingInvoices;

  return {
    // UI state
    activeTab, setActiveTab,
    createInvoiceOpen, setCreateInvoiceOpen,
    createPaymentOpen, setCreatePaymentOpen,
    selectedInvoice, setSelectedInvoice,
    selectedPayment, setSelectedPayment,
    prefillPaymentInvoiceId, setPrefillPaymentInvoiceId,
    bulkEditOpen, setBulkEditOpen,

    // Filters — invoices
    statusFilter, setStatusFilter,
    contractorFilter, setContractorFilter,

    // Filters — payments
    paymentKindFilter, setPaymentKindFilter,
    paymentContractorFilter, setPaymentContractorFilter,
    amountFrom, setAmountFrom,
    amountTo, setAmountTo,
    debtorOnly, setDebtorOnly,

    // Period
    periodPreset, setPeriodPreset,
    customFrom, setCustomFrom,
    customTo, setCustomTo,
    periodRange,

    // Data
    invoices, contractors, invoiceStatuses, financeQuickActions,

    // Table hooks
    outgoingTable, incomingTable, paymentsTable, financeTabsTable,

    // Filtered / paginated
    outgoingInvoices, incomingInvoices, filteredPayments,
    paginatedOutgoing, paginatedIncoming, paginatedPayments,

    // Stats
    totalReceivables, overdueCount, paidCount,
    totalInvoices: (invoices || []).length,

    // Column labels
    invoiceColumnLabels, paymentColumnLabels,

    // Handlers
    handleBulkDeleteInvoices, handleBulkDeletePayments,
    handleBulkUpdateInvoices, handleBulkUpdatePayments,
    handleDeleteInvoice, handleDeletePayment,
    handleSaveInvoice, handleSavePayment,
    handleInvoiceQuickAction, handlePaymentQuickAction,
    refetchInvoices, refetchPayments,

    // Derived
    isLoading, isInvoiceTab, activeInvoiceTable, activeInvoiceList,
  };
}

// frontend/src/modules/finance/pages/FinancePage.tsx
