import { useContractors } from "@/modules/contractors";
import { useCategories } from "../hooks/useFinance";
import { Plus, DollarSign, AlertCircle, CheckCircle, FileText, BarChart3, Download, Users } from "lucide-react";
import { Skeleton } from "@/components/ui/skeleton";

export function FinancePage() {
  const { t } = useTranslation();
  const { getTagsByModule, getPrioritiesByModule } = useSettings();
  const { projects: projectsData } = useProjects();
  const { tasks: tasksData } = useTasks();
  const { contractors: contractorsData } = useContractors();
  const { data: categoriesData } = useCategories();
  const tagsData = getTagsByModule("finance") || [];
  const [showDdsCategories, setShowDdsCategories] = useState(false);
  const [reportExportFn, setReportExportFn] = useState<(() => void) | null>(null);

  const {
    // UI state
    activeTab, setActiveTab,
    createInvoiceOpen, setCreateInvoiceOpen,
    createPaymentOpen, setCreatePaymentOpen,
    selectedInvoice, setSelectedInvoice,
    selectedPayment, setSelectedPayment,
    prefillPaymentInvoiceId, setPrefillPaymentInvoiceId,
    bulkEditOpen, setBulkEditOpen,

    // Filters — invoices
    statusFilter, setStatusFilter,
    contractorFilter, setContractorFilter,

    // Filters — payments
    paymentKindFilter, setPaymentKindFilter,
    paymentContractorFilter, setPaymentContractorFilter,
    amountFrom, setAmountFrom,
    amountTo, setAmountTo,
    debtorOnly, setDebtorOnly,

    // Period
    periodPreset, setPeriodPreset,
    customFrom, setCustomFrom,
    customTo, setCustomTo,
    periodRange,

    // Data
    invoices, contractors, invoiceStatuses, financeQuickActions,

    // Table hooks
    outgoingTable, incomingTable, paymentsTable, financeTabsTable,

    // Filtered / paginated
    outgoingInvoices, incomingInvoices, filteredPayments,
    paginatedOutgoing, paginatedIncoming, paginatedPayments,

    // Stats
    totalReceivables, overdueCount, paidCount, totalInvoices,

    // Column labels
    invoiceColumnLabels, paymentColumnLabels,

    // Handlers
    handleBulkDeleteInvoices, handleBulkDeletePayments,
    handleBulkUpdateInvoices, handleBulkUpdatePayments,
    handleDeleteInvoice, handleSaveInvoice, handleSavePayment,
    handleInvoiceQuickAction, handlePaymentQuickAction,
    refetchInvoices, refetchPayments,

    // Derived
    isLoading, isInvoiceTab, activeInvoiceTable,
  } = useFinancePage();

  // ── Main action button ────────────────────────────────────────
  const mainAction = (() => {
    if (activeTab === "outgoing")
      return (
        <Button className="gap-2" onClick={() => setCreateInvoiceOpen(true)}>
          <Plus className="w-4 h-4" />
          {t("finance.invoice.create")}
        </Button>
      );
    if (activeTab === "incoming")
      return (
        <Button className="gap-2" variant="outline" onClick={() => setCreateInvoiceOpen(true)}>
          <Plus className="w-4 h-4" />
          {t("generated.vhodyaschiy_schet")}
        </Button>
      );
    if (activeTab === "payments")
      return (
        <Button className="gap-2" onClick={() => setCreatePaymentOpen(true)}>
          <Plus className="w-4 h-4" />
          {t("finance.payment.create")}
        </Button>
      );
    return null;
  })();

  // ── Filter content nodes (passed as slot props) ───────────────
  const invoiceFilterContent = (
    <InvoiceFilters
      statusFilter={statusFilter}
      onStatusChange={setStatusFilter}
      contractorFilter={contractorFilter}
      onContractorChange={setContractorFilter}
      invoiceStatuses={invoiceStatuses}
      contractors={contractors || []}
    />
  );

  const paymentFilterContent = (
    <PaymentFilters
      paymentKindFilter={paymentKindFilter}
      onPaymentKindChange={setPaymentKindFilter}
      paymentContractorFilter={paymentContractorFilter}
      onPaymentContractorChange={setPaymentContractorFilter}
      amountFrom={amountFrom}
      onAmountFromChange={setAmountFrom}
      amountTo={amountTo}
      onAmountToChange={setAmountTo}
      debtorOnly={debtorOnly}
      onDebtorOnlyChange={setDebtorOnly}
      contractors={contractors || []}
    />
  );

  // ── Shared tabs toolbar props ─────────────────────────────────
  const tabsToolbarProps = {
    tabsConfig:  financeTabsTable.tabsConfig,
    onMoveTab:   financeTabsTable.moveTab,
    onToggleTab: financeTabsTable.toggleTabVisibility,
  };

  return (
    <AppLayout
      title={t("finance.title")}
      subtitle={t("finance.subtitle")}
      breadcrumbs={[{ label: t("finance.title") }]}
      actions={mainAction}
    >
      {/* Stats */}
      <div className="grid grid-cols-2 lg:grid-cols-4 gap-4 mb-6">
        {isLoading ? (
          [1, 2, 3, 4].map((i) => <Skeleton key={i} className="h-32 rounded-lg" />)
        ) : (
          <>
            <StatsCard
              title={t("finance.stats.receivables")}
              value={new Intl.NumberFormat("ru-RU", {
                style: "currency",
                currency: "RUB",
                minimumFractionDigits: 2,
                maximumFractionDigits: 2,
              }).format(totalReceivables)}
              icon={DollarSign}
            />
            <StatsCard title={t("finance.stats.overdue")}        value={String(overdueCount)}  icon={AlertCircle} />
            <StatsCard title={t("finance.stats.paid_invoices")}  value={String(paidCount)}     icon={CheckCircle} />
            <StatsCard title={t("finance.stats.total_invoices")} value={String(totalInvoices)} icon={FileText} />
          </>
        )}
      </div>

      {/* Period filter bar */}
      <PeriodFilterBar
        preset={periodPreset}
        onPresetChange={setPeriodPreset}
        customFrom={customFrom}
        onCustomFromChange={setCustomFrom}
        customTo={customTo}
        onCustomToChange={setCustomTo}
        periodRange={periodRange}
      />

      <Tabs
        value={activeTab}
        onValueChange={(v) => setActiveTab(v as typeof activeTab)}
        className="space-y-4"
      >
        {/* Tab header: tabs list + toolbar */}
        <div className="flex justify-between items-center flex-wrap gap-3">
          <SortableTabsList
            tabsConfig={financeTabsTable.tabsConfig}
