          />

          {isInvoiceTab && (
            <DataTableToolbar
              searchQuery={activeInvoiceTable.searchQuery}
              onSearchChange={activeInvoiceTable.setSearchQuery}
              selectedCount={activeInvoiceTable.selectedIds.size}
              onCancelSelection={activeInvoiceTable.clearSelection}
              onBulkDelete={() => handleBulkDeleteInvoices(activeInvoiceTable)}
              bulkActions={
                <Button variant="outline" size="sm" onClick={() => setBulkEditOpen(true)}>
                  <Users className="w-4 h-4 mr-2" />
