          )}

          {activeTab === "payments" && (
            <DataTableToolbar
              searchQuery={paymentsTable.searchQuery}
              onSearchChange={paymentsTable.setSearchQuery}
              selectedCount={paymentsTable.selectedIds.size}
              onCancelSelection={paymentsTable.clearSelection}
              onBulkDelete={handleBulkDeletePayments}
              bulkActions={
                <Button variant="outline" size="sm" onClick={() => setBulkEditOpen(true)}>
                  <Users className="w-4 h-4 mr-2" />
                  <span className="hidden sm:inline">{t('common.bulk_edit')}</span>
                </Button>
              }
              columnLabels={paymentColumnLabels}
              visibleColumns={paymentsTable.visibleColumns}
              onToggleColumn={paymentsTable.toggleColumnVisibility}
              columnOrder={paymentsTable.columnOrder}
              onMoveColumn={paymentsTable.moveColumn}
              filters={paymentFilterContent}
              filterDropdownWidth="w-80"
              {...tabsToolbarProps}
            />
          )}

          {activeTab === "reports" && (
            <div className="flex items-center gap-2">
              {reportExportFn && (
                <Button size="sm" variant="outline" className="gap-2" onClick={reportExportFn}>
                  <Download className="w-4 h-4" />
                  {t('finance.reports.register_export')}
                </Button>
              )}
              <DataTableToolbar {...tabsToolbarProps} />
            </div>
          )}

          {/* Кнопка управления статьями + шестерёнка для ДДС */}
          {activeTab === "dds" && (
            <div className="flex items-center gap-2">
              <Button
                size="sm"
                variant="outline"
