              >
                <BarChart3 className="w-4 h-4" />
                {t('finance.dds.manage_categories')}
              </Button>
              <DataTableToolbar {...tabsToolbarProps} />
            </div>
          )}

          {/* Settings gear for tabs without their own toolbar */}
          {!isInvoiceTab && activeTab !== "payments" && activeTab !== "dds" && activeTab !== "reports" && (
            <DataTableToolbar {...tabsToolbarProps} />
          )}
        </div>

        {/* Outgoing invoices */}
        <TabsContent value="outgoing" className="m-0">
          <div className="overflow-x-auto">
            <InvoicesTable
              invoices={paginatedOutgoing}
              visibleColumns={outgoingTable.visibleColumns}
              columnOrder={outgoingTable.columnOrder}
              onReorderColumn={outgoingTable.reorderColumn}
              selectedIds={outgoingTable.selectedIds}
              toggleSelection={(id) => outgoingTable.toggleSelection(id)}
              toggleAllSelection={() => outgoingTable.toggleAllSelection(paginatedOutgoing)}
              onEdit={setSelectedInvoice}
              quickActions={financeQuickActions}
              onQuickAction={handleInvoiceQuickAction}
              sortConfig={outgoingTable.sortConfig as any}
              onSort={outgoingTable.handleSort}
              statuses={invoiceStatuses}
              columnWidths={outgoingTable.columnWidths}
              onColumnResize={outgoingTable.setColumnWidth}
            />
            <TableFooterPagination
              shownCount={paginatedOutgoing.length}
              totalCount={outgoingInvoices.length}
              rowsPerPage={outgoingTable.rowsPerPage}
              onRowsPerPageChange={outgoingTable.setRowsPerPage}
              currentPage={outgoingTable.currentPage}
              onPageChange={outgoingTable.setCurrentPage}
              className="flex items-center justify-between p-4 border-x border-b border-border rounded-b-lg"
            />
          </div>
        </TabsContent>

        {/* Incoming invoices */}
        <TabsContent value="incoming" className="m-0">
          <div className="overflow-x-auto">
            <InvoicesTable
              invoices={paginatedIncoming}
              visibleColumns={incomingTable.visibleColumns}
              columnOrder={incomingTable.columnOrder}
              onReorderColumn={incomingTable.reorderColumn}
              selectedIds={incomingTable.selectedIds}
              toggleSelection={(id) => incomingTable.toggleSelection(id)}
              toggleAllSelection={() => incomingTable.toggleAllSelection(paginatedIncoming)}
              onEdit={setSelectedInvoice}
              quickActions={financeQuickActions}
              onQuickAction={handleInvoiceQuickAction}
              sortConfig={incomingTable.sortConfig as any}
              onSort={incomingTable.handleSort}
              statuses={invoiceStatuses}
              columnWidths={incomingTable.columnWidths}
              onColumnResize={incomingTable.setColumnWidth}
            />
            <TableFooterPagination
              shownCount={paginatedIncoming.length}
              totalCount={incomingInvoices.length}
              rowsPerPage={incomingTable.rowsPerPage}
              onRowsPerPageChange={incomingTable.setRowsPerPage}
              currentPage={incomingTable.currentPage}
              onPageChange={incomingTable.setCurrentPage}
              className="flex items-center justify-between p-4 border-x border-b border-border rounded-b-lg"
            />
          </div>
        </TabsContent>

        {/* Payments */}
        <TabsContent value="payments" className="m-0">
          <div className="overflow-x-auto">
            <PaymentsTable
              payments={paginatedPayments}
              visibleColumns={paymentsTable.visibleColumns}
              columnOrder={paymentsTable.columnOrder}
              onReorderColumn={paymentsTable.reorderColumn}
              selectedIds={paymentsTable.selectedIds}
              toggleSelection={(id) => paymentsTable.toggleSelection(id)}
              toggleAllSelection={() => paymentsTable.toggleAllSelection(paginatedPayments)}
              onEdit={setSelectedPayment}
              quickActions={financeQuickActions}
              onQuickAction={handlePaymentQuickAction}
              sortConfig={paymentsTable.sortConfig as any}
              onSort={paymentsTable.handleSort}
              columnWidths={paymentsTable.columnWidths}
              onColumnResize={paymentsTable.setColumnWidth}
            />
            <TableFooterPagination
              shownCount={paginatedPayments.length}
              totalCount={filteredPayments.length}
              rowsPerPage={paymentsTable.rowsPerPage}
              onRowsPerPageChange={paymentsTable.setRowsPerPage}
              currentPage={paymentsTable.currentPage}
              onPageChange={paymentsTable.setCurrentPage}
              className="flex items-center justify-between p-4 border-x border-b border-border rounded-b-lg"
            />
          </div>
        </TabsContent>

        {/* Passive tabs — delegates rendering to dedicated components */}
        <TabsContent value="statements" className="m-0"><BankStatementsTab /></TabsContent>
        <TabsContent value="debts"      className="m-0"><DebtsDashboard /></TabsContent>
        <TabsContent value="dds"        className="m-0"><DDSTab dateFrom={periodRange.from} dateTo={periodRange.to} showCategories={showDdsCategories} /></TabsContent>
        <TabsContent value="reports"    className="m-0"><ReportsTab dateFrom={periodRange.from} dateTo={periodRange.to} onExportReady={(fn) => setReportExportFn(() => fn)} /></TabsContent>
      </Tabs>

      {/* Sheets */}
      <CreateInvoiceSheet
        open={selectedInvoice !== null || createInvoiceOpen}
        onOpenChange={(open) => {
          if (!open) { setSelectedInvoice(null); setCreateInvoiceOpen(false); }
        }}
        invoice={selectedInvoice}
        defaultInvoiceType={activeTab === "incoming" ? "incoming" : "outgoing"}
        onSave={handleSaveInvoice}
        onDelete={handleDeleteInvoice}
        onRefetch={async () => { refetchInvoices(); }}
      />

      <CreatePaymentSheet
        open={selectedPayment !== null || createPaymentOpen}
        onOpenChange={(open) => {
          if (!open) {
            setSelectedPayment(null);
            setCreatePaymentOpen(false);
            setPrefillPaymentInvoiceId(null);
          }
        }}
        payment={selectedPayment ?? undefined}
        onRefetch={async () => { refetchPayments(); }}
      />

      {/* Bulk Edit Dialog */}
      <BulkEditDialog
        open={bulkEditOpen}
        onOpenChange={setBulkEditOpen}
        onConfirm={activeTab === 'payments' ? handleBulkUpdatePayments : handleBulkUpdateInvoices}
        count={activeTab === 'payments' ? paymentsTable.selectedIds.size : activeInvoiceTable.selectedIds.size}
        moduleId="finance"
        referenceData={{
          statuses: invoiceStatuses || [],
          priorities: getPrioritiesByModule("finance") || [],
          tags: tagsData,
          users: [],
          // Для payments - передаём под разными ключами для совместимости
          expenseCategories: categoriesData || [],
          categories: categoriesData || [],
          finance_expenseCategories: categoriesData || [],
          projects: Array.isArray(projectsData) ? projectsData : (projectsData as any) || [],
          finance_projects: Array.isArray(projectsData) ? projectsData : (projectsData as any) || [],
          tasks: Array.isArray(tasksData) ? tasksData : (tasksData as any) || [],
          finance_tasks: Array.isArray(tasksData) ? tasksData : (tasksData as any) || [],
          contractors: Array.isArray(contractorsData) ? contractorsData : (contractorsData as any) || [],
          finance_contractors: Array.isArray(contractorsData) ? contractorsData : (contractorsData as any) || [],
          // Для invoices
          invoiceTypes: [
            { id: 'outgoing', name: 'Исходящий' },
            { id: 'incoming', name: 'Входящий' }
          ],
          currencies: [
            { id: 'RUB', name: 'Рубль' },
            { id: 'USD', name: 'Доллар' },
            { id: 'EUR', name: 'Евро' },
            { id: 'CNY', name: 'Юань' }
          ],
          paymentMethods: [
            { id: 'bank', name: 'Банк' },
            { id: 'cash', name: 'Наличные' },
            { id: 'card', name: 'Карта' }
          ]
        }}
      />
    </AppLayout>
  );
}

