import { useState, useEffect, useRef, useCallback } from "react";
import {
  Sheet,
  SheetContent,
  SheetHeader,
  SheetTitle,
  SheetDescription,
  SheetFooter,
} from "@/components/ui/sheet";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
  DialogFooter,
} from "@/components/ui/dialog";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Button } from "@/components/ui/button";
import { useTranslation } from "@/lib/i18n";
import { toast } from "sonner";
import { CheckCircle2, Trash2, Folder, DollarSign, Clock, FileText, MessageSquare, BarChart3, X } from "lucide-react";
import { LegalCase, CaseStatus } from "../types";
import { CaseGeneralTab } from "./case-tabs/CaseGeneralTab";
import { CaseFinanceTab } from "./case-tabs/CaseFinanceTab";
import { CaseTimelineTab } from "./case-tabs/CaseTimelineTab";
import { CaseDocumentsTab } from "./case-tabs/CaseDocumentsTab";
import { CaseNotesTab } from "./case-tabs/CaseNotesTab";
import { CaseAnalyticsTab } from "./case-tabs/CaseAnalyticsTab";
import { cn } from "@/lib/utils";
import { Contractor, ContractorSheet } from "@/modules/contractors";
import { useSheetTabs } from "@/hooks/useSheetTabs";
import { useSheetWidth } from "@/hooks/useSheetWidth";
import { SheetTabSettings } from "@/components/shared";
import { DiscardChangesDialog } from "@/components/shared";
import { useUploadedFilesTracker } from "@/components/ui/useUploadedFilesTracker";

interface CaseSheetProps {
  legalCase: LegalCase | null;
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onSave: (legalCase: LegalCase) => void;
  onDelete?: (id: string) => void;
  contractors: Contractor[];
  onAddContractor: (contractor: Contractor) => void;
}

export function CaseSheet({
  legalCase,
  open,
  onOpenChange,
  onSave,
  onDelete,
  contractors,
  onAddContractor
}: CaseSheetProps) {
  const { t } = useTranslation();
  const [formData, setFormData] = useState<Partial<LegalCase>>({});
  const [hasUnsavedChanges, setHasUnsavedChanges] = useState(false);
  const [showDiscardDialog, setShowDiscardDialog] = useState(false);
  const [pendingClose, setPendingClose] = useState(false);

  // Lawyer Sheet Width Control
  const {
    width: sheetWidth,
    setCustomWidth: setSheetCustomWidth,
    getWidthClass,
    getWidthValue,
  } = useSheetWidth('lawyer-sheet', 'lg');

  const sheetRef = useRef<HTMLDivElement>(null);
  const resizeHandleRef = useRef<HTMLDivElement>(null);
  const startXRef = useRef(0);
  const startWidthRef = useRef(0);

  // Resize handler
  const handleMouseDown = useCallback((e: React.MouseEvent) => {
    e.preventDefault();
    e.stopPropagation();

    startXRef.current = e.clientX;
    startWidthRef.current = sheetWidth.customWidth || getWidthValue();

    const handleMouseMove = (moveEvent: MouseEvent) => {
      const deltaX = startXRef.current - moveEvent.clientX;
      const newWidth = Math.max(400, Math.min(startWidthRef.current + deltaX, Math.min(window.innerWidth * 0.9, 1600)));
      setSheetCustomWidth(newWidth);
    };

    const handleMouseUp = () => {
      document.removeEventListener('mousemove', handleMouseMove);
      document.removeEventListener('mouseup', handleMouseUp);
      document.body.style.cursor = '';
      document.body.style.userSelect = '';
    };

    document.addEventListener('mousemove', handleMouseMove);
    document.addEventListener('mouseup', handleMouseUp);
    document.body.style.cursor = 'col-resize';
    document.body.style.userSelect = 'none';
  }, [sheetWidth.customWidth, setSheetCustomWidth, getWidthValue]);

  // Track uploaded files for cleanup on cancel
  const { trackFile, cleanup: cleanupUploadedFiles, clear: clearUploadedFiles } = useUploadedFilesTracker({
    cleanupEndpoint: '/legal-cases/documents/cleanup',
    onCleanup: (ids) => console.log('[CaseSheet] Cleaned up', ids.length, 'unused files'),
    onError: (error) => console.error('[CaseSheet] Cleanup error:', error),
  });

  // Track changes in notes tab
  const handleNotesChange = () => {
    setHasUnsavedChanges(true);
  };

  // Tab Management
  const { tabs, toggleTab, moveTab } = useSheetTabs([
    { id: "general", label: "sheet.tabs.overview", icon: Folder, visible: true },
    { id: "finance", label: "sheet.tabs.finance", icon: DollarSign, visible: true },
    { id: "analytics", label: "sheet.tabs.analytics", icon: BarChart3, visible: true },
    { id: "timeline", label: "sheet.tabs.timeline", icon: Clock, visible: true },
    { id: "documents", label: "sheet.tabs.documents", icon: FileText, visible: true },
    { id: "notes", label: "sheet.tabs.notes", icon: MessageSquare, visible: true },
  ]);

  const [activeTab, setActiveTab] = useState("general");

  // Ensure active tab is visible
  useEffect(() => {
      const currentTab = tabs.find(t => t.id === activeTab);
      if (currentTab && !currentTab.visible) {
          const firstVisible = tabs.find(t => t.visible);
          if (firstVisible) setActiveTab(firstVisible.id);
      }
  }, [tabs, activeTab]);

  // Contractor Sheet State — Promise-resolver pattern
  const contractorResolverRef = useRef<{ resolve: (name: string) => void; reject: () => void } | null>(null);
  const [isContractorSheetOpen, setIsContractorSheetOpen] = useState(false);
  const [pendingContractorName, setPendingContractorName] = useState('');

  useEffect(() => {
    if (legalCase) {
      console.log('[CaseSheet] Initializing with case:', {
        title: legalCase.title,
        lawyerId: legalCase.lawyerId,
        caseNumber: legalCase.caseNumber,
        creationDate: legalCase.creationDate
      });
      setFormData(legalCase);
      clearUploadedFiles(); // Reset for existing case
    } else {
      const defaultCase: Partial<LegalCase> = {
        status: "new",
        creationDate: new Date().toLocaleDateString("ru-RU"), // Default to today
        claimAmount: { amount: 0, currency: "RUB" },
        recoveredAmount: { amount: 0, currency: "RUB" },
        thirdParties: [],
        stateDuty: 0,
        price: 0,
        events: [],
        documents: [],
        notes: []
      };
      console.log('[CaseSheet] Initializing with new case defaults');
      setFormData(defaultCase);
      clearUploadedFiles(); // Reset for new case
    }
    setHasUnsavedChanges(false);
  }, [legalCase, open]); // IMPORTANT: Don't include clearUploadedFiles - it causes infinite re-renders

  const handleInputChange = (field: keyof LegalCase, value: unknown) => {
    setFormData(prev => ({ ...prev, [field]: value }));
    setHasUnsavedChanges(true);
  };

  // Track uploaded file IDs
  const handleDocumentUploadSuccess = (upload: any) => {
    if (upload.response?.id) {
      trackFile(upload.response.id, upload.response.name, upload.response.url);
    }
  };

  const handleSave = () => {
    console.log('[CaseSheet] handleSave called with formData:', formData);

    // Валидация перед отправкой
    if (!formData.title?.toString().trim()) {
      toast.error('Заполните название дела');
      return;
    }
    if (!formData.type) {
      toast.error('Выберите тип дела');
      return;
    }
    if (!formData.status) {
      toast.error('Выберите статус дела');
      return;
    }
    if (!formData.lawyerId) {
      toast.error('Выберите юриста');
      return;
    }
    if (!formData.caseNumber) {
      toast.error('Заполните номер дела');
      return;
    }
    if (!formData.creationDate) {
      toast.error('Заполните дату создания');
      return;
    }

    console.log('[CaseSheet] All validations passed, calling onSave');
    onSave(formData as LegalCase);
    setHasUnsavedChanges(false);
    clearUploadedFiles(); // Clear tracking after successful save (files are now associated with the case)
    onOpenChange(false);
  };

  const handleOpenChange = (newOpen: boolean) => {
    if (!newOpen && hasUnsavedChanges) {
      // User is trying to close with unsaved changes
      setPendingClose(true);
      setShowDiscardDialog(true);
    } else if (!newOpen && !hasUnsavedChanges) {
      // Clean up any uploaded files before closing
      cleanupUploadedFiles();
      onOpenChange(false);
    } else {
      onOpenChange(newOpen);
    }
  };

  const handleAddContractorSuccess = (newContractor: Contractor) => {
    onAddContractor(newContractor);
    if (contractorResolverRef.current) {
      contractorResolverRef.current.resolve(newContractor.name);
      contractorResolverRef.current = null;
    }
  };

  const handleCreateContractor = (name: string): Promise<string> =>
    new Promise((resolve, reject) => {
      contractorResolverRef.current = { resolve, reject };
      setPendingContractorName(name);
      setIsContractorSheetOpen(true);
    });

  // Funnel steps logic
  const steps: CaseStatus[] = ["new", "preparation", "filing", "hearing", "decision", "enforcement", "done"];
  const currentStepIndex = steps.indexOf(formData.status as CaseStatus);

  return (
    <>
    <Sheet open={open} onOpenChange={onOpenChange}>
      <SheetContent 
        ref={sheetRef}
        className={`w-full ${getWidthClass()} flex flex-col h-full p-0 gap-0`}
        style={sheetWidth.customWidth ? { width: `${sheetWidth.customWidth}px`, maxWidth: `${sheetWidth.customWidth}px`, transition: 'none' } : undefined}
        side="right"
      >
        {/* Resize Handle (левый край) */}
        <div
          ref={resizeHandleRef}
          className="absolute left-0 top-0 bottom-0 w-1 cursor-col-resize hover:bg-primary/20 transition-colors z-[100]"
          onMouseDown={handleMouseDown}
          title={t('projects.sheet.width.drag_to_resize')}
          style={{
            pointerEvents: 'auto',
            touchAction: 'none',
          }}
        />
        <div className="p-6 border-b border-border bg-background z-10">
          <div className="flex items-start justify-between gap-4">
            <SheetHeader className="flex-1">
              <SheetTitle className="text-xl font-semibold">
                {legalCase ? t('lawyers.case_sheet.title_edit') : t('lawyers.case_sheet.title_new')}
              </SheetTitle>
              <SheetDescription className="flex items-center gap-2">
                <Folder className="w-4 h-4 text-primary" />
                {formData.title || t('lawyers.case_sheet.default_title')}
              </SheetDescription>
            </SheetHeader>
            <Button
              variant="ghost"
              size="sm"
              className="h-8 w-8 p-0 flex-shrink-0"
              onClick={() => {
                if (hasUnsavedChanges) {
                  setShowDiscardDialog(true);
                } else {
                  onOpenChange(false);
                }
              }}
            >
              <X className="w-4 h-4" />
            </Button>
          </div>

          {/* Visual Status Pipeline */}
          <div className="mt-6 mb-2">
            <div className="flex items-center justify-between relative">
              {/* Line background */}
              <div className="absolute left-0 top-1/2 -translate-y-1/2 w-full h-0.5 bg-secondary -z-10" />

              {steps.map((step, index) => {
                const isActive = index === currentStepIndex;
                const isCompleted = index < currentStepIndex;

                return (
                  <div key={step} className="flex flex-col items-center gap-1 group cursor-pointer" onClick={() => handleInputChange('status', step)}>
                    <div className={cn(
                      "w-3 h-3 rounded-full border-2 transition-colors duration-200",
                      isActive ? "bg-primary border-primary ring-4 ring-primary/20" : 
                      isCompleted ? "bg-primary border-primary" : 
                      "bg-background border-muted-foreground"
                    )} />
                    <span className={cn(
                      "text-[10px] font-medium transition-colors duration-200",
                      isActive ? "text-primary" : 
                      isCompleted ? "text-foreground" : 
                      "text-muted-foreground"
                    )}>
                      {t(`lawyers.case_status.${step}`).slice(0, 8)}..
                    </span>
                  </div>
                );
              })}
            </div>
          </div>

          <div className="flex items-center gap-2 mt-6 flex-nowrap">
            <Tabs value={activeTab} onValueChange={setActiveTab} className="w-full">
              <TabsList className="w-full justify-start overflow-x-auto">
                {tabs.map(tab => {
                    if (!tab.visible) return null;
                    const Icon = tab.icon;
                    return (
                        <TabsTrigger key={tab.id} value={tab.id} className="gap-1.5 text-xs">
                            <Icon className="w-3.5 h-3.5" />
                            {t(tab.label)}
                        </TabsTrigger>
                    );
                })}
              </TabsList>
            </Tabs>

            <SheetTabSettings
                tabs={tabs}
                onToggle={toggleTab}
                onMove={moveTab}
            />
          </div>
        </div>

        <div className="flex-1 overflow-y-auto p-6">
          {activeTab === "general" && (
            <CaseGeneralTab 
                formData={formData} 
                handleChange={handleInputChange} 
                contractors={contractors}
                onCreateContractor={handleCreateContractor}
            />
          )}
          {activeTab === "finance" && (
            <CaseFinanceTab formData={formData} handleChange={handleInputChange} />
          )}
          {activeTab === "analytics" && (
            <CaseAnalyticsTab legalCase={formData} />
          )}
          {activeTab === "timeline" && (
            <CaseTimelineTab 
              events={formData.events} 
              onChange={(events) => handleInputChange('events', events)}
            />
          )}
          {activeTab === "documents" && (
            <CaseDocumentsTab
              documents={formData.documents}
              notes={formData.notes}
              onChange={(documents) => handleInputChange('documents', documents)}
              onNotesChange={(notes) => handleInputChange('notes', notes)}
              caseId={legalCase?.id}
              onUploadSuccess={handleDocumentUploadSuccess}
            />
          )}
          {activeTab === "notes" && (
            <CaseNotesTab
              notes={formData.notes}
              handleChange={(field, value) => {
                handleInputChange(field, value);
                handleNotesChange();
              }}
            />
          )}
        </div>

        <SheetFooter className="p-6 border-t border-border mt-auto bg-background">
          <div className="flex items-center justify-between w-full">
            {legalCase ? (
              <Button
                variant="ghost"
                className="text-destructive hover:text-destructive hover:bg-destructive/10 gap-2"
                onClick={() => onDelete && onDelete(legalCase.id)}
              >
                <Trash2 className="w-4 h-4" />
                {t('common.delete')}
              </Button>
            ) : <div />}
            <div className="flex gap-2">
              <Button
                variant="outline"
                onClick={() => {
                  if (hasUnsavedChanges) {
                    setShowDiscardDialog(true);
                  } else {
                    onOpenChange(false);
                  }
                }}
              >
                {t('common.cancel')}
              </Button>
              <Button onClick={handleSave} className="gap-2">
                <CheckCircle2 className="w-4 h-4" />
                {t('common.save')}
              </Button>
            </div>
          </div>
        </SheetFooter>
      </SheetContent>
    </Sheet>

    {/* Discard Changes Confirmation Dialog */}
    <DiscardChangesDialog
      open={showDiscardDialog}
      onOpenChange={setShowDiscardDialog}
      onContinue={() => {
        // Continue editing - do nothing, just close dialog
      }}
      onDiscard={async () => {
        // Discard changes and close - cleanup uploaded files
        await cleanupUploadedFiles();
        setHasUnsavedChanges(false);
        onOpenChange(false);
      }}
      onSave={handleSave}
    />

    {/* Contractor Creation Sheet Stacking */}
    <ContractorSheet 
        contractor={null}
        initialName={pendingContractorName}
        open={isContractorSheetOpen}
        onOpenChange={(open) => {
          if (!open) {
            contractorResolverRef.current?.reject();
            contractorResolverRef.current = null;
            setIsContractorSheetOpen(false);
          }
        }}
        onSave={handleAddContractorSuccess}
    />
    </>
  );
}

import React, { useCallback } from "react";
import { LegalCase } from "../types";
import { useTranslation } from "@/lib/i18n";
import { QuickAction, StatusItem } from "@/lib/settings-data";
import {
  Table,
  TableBody,
  TableCell,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { Avatar, AvatarFallback } from "@/components/ui/avatar";
import { StatusBadge } from "@/components/ui/status-system";
import { OutcomeBadge } from "@/components/ui/status-system";
import { Checkbox } from "@/components/ui/checkbox";
import { QuickActionsMenu } from "@/components/ui/QuickActionsMenu";
import { Calendar, Trophy } from "lucide-react";
import { SortableTableHead, TableUtilityHead } from "@/components/shared";
import { useColumnDrag } from "@/hooks/useColumnDrag";
import { Badge } from "@/components/ui/badge";

// Функция для преобразования кода валюты в символ
const getCurrencySymbol = (currency: string): string => {
  const symbols: Record<string, string> = {
    'RUB': '₽',
    'USD': '$',
    'EUR': '€',
    'GBP': '£',
    'CNY': '¥',
  };
  return symbols[currency] || currency;
};

interface CasesListProps {
  cases: LegalCase[];
  selectedIds: Set<string | number>;
  toggleSelection: (id: string) => void;
  toggleAllSelection: () => void;
  visibleColumns: Record<string, boolean>;
  columnOrder?: string[];
  onReorderColumn?: (fromKey: string, toKey: string) => void;
  onEdit: (legalCase: LegalCase) => void;
  onDelete: (id: string) => void;
  sortConfig: { key: keyof LegalCase; direction: 'asc' | 'desc' } | null;
  onSort: (key: keyof LegalCase) => void;
  caseStatuses: StatusItem[];
  quickActions: QuickAction[];
  onAction: (action: string, itemId: string | number) => void;
  columnWidths?: Record<string, number>;
  onColumnResize?: (key: string, width: number) => void;
}

export function CasesList({
  cases,
  selectedIds,
  toggleSelection,
  toggleAllSelection,
  visibleColumns,
  columnOrder,
  onReorderColumn,
  onEdit,
  onDelete,
  sortConfig,
  onSort,
  caseStatuses,
  quickActions,
  onAction,
  columnWidths,
  onColumnResize,
}: CasesListProps) {
  const { t } = useTranslation();

  const handleReorder = useCallback((from: string, to: string) => {
    onReorderColumn?.(from, to);
  }, [onReorderColumn]);
  const { dragging, dragOver, onColumnMouseDown, onColumnMouseEnter } = useColumnDrag(handleReorder);

  const CASES_COLUMN_ORDER = ['title', 'plaintiff', 'defendant', 'client', 'lawyer', 'status', 'outcome', 'claim_amount', 'expenses', 'total', 'deadline', 'price'];
  const effectiveColumnOrder = columnOrder ?? CASES_COLUMN_ORDER;

  const caseColumnLabels: Record<string, string> = {
    title: t('lawyers.table.case_name'),
    plaintiff: t('lawyers.table.plaintiff'),
    defendant: t('lawyers.table.defendant'),
    client: t('lawyers.table.client'),
    lawyer: t('lawyers.table.lawyer'),
    status: t('lawyers.table.status'),
    outcome: t('lawyers.table.outcome'),
    claim_amount: t('lawyers.table.claim_amount'),
    expenses: t('lawyers.table.expenses'),
    total: t('lawyers.table.total'),
    deadline: t('lawyers.table.deadline'),
    price: t('lawyers.table.price'),
  };
  const caseSortKeys: Partial<Record<string, keyof LegalCase>> = {
    title: 'title',
    plaintiff: 'plaintiff',
    defendant: 'defendant',
    client: 'client',
    lawyer: 'lawyerName',
    status: 'status',
    outcome: 'outcome',
    claim_amount: 'claimAmount',
    expenses: 'expenses',
    total: 'price',
    deadline: 'deadline',
    price: 'price',
  };

  return (
    <div className="titan-card overflow-x-auto">
        <Table>
            <TableHeader>
            <TableRow>
                <TableUtilityHead className="w-10">
                    <Checkbox 
                        checked={cases.length > 0 && selectedIds.size === cases.length}
                        onCheckedChange={toggleAllSelection}
                    />
                </TableUtilityHead>
                {effectiveColumnOrder.filter(key => visibleColumns[key]).map(key => (
                  <SortableTableHead
                    key={key}
                    label={caseColumnLabels[key] ?? key}
                    onSort={() => onSort(caseSortKeys[key] ?? key as any)}
                    direction={sortConfig?.key === (caseSortKeys[key] ?? key) ? sortConfig.direction : null}
                    columnKey={key}
                    isDragging={dragging === key}
                    isDragOver={dragOver === key}
                    onColumnMouseDown={onColumnMouseDown}
                    onColumnMouseEnter={onColumnMouseEnter}
                    width={columnWidths?.[key]}
                    onResize={onColumnResize ? (w) => onColumnResize(key, w) : undefined}
                  />
                ))}
                <TableUtilityHead className="w-10" />
            </TableRow>
            </TableHeader>
            <TableBody>
            {cases.length === 0 ? (
                <TableRow>
                    <TableCell colSpan={13} className="text-center py-8 text-muted-foreground">{t('generated.net_dannyh')}</TableCell>
                </TableRow>
            ) : (
                cases.map((legalCase) => (
                    <TableRow 
                        key={legalCase.id} 
                        className={`hover:bg-muted/50 cursor-pointer ${selectedIds.has(legalCase.id) ? "bg-muted" : ""}`}
                        onClick={() => onEdit(legalCase)}
                    >
                        <TableCell onClick={(e) => e.stopPropagation()}>
                            <Checkbox 
                                checked={selectedIds.has(legalCase.id)}
                                onCheckedChange={() => toggleSelection(legalCase.id)}
                            />
                        </TableCell>
                        {effectiveColumnOrder.filter(key => visibleColumns[key]).map(key => {
                          switch (key) {
                            case 'title': return (
                              <TableCell key="title">
                                  <div className="flex flex-col">
                                      <span className="font-medium">{legalCase.title}</span>
                                      {legalCase.caseNumber && (
                                          <span className="text-xs text-muted-foreground font-mono">{legalCase.caseNumber}</span>
                                      )}
                                  </div>
                              </TableCell>
                            );
                            case 'plaintiff': return (
                              <TableCell key="plaintiff">{legalCase.plaintiff || "—"}</TableCell>
                            );
                            case 'defendant': return (
                              <TableCell key="defendant">{legalCase.defendant || "—"}</TableCell>
                            );
                            case 'client': return (
                              <TableCell key="client">{legalCase.client || "—"}</TableCell>
                            );
                            case 'lawyer': return (
                              <TableCell key="lawyer">
                                  <div className="flex items-center gap-2">
                                      <Avatar className="w-6 h-6">
                                      <AvatarFallback className="text-[10px] bg-primary/10 text-primary">
                                          {(legalCase.lawyerName || "?").charAt(0)}
                                      </AvatarFallback>
                                      </Avatar>
                                      <span className="text-sm">{legalCase.lawyerName || "—"}</span>
                                  </div>
                              </TableCell>
                            );
                            case 'status': return (
                              <TableCell key="status">
                                  <StatusBadge statusId={legalCase.status} />
                              </TableCell>
                            );
                            case 'outcome': return (
                              <TableCell key="outcome">
                                {legalCase.outcome ? (
                                  <OutcomeBadge outcomeId={legalCase.outcome} />
                                ) : (
                                  <span className="text-muted-foreground">—</span>
                                )}
                              </TableCell>
                            );
                            case 'claim_amount': return (
                              <TableCell key="claim_amount">
                                <div className="text-right font-mono whitespace-nowrap">
                                  {legalCase.claimAmount?.amount != null
                                    ? new Intl.NumberFormat('ru-RU', {
                                        minimumFractionDigits: 2,
                                        maximumFractionDigits: 2
                                      }).format(Number(legalCase.claimAmount.amount))
                                    : '0,00'}{getCurrencySymbol(legalCase.claimAmount?.currency || 'RUB')}
                                </div>
                              </TableCell>
                            );
                            case 'expenses': return (
                              <TableCell key="expenses">
                                <div className="text-right font-mono text-destructive whitespace-nowrap">
                                  {/* Считаем сумму из таблиц расходов */}
                                  {(() => {
                                    const flatExpenses = Number(legalCase.transportExpenses || 0) +
                                                        Number(legalCase.translationExpenses || 0) +
                                                        Number(legalCase.otherExpenses || 0);
                                    const itemExpenses = (legalCase.expenses || []).reduce((sum, item) => sum + Number(item.amount || 0), 0);
                                    const total = flatExpenses + itemExpenses;
                                    return total > 0
                                      ? new Intl.NumberFormat('ru-RU', {
                                          minimumFractionDigits: 2,
                                          maximumFractionDigits: 2
                                        }).format(total)
                                      : '0,00';
                                  })()}{getCurrencySymbol(legalCase.claimAmount?.currency || 'RUB')}
                                </div>
                              </TableCell>
                            );
                            case 'total': return (
                              <TableCell key="total">
                                <div className="text-right font-mono font-semibold whitespace-nowrap">
                                  {(() => {
                                    // ИТОГ = сумма иска - расходы
                                    const claimAmount = Number(legalCase.claimAmount?.amount || 0);
                                    const flatExpenses = Number(legalCase.transportExpenses || 0) +
                                                        Number(legalCase.translationExpenses || 0) +
                                                        Number(legalCase.otherExpenses || 0);
                                    const itemExpenses = (legalCase.expenses || []).reduce((sum, item) => sum + Number(item.amount || 0), 0);
                                    const totalExpenses = flatExpenses + itemExpenses;
                                    const result = claimAmount - totalExpenses;
                                    return new Intl.NumberFormat('ru-RU', {
                                      minimumFractionDigits: 2,
                                      maximumFractionDigits: 2
                                    }).format(result);
                                  })()}{getCurrencySymbol(legalCase.claimAmount?.currency || 'RUB')}
                                </div>
                              </TableCell>
                            );
                            case 'deadline': return (
                              <TableCell key="deadline">
                                  <div className="flex items-center gap-1.5 text-muted-foreground text-sm">
                                      <Calendar className="w-3.5 h-3.5" />
                                      {legalCase.deadline}
                                  </div>
                              </TableCell>
                            );
                            case 'price': return (
                              <TableCell key="price">
                                <div className="whitespace-nowrap">{Number(legalCase.price || 0).toLocaleString('ru-RU')} ₽</div>
                              </TableCell>
                            );
                            default: return null;
                          }
                        })}
                        <TableCell onClick={(e) => e.stopPropagation()}>
                            <div className="flex items-center gap-1">
                                <QuickActionsMenu
                                    itemId={legalCase.id}
                                    itemName={legalCase.title}
                                    options={quickActions}
                                    onAction={onAction}
                                />
                            </div>
                        </TableCell>
                    </TableRow>
                ))
            )}
            </TableBody>
        </Table>
    </div>
  );
}

