import { useState, useEffect, useCallback } from "react";
import { toast } from "sonner";
import { useTranslation } from "@/lib/i18n";
import { Lawyer, LegalCase, LawyerFilters, CaseFilters } from "../types/lawyer.types";
import { CreateLawyerRequest, CreateCaseRequest } from "../types/api.types";
import { lawyerService } from "../api/lawyerService";

interface UseLawyersReturn {
  lawyers: Lawyer[];
  loading: boolean;
  error: Error | null;
  fetchLawyers: () => Promise<void>;
  createLawyer: (data: Partial<Lawyer>) => Promise<Lawyer | null>;
  updateLawyer: (id: string, data: Partial<Lawyer>) => Promise<Lawyer | null>;
  deleteLawyer: (id: string) => Promise<boolean>;
}

export function useLawyers(): UseLawyersReturn {
  const { t } = useTranslation();
  const [lawyers, setLawyers] = useState<Lawyer[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<Error | null>(null);

  const fetchLawyers = useCallback(async () => {
    try {
      setLoading(true);
      const data = await lawyerService.getAllLawyers();
      setLawyers(data);
      setError(null);
    } catch (err) {
      setError(err instanceof Error ? err : new Error(String(err)));
      toast.error(t("general.toast.error.lawyer_load"));
    } finally {
      setLoading(false);
    }
  }, [t]);

  const createLawyer = useCallback(
    async (data: Partial<Lawyer>): Promise<Lawyer | null> => {
      try {
        const newLawyer = await lawyerService.createLawyer(data as unknown as CreateLawyerRequest);
        setLawyers((prev) => [newLawyer, ...prev]);
        toast.success(t("general.toast.success.lawyer_created"));
        return newLawyer;
      } catch (err) {
        toast.error(t("general.toast.error.lawyer_save"));
        return null;
      }
    },
    [t]
  );

  const updateLawyer = useCallback(
    async (id: string, data: Partial<Lawyer>): Promise<Lawyer | null> => {
      try {
        const updatedLawyer = await lawyerService.updateLawyer(id, { id, ...data });
        setLawyers((prev) =>
          prev.map((l) => (l.id === id ? updatedLawyer : l))
        );
        toast.success(t("general.toast.success.lawyer_updated"));
        return updatedLawyer;
      } catch (err) {
        toast.error(t("general.toast.error.lawyer_save"));
        return null;
      }
    },
    [t]
  );

  const deleteLawyer = useCallback(
    async (id: string): Promise<boolean> => {
      try {
        await lawyerService.deleteLawyer(id);
        setLawyers((prev) => prev.filter((l) => l.id !== id));
        toast.success(t("general.toast.success.lawyer_deleted"));
        return true;
      } catch (err) {
        toast.error(t("general.toast.error.lawyer_delete"));
        return false;
      }
    },
    [t]
  );

  useEffect(() => {
    fetchLawyers();
  }, [fetchLawyers]);

  return {
    lawyers,
    loading,
    error,
    fetchLawyers,
    createLawyer,
    updateLawyer,
    deleteLawyer,
  };
}

interface UseCasesReturn {
  cases: LegalCase[];
  loading: boolean;
  error: Error | null;
  fetchCases: () => Promise<void>;
  createCase: (data: Partial<LegalCase>) => Promise<LegalCase | null>;
  updateCase: (id: string, data: Partial<LegalCase>) => Promise<LegalCase | null>;
  deleteCase: (id: string) => Promise<boolean>;
}

export function useCases(): UseCasesReturn {
  const { t } = useTranslation();
  const [cases, setCases] = useState<LegalCase[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<Error | null>(null);

  const fetchCases = useCallback(async () => {
    try {
      setLoading(true);
      const data = await lawyerService.getAllCases();
      setCases(data);
      setError(null);
    } catch (err) {
      setError(err instanceof Error ? err : new Error(String(err)));
      toast.error(t("general.toast.error.cases_load"));
    } finally {
      setLoading(false);
    }
  }, [t]);

  const createCase = useCallback(
    async (data: Partial<LegalCase>): Promise<LegalCase | null> => {
      try {
        const newCase = await lawyerService.createCase(data as unknown as CreateCaseRequest);
        setCases((prev) => [newCase, ...prev]);
        toast.success(t("general.toast.success.case_created"));
        return newCase;
      } catch (err) {
        toast.error(t("general.toast.error.case_save"));
        return null;
      }
    },
    [t]
  );

  const updateCase = useCallback(
    async (id: string, data: Partial<LegalCase>): Promise<LegalCase | null> => {
      try {
        const updatedCase = await lawyerService.updateCase(id, { id, ...data });
        setCases((prev) =>
          prev.map((c) => (c.id === id ? updatedCase : c))
        );
        toast.success(t("general.toast.success.case_updated"));
        return updatedCase;
      } catch (err) {
        toast.error(t("general.toast.error.case_save"));
        return null;
      }
    },
    [t]
  );

  const deleteCase = useCallback(
    async (id: string): Promise<boolean> => {
      try {
        await lawyerService.deleteCase(id);
        setCases((prev) => prev.filter((c) => c.id !== id));
        toast.success(t("general.toast.success.case_deleted"));
        return true;
      } catch (err) {
        toast.error(t("general.toast.error.case_delete"));
        return false;
      }
    },
    [t]
  );

  useEffect(() => {
    fetchCases();
  }, [fetchCases]);

  return {
    cases,
    loading,
    error,
    fetchCases,
    createCase,
    updateCase,
    deleteCase,
  };
}

// frontend/src/modules/lawyers/hooks/useLawyersPage.ts
import { useState, useMemo, useEffect, useRef } from "react";
import { useTranslation } from "@/lib/i18n";
import { useSettings } from "@/hooks/use-settings";
import { useModuleSettings } from "@/modules/settings/hooks";
import { useDataTable } from "@/hooks/useDataTable";
import { usePersistedTab } from "@/hooks/usePersistedTab";
import { useValidationToast } from "@/components/shared";
import { api } from "@/lib/api";
import { parseRowsPerPage } from "@/lib/utils";
import { toast } from "sonner";
import { Scale, Gavel, FileText, Building2 } from "lucide-react";
import { Lawyer, LegalCase, CaseStatus, CaseOutcome, CaseDocument } from "../types";
import type { Contractor } from "@/modules/contractors";
import type { TaskReference } from "@/lib/types";

interface LawyerApiSource extends Omit<Lawyer, "specializations"> {
  specializations?: unknown;
  fullName?: string;
}

interface AddCaseEventDetail {
  lawyerId: string;
}

const normalizeSpecializations = (specializations: unknown): Lawyer["specializations"] => {
  if (Array.isArray(specializations)) return specializations as Lawyer["specializations"];
  if (specializations) {
    return String(specializations)
      .split(",")
      .map((item) => item.trim())
      .filter(Boolean) as Lawyer["specializations"];
  }
  return [];
};

const normalizeFromResponse = (res: LawyerApiSource): Lawyer => ({
  ...res,
  name: res.name ?? res.fullName ?? 'Неизвестный',
  specializations: normalizeSpecializations(res.specializations),
});

const buildEmptyCase = (overrides: Partial<LegalCase> = {}): LegalCase => {
  const currentUserId = localStorage.getItem('titan_user_id') || '';
  const defaultClient = localStorage.getItem('titan_company_name') || 'ТИТАН';
  const defaultLawyerName = localStorage.getItem('titan_user_name') || '';

  return {
    id: "",
    type: "court",
    title: "",
    status: "new",
    creationDate: new Date().toLocaleDateString("ru-RU"),
    startDate: new Date().toLocaleDateString("ru-RU"),
    client: defaultClient,
    plaintiff: "",
    defendant: "",
    lawyerId: currentUserId,
    lawyerName: defaultLawyerName,
    caseNumber: "",
    courtName: "",
    judge: "",
    deadline: "",
    price: 0,
    claimAmount: { amount: 0, currency: "RUB" },
    recoveredAmount: { amount: 0, currency: "RUB" },
    recoveredItems: [],
    thirdParties: [],
    stateDuty: 0,
    expertiseCost: 0,
    otherClaimCosts: 0,
    enforcementFee: 0,
    executionCosts: 0,
    transportExpenses: 0,
    translationExpenses: 0,
    otherExpenses: 0,
    expenses: [],
    outcome: undefined,
    events: [],
    documents: [],
    notes: [],
    ...overrides,
  } as LegalCase;
};

export function useLawyersPage() {
  const { t } = useTranslation();
  const { getStatusesByModule, getQuickActionsByModule } = useSettings();
  const { validate } = useValidationToast();
  const { settings: moduleSettings } = useModuleSettings('lawyers');

  type LawyerTabType = "specialists" | "cases" | "claims" | "courts";
  const [activeTab, setActiveTab] = usePersistedTab<LawyerTabType>("tab:lawyers", "cases");
  const [isTaskSheetOpen, setIsTaskSheetOpen] = useState(false);

  const lawyerStatuses = getStatusesByModule("lawyers");
  const caseStatuses = getStatusesByModule("cases");
  const lawyerQuickActions = getQuickActionsByModule("lawyers");
  const caseQuickActions = getQuickActionsByModule("cases");

  const [lawyers, setLawyers] = useState<Lawyer[]>([]);
  const [cases, setCases] = useState<LegalCase[]>([]);
  const [contractors, setContractors] = useState<Contractor[]>([]);

  const [statusFilter, setStatusFilter] = useState("all");
  const [lawyerFilter, setLawyerFilter] = useState("all");
  const [lawyerStatusFilter, setLawyerStatusFilter] = useState("all");

  const [selectedLawyer, setSelectedLawyer] = useState<Lawyer | null>(null);
  const [isLawyerSheetOpen, setIsLawyerSheetOpen] = useState(false);

  const [selectedCase, setSelectedCase] = useState<LegalCase | null>(null);
  const [isCaseSheetOpen, setIsCaseSheetOpen] = useState(false);

  // Bulk edit dialog state
  const [isBulkEditDialogOpen, setIsBulkEditDialogOpen] = useState(false);

  // Fetch Data
  useEffect(() => {
    const fetchData = async () => {
      try {
        const [casesData, lawyersData, contractorsData, userData] = await Promise.all([
          api.get("/legal-cases"),
          api.get("/lawyers"),
          api.get("/contractors"),
          // Get current user data
          api.get("/users/me").catch(() => null),
        ]);
        setCases(casesData);
        setLawyers((lawyersData as LawyerApiSource[]).map(normalizeFromResponse));
        setContractors(contractorsData);

        // Store current user info in localStorage for default values
        if (userData) {
          localStorage.setItem('titan_user_name', userData.name);
          localStorage.setItem('titan_user_id', userData.id);
        }

        // Get company name from API
        try {
          const companyData = await api.get("/company/profile");
          if (companyData && companyData.shortName) {
            localStorage.setItem('titan_company_name', companyData.shortName);
          }
        } catch {
          // Fallback to default
          localStorage.setItem('titan_company_name', 'ТИТАН');
        }
      } catch (err) {
        console.error('[LAWYERS_PAGE] Failed to fetch data:', err);
        toast.error(t("general.toast.error.lawyers_data_load"));
      }
    };
    fetchData();
  }, [t]);

  // Listen for "add case from lawyer card" event
  useEffect(() => {
    const handleAddCase = (event: Event) => {
      const detail = (event as CustomEvent<AddCaseEventDetail>).detail;
      if (!detail) return;
      const lawyer = lawyers.find((l) => l.id === detail.lawyerId);
      if (lawyer) {
        setSelectedCase(
          buildEmptyCase({ lawyerId: lawyer.id, lawyerName: lawyer.name })
        );
        setIsCaseSheetOpen(true);
      }
    };
    window.addEventListener("addCase", handleAddCase as EventListener);
    return () => window.removeEventListener("addCase", handleAddCase as EventListener);
  }, [lawyers]);

  // Cases table hook (for "cases" and "claims" tabs - separate settings)
  const casesTable = useDataTable<LegalCase>({
    initialData: [],
    initialColumns: {
      title: true,
      plaintiff: true,
      defendant: true,
      client: true,
      lawyer: true,
      status: true,
      outcome: moduleSettings?.display?.showOutcome ?? false,
      claim_amount: false,
      expenses: false,
      total: false,
      deadline: true,
      price: true,
    },
    initialTabs: [
      { id: "specialists", label: "lawyers.tabs.specialists", icon: Scale, visible: true },
      { id: "cases", label: "lawyers.tabs.cases", icon: Gavel, visible: true },
      { id: "claims", label: "lawyers.tabs.claims", icon: FileText, visible: true },
      { id: "courts", label: "lawyers.tabs.courts", icon: Building2, visible: false },
    ],
    storageKey: "lawyers-cases-table",
  });

  // Lawyers (Specialists) table hook - replaces manual state
  const lawyersTable = useDataTable<Lawyer>({
    initialData: [],
    initialColumns: {
      name: true,
      specialization: true,
      rating: true,
      caseload: true,
      status: true,
    },
    storageKey: "lawyers-specialists-table",
  });

  // Синхронизация настройки showOutcome из настроек модуля
  useEffect(() => {
    if (moduleSettings?.display?.showOutcome !== undefined) {
      casesTable.setVisibleColumns(prev => ({
        ...prev,
        outcome: moduleSettings.display.showOutcome,
      }));
    }
  }, [moduleSettings?.display?.showOutcome]); // eslint-disable-line react-hooks/exhaustive-deps

  // Sync active tab if its visibility is toggled off
  useEffect(() => {
    const currentTabConfig = casesTable.tabsConfig.find((tab) => tab.id === activeTab);
    if (currentTabConfig && !currentTabConfig.visible) {
      const firstVisible = casesTable.tabsConfig.find((tab) => tab.visible);
      if (firstVisible) setActiveTab(firstVisible.id as LawyerTabType);
    }
  }, [casesTable.tabsConfig, activeTab]);

  // Replaced manual lawyer column state with lawyersTable

  // Filtered/sorted case list
  const displayedCases = useMemo(() => {
    if (activeTab === "specialists") return [];

    let result = cases.filter((c) =>
      activeTab === "cases" ? c.type === "court" : c.type === "claim"
    );

    if (casesTable.searchQuery) {
      const q = casesTable.searchQuery.toLowerCase();
      result = result.filter(
        (c) =>
          c.title.toLowerCase().includes(q) ||
          c.plaintiff.toLowerCase().includes(q) ||
          (c.caseNumber && c.caseNumber.toLowerCase().includes(q))
      );
    }
    if (statusFilter !== "all") result = result.filter((c) => c.status === statusFilter);
    if (lawyerFilter !== "all") result = result.filter((c) => c.lawyerName === lawyerFilter);

    if (casesTable.sortConfig) {
      result = [...result].sort((a, b) => {
        const { key, direction } = casesTable.sortConfig;
        const aVal = String(a[key] ?? "");
        const bVal = String(b[key] ?? "");
        return direction === "asc" ? aVal.localeCompare(bVal) : bVal.localeCompare(aVal);
      });
    }
    return result;
  }, [cases, activeTab, casesTable.searchQuery, casesTable.sortConfig, statusFilter, lawyerFilter]);

  const filteredLawyers = useMemo(() => {
    let result = lawyers.filter((l) =>
      (l.name ?? '').toLowerCase().includes(lawyersTable.searchQuery.toLowerCase())
    );
    if (lawyerStatusFilter !== "all") {
      result = result.filter((l) => l.status === lawyerStatusFilter);
    }
    return result;
  }, [lawyers, lawyersTable.searchQuery, lawyerStatusFilter]);

  // Reset page when filters or tab changes
  useEffect(() => {
    casesTable.setCurrentPage(1);
    lawyersTable.setCurrentPage(1);
  }, [activeTab, statusFilter, lawyerFilter, lawyerStatusFilter, casesTable.searchQuery, lawyersTable.searchQuery]); // eslint-disable-line react-hooks/exhaustive-deps

  // Paginated results
  const casesPerPage = parseRowsPerPage(casesTable.rowsPerPage);
  const paginatedCases = displayedCases.slice(
    (casesTable.currentPage - 1) * casesPerPage,
    casesTable.currentPage * casesPerPage
  );
  const paginatedLawyers = filteredLawyers.slice(
    (lawyersTable.currentPage - 1) * casesPerPage,
    lawyersTable.currentPage * casesPerPage
  );

  // ── Handlers ──────────────────────────────────────────────────

  const handleCreateTask = async (task: TaskReference) => {
    try {
      if (!task.title?.trim()) {
        toast.error(t("business.validation.title_required"));
        return;
      }
      await api.post("/tasks", { ...task, project: task.project || "General" });
      toast.success(t("general.toast.success.task_created"));
      setIsTaskSheetOpen(false);
    } catch {
      toast.error(t("general.toast.error.task_save"));
    }
  };

  const handleBulkDelete = async () => {
    if (!confirm(`Удалить выбранные записи (${casesTable.selectedIds.size})?`)) return;
    try {
      await Promise.all(
        Array.from(casesTable.selectedIds).map((id) => api.delete(`/legal-cases/${id}`))
      );
      setCases((prev) => prev.filter((c) => !casesTable.selectedIds.has(c.id)));
      casesTable.clearSelection();
      toast.success(t("general.toast.success.records_deleted"));
    } catch {
      toast.error(t("general.toast.error.records_delete"));
    }
  };

  const handleBulkEdit = async (field: string, value: string) => {
    try {
      const updates: Record<string, any> = { [field]: value };

      // Если это lawyerId, нужно также добавить lawyerName
      if (field === 'lawyerId') {
        const lawyer = lawyers.find(l => l.id === value);
        if (lawyer) {
          updates.lawyerName = lawyer.name;
        }
      }

      const updatePromises = Array.from(casesTable.selectedIds).map((id) => {
        const legalCase = cases.find((c) => c.id === id);
        if (!legalCase) return Promise.reject(new Error(`Case ${id} not found`));

        const updatedCase = {
          ...legalCase,
          ...updates,
        };

        // Normalize numeric fields
        const normalizedCase = {
          ...updatedCase,
          client: updatedCase.client || 'ТИТАН',
          price: Number(updatedCase.price) || 0,
          stateDuty: Number(updatedCase.stateDuty) || 0,
          expertiseCost: Number(updatedCase.expertiseCost) || 0,
          otherClaimCosts: Number(updatedCase.otherClaimCosts) || 0,
          enforcementFee: Number(updatedCase.enforcementFee) || 0,
          executionCosts: Number(updatedCase.executionCosts) || 0,
          transportExpenses: Number(updatedCase.transportExpenses) || 0,
          translationExpenses: Number(updatedCase.translationExpenses) || 0,
          otherExpenses: Number(updatedCase.otherExpenses) || 0,
          claimAmount: {
            amount: Number(updatedCase.claimAmount?.amount) || 0,
            currency: updatedCase.claimAmount?.currency || 'RUB'
          },
          recoveredAmount: {
            amount: Number(updatedCase.recoveredAmount?.amount) || 0,
            currency: updatedCase.recoveredAmount?.currency || 'RUB'
          },
          recoveredItems: (updatedCase.recoveredItems || []).map(item => ({
            ...item,
            amount: Number(item.amount) || 0
          })),
          expenses: (updatedCase.expenses || []).map(item => ({
            ...item,
            amount: Number(item.amount) || 0
          }))
        };

        return api.put(`/legal-cases/${id}`, normalizedCase);
      });

      await Promise.all(updatePromises);

      // Update local state
      setCases((prev) => prev.map((c) => {
        if (casesTable.selectedIds.has(c.id)) {
          return { ...c, ...updates };
        }
        return c;
      }));

      casesTable.clearSelection();
      toast.success(t("general.toast.success.records_updated"));
    } catch (err) {
      console.error('[BULK EDIT ERROR]', err);
      toast.error(t("general.toast.error.records_update"));
    }
  };

  const handleEditLawyer = (lawyer: Lawyer) => {
    setSelectedLawyer(lawyer);
    setIsLawyerSheetOpen(true);
  };

  const handleAddLawyer = () => {
    setSelectedLawyer(null);
    setIsLawyerSheetOpen(true);
  };

  const handleSaveLawyer = async (lawyer: Lawyer) => {
    try {
      if (selectedLawyer) {
        const res = await api.put(`/lawyers/${lawyer.id}`, lawyer);
        setLawyers((prev) =>
          prev.map((l) => (l.id === lawyer.id ? normalizeFromResponse(res) : l))
        );
        toast.success(t("general.toast.success.lawyer_updated"));
      } else {
        const res = await api.post("/lawyers", lawyer);
        setLawyers((prev) => [...prev, normalizeFromResponse(res)]);
        toast.success(t("general.toast.success.lawyer_added"));
      }
    } catch {
      toast.error(t("general.toast.error.lawyer_save"));
    }
  };

  const handleDeleteLawyer = async (id: string) => {
    try {
      await api.delete(`/lawyers/${id}`);
      setLawyers((prev) => prev.filter((l) => l.id !== id));
      setIsLawyerSheetOpen(false);
      toast.success(t("general.toast.success.lawyer_deleted"));
    } catch {
      toast.error(t("general.toast.error.lawyer_delete"));
    }
  };

  const handleEditCase = (legalCase: LegalCase) => {
    setSelectedCase(legalCase);
    setIsCaseSheetOpen(true);
  };

  const handleAddCase = (type: "claim" | "court" = "court") => {
    setSelectedCase(
      buildEmptyCase({
        type,
        status: type === "court" ? "new" : "claim_draft",
      })
    );
    setIsCaseSheetOpen(true);
  };

  const handleSaveCase = async (legalCase: LegalCase) => {
    try {
      console.log('[CASE SAVE] handleSaveCase called with legalCase:', {
        id: legalCase.id,
        title: legalCase.title,
        type: legalCase.type,
        status: legalCase.status,
        lawyerId: legalCase.lawyerId,
        caseNumber: legalCase.caseNumber,
        creationDate: legalCase.creationDate,
        notesCount: legalCase.notes?.length || 0,
        notesWithAttachments: legalCase.notes?.filter(n => n.attachments?.length).length || 0
      });

      // Validate required fields using the new hook
      const isValid = validate([
        { name: 'title', label: 'Название дела', value: legalCase.title },
        { name: 'type', label: 'Тип дела', value: legalCase.type },
        { name: 'status', label: 'Статус', value: legalCase.status },
        { name: 'lawyerId', label: 'Юрист', value: legalCase.lawyerId },
        { name: 'caseNumber', label: 'Номер дела', value: legalCase.caseNumber },
        { name: 'creationDate', label: 'Дата создания', value: legalCase.creationDate },
      ], 'Заполните обязательные поля');

      if (!isValid) return;

      // Сначала загружаем новые файлы (с pending_ в id)
      const pendingDocs = (legalCase.documents || []).filter(doc => doc.id?.startsWith('pending_'));
      const uploadedDocs: CaseDocument[] = [];

      for (const doc of pendingDocs) {
        if (doc.file) {
          const formData = new FormData();
          formData.append('file', doc.file);
          formData.append('name', doc.name);
          formData.append('type', doc.type || 'other');
          formData.append('case_id', selectedCase?.id || '');

          const uploadRes = await api.post('/legal-cases/documents', formData, {
            headers: {}
          });

          uploadedDocs.push({
            id: uploadRes.id,
            name: uploadRes.name,
            url: uploadRes.url,
            type: doc.type || 'other',
            date: doc.date || new Date().toISOString().split('T')[0],
            size: doc.size || '0',
            author: doc.author || ''
          });
        }
      }

      // Normalize numeric fields and dates
      const normalizedCase = {
        ...legalCase,
        client: legalCase.client || 'ТИТАН',
        lawyerId: legalCase.lawyerId || '', // Должно быть заполнено (проверено выше)
        caseNumber: legalCase.caseNumber?.toString().trim() || '', // Должно быть заполнено (проверено выше)
        lawyerName: legalCase.lawyerName || '',
        // Convert dates from DD.MM.YYYY to YYYY-MM-DD for PostgreSQL
        creationDate: legalCase.creationDate ?
          (typeof legalCase.creationDate === 'string' && legalCase.creationDate.includes('.')
            ? legalCase.creationDate.split('.').reverse().join('-')
            : legalCase.creationDate)
          : new Date().toISOString().split('T')[0],
        deadline: legalCase.deadline ?
          (typeof legalCase.deadline === 'string' && legalCase.deadline.includes('.')
            ? legalCase.deadline.split('.').reverse().join('-')
            : legalCase.deadline)
          : null,
        price: Number(legalCase.price) || 0,
        stateDuty: Number(legalCase.stateDuty) || 0,
        expertiseCost: Number(legalCase.expertiseCost) || 0,
        otherClaimCosts: Number(legalCase.otherClaimCosts) || 0,
        enforcementFee: Number(legalCase.enforcementFee) || 0,
        executionCosts: Number(legalCase.executionCosts) || 0,
        transportExpenses: Number(legalCase.transportExpenses) || 0,
        translationExpenses: Number(legalCase.translationExpenses) || 0,
        otherExpenses: Number(legalCase.otherExpenses) || 0,
        claimAmount: {
          amount: Number(legalCase.claimAmount?.amount) || 0,
          currency: legalCase.claimAmount?.currency || 'RUB'
        },
        recoveredAmount: {
          amount: Number(legalCase.recoveredAmount?.amount) || 0,
          currency: legalCase.recoveredAmount?.currency || 'RUB'
        },
        recoveredItems: (legalCase.recoveredItems || []).map(item => ({
          ...item,
          amount: Number(item.amount) || 0
        })),
        expenses: (legalCase.expenses || []).map(item => ({
          ...item,
          amount: Number(item.amount) || 0
        })),
        // Normalize documents - replace pending with uploaded
        documents: (legalCase.documents || [])
          .filter(doc => !doc.id?.startsWith('pending_')) // Убираем pending документы
          .concat(uploadedDocs) // Добавляем загруженные
          .map(doc => ({
            id: doc.id,
            name: doc.name,
            type: doc.type,
            date: doc.date,
            size: doc.size,
            author: doc.author,
            url: doc.url
          })),
        // Normalize and deduplicate notes with attachments
        notes: (() => {
          // Deduplicate notes by ID (keep the last occurrence)
          const seenNoteIds = new Map();
          (legalCase.notes || []).forEach(note => {
            seenNoteIds.set(note.id, note);
          });

          // Convert to normalized format
          return Array.from(seenNoteIds.values()).map(note => ({
            id: note.id,
            author: note.author,
            authorId: note.authorId || note.author, // Используем author как fallback для authorId
            initials: note.initials,
            date: note.date 
              ? typeof note.date === 'string'
                ? note.date.includes('.')
                  ? note.date.split('.').reverse().join('-') // DD.MM.YYYY → YYYY-MM-DD
                  : note.date.includes('T')
                  ? note.date.split('T')[0] // ISO format with time → just date
                  : note.date // Already in YYYY-MM-DD format or other format
                : note.date
              : new Date().toISOString().split('T')[0],
            text: note.text,
            isInternal: note.isInternal,
            attachments: note.attachments?.map(att => ({
              id: att.id,
              name: att.name,
              url: att.url,
              type: att.type,
              addedAt: att.addedAt 
                ? typeof att.addedAt === 'string'
                  ? att.addedAt.includes('.')
                    ? att.addedAt.split('.').reverse().join('-') // DD.MM.YYYY → YYYY-MM-DD
                    : att.addedAt.includes('T')
                    ? att.addedAt.split('T')[0] // ISO format with time → just date
                    : att.addedAt // Already in YYYY-MM-DD format
                  : att.addedAt
                : new Date().toISOString().split('T')[0]
            })) || []
          }));
        })()
      };

      // Check if this is an existing case (id from database should be like 'case-12345' without Cyrillic)
      const isValidId = selectedCase?.id && 
                        selectedCase.id !== "" && 
                        selectedCase.id.startsWith('case-') &&
                        !/[\u0400-\u04FF]/.test(selectedCase.id); // No Cyrillic characters

      if (isValidId) {
        // Existing case with valid ID from database
        console.log('[CASE SAVE] Sending PUT request with normalized data:', {
          caseId: selectedCase.id,
          title: normalizedCase.title,
          type: normalizedCase.type,
          status: normalizedCase.status,
          lawyerId: normalizedCase.lawyerId,
          caseNumber: normalizedCase.caseNumber,
          creationDate: normalizedCase.creationDate,
          notesCount: normalizedCase.notes?.length || 0
        });
        const res = await api.put(`/legal-cases/${selectedCase.id}`, normalizedCase);
        setCases((prev) => prev.map((c) => (c.id === selectedCase.id ? { ...c, ...res } : c)));
        setSelectedCase(res); // Update selected case with fresh data from server
        toast.success(t("general.toast.success.case_saved"));
      } else {
        // New case or invalid ID - create via POST
        console.log('[CASE SAVE] Sending POST request (new case) with FULL normalized data:');
        console.log('[CASE SAVE] Full object:', JSON.stringify(normalizedCase, null, 2));
        console.log('[CASE SAVE] Required fields check:', {
          title: `"${normalizedCase.title}" (${normalizedCase.title ? 'OK' : 'MISSING'})`,
          type: `"${normalizedCase.type}" (${normalizedCase.type ? 'OK' : 'MISSING'})`,
          status: `"${normalizedCase.status}" (${normalizedCase.status ? 'OK' : 'MISSING'})`,
          lawyerId: `"${normalizedCase.lawyerId}" (${normalizedCase.lawyerId ? 'OK' : 'MISSING'})`,
          caseNumber: `"${normalizedCase.caseNumber}" (${normalizedCase.caseNumber ? 'OK' : 'MISSING'})`,
          creationDate: `"${normalizedCase.creationDate}" (${normalizedCase.creationDate ? 'OK' : 'MISSING'})`,
          client: `"${normalizedCase.client}" (${normalizedCase.client ? 'OK' : 'MISSING'})`
        });
        const res = await api.post("/legal-cases", normalizedCase);
        setCases((prev) => [...prev, res]);
        setSelectedCase(res); // Update selected case with fresh data from server
        toast.success(t("general.toast.success.case_created"));
        if (res.type === "court") setActiveTab("cases");
        else if (res.type === "claim") setActiveTab("claims");
      }
    } catch (err) {
      console.error('[CASE SAVE ERROR]', err);
      console.error('[CASE SAVE ERROR] Full error details:', {
        message: err.message,
        status: err.status,
        response: err.response,
        stack: err.stack
      });
      toast.error(t("general.toast.error.case_save"));
    }
  };

  const handleDeleteCase = async (id: string) => {
    try {
      await api.delete(`/legal-cases/${id}`);
      setCases((prev) => prev.filter((c) => c.id !== id));
      setIsCaseSheetOpen(false);
      toast.success(t("general.toast.success.case_deleted"));
    } catch {
      toast.error(t("general.toast.error.case_delete"));
    }
  };

  const handleTransferToCourt = async (legalCase: LegalCase) => {
    try {
      const updated = { ...legalCase, type: "court", status: "new", title: `Иск: ${legalCase.title}` };
      await api.put(`/legal-cases/${legalCase.id}`, updated);
      setCases((prev) => prev.map((c) => (c.id === legalCase.id ? (updated as LegalCase) : c)));
      toast.success(t("general.toast.success.sent_to_court"));
    } catch {
      toast.error(t("general.toast.error.case_update"));
    }
  };

  const handleReturnToClaim = async (legalCase: LegalCase) => {
    try {
      const updated = {
        ...legalCase,
        type: "claim",
        status: "claim_negotiation",
        title: legalCase.title.replace(t('lawyers.messages.prefix_lawsuit'), ""),
      };
      await api.put(`/legal-cases/${legalCase.id}`, updated);
      setCases((prev) => prev.map((c) => (c.id === legalCase.id ? (updated as LegalCase) : c)));
      toast.info(t("general.toast.info.returned_to_claim"));
    } catch {
      toast.error(t("general.toast.error.case_update"));
    }
  };

  const handleAddContractor = async (contractor: Contractor) => {
    try {
      const res = await api.post("/contractors", contractor);
      setContractors((prev) => [...prev, res]);
      toast.success(t("general.toast.success.contractor_added"));
    } catch {
      toast.error(t("general.toast.error.contractor_create"));
    }
  };

  const handleQuickAction = (action: string, id: number | string) => {
    const legalCase = cases.find((c) => c.id === id);
    if (!legalCase) return;

    switch (action) {
      case "create_case":
        setSelectedCase(null);
        setIsCaseSheetOpen(true);
        break;
      case "assign_lawyer":
      case "upload_document":
      case "financial_details":
      case "add_document":
      case "edit":
        setSelectedCase(legalCase);
        setIsCaseSheetOpen(true);
        break;
      case "add_event":
        toast.info(t("generated.dobavlenie_sobytiya_k_delu") + legalCase.title);
        break;
      case "send_to_court":
        if (legalCase.type !== "court") handleTransferToCourt(legalCase);
        else toast.info(t("general.toast.info.already_in_court"));
        break;
      case "return_to_claim":
        if (legalCase.type !== "claim") handleReturnToClaim(legalCase);
        else toast.info(t("general.toast.info.already_claim"));
        break;
      case "create_task":
        setIsTaskSheetOpen(true);
        break;
      case "delete":
        if (confirm(`Удалить дело "${legalCase.title}"?`)) handleDeleteCase(legalCase.id);
        break;
      default:
        toast.info(t("general.toast.info.action_completed").replace("{0}", action));
    }
  };

  return {
    t,
    activeTab,
    setActiveTab,
    isTaskSheetOpen,
    setIsTaskSheetOpen,
    lawyerStatuses,
    caseStatuses,
    lawyerQuickActions,
    caseQuickActions,
    lawyers,
    cases,
    contractors,
    statusFilter,
    setStatusFilter,
    lawyerFilter,
    setLawyerFilter,
    lawyerStatusFilter,
    setLawyerStatusFilter,
    selectedLawyer,
    isLawyerSheetOpen,
    setIsLawyerSheetOpen,
    selectedCase,
    isCaseSheetOpen,
    setIsCaseSheetOpen,
    isBulkEditDialogOpen,
    setIsBulkEditDialogOpen,
    casesTable,
    lawyersTable,
    displayedCases,
    filteredLawyers,
    paginatedCases,
    paginatedLawyers,
    handleCreateTask,
    handleBulkDelete,
    handleBulkEdit,
    handleEditLawyer,
    handleAddLawyer,
    handleSaveLawyer,
    handleDeleteLawyer,
    handleEditCase,
    handleAddCase,
    handleSaveCase,
    handleDeleteCase,
    handleAddContractor,
    handleQuickAction,
  };
}

