import React, { useEffect, useState } from 'react';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu';
import {
  FolderOpen,
  CheckCircle,
  Trash2,
  Edit2,
  FolderPlus,
  Eraser,
} from 'lucide-react';
import { toast } from 'sonner';
import { api } from '@/lib/api';

interface FolderContextMenuProps {
  folder: {
    id: string;
    folderName: string;
    folderType: string;
    accountId: string;
  };
  onSelectAction: (action: string, folder: any) => void;
  onClose: () => void;
}

export function FolderContextMenu({
  folder,
  onSelectAction,
  onClose,
}: FolderContextMenuProps) {
  const [open, setOpen] = useState(false);
  const systemFolderTypes = new Set(['system', 'inbox', 'sent', 'drafts', 'archive', 'spam', 'trash']);
  const isSystemFolder = systemFolderTypes.has((folder.folderType || '').toLowerCase());

  useEffect(() => {
    setOpen(true);

    const handleClickOutside = () => {
      setOpen(false);
      onClose();
    };

    const handleEsc = (e: KeyboardEvent) => {
      if (e.key === 'Escape') {
        setOpen(false);
        onClose();
      }
    };

    document.addEventListener('click', handleClickOutside);
    document.addEventListener('keydown', handleEsc);

    return () => {
      document.removeEventListener('click', handleClickOutside);
      document.removeEventListener('keydown', handleEsc);
    };
  }, [onClose]);

  const handleAction = (action: string) => {
    if (isSystemFolder && ['delete_folder', 'rename_folder', 'create_subfolder'].includes(action)) {
      toast.error('Нельзя изменить системную папку');
      return;
    }

    onSelectAction(action, folder);
    setOpen(false);
    onClose();
  };

  return (
    <DropdownMenu open={open} onOpenChange={setOpen} modal={false}>
      <DropdownMenuTrigger asChild>
        <div className="fixed w-0 h-0" />
      </DropdownMenuTrigger>
      <DropdownMenuContent 
        className="w-56" 
        align="start" 
        side="right"
        onCloseAutoFocus={(e) => e.preventDefault()}
      >
        {/* Открыть папку */}
        <DropdownMenuItem onClick={() => handleAction('open_folder')}>
          <FolderOpen className="mr-2 h-4 w-4" />
          Открыть
        </DropdownMenuItem>

        <DropdownMenuSeparator />

        {/* Пометить всё как прочитанное */}
        <DropdownMenuItem onClick={() => handleAction('mark_all_read')}>
          <CheckCircle className="mr-2 h-4 w-4" />
          Пометить всё как прочитанное
        </DropdownMenuItem>

        <DropdownMenuSeparator />

        {/* Удалить папку */}
        <DropdownMenuItem 
          onClick={() => handleAction('delete_folder')}
          className={isSystemFolder ? 'text-muted-foreground opacity-50' : 'text-destructive focus:text-destructive'}
          disabled={isSystemFolder}
        >
          <Trash2 className="mr-2 h-4 w-4" />
          Удалить папку
        </DropdownMenuItem>

        {/* Переименовать */}
        <DropdownMenuItem 
          onClick={() => handleAction('rename_folder')}
          className={isSystemFolder ? 'text-muted-foreground opacity-50' : ''}
          disabled={isSystemFolder}
        >
          <Edit2 className="mr-2 h-4 w-4" />
          Переименовать
        </DropdownMenuItem>

        {/* Создать подпапку */}
        <DropdownMenuItem 
          onClick={() => handleAction('create_subfolder')}
          className={isSystemFolder ? 'text-muted-foreground opacity-50' : ''}
          disabled={isSystemFolder}
        >
          <FolderPlus className="mr-2 h-4 w-4" />
          Создать подпапку
        </DropdownMenuItem>

        {/* Очистить папку */}
        <DropdownMenuItem 
          onClick={() => handleAction('clear_folder')}
          className="text-destructive focus:text-destructive"
        >
          <Eraser className="mr-2 h-4 w-4" />
          Очистить папку
        </DropdownMenuItem>
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

