import React, { useState, useEffect } from "react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { ScrollArea } from "@/components/ui/scroll-area";
import { Badge } from "@/components/ui/badge";
import { Alert, AlertDescription } from "@/components/ui/alert";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { useTranslation } from "@/lib/i18n";
import { api } from "@/lib/api";
import { toast } from "sonner";
import { cn } from "@/lib/utils";
import {
  ChevronLeft,
  Send,
  CheckCircle,
  AlertCircle,
  Loader,
  Eye,
  EyeOff,
  Folder,
  RefreshCw,
} from "lucide-react";

interface MailAccount {
  id: string;
  email: string;
  displayName?: string;
  accountType: string;
  imapHost?: string;
  imapPort?: number;
  smtpHost?: string;
  smtpPort?: number;
  useTls?: boolean;
  isActive: boolean;
  hasPassword?: boolean;
}

interface MailFolder {
  id: string;
  folderName: string;
  folderType: string;
  imapFolderPath?: string;
}

interface IMAPFolder {
  name: string;
  path: string;
  folderType?: string;
  matchedFolderId?: string;
}

interface FormData {
  email: string;
  display_name: string;
  account_type: "gmail" | "outlook" | "mailru" | "imap";
  imap_host?: string;
  imap_port?: number;
  smtp_host?: string;
  smtp_port?: number;
  login: string;
  password: string;
  use_tls: boolean;
  sync_mode: "light" | "heavy";
}

interface MailAccountSettingsProps {
  accountId?: string;
  onSave?: () => void;
  onCancel?: () => void;
  variant?: 'dialog' | 'page';
}

const defaultFormData: FormData = {
  email: "",
  display_name: "",
  account_type: "gmail",
  imap_host: "imap.gmail.com",
  imap_port: 993,
  smtp_host: "smtp.gmail.com",
  smtp_port: 587,
  login: "",
  password: "",
  use_tls: true,
  sync_mode: "light",
};

const presets: Record<string, Partial<FormData>> = {
  gmail: {
    imap_host: "imap.gmail.com",
    imap_port: 993,
    smtp_host: "smtp.gmail.com",
    smtp_port: 587,
    use_tls: true,
  },
  outlook: {
    imap_host: "outlook.office365.com",
    imap_port: 993,
    smtp_host: "smtp.office365.com",
    smtp_port: 587,
    use_tls: true,
  },
  mailru: {
    imap_host: "imap.mail.ru",
    imap_port: 993,
    smtp_host: "smtp.mail.ru",
    smtp_port: 465,
    use_tls: true,
  },
};

export function MailAccountSettings({
  accountId,
  onSave,
  onCancel,
  variant = 'page',
}: MailAccountSettingsProps) {
  const { t } = useTranslation();
  const [loading, setLoading] = useState(false);
  const [saving, setSaving] = useState(false);
  const [testingId, setTestingId] = useState<string | null>(null);
  const [showPassword, setShowPassword] = useState(false);
  const [hasExistingPassword, setHasExistingPassword] = useState(false);
  const [formData, setFormData] = useState<FormData>(defaultFormData);
  const [userModifiedFields, setUserModifiedFields] = useState<Set<string>>(new Set());
  const [connectionTested, setConnectionTested] = useState(false);
  const [folders, setFolders] = useState<MailFolder[]>([]);
  const [imapFolders, setImapFolders] = useState<IMAPFolder[]>([]);
  const [loadingFolders, setLoadingFolders] = useState(false);

  const isEditing = !!accountId;

  useEffect(() => {
    if (accountId) {
      loadAccount(accountId);
    }
  }, [accountId]);

  const loadAccount = async (id: string) => {
    try {
      setLoading(true);
      const response = await api.get(`/mail/accounts/${id}`);
      const account = response?.data || response;

      if (!account) {
        throw new Error('No account data received');
      }

      setFormData({
        email: account.email || "",
        display_name: account.displayName || account.email || "",
        account_type: account.accountType as FormData["account_type"],
        imap_host: account.imapHost || "imap.gmail.com",
        imap_port: account.imapPort || 993,
        smtp_host: account.smtpHost || "smtp.gmail.com",
        smtp_port: account.smtpPort || 587,
        login: account.login || "",
        password: "",
        use_tls: account.useTls !== false,
        sync_mode: account.syncMode || "light",
      });

      setHasExistingPassword(account.hasPassword || false);
      setUserModifiedFields(new Set());

      // При редактировании существующего аккаунта сразу загружаем папки
      // и отмечаем подключение как проверенное
      setConnectionTested(true);
      await loadFoldersForAccount(id);
    } catch (error: any) {
      console.error("Error loading account:", error);
      toast.error("Не удалось загрузить данные аккаунта");
    } finally {
      setLoading(false);
    }
  };

  const handleAccountTypeChange = (type: string) => {
    const preset = presets[type as keyof typeof presets];

    setFormData((prev) => {
      const newData = {
        ...prev,
        account_type: type as FormData["account_type"],
      };

      if (preset && !isEditing) {
        const presetFields = ['imap_host', 'imap_port', 'smtp_host', 'smtp_port', 'use_tls'];

        presetFields.forEach(field => {
          const presetKey = field as keyof typeof preset;
          if (userModifiedFields.has(field)) {
            (newData as any)[field] = (prev as any)[field];
          } else if (preset[presetKey] !== undefined) {
            (newData as any)[field] = preset[presetKey];
          }
        });
      }

      return newData;
    });
  };

  const updateFormField = (field: keyof FormData, value: any) => {
    setUserModifiedFields(prev => {
      const next = new Set(prev);
      next.add(field);
      return next;
    });

    setFormData(prev => ({
      ...prev,
      [field]: value
    }));
  };

  const handleTest = async () => {
    try {
      if (!formData.login || !formData.password) {
        toast.error("Заполните логин и пароль");
        return;
      }

      if (!formData.smtp_host || !formData.smtp_port) {
        toast.error("Заполните SMTP хост и порт");
        return;
      }

      setTestingId("temp-test");

      // Таймаут 30 секунд на тест подключения
      const timeoutPromise = new Promise<never>((_, reject) =>
        setTimeout(() => reject(new Error("Таймаут проверки подключения (30с)")), 30000)
      );

      const testPromise = api.post("/mail/test-connection", {
        login: formData.login,
        password: formData.password,
        imapHost: formData.imap_host,
        imapPort: formData.imap_port,
        smtpHost: formData.smtp_host,
        smtpPort: formData.smtp_port,
        useTls: formData.use_tls,
      });

      const response = await Promise.race([testPromise, timeoutPromise]);

      if (response.results) {
        const { imap, smtp } = response.results;
        const messages: string[] = [];

        if (imap.success) {
          messages.push(`✓ IMAP: ${imap.message}`);
        } else if (imap.error && imap.message !== 'Not tested') {
          messages.push(`✗ IMAP: ${imap.error}`);
        }

        if (smtp.success) {
          messages.push(`✓ SMTP: ${smtp.message}`);
        } else if (smtp.error && smtp.message !== 'Not tested') {
          messages.push(`✗ SMTP: ${smtp.error}`);
        }

        if (imap.success && smtp.success) {
          toast.success(response.message || "Все подключения успешны!");
          setConnectionTested(true);
          if (isEditing && accountId) {
            await loadFoldersForAccount(accountId);
          }
        } else if (imap.success || smtp.success) {
          toast.warning(response.message || "Частичный успех", { description: messages.join('\n') });
          if (imap.success && isEditing && accountId) {
            setConnectionTested(true);
            await loadFoldersForAccount(accountId);
          }
        } else {
          toast.error(response.error || "Все подключения не успешны", { description: messages.join('\n') });
        }
      } else if (response.success || response.message === "Connection successful") {
        toast.success("Подключение успешно!");
        setConnectionTested(true);
        if (isEditing) {
          await loadFoldersForAccount(accountId!);
        }
      }
    } catch (error: any) {
      console.error("Error testing connection:", error);
      if (error.response?.data?.results) {
        const { imap, smtp } = error.response.data.results;
        const messages: string[] = [];

        if (imap.error && imap.message !== 'Not tested') {
          messages.push(`✗ IMAP: ${imap.error}`);
        }

        if (smtp.error && smtp.message !== 'Not tested') {
          messages.push(`✗ SMTP: ${smtp.error}`);
        }

        if (messages.length > 0) {
          toast.error(error.response?.data?.error || "Ошибка подключения", {
            description: messages.join('\n')
          });
        }
      } else {
        const errorMessage = error.response?.data?.details ||
                            error.response?.data?.error ||
                            error.message ||
                            "Не удалось подключиться";
        toast.error(errorMessage);
      }
    } finally {
      setTimeout(() => setTestingId(null), 0);
    }
  };

  const loadFoldersForAccount = async (accountId: string) => {
    try {
      setLoadingFolders(true);

      // Таймаут 15 секунд на загрузку папок
      const timeoutPromise = new Promise<never>((_, reject) =>
        setTimeout(() => reject(new Error("Таймаут загрузки папок (15с)")), 15000)
      );

      const foldersPromise = api.get(`/mail/folders/${accountId}`);
      const response = await Promise.race([foldersPromise, timeoutPromise]);
      const folderList = Array.isArray(response) ? response : (response?.data || []);
      setFolders(folderList);

      const imapTimeoutPromise = new Promise<never>((_, reject) =>
        setTimeout(() => reject(new Error("Таймаут загрузки IMAP папок (15с)")), 15000)
      );
      const imapPromise = api.post(`/mail/accounts/${accountId}/imap-folders`, {});
      const imapResponse = await Promise.race([imapPromise, imapTimeoutPromise]);
      const mappedImapFolders: IMAPFolder[] = imapResponse.map((imapFolder: IMAPFolder) => {
        const matchedFolder = folderList.find((f: MailFolder) =>
          f.imapFolderPath === imapFolder.path ||
          f.folderName.toLowerCase() === imapFolder.name.toLowerCase()
        );
        return {
          ...imapFolder,
          folderType: matchedFolder?.folderType || 'custom',
          matchedFolderId: matchedFolder?.id
        };
      });
      setImapFolders(mappedImapFolders);
    } catch (error: any) {
      console.error('Error loading folders:', error);
      const message = error.message || 'Не удалось загрузить папки';
      toast.error(message);
    } finally {
      setLoadingFolders(false);
    }
  };

  const handleUpdateFolderType = (imapFolder: IMAPFolder, newType: string) => {
    setImapFolders(prev => prev.map(f =>
      f.path === imapFolder.path ? { ...f, folderType: newType } : f
    ));
  };

  const handleSyncFolders = async () => {
    try {
      setLoadingFolders(true);
      if (!accountId) {
        toast.error('Сначала сохраните аккаунт');
        return;
      }

      const response = await api.post(`/mail/accounts/${accountId}/imap-folders`, {});
      const mappedImapFolders: IMAPFolder[] = response.map((imapFolder: IMAPFolder) => {
        const matchedFolder = folders.find((f: MailFolder) =>
          f.imapFolderPath === imapFolder.path ||
          f.folderName.toLowerCase() === imapFolder.name.toLowerCase()
        );
        return {
          ...imapFolder,
          folderType: matchedFolder?.folderType || 'custom',
          matchedFolderId: matchedFolder?.id
        };
      });
      setImapFolders(mappedImapFolders);
      toast.success(`Загружено ${response.length} IMAP папок`);
    } catch (error: any) {
      console.error('Error syncing folders:', error);
      const errorMsg = error.response?.data?.details || error.message || 'Ошибка синхронизации';
      toast.error(`Ошибка: ${errorMsg}`);
    } finally {
      setLoadingFolders(false);
    }
  };

  const handleSave = async () => {
    try {
      if (!formData.email || !formData.login) {
        toast.error("Заполните все обязательные поля");
        return;
      }

      if (!isEditing && !formData.password) {
        toast.error("Заполните пароль для нового аккаунта");
        return;
      }

      if (isEditing && !hasExistingPassword && !formData.password) {
        toast.error("Заполните пароль");
        return;
      }

      const payload: any = {
        email: formData.email,
        displayName: formData.display_name,
        accountType: formData.account_type,
        imapHost: formData.imap_host || "imap.gmail.com",
        imapPort: formData.imap_port || 993,
        smtpHost: formData.smtp_host || "smtp.gmail.com",
        smtpPort: formData.smtp_port || 587,
        login: formData.login,
        useTls: formData.use_tls,
        syncMode: formData.sync_mode,
      };

      if (formData.password) {
        payload.password = formData.password;
      }

      setSaving(true);

      if (isEditing) {
        await api.put(`/mail/accounts/${accountId}`, payload);

        // Сохраняем сопоставление папок если они есть
        if (imapFolders.length > 0) {
          try {
            let savedCount = 0;
            for (const imapFolder of imapFolders) {
              if (imapFolder.matchedFolderId) {
                await api.put(`/mail/folders/${imapFolder.matchedFolderId}`, {
                  folderType: imapFolder.folderType,
                  imapFolderPath: imapFolder.path
                });
                savedCount++;
              } else {
                await api.post('/mail/folders', {
                  accountId: accountId,
                  folderName: imapFolder.name,
                  folderType: imapFolder.folderType,
                  imapFolderPath: imapFolder.path
                });
                savedCount++;
              }
            }
            if (savedCount > 0) {
              toast.success(`Аккаунт обновлён, сохранено ${savedCount} папок`);
            } else {
              toast.success("Аккаунт обновлён");
            }
          } catch (folderError) {
            console.error('Error saving folders:', folderError);
            toast.success("Аккаунт обновлён (ошибка сохранения папок)");
          }
        } else {
          toast.success("Аккаунт обновлён");
        }
      } else {
        await api.post("/mail/accounts", payload);
        toast.success("Аккаунт добавлен");
      }

      onSave?.();
    } catch (error: any) {
      console.error("Error saving account:", error);
      toast.error("Не удалось сохранить аккаунт");
    } finally {
      setSaving(false);
    }
  };

  const titleText = isEditing ? "Редактировать аккаунт" : "Добавить новый аккаунт";
  const descriptionText = isEditing ? "Обновление настроек почтового аккаунта" : "Заполните форму для добавления почтового аккаунта";

  const settingsContent = (
    <div className="flex-1 overflow-y-auto px-6 py-4 space-y-4">
      {/* Основные настройки */}
      <div className="space-y-1">
        <Label htmlFor="email" className="text-sm font-medium">
          Email <span className="text-red-500">*</span>
        </Label>
        <Input
          id="email"
          type="email"
          value={formData.email}
          onChange={(e) =>
            setFormData((prev) => ({ ...prev, email: e.target.value }))
          }
          placeholder="example@mail.ru"
          className="h-10"
          disabled={loading || saving}
        />
      </div>

      <div className="space-y-1">
        <Label htmlFor="displayName" className="text-sm font-medium">
          Отображаемое имя
        </Label>
        <Input
          id="displayName"
          value={formData.display_name}
          onChange={(e) =>
            setFormData((prev) => ({
              ...prev,
              display_name: e.target.value,
            }))
          }
          placeholder="Мой аккаунт"
          className="h-9"
          disabled={loading || saving}
        />
      </div>

      <div className="space-y-1">
        <Label htmlFor="accountType" className="text-sm font-medium">
          Тип аккаунта
        </Label>
        <select
          id="accountType"
          className="w-full h-9 px-3 border border-input rounded-md bg-background text-sm"
          value={formData.account_type}
          onChange={(e) => handleAccountTypeChange(e.target.value)}
          disabled={loading || saving}
        >
          <option value="gmail">Gmail</option>
          <option value="outlook">Outlook/Office365</option>
          <option value="mailru">Mail.ru</option>
          <option value="imap">Другой (IMAP/SMTP)</option>
        </select>
        {formData.account_type === 'mailru' && (
          <p className="text-xs text-muted-foreground mt-1">
            ✓ Настройки Mail.ru: IMAP imap.mail.ru:993, SMTP smtp.mail.ru:465 (SSL/TLS)
          </p>
        )}
      </div>

      <div className="space-y-1">
        <Label htmlFor="syncMode" className="text-sm font-medium">
          Режим загрузки вложений
        </Label>
        <select
          id="syncMode"
          className="w-full h-9 px-3 border border-input rounded-md bg-background text-sm"
          value={formData.sync_mode}
          onChange={(e) => updateFormField("sync_mode", e.target.value)}
          disabled={loading || saving}
        >
          <option value="light">Лёгкий (скачиваются по требованию)</option>
          <option value="heavy">Стандартный (скачивать всё сразу)</option>
        </select>
        <p className="text-xs text-muted-foreground mt-1">
          "Лёгкий режим" экономит место на диске. В стандартном режиме все файлы выкачиваются в процессе фоновой синхронизации по расписанию.
        </p>
      </div>

      {/* Настройки IMAP/SMTP */}
      {(formData.account_type === "imap" || formData.account_type === "mailru" || isEditing || formData.imap_host?.includes("imap")) && (
        <>
          <div className="grid grid-cols-2 gap-3">
            <div className="space-y-1">
              <Label htmlFor="imapHost" className="text-sm font-medium">
                IMAP сервер
              </Label>
              <Input
                id="imapHost"
                value={formData.imap_host || ""}
                onChange={(e) => updateFormField('imap_host', e.target.value)}
                placeholder="imap.mail.ru"
                className="h-9"
                disabled={loading || saving}
              />
            </div>
            <div className="space-y-1">
              <Label htmlFor="imapPort" className="text-sm font-medium">
                IMAP порт
              </Label>
              <Input
                id="imapPort"
                type="number"
                value={formData.imap_port || 993}
                onChange={(e) => updateFormField('imap_port', parseInt(e.target.value))}
                className="h-9"
                disabled={loading || saving}
              />
            </div>
          </div>

          <div className="grid grid-cols-2 gap-3">
            <div className="space-y-1">
              <Label htmlFor="smtpHost" className="text-sm font-medium">
                SMTP сервер
              </Label>
              <Input
                id="smtpHost"
                value={formData.smtp_host || ""}
                onChange={(e) => updateFormField('smtp_host', e.target.value)}
                placeholder="smtp.mail.ru"
                className="h-9"
                disabled={loading || saving}
              />
            </div>
            <div className="space-y-1">
              <Label htmlFor="smtpPort" className="text-sm font-medium">
                SMTP порт
              </Label>
              <Input
                id="smtpPort"
                type="number"
                value={formData.smtp_port || 587}
                onChange={(e) => updateFormField('smtp_port', parseInt(e.target.value))}
                className="h-9"
                disabled={loading || saving}
              />
            </div>
          </div>
        </>
      )}

      <div className="space-y-1">
        <Label htmlFor="login" className="text-sm font-medium">
          Логин <span className="text-red-500">*</span>
        </Label>
        <Input
          id="login"
          value={formData.login}
          onChange={(e) =>
            setFormData((prev) => ({ ...prev, login: e.target.value }))
          }
          placeholder="your@email.com"
          className="h-9"
          disabled={loading || saving}
        />
      </div>

      <div className="space-y-1">
        <div className="flex items-center justify-between">
          <Label htmlFor="password" className="text-sm font-medium">
            Пароль <span className="text-red-500">*</span>
          </Label>
          <span className="text-xs text-muted-foreground">
            {isEditing
              ? (hasExistingPassword ? "опционально" : "обязательно")
              : "обязательно"}
          </span>
        </div>
        <div className="relative">
          <Input
            id="password"
            type={showPassword ? "text" : "password"}
            value={formData.password}
            onChange={(e) =>
              setFormData((prev) => ({
                ...prev,
                password: e.target.value,
              }))
            }
            placeholder="••••••••"
            className="h-9 pr-10"
            disabled={loading || saving}
          />
          <button
            type="button"
            onClick={() => setShowPassword(!showPassword)}
            className="absolute right-3 top-1/2 -translate-y-1/2 text-muted-foreground hover:text-foreground transition-colors"
            tabIndex={-1}
          >
            {showPassword ? (
              <EyeOff className="w-4 h-4" />
            ) : (
              <Eye className="w-4 h-4" />
            )}
          </button>
        </div>
        {isEditing && (
          <p className="text-xs text-muted-foreground mt-1">
            {hasExistingPassword
              ? "Оставьте пусто если не менять. Введите новый чтобы обновить."
              : "Введите пароль если хотите проверить подключение"}
          </p>
        )}
      </div>

      <div className="flex items-center gap-2">
        <input
          type="checkbox"
          id="useTls"
          checked={formData.use_tls}
          onChange={(e) => updateFormField('use_tls', e.target.checked)}
          disabled={loading || saving}
        />
        <Label htmlFor="useTls" className="cursor-pointer text-sm">
          Использовать SSL/TLS
        </Label>
      </div>

      {/* Кнопка проверки подключения */}
      <div className="pt-2">
        <Button
          type="button"
          variant="outline"
          className="w-full"
          onClick={handleTest}
          disabled={testingId === "temp-test" || !formData.login || !formData.password || !formData.smtp_host || !formData.smtp_port || loading || saving}
        >
          {testingId === "temp-test" ? (
            <>
              <Loader className="w-4 h-4 mr-2 animate-spin" />
              Проверка подключения...
            </>
          ) : (
            <>
              <CheckCircle className="w-4 h-4 mr-2" />
              Проверить подключение
            </>
          )}
        </Button>
        {!connectionTested && (
          <p className="text-xs text-muted-foreground mt-2 text-center">
            💡 После успешного теста станут доступны настройки папок
          </p>
        )}
      </div>

      {/* Секция настроек папок */}
      {connectionTested && isEditing && (
        <div className="mt-6 pt-6 border-t space-y-4">
          <div className="flex items-center justify-between">
            <div>
              <h3 className="text-sm font-semibold flex items-center gap-2">
                <Folder className="w-4 h-4" />
                Настройки папок
              </h3>
              <p className="text-xs text-muted-foreground">
                Сопоставление IMAP папок с системными
              </p>
            </div>
            <div className="flex gap-2">
              <Button
                onClick={handleSyncFolders}
                size="sm"
                variant="outline"
                disabled={loadingFolders}
                className="gap-2 h-8"
              >
                <RefreshCw className={cn("w-3 h-3", loadingFolders && "animate-spin")} />
                Загрузить IMAP
              </Button>
            </div>
          </div>

          {loadingFolders ? (
            <div className="flex items-center justify-center py-8">
              <Loader className="w-5 h-5 animate-spin text-muted-foreground" />
              <span className="ml-2 text-sm text-muted-foreground">Загрузка папок...</span>
            </div>
          ) : imapFolders.length > 0 ? (
            <div className="space-y-2">
              <Alert className="mb-3">
                <AlertCircle className="h-3 w-3" />
                <AlertDescription className="text-xs">
                  Настройте тип для каждой IMAP папки и нажмите "Обновить" для сохранения
                </AlertDescription>
              </Alert>

              <div className="space-y-1 max-h-64 overflow-y-auto">
                {imapFolders.map((imapFolder) => (
                  <div
                    key={imapFolder.path}
                    className="flex items-center justify-between p-2 border rounded-lg"
                  >
                    <div className="flex items-center gap-2 flex-1 min-w-0">
                      <Folder className="w-3 h-3 text-muted-foreground flex-shrink-0" />
                      <div className="min-w-0">
                        <p className="text-sm font-medium truncate">{imapFolder.name}</p>
                        <p className="text-xs text-muted-foreground">
                          {imapFolder.path}
                        </p>
                      </div>
                    </div>
                    <Select
                      value={imapFolder.folderType || 'custom'}
                      onValueChange={(value) => handleUpdateFolderType(imapFolder, value)}
                    >
                      <SelectTrigger className="w-[160px] h-8">
                        <SelectValue />
                      </SelectTrigger>
                      <SelectContent>
                        <SelectItem value="inbox">📥 Входящие</SelectItem>
                        <SelectItem value="sent">📤 Отправленные</SelectItem>
                        <SelectItem value="drafts">📝 Черновики</SelectItem>
                        <SelectItem value="archive">📁 Архив</SelectItem>
                        <SelectItem value="spam">⚠️ Спам</SelectItem>
                        <SelectItem value="trash">🗑️ Корзина</SelectItem>
                        <SelectItem value="custom">📁 Пользовательская</SelectItem>
                      </SelectContent>
                    </Select>
                  </div>
                ))}
              </div>
            </div>
          ) : (
            <div className="text-center py-8 text-muted-foreground">
              <Folder className="w-8 h-8 mx-auto mb-2 opacity-50" />
              <p className="text-sm">Папки не загружены</p>
              <Button
                variant="link"
                onClick={handleSyncFolders}
                className="mt-1"
                size="sm"
              >
                Загрузить из IMAP
              </Button>
            </div>
          )}
        </div>
      )}
    </div>
  );

  const settingsFooter = (
    <div className="px-6 py-4 border-t bg-muted/30">
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-2">
          {connectionTested && isEditing && (
            <Badge variant="outline" className="gap-1">
              <CheckCircle className="w-3 h-3 text-green-600" />
              Подключение провержено
            </Badge>
          )}
        </div>

        <div className="flex items-center gap-2">
          <Button
            variant="outline"
            onClick={onCancel || (() => {})}
            disabled={loading || saving}
          >
            Отмена
          </Button>
          <Button 
            onClick={handleSave}
            disabled={loading || saving}
            className="gap-2"
          >
            {saving ? (
              <>
                <Loader className="w-4 h-4 animate-spin" />
                {isEditing ? "Сохранение..." : "Добавление..."}
              </>
            ) : (
              <>
                <Send className="w-4 h-4" />
                {isEditing ? "Обновить" : "Добавить"}
              </>
            )}
          </Button>
        </div>
      </div>
    </div>
  );

  if (variant === 'page') {
    return (
      <div className="flex-1 flex flex-col h-full">
        <div className="flex items-center gap-2 px-4 py-3 border-b bg-muted/30">
          <Button variant="ghost" size="icon" onClick={onCancel || (() => {})} disabled={loading || saving}>
            <ChevronLeft className="h-4 w-4" />
          </Button>
          <div className="flex flex-col">
            <div className="text-lg font-semibold">{titleText}</div>
            <div className="text-xs text-muted-foreground">{descriptionText}</div>
          </div>
        </div>

        <div className="flex-1 min-h-0">
          <ScrollArea className="h-full">
            {settingsContent}
          </ScrollArea>
        </div>

        {settingsFooter}
      </div>
    );
  }

  // Dialog variant можно добавить позже если понадобится
  return settingsContent;
}

