import React, { useState, useRef, useCallback } from 'react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Textarea } from '@/components/ui/textarea';
import { ScrollArea } from '@/components/ui/scroll-area';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Label } from '@/components/ui/label';
import {
  Send,
  Paperclip,
  Bold,
  Italic,
  Underline,
  Link,
  List,
  ListOrdered,
  AlignLeft,
  AlignCenter,
  AlignRight,
  File,
  Trash2,
  Eye,
  EyeOff,
  Save,
  ChevronLeft,
  BookTemplate,
  Loader2
} from 'lucide-react';
import { useTranslation } from '@/lib/i18n';
import { api } from '@/lib/api';
import { toast } from 'sonner';
import { cn } from '@/lib/utils';
import { Badge } from '@/components/ui/badge';
import { Progress } from '@/components/ui/progress';

interface Attachment {
  id: string;
  filename: string;
  size: number;
  contentType: string;
  url?: string;
}

interface MailComposeProps {
  open: boolean;
  onClose: () => void;
  accountId?: string;
  onSent?: () => void;
  variant?: 'dialog' | 'page';
  // Для ответа/пересылки
  replyTo?: {
    subject: string;
    sender: string;
    senderEmail: string;
    content: string;
    date: string;
    recipients?: string[]; // Для "ответить всем"
  };
  // Для черновика
  draft?: {
    id: string;
    to: string;
    cc: string;
    bcc: string;
    subject: string;
    body: string;
  };
}

const fixMojibake = (value: string) => {
  if (!value) return value;
  if (!/[ÐÑÃ]/.test(value)) return value;

  try {
    const bytes = Uint8Array.from(value, (char) => char.charCodeAt(0));
    const decoded = new TextDecoder('utf-8').decode(bytes);
    return decoded.includes('\u0000') ? value : decoded;
  } catch {
    return value;
  }
};

export function MailCompose({
  open,
  onClose,
  accountId,
  onSent,
  variant = 'dialog',
  replyTo,
  draft
}: MailComposeProps) {
  const { t } = useTranslation();

  const [to, setTo] = useState('');
  const [subject, setSubject] = useState('');
  const [body, setBody] = useState('');
  const [cc, setCc] = useState('');
  const [bcc, setBcc] = useState('');

  const [loading, setLoading] = useState(false);
  const [showAdvanced, setShowAdvanced] = useState(!!draft || !!replyTo);
  const [attachments, setAttachments] = useState<Attachment[]>([]);
  const [uploading, setUploading] = useState(false);
  const [uploadProgress, setUploadProgress] = useState(0);
  const [isHtmlMode, setIsHtmlMode] = useState(false);
  const [savingDraft, setSavingDraft] = useState(false);
  const [draftId, setDraftId] = useState<string | null>(draft?.id || null);

  // Шаблоны
  const [templates, setTemplates] = useState<any[]>([]);
  const [isTemplateDialogOpen, setIsTemplateDialogOpen] = useState(false);
  const [loadingTemplates, setLoadingTemplates] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);

  React.useEffect(() => {
    if (open) {
      if (replyTo) {
        setSubject(`Re: ${replyTo.subject}`);
        setTo(replyTo.senderEmail || '');

        if (replyTo.recipients && replyTo.recipients.length > 0) {
          const otherRecipients = replyTo.recipients
            .filter(r => r !== replyTo.senderEmail)
            .join(', ');
          if (otherRecipients) {
            setCc(otherRecipients);
          }
        }

        if (replyTo.content) {
          const date = new Date(replyTo.date).toLocaleString('ru-RU');
          setBody(`\n\n---\n${replyTo.sender} <${replyTo.senderEmail}>, ${date}:\n\n> ${replyTo.content.split('\n').join('\n> ')}`);
        }
      } else if (draft) {
        setTo(draft.to || '');
        setSubject(draft.subject || '');
        setBody(draft.body || '');
        setCc(draft.cc || '');
        setBcc(draft.bcc || '');
      } else {
        setTo('');
        setSubject('');
        setBody('');
        setCc('');
        setBcc('');
      }
    }
  }, [replyTo, draft, open]);

  const fetchTemplates = async () => {
    setLoadingTemplates(true);
    try {
      const data = await api.get('/mail/templates');
      setTemplates(data || []);
    } catch (err) {
      toast.error('Не удалось загрузить шаблоны');
    } finally {
      setLoadingTemplates(false);
    }
  };

  const handleApplyTemplate = (template: any) => {
    if (template.subject && !subject) setSubject(template.subject);

    // Вставляем текст (простая конкатенация для примера, можно улучшить)
    const newBody = body ? `${body}\n\n${template.content}` : template.content;
    setBody(newBody);

    setIsTemplateDialogOpen(false);
    toast.success(`Применен шаблон: ${template.name}`);
  };

  React.useEffect(() => {
    if (!open) {
      setTo('');
      setSubject('');
      setBody('');
      setCc('');
      setBcc('');
      setAttachments([]);
      setDraftId(null);
    }
  }, [open]);

  const execCommand = (command: string, value?: string) => {
    document.execCommand(command, false, value);
    textareaRef.current?.focus();
  };

  const handleBold = () => execCommand('bold');
  const handleItalic = () => execCommand('italic');
  const handleUnderline = () => execCommand('underline');
  const handleJustifyLeft = () => execCommand('justifyLeft');
  const handleJustifyCenter = () => execCommand('justifyCenter');
  const handleJustifyRight = () => execCommand('justifyRight');
  const handleInsertUnorderedList = () => execCommand('insertUnorderedList');
  const handleInsertOrderedList = () => execCommand('insertOrderedList');

  const handleInsertLink = () => {
    const url = prompt('Введите URL ссылки:');
    if (url) {
      execCommand('createLink', url);
    }
  };

  const normalizeAttachment = (attachment: any): Attachment => ({
    id: attachment?.id || '',
    filename: fixMojibake(attachment?.filename || attachment?.name || 'attachment'),
    size: Number(attachment?.size ?? attachment?.file_size ?? 0),
    contentType: attachment?.contentType || attachment?.content_type || '',
    url: attachment?.url || attachment?.stored_path,
  });

  const handleFileSelect = useCallback(async (event: React.ChangeEvent<HTMLInputElement>) => {
    const files = event.target.files;
    if (!files || files.length === 0) return;

    let tempMailId = draftId;
    if (!tempMailId) {
      try {
        const tempResponse = await api.post('/mail', {
          accountId: accountId || '',
          to: to || 'temp@example.com',
          subject: subject || 'Черновик',
          content: body || '',
          saveToSent: false
        });
        tempMailId = tempResponse.mailId;
        setDraftId(tempMailId);
      } catch (error) {
        toast.error('Ошибка при создании черновика');
        return;
      }
    }

    setUploading(true);
    setUploadProgress(0);

    try {
      const formData = new FormData();
      for (let i = 0; i < files.length; i++) {
        formData.append('files', files[i]);
      }

      const progressInterval = setInterval(() => {
        setUploadProgress(prev => Math.min(prev + 10, 90));
      }, 200);

      const response = await api.post(`/mail/${tempMailId}/attachments`, formData);

      clearInterval(progressInterval);
      setUploadProgress(100);

      const uploaded = Array.isArray(response) ? response : [];
      const fileList = Array.from(files);
      const normalized = uploaded.map((item, index) => {
        const fallbackSize = fileList[index]?.size ?? 0;
        const responseSize = Number(item?.size ?? item?.file_size);
        const size = Number.isFinite(responseSize) && responseSize > 0
          ? responseSize
          : fallbackSize;
        return normalizeAttachment({
          ...item,
          size
        });
      });

      setAttachments(prev => [...prev, ...normalized]);
      toast.success(`Загружено ${normalized.length} вложение(ий)`);
    } catch (error) {
      console.error('Upload error:', error);
      toast.error('Ошибка при загрузке вложений');
    } finally {
      setUploading(false);
      setUploadProgress(0);
      if (fileInputRef.current) {
        fileInputRef.current.value = '';
      }
    }
  }, [accountId, to, subject, body, draftId]);

  const handleRemoveAttachment = async (attachmentId: string) => {
    try {
      await api.delete(`/mail/attachments/${attachmentId}`);
      setAttachments(prev => prev.filter(a => a.id !== attachmentId));
      toast.success('Вложение удалено');
    } catch (error) {
      toast.error('Ошибка при удалении вложения');
    }
  };

  const formatFileSize = (bytes: number): string => {
    if (!Number.isFinite(bytes)) return '';
    if (bytes === 0) return '0 Bytes';
    const k = 1024;
    const sizes = ['Bytes', 'KB', 'MB', 'GB'];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return Math.round(bytes / Math.pow(k, i) * 100) / 100 + ' ' + sizes[i];
  };

  const handleSend = async () => {
    if (!to.trim()) {
      toast.error('Укажите получателя');
      return;
    }

    if (!subject.trim()) {
      toast.error('Укажите тему');
      return;
    }

    if (!body.trim()) {
      toast.error('Введите текст письма');
      return;
    }

    if (!accountId) {
      toast.error('Выберите почтовый аккаунт');
      return;
    }

    try {
      setLoading(true);

      const attachmentIds = attachments.map(a => a.id);

      const response = await api.post('/mail', {
        accountId,
        to: to.split(',').map(e => e.trim()).filter(Boolean),
        cc: cc ? cc.split(',').map(e => e.trim()).filter(Boolean) : [],
        bcc: bcc ? bcc.split(',').map(e => e.trim()).filter(Boolean) : [],
        subject,
        content: body,
        htmlContent: isHtmlMode ? body : undefined,
        attachmentIds: attachmentIds.length > 0 ? attachmentIds : undefined
      });

      console.log('✅ Mail sent:', response);
      toast.success('Письмо отправлено!');

      onSent?.();
      handleClose();
    } catch (error: any) {
      console.error('❌ Failed to send mail:', error);
      const errorMsg = error.response?.data?.details || error.message || 'Ошибка при отправке';
      toast.error(errorMsg);
    } finally {
      setLoading(false);
    }
  };

  const handleSaveDraft = async () => {
    if (!accountId) {
      toast.error('Выберите почтовый аккаунт');
      return;
    }

    try {
      setSavingDraft(true);

      const payload: any = {
        accountId,
        to: to || '',
        subject: subject || 'Без темы',
        content: body || '',
        saveToSent: false
      };

      if (cc) payload.cc = cc;
      if (bcc) payload.bcc = bcc;

      if (draftId) {
        toast.info('Черновик обновлён');
      } else {
        const response = await api.post('/mail', payload);
        setDraftId(response.mailId);
        toast.success('Черновик сохранён');
      }
    } catch (error) {
      console.error('Draft save error:', error);
      toast.error('Ошибка при сохранении черновика');
    } finally {
      setSavingDraft(false);
    }
  };

  const handleClose = async () => {
    if ((to || subject || body || attachments.length > 0) && !draftId) {
      const confirmClose = await import('@/components/ui/confirm-dialog').then(m =>
        m.showConfirm({ title: 'Закрыть черновик', description: 'Письмо не сохранено. Закрыть?', confirmText: 'Закрыть', variant: 'destructive' })
      );
      if (!confirmClose) return;
    }
    onClose();
  };

  const titleText = replyTo
    ? (replyTo?.recipients && replyTo.recipients.length > 1 ? 'Ответить всем' : 'Ответить')
    : draft
      ? 'Редактировать черновик'
      : 'Новое письмо';

  const descriptionText = accountId
    ? 'Отправка с аккаунта'
    : 'Выберите аккаунт для отправки';

  const composeBody = (
    <div className="flex-1 overflow-y-auto px-6 py-4 space-y-4">
      <div className="space-y-1">
        <Label htmlFor="to" className="text-sm font-medium flex items-center gap-2">
          <span>Кому</span>
          <span className="text-red-500">*</span>
        </Label>
        <Input
          id="to"
          placeholder="email@example.com"
          value={to}
          onChange={(e) => setTo(e.target.value)}
          disabled={loading || savingDraft}
          className="h-10"
        />
      </div>

      {showAdvanced && (
        <div className="space-y-3 animate-in slide-in-from-top-2 duration-200">
          <div className="space-y-1">
            <Label htmlFor="cc" className="text-sm font-medium">
              Копия (CC)
            </Label>
            <Input
              id="cc"
              placeholder="cc@example.com"
              value={cc}
              onChange={(e) => setCc(e.target.value)}
              disabled={loading || savingDraft}
              className="h-9"
            />
          </div>

          <div className="space-y-1">
            <Label htmlFor="bcc" className="text-sm font-medium">
              Скрытая копия (BCC)
            </Label>
            <Input
              id="bcc"
              placeholder="bcc@example.com"
              value={bcc}
              onChange={(e) => setBcc(e.target.value)}
              disabled={loading || savingDraft}
              className="h-9"
            />
          </div>
        </div>
      )}

      <div className="space-y-1">
        <Label htmlFor="subject" className="text-sm font-medium flex items-center gap-2">
          <span>Тема</span>
          <span className="text-red-500">*</span>
        </Label>
        <Input
          id="subject"
          placeholder="Тема письма"
          value={subject}
          onChange={(e) => setSubject(e.target.value)}
          disabled={loading || savingDraft}
          className="h-10"
        />
      </div>

      <div className="flex items-center gap-1 flex-wrap">
        <Button variant="ghost" size="icon" onClick={handleBold}><Bold className="h-4 w-4" /></Button>
        <Button variant="ghost" size="icon" onClick={handleItalic}><Italic className="h-4 w-4" /></Button>
        <Button variant="ghost" size="icon" onClick={handleUnderline}><Underline className="h-4 w-4" /></Button>
        <div className="w-px h-5 bg-border mx-1" />
        <Button variant="ghost" size="icon" onClick={handleJustifyLeft}><AlignLeft className="h-4 w-4" /></Button>
        <Button variant="ghost" size="icon" onClick={handleJustifyCenter}><AlignCenter className="h-4 w-4" /></Button>
        <Button variant="ghost" size="icon" onClick={handleJustifyRight}><AlignRight className="h-4 w-4" /></Button>
        <div className="w-px h-5 bg-border mx-1" />
        <Button variant="ghost" size="icon" onClick={handleInsertUnorderedList}><List className="h-4 w-4" /></Button>
        <Button variant="ghost" size="icon" onClick={handleInsertOrderedList}><ListOrdered className="h-4 w-4" /></Button>
        <div className="w-px h-5 bg-border mx-1" />
        <Button variant="ghost" size="icon" onClick={handleInsertLink}><Link className="h-4 w-4" /></Button>

        <div className="flex-1" />

        <Button
          variant="ghost"
          size="sm"
          className={cn("h-8 gap-1", isHtmlMode && "bg-primary text-primary-foreground")}
          onClick={() => setIsHtmlMode(!isHtmlMode)}
        >
          {isHtmlMode ? <Eye className="h-4 w-4" /> : <EyeOff className="h-4 w-4" />}
          <span className="text-xs">{isHtmlMode ? 'HTML' : 'Текст'}</span>
        </Button>
      </div>

      <div className="space-y-1">
        <Label htmlFor="body" className="text-sm font-medium">
          Сообщение <span className="text-red-500">*</span>
        </Label>
        <Textarea
          ref={textareaRef}
          id="body"
          placeholder="Введите текст письма..."
          value={body}
          onChange={(e) => setBody(e.target.value)}
          disabled={loading || savingDraft}
          className={cn(
            "min-h-[300px] resize-y font-normal",
            isHtmlMode && "font-mono text-sm"
          )}
        />
      </div>

      {(attachments.length > 0 || uploading) && (
        <div className="space-y-2">
          <Label className="text-sm font-medium">Вложения</Label>
          <div className="flex flex-wrap gap-2">
            {attachments.map((attachment) => (
              <Badge
                key={attachment.id}
                variant="secondary"
                className="flex items-center gap-2 px-3 py-1.5 h-auto"
              >
                <File className="h-3.5 w-3.5" />
                <span className="max-w-[150px] truncate" title={attachment.filename}>
                  {attachment.filename}
                </span>
                <span className="text-xs text-muted-foreground">
                  {formatFileSize(attachment.size)}
                </span>
                <button
                  onClick={() => handleRemoveAttachment(attachment.id)}
                  className="ml-1 hover:text-destructive transition-colors"
                >
                  <Trash2 className="h-3.5 w-3.5" />
                </button>
              </Badge>
            ))}
          </div>
          {uploading && (
            <div className="space-y-1">
              <Progress value={uploadProgress} className="h-1" />
              <p className="text-xs text-muted-foreground">Загрузка вложений...</p>
            </div>
          )}
        </div>
      )}
    </div>
  );

  const composeFooter = (
    <div className="px-6 py-4 border-t bg-muted/30">
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-2">
          <input
            type="file"
            ref={fileInputRef}
            onChange={handleFileSelect}
            className="hidden"
            multiple
            disabled={loading || savingDraft}
          />
          <Button
            variant="outline"
            size="sm"
            onClick={() => fileInputRef.current?.click()}
            disabled={loading || savingDraft || uploading}
            className="gap-2"
          >
            <Paperclip className="h-4 w-4" />
            Вложение
          </Button>
          <Button
            variant="outline"
            size="sm"
            onClick={handleSaveDraft}
            disabled={loading || savingDraft}
            className="gap-2"
          >
            <Save className={cn("h-4 w-4", savingDraft && "animate-pulse")} />
            {savingDraft ? 'Сохранение...' : 'Черновик'}
          </Button>
          <Button
            variant="outline"
            size="sm"
            onClick={() => {
              fetchTemplates();
              setIsTemplateDialogOpen(true);
            }}
            className="gap-2 text-primary border-primary/20 hover:bg-primary/5"
          >
            <BookTemplate className="h-4 w-4" />
            Шаблоны
          </Button>
        </div>

        <div className="flex items-center gap-2">
          <Button
            variant="outline"
            onClick={handleClose}
            disabled={loading || savingDraft}
          >
            Отмена
          </Button>
          <Button
            onClick={handleSend}
            disabled={loading || savingDraft || !to || !subject || !body}
            className="gap-2 bg-primary hover:bg-primary/90"
          >
            {loading ? (
              <>
                <span className="animate-pulse">⏳</span>
                Отправка...
              </>
            ) : (
              <>
                <Send className="h-4 w-4" />
                Отправить
              </>
            )}
          </Button>
        </div>
      </div>

      {replyTo && (
        <p className="text-xs text-muted-foreground mt-2">
          Ответ на письмо от {replyTo.sender} &lt;{replyTo.senderEmail}&gt;
        </p>
      )}
    </div>
  );

  if (variant === 'page') {
    return (
      <div className="flex-1 flex flex-col h-full">
        <div className="flex items-center gap-2 px-4 py-3 border-b bg-muted/30">
          <Button variant="ghost" size="icon" onClick={handleClose} disabled={loading || savingDraft}>
            <ChevronLeft className="h-4 w-4" />
          </Button>
          <div className="flex flex-col">
            <div className="text-lg font-semibold">{titleText}</div>
            <div className="text-xs text-muted-foreground">{descriptionText}</div>
          </div>
        </div>

        <div className="flex-1 min-h-0">
          <ScrollArea className="h-full">
            {composeBody}
          </ScrollArea>
        </div>

        {composeFooter}
      </div>
    );
  }

  return (
    <Dialog open={open} onOpenChange={(nextOpen) => !nextOpen && handleClose()}>
      <DialogContent className="max-w-4xl max-h-[95vh] flex flex-col p-0 gap-0">
        <DialogHeader className="px-6 pt-6 pb-4 border-b">
          <div className="flex items-center justify-between">
            <div>
              <DialogTitle className="text-xl">{titleText}</DialogTitle>
              <DialogDescription className="text-sm text-muted-foreground">
                {descriptionText}
              </DialogDescription>
            </div>
          </div>
        </DialogHeader>

        {composeBody}

        {composeFooter}
      </DialogContent>

      <Dialog open={isTemplateDialogOpen} onOpenChange={setIsTemplateDialogOpen}>
        <DialogContent className="max-w-md">
          <DialogHeader>
            <DialogTitle>Выберите шаблон</DialogTitle>
            <DialogDescription>
              Текст шаблона будет добавлен в тело письма
            </DialogDescription>
          </DialogHeader>
          <div className="py-4">
            {loadingTemplates ? (
              <div className="flex justify-center p-4"><Loader2 className="animate-spin" /></div>
            ) : templates.length === 0 ? (
              <p className="text-center text-muted-foreground py-8">Шаблонов пока нет</p>
            ) : (
              <ScrollArea className="max-h-[300px]">
                <div className="space-y-2">
                  {templates.map(t => (
                    <button
                      key={t.id}
                      onClick={() => handleApplyTemplate(t)}
                      className="w-full text-left p-3 border rounded-md hover:bg-muted transition-colors"
                    >
                      <div className="font-medium">{t.name}</div>
                      {t.subject && <div className="text-xs text-muted-foreground truncate">Тема: {t.subject}</div>}
                    </button>
                  ))}
                </div>
              </ScrollArea>
            )}
          </div>
        </DialogContent>
      </Dialog>
    </Dialog>
  );
}

import React, { useEffect, useRef, useState } from 'react';
import { cn } from '@/lib/utils';
import {
  Mail,
  Reply,
  ReplyAll,
  Forward,
  Eye,
  EyeOff,
  FolderOpen,
  Trash2,
  ShieldAlert,
  Tag,
  Printer,
  Plus,
  ChevronRight,
} from 'lucide-react';

interface MailContextMenuProps {
  mail: any;
  folders: Array<{ id: string; folderName: string; folderType: string }>;
  labels?: string[];
  onSelectAction: (action: string, mail: any, data?: any) => void;
  onClose: () => void;
  position: { x: number; y: number };
}

export function MailContextMenu({
  mail,
  folders,
  labels = [],
  onSelectAction,
  onClose,
  position,
}: MailContextMenuProps) {
  const menuRef = useRef<HTMLDivElement>(null);
  const [adjustedPos, setAdjustedPos] = useState(position);

  useEffect(() => {
    const handleClickOutside = (e: MouseEvent) => {
      if (menuRef.current && !menuRef.current.contains(e.target as Node)) {
        onClose();
      }
    };

    const handleEsc = (e: KeyboardEvent) => {
      if (e.key === 'Escape') {
        onClose();
      }
    };

    const handleContextMenu = (e: MouseEvent) => {
      e.preventDefault();
      onClose();
    };

    document.addEventListener('mousedown', handleClickOutside);
    document.addEventListener('keydown', handleEsc);
    document.addEventListener('contextmenu', handleContextMenu);

    return () => {
      document.removeEventListener('mousedown', handleClickOutside);
      document.removeEventListener('keydown', handleEsc);
      document.removeEventListener('contextmenu', handleContextMenu);
    };
  }, [onClose]);

  // Корректировка позиции чтобы меню не выходило за экран
  useEffect(() => {
    if (!menuRef.current) return;

    const rect = menuRef.current.getBoundingClientRect();
    let newX = position.x;
    let newY = position.y;

    if (newX + rect.width > window.innerWidth) {
      newX = window.innerWidth - rect.width - 8;
    }
    if (newY + rect.height > window.innerHeight) {
      newY = window.innerHeight - rect.height - 8;
    }

    newX = Math.max(0, newX);
    newY = Math.max(0, newY);

    setAdjustedPos({ x: newX, y: newY });
  }, [position]);

  const handleAction = (action: string, data?: any) => {
    console.log('[MailContextMenu] handleAction called:', action, 'mailId:', mail.id, 'data:', data);
    onSelectAction(action, mail, data);
    onClose();
  };

  const systemFolderTypes = new Set(['system', 'inbox', 'sent', 'drafts', 'archive', 'spam', 'trash']);
  const isSystemFolder = (folderType?: string) => systemFolderTypes.has((folderType || '').toLowerCase());

  const systemFolders = folders.filter(f => isSystemFolder(f.folderType));
  const userFolders = folders.filter(f => !isSystemFolder(f.folderType));

  const [hoveredSubmenu, setHoveredSubmenu] = useState<string | null>(null);

  return (
    <div
      ref={menuRef}
      className="fixed z-[9999] bg-popover border rounded-md shadow-md py-1 min-w-[220px]"
      style={{
        left: adjustedPos.x,
        top: adjustedPos.y,
      }}
      onClick={(e) => e.stopPropagation()}
    >
      {/* Основные действия */}
      <button
        className="w-full px-2 py-1.5 text-sm flex items-center hover:bg-accent cursor-pointer"
        onClick={() => handleAction('open')}
      >
        <Mail className="mr-2 h-4 w-4" />
        Открыть
      </button>

      <div className="my-1 h-px bg-border" />

      <button
        className="w-full px-2 py-1.5 text-sm flex items-center hover:bg-accent cursor-pointer"
        onClick={() => handleAction('reply')}
      >
        <Reply className="mr-2 h-4 w-4" />
        Ответить
      </button>

      <button
        className="w-full px-2 py-1.5 text-sm flex items-center hover:bg-accent cursor-pointer"
        onClick={() => handleAction('replyAll')}
      >
        <ReplyAll className="mr-2 h-4 w-4" />
        Ответить всем
      </button>

      <button
        className="w-full px-2 py-1.5 text-sm flex items-center hover:bg-accent cursor-pointer"
        onClick={() => handleAction('forward')}
      >
        <Forward className="mr-2 h-4 w-4" />
        Переслать
      </button>

      <div className="my-1 h-px bg-border" />

      {/* Статус прочтения */}
      <button
        className="w-full px-2 py-1.5 text-sm flex items-center hover:bg-accent cursor-pointer"
        onClick={() => handleAction('markRead', !mail.isRead)}
      >
        {mail.isRead ? (
          <>
            <EyeOff className="mr-2 h-4 w-4" />
            Пометить как непрочитанное
          </>
        ) : (
          <>
            <Eye className="mr-2 h-4 w-4" />
            Пометить как прочитанное
          </>
        )}
      </button>

      <div className="my-1 h-px bg-border" />

      {/* Переместить в папку — подменю */}
      <div
        className="relative group"
        onMouseEnter={() => setHoveredSubmenu('folder')}
        onMouseLeave={() => setHoveredSubmenu(null)}
      >
        <button
          className="w-full px-2 py-1.5 text-sm flex items-center justify-between hover:bg-accent cursor-pointer"
        >
          <span className="flex items-center">
            <FolderOpen className="mr-2 h-4 w-4" />
            Переместить в папку
          </span>
          <ChevronRight className="h-3 w-3" />
        </button>

        {hoveredSubmenu === 'folder' && (
          <div className="absolute left-full top-0 ml-1 bg-popover border rounded-md shadow-md py-1 min-w-[180px] z-[10000]">
            {systemFolders.map(folder => (
              <button
                key={folder.id}
                className="w-full px-2 py-1.5 text-sm text-left hover:bg-accent cursor-pointer"
                onClick={() => handleAction('moveToFolder', folder.id)}
              >
                {folder.folderName}
              </button>
            ))}

            {systemFolders.length > 0 && userFolders.length > 0 && (
              <div className="my-1 h-px bg-border" />
            )}

            {userFolders.map(folder => (
              <button
                key={folder.id}
                className="w-full px-2 py-1.5 text-sm text-left hover:bg-accent cursor-pointer"
                onClick={() => handleAction('moveToFolder', folder.id)}
              >
                {folder.folderName}
              </button>
            ))}
          </div>
        )}
      </div>

      <div className="my-1 h-px bg-border" />

      {/* Удалить */}
      <button
        className="w-full px-2 py-1.5 text-sm flex items-center hover:bg-accent cursor-pointer text-destructive"
        onClick={() => handleAction('delete')}
      >
        <Trash2 className="mr-2 h-4 w-4" />
        Удалить
      </button>

      {/* Спам */}
      <button
        className="w-full px-2 py-1.5 text-sm flex items-center hover:bg-accent cursor-pointer text-destructive"
        onClick={() => handleAction('spam')}
      >
        <ShieldAlert className="mr-2 h-4 w-4" />
        Спам
      </button>

      <div className="my-1 h-px bg-border" />

      {/* Добавить метку — подменю */}
      <div
        className="relative group"
        onMouseEnter={() => setHoveredSubmenu('label')}
        onMouseLeave={() => setHoveredSubmenu(null)}
      >
        <button
          className="w-full px-2 py-1.5 text-sm flex items-center justify-between hover:bg-accent cursor-pointer"
        >
          <span className="flex items-center">
            <Tag className="mr-2 h-4 w-4" />
            Добавить метку
          </span>
          <ChevronRight className="h-3 w-3" />
        </button>

        {hoveredSubmenu === 'label' && (
          <div className="absolute left-full top-0 ml-1 bg-popover border rounded-md shadow-md py-1 min-w-[180px] z-[10000]">
            {labels.length > 0 ? (
              labels.map(label => (
                <button
                  key={label}
                  className="w-full px-2 py-1.5 text-sm text-left hover:bg-accent cursor-pointer"
                  onClick={() => handleAction('addLabel', label)}
                >
                  {label}
                </button>
              ))
            ) : (
              <div className="px-2 py-1.5 text-sm text-muted-foreground">
                Нет меток
              </div>
            )}

            {labels.length > 0 && (
              <div className="my-1 h-px bg-border" />
            )}

            <button
              className="w-full px-2 py-1.5 text-sm flex items-center hover:bg-accent cursor-pointer"
              onClick={() => handleAction('createLabel')}
            >
              <Plus className="mr-2 h-4 w-4" />
              Создать новую метку
            </button>
          </div>
        )}
      </div>

      <div className="my-1 h-px bg-border" />

      {/* Печать */}
      <button
        className="w-full px-2 py-1.5 text-sm flex items-center hover:bg-accent cursor-pointer"
        onClick={() => handleAction('print')}
      >
        <Printer className="mr-2 h-4 w-4" />
        Печать
      </button>
    </div>
  );
}

