import React, { useEffect, useRef, useState } from 'react';
import { cn } from '@/lib/utils';
import { Button } from '@/components/ui/button';
import { ScrollArea } from '@/components/ui/scroll-area';
import { Avatar, AvatarFallback, AvatarImage } from '@/components/ui/avatar';
import { Separator } from '@/components/ui/separator';
import {
  Reply,
  Forward,
  Trash2,
  Paperclip,
  Download,
  Save,
  Star,
  CheckCircle,
  FolderOpen,
  ShieldAlert,
  Copy,
  Search,
  ExternalLink,
  List,
  FileText,
  FileImage,
  FileArchive,
  FileSpreadsheet,
  FileType,
  File,
  ChevronLeft,
  ChevronDown,
  Loader2,
} from 'lucide-react';
import { Mail, Attachment } from '../types';
import { useTranslation } from '@/lib/i18n';
import { format } from 'date-fns';
import { ru } from 'date-fns/locale';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu';
import { toast } from 'sonner';
import { api } from '@/lib/api';
import { transformMailData } from '../utils/mailUtils';

interface MailDisplayProps {
  mail?: Mail;
  folders?: Array<{ id: string; folderName: string; folderType: string }>;
  onReply?: (mail: Mail) => void;
  onForward?: (mail: Mail) => void;
  onArchive?: (mail: Mail) => void;
  onDelete?: (mail: Mail) => void;
  onMove?: (mail: Mail) => void;
  onMailUpdate?: () => void;
  setViewMode?: (mode: 'list' | 'mail' | 'compose') => void;
  // MAIL-9: Навигация между письмами
  filteredMails?: Mail[];
  selectedMail?: Mail | null;
  setSelectedMail?: (mail: Mail | null) => void;
}

export function MailDisplay({
  mail,
  folders,
  onReply,
  onForward,
  onArchive,
  onDelete,
  onMove,
  onMailUpdate,
  setViewMode,
  filteredMails = [],
  selectedMail,
  setSelectedMail
}: MailDisplayProps) {
  const { t } = useTranslation();
  const [deleting, setDeleting] = useState(false);
  const [resolvedAttachments, setResolvedAttachments] = useState<Mail['attachments']>(mail?.attachments || []);
  const [attachmentsLoading, setAttachmentsLoading] = useState(false);
  const [attachmentsLoadError, setAttachmentsLoadError] = useState<string | null>(null);
  const [attachmentPreviews, setAttachmentPreviews] = useState<Record<string, string>>({});
  // Состояние загрузки отдельных вложений (on-demand из IMAP)
  const [downloadingAttachments, setDownloadingAttachments] = useState<Set<string>>(new Set());
  const iframeRef = useRef<HTMLIFrameElement | null>(null);
  const iframeResizeObserver = useRef<ResizeObserver | null>(null);
  // MAIL-13: Контекстное меню для текста
  const [contextMenuOpen, setContextMenuOpen] = useState(false);
  const [selectedText, setSelectedText] = useState('');
  const [clickedLink, setClickedLink] = useState<string | null>(null);

  // Thread (Похожие письма)
  const [threadMails, setThreadMails] = useState<Mail[]>([]);
  const [threadLoading, setThreadLoading] = useState(false);

  const systemFolderTypes = new Set(['system', 'inbox', 'sent', 'drafts', 'archive', 'spam', 'trash']);
  const isSystemFolder = (folderType?: string) => systemFolderTypes.has((folderType || '').toLowerCase());

  const fixMojibake = (value: string) => {
    if (!value) return value;
    if (!/[ÐÑÃ]/.test(value)) return value;

    try {
      const bytes = Uint8Array.from(value, (char) => char.charCodeAt(0));
      const decoded = new TextDecoder('utf-8').decode(bytes);
      return decoded.includes('\u0000') ? value : decoded;
    } catch {
      return value;
    }
  };

  const normalizeAttachment = (attachment: any) => ({
    id: attachment?.id || '',
    name: fixMojibake(attachment?.name || attachment?.filename || 'attachment'),
    size: Number(attachment?.size ?? attachment?.file_size ?? 0),
    type: attachment?.type || attachment?.content_type || '',
    url: attachment?.url || attachment?.stored_path || '',
  });

  const isPreviewable = (attachment: Attachment | undefined) =>
    Boolean(attachment?.type?.startsWith('image/') || attachment?.type === 'application/pdf');

  const getFileIcon = (attachment: Attachment | undefined) => {
    const name = (attachment?.name || '').toLowerCase();
    const type = (attachment?.type || '').toLowerCase();
    const ext = name.includes('.') ? name.split('.').pop() || '' : '';

    if (type.startsWith('image/') || ['png', 'jpg', 'jpeg', 'gif', 'webp', 'bmp', 'svg'].includes(ext)) {
      return FileImage;
    }

    if (type === 'application/pdf' || ext === 'pdf') {
      return FileType;
    }

    if (['xlsx', 'xls', 'csv', 'ods'].includes(ext)) {
      return FileSpreadsheet;
    }

    if (['zip', 'rar', '7z', 'tar', 'gz'].includes(ext)) {
      return FileArchive;
    }

    if (['doc', 'docx', 'rtf', 'txt', 'odt'].includes(ext)) {
      return FileText;
    }

    return File;
  };

  const loadAttachments = async (mailId: string) => {
    setAttachmentsLoading(true);
    setAttachmentsLoadError(null);

    try {
      const response = await api.get(`/mail/${mailId}/attachments`);
      const normalized = Array.isArray(response)
        ? response.map((attachment: any) => normalizeAttachment(attachment))
        : [];

      if (normalized.length > 0) {
        setResolvedAttachments(normalized);
        return;
      }

      // Fallback: у некоторых писем вложения приходят только в деталях письма
      const detailedMail = await api.get(`/mail/${mailId}`);
      const fromDetails = Array.isArray(detailedMail?.attachments)
        ? detailedMail.attachments.map((attachment: any) => normalizeAttachment(attachment))
        : [];

      setResolvedAttachments(fromDetails);
    } catch (error) {
      console.error('[MailDisplay] Failed to load attachments:', error);
      setAttachmentsLoadError('Не удалось загрузить вложения');
    } finally {
      setAttachmentsLoading(false);
    }
  };

  const loadThread = async (mailId: string) => {
    setThreadLoading(true);
    try {
      const resp = await api.get(`/mail/${mailId}/thread`);
      const threadData = Array.isArray(resp) ? resp : (resp?.mails || []);
      const transformed = transformMailData(threadData);
      setThreadMails(transformed || []);
    } catch (err) {
      console.warn('Failed to load thread:', err);
    } finally {
      setThreadLoading(false);
    }
  };

  useEffect(() => {
    const currentAttachments = mail?.attachments || [];
    setResolvedAttachments(currentAttachments);
    setAttachmentsLoadError(null);

    if (!mail?.id || currentAttachments.length > 0) {
      setAttachmentsLoading(false);
    } else {
      loadAttachments(mail.id);
    }

    if (mail?.id) {
      loadThread(mail.id);
    }
  }, [mail?.id, mail?.attachments]);

  useEffect(() => {
    let isActive = true;
    const createdUrls: string[] = [];

    setAttachmentPreviews({});

    const loadPreviews = async () => {
      for (const attachment of resolvedAttachments || []) {
        if (!attachment?.id || !isPreviewable(attachment)) {
          continue;
        }

        try {
          const blob = await api.get(`/mail/attachments/download/${attachment.id}`, {
            responseType: 'blob'
          });
          const url = window.URL.createObjectURL(new Blob([blob]));
          createdUrls.push(url);

          if (isActive) {
            setAttachmentPreviews((prev) => ({
              ...prev,
              [attachment.id]: url
            }));
          }
        } catch (error) {
          console.warn('[MailDisplay] Preview load failed:', error);
        }
      }
    };

    if (resolvedAttachments?.length) {
      loadPreviews();
    }

    return () => {
      isActive = false;
      createdUrls.forEach((url) => window.URL.revokeObjectURL(url));
    };
  }, [resolvedAttachments]);

  // MAIL-9: Навигация между письмами
  const currentIndex = mail ? filteredMails.findIndex(m => m.id === mail.id) : -1;
  const hasPrevious = currentIndex > 0;
  const hasNext = currentIndex < filteredMails.length - 1;

  const handlePrevious = () => {
    if (hasPrevious && setSelectedMail) {
      setSelectedMail(filteredMails[currentIndex - 1]);
    }
  };

  const handleNext = () => {
    if (hasNext && setSelectedMail) {
      setSelectedMail(filteredMails[currentIndex + 1]);
    }
  };

  const handleTextContextMenu = (e: React.MouseEvent) => {
    const selection = window.getSelection();
    const selected = selection?.toString() || '';

    // Проверяем, кликнули ли на ссылку
    const target = e.target as HTMLElement;
    const link = target.closest('a');

    setSelectedText(selected);
    setClickedLink(link?.href || null);
    setContextMenuOpen(true);
  };

  const handleCopy = async () => {
    if (selectedText) {
      await navigator.clipboard.writeText(selectedText);
      toast.success('Текст скопирован в буфер обмена');
    }
  };

  const adjustIframeHeight = (iframe: HTMLIFrameElement | null) => {
    if (!iframe) return;
    const doc = iframe.contentDocument || iframe.contentWindow?.document;
    if (!doc) return;

    const body = doc.body;
    const html = doc.documentElement;
    const height = Math.max(
      body?.scrollHeight || 0,
      body?.offsetHeight || 0,
      html?.scrollHeight || 0,
      html?.offsetHeight || 0
    );

    iframe.style.height = `${Math.max(height, 400)}px`;
  };

  useEffect(() => {
    return () => {
      iframeResizeObserver.current?.disconnect();
      iframeResizeObserver.current = null;
    };
  }, []);

  const handleFindInText = () => {
    const searchText = prompt('Найти в тексте:');
    if (searchText && mail?.content) {
      const index = mail.content.toLowerCase().indexOf(searchText.toLowerCase());
      if (index >= 0) {
        toast.success(`Найдено совпадение (позиция ${index})`);
      } else {
        toast.info('Совпадений не найдено');
      }
    }
  };

  if (!mail) {
    return (
      <div className="flex-1 flex items-center justify-center p-8 text-muted-foreground">
        <div className="text-center">
          <p className="text-lg mb-2">{t('mail.select_message')}</p>
          <p className="text-sm">{t('mail.no_selection_desc')}</p>
        </div>
      </div>
    );
  }

  const handleDelete = async () => {
    if (!mail.id) return;

    try {
      setDeleting(true);
      await api.delete(`/mail/${mail.id}`);
      toast.success('Письмо удалено');
      onDelete?.(mail);
    } catch (error) {
      toast.error('Ошибка при удалении письма');
    } finally {
      setDeleting(false);
    }
  };

  const handleStar = async () => {
    if (!mail?.id) return;

    try {
      await api.patch(`/mail/${mail.id}/star`, { isStarred: !mail.isStarred });
      toast.success(mail.isStarred ? 'Удалено из избранного' : 'Добавлено в избранное');
      // Обновляем список писем
      onMailUpdate?.();
    } catch (error) {
      toast.error('Ошибка при обновлении статуса');
    }
  };

  const handleMarkRead = async () => {
    if (!mail?.id) return;

    try {
      await api.patch(`/mail/${mail.id}/read`, { isRead: !mail.isRead });
      toast.success(mail.isRead ? 'Отмечено как непрочитанное' : 'Отмечено как прочитанное');
      // Обновляем список писем
      onMailUpdate?.();
    } catch (error) {
      toast.error('Ошибка при обновлении статуса');
    }
  };

  const handleDownloadAttachment = async (attachmentId: string, filename: string) => {
    // Добавляем в состояние загрузки
    setDownloadingAttachments(prev => new Set(prev).add(attachmentId));

    try {
      const response = await api.get(`/mail/attachments/download/${attachmentId}`, {
        responseType: 'blob'
      });

      const url = window.URL.createObjectURL(new Blob([response]));
      const link = document.createElement('a');
      link.href = url;
      link.setAttribute('download', filename);
      document.body.appendChild(link);
      link.click();
      link.remove();
      window.URL.revokeObjectURL(url);

      toast.success('Вложение скачано');
    } catch (error) {
      console.error('[AttachmentDownload] Error:', error);
      toast.error('Ошибка при скачивании вложения');
    } finally {
      // Удаляем из состояния загрузки
      setDownloadingAttachments(prev => {
        const next = new Set(prev);
        next.delete(attachmentId);
        return next;
      });
    }
  };

  const handleSaveToDocs = async (attachmentId: string) => {
    try {
      const resp = await api.post(`/mail/attachments/${attachmentId}/save-to-docs`, {});
      toast.success('Файл сохранен в Документы');
    } catch (error) {
      console.error('Save to docs error:', error);
      toast.error('Ошибка при сохранении в Документы');
    }
  };

  const formatFileSize = (bytes: number): string => {
    if (!bytes) return '';
    if (bytes < 1024) return bytes + ' B';
    if (bytes < 1024 * 1024) return (bytes / 1024).toFixed(1) + ' KB';
    return (bytes / (1024 * 1024)).toFixed(1) + ' MB';
  };

  const getInitials = (name?: string) => {
    if (!name) return '?';
    const parts = name.split(' ');
    if (parts.length >= 2) {
      return (parts[0][0] + parts[1][0]).toUpperCase();
    }
    return name.charAt(0).toUpperCase();
  };

  return (
    <div className="flex-1 flex flex-col h-full">
      {/* MAIL-9: Верхняя панель с кнопкой Назад */}
      <div className="flex items-center gap-1 p-2 border-b bg-muted/30">
        <Button
          variant="ghost"
          size="sm"
          onClick={() => setViewMode?.('list')}
          title="Назад к списку"
          className="h-8 gap-2"
        >
          <ChevronLeft className="h-4 w-4" />
          <span>Назад</span>
        </Button>
        <div className="h-4 w-px bg-border mx-1" />
        <Button
          variant="ghost"
          size="icon"
          onClick={() => {
            const recipients: string[] = [];
            if (typeof mail.sender === 'object' && mail.sender?.email) {
              recipients.push(mail.sender.email);
            } else if (typeof mail.sender === 'string') {
              recipients.push(mail.sender);
            }
            onReply?.({ ...mail, recipients });
          }}
          title="Ответить"
        >
          <Reply className="h-4 w-4" />
        </Button>
        <Button
          variant="ghost"
          size="icon"
          onClick={() => onForward?.(mail)}
          title="Переслать"
        >
          <Forward className="h-4 w-4" />
        </Button>
        <div className="h-4 w-px bg-border mx-1" />
        <Button
          variant="ghost"
          size="icon"
          onClick={handleStar}
          title={mail.isStarred ? "Удалить из избранного" : "В избранное"}
        >
          <Star className={cn("h-4 w-4", mail.isStarred && "fill-yellow-400 text-yellow-400")} />
        </Button>
        <Button
          variant="ghost"
          size="icon"
          onClick={handleMarkRead}
          title={mail.isRead ? "Отметить как непрочитанное" : "Отметить как прочитанное"}
        >
          <CheckCircle className="h-4 w-4" />
        </Button>
        <DropdownMenu modal={false}>
          <DropdownMenuTrigger asChild>
            <Button variant="ghost" size="icon" title="В папку">
              <FolderOpen className="h-4 w-4" />
            </Button>
          </DropdownMenuTrigger>
          <DropdownMenuContent align="start">
            {folders?.filter(f => isSystemFolder(f.folderType)).map(folder => (
              <DropdownMenuItem
                key={folder.id}
                onClick={() => {
                  api.patch(`/mail/${mail.id}/move`, { folderId: folder.id });
                  toast.success(`Перемещено в ${folder.folderName}`);
                  onMailUpdate?.();
                }}
              >
                {folder.folderName}
              </DropdownMenuItem>
            ))}
            {folders && folders.filter(f => isSystemFolder(f.folderType)).length > 0 && folders.filter(f => !isSystemFolder(f.folderType)).length > 0 && (
              <DropdownMenuSeparator />
            )}
            {folders?.filter(f => !isSystemFolder(f.folderType)).map(folder => (
              <DropdownMenuItem
                key={folder.id}
                onClick={() => {
                  api.patch(`/mail/${mail.id}/move`, { folderId: folder.id });
                  toast.success(`Перемещено в ${folder.folderName}`);
                  onMailUpdate?.();
                }}
              >
                {folder.folderName}
              </DropdownMenuItem>
            ))}
          </DropdownMenuContent>
        </DropdownMenu>
        <Button
          variant="ghost"
          size="icon"
          onClick={async () => {
            const spamFolder = folders?.find(f => f.folderName.toLowerCase().includes('spam'));
            if (!spamFolder) {
              toast.error('Папка Spam не найдена');
              return;
            }
            try {
              await api.patch(`/mail/${mail.id}/move`, { folderId: spamFolder.id });
              toast.success('Перемещено в спам');
              onMailUpdate?.();
            } catch (error) {
              toast.error('Ошибка при перемещении в спам');
            }
          }}
          title="Спам"
        >
          <ShieldAlert className="h-4 w-4 text-destructive" />
        </Button>
        <div className="h-4 w-px bg-border mx-1" />
        <Button
          variant="ghost"
          size="icon"
          onClick={handleDelete}
          disabled={deleting}
          title="Удалить"
        >
          <Trash2 className="h-4 w-4 text-destructive" />
        </Button>
        <div className="flex-1" />
        {/* MAIL-9: Навигация между письмами */}
        <Button
          variant="ghost"
          size="sm"
          onClick={handlePrevious}
          disabled={!hasPrevious}
          title="Предыдущее"
          className="h-8"
        >
          <ChevronDown className="h-4 w-4 rotate-180" />
        </Button>
        <Button
          variant="ghost"
          size="sm"
          onClick={handleNext}
          disabled={!hasNext}
          title="Следующее"
          className="h-8"
        >
          <ChevronDown className="h-4 w-4" />
        </Button>
      </div>

      {/* Subject */}
      <div className="px-4 py-3 border-b bg-muted/30">
        <h2 className="text-lg font-semibold">{mail.subject || t('mail.no_subject')}</h2>
        <div className="flex items-center gap-4 mt-1 text-xs text-muted-foreground">
          <span>
            {(() => {
              try {
                const date = mail.timestamp ? new Date(mail.timestamp) : new Date();
                if (isNaN(date.getTime())) return t('mail.invalid_date');
                return format(date, 'd MMMM yyyy, H:mm', { locale: ru });
              } catch {
                return t('mail.invalid_date');
              }
            })()}
          </span>
          {mail.hasAttachments && (
            <span className="flex items-center gap-1">
              <Paperclip className="h-3 w-3" />
              {t('mail.has_attachments')}
            </span>
          )}
        </div>
      </div>

      {/* Content */}
      <ScrollArea className="flex-1">
        <div className="p-6 bg-white">
          {(mail.htmlContent && mail.htmlContent.trim()) ? (
            <iframe
              data-testid="mail-html-content"
              srcDoc={`
                <!DOCTYPE html>
                <html>
                <head>
                  <meta charset="UTF-8">
                  <meta name="viewport" content="width=device-width, initial-scale=1.0">
                  <style>
                    body {
                      font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
                      padding: 16px;
                      margin: 0;
                      background: transparent;
                      line-height: 1.5;
                      color: #333;
                    }
                    html, body {
                      height: auto !important;
                      overflow: visible !important;
                    }
                    img {
                      max-width: 100%;
                      height: auto;
                    }
                    table {
                      border-collapse: collapse;
                    }
                    a {
                      color: #0066cc;
                      text-decoration: none;
                    }
                    a:hover {
                      text-decoration: underline;
                    }
                    blockquote {
                      border-left: 3px solid #ddd;
                      margin: 0;
                      padding-left: 16px;
                      color: #666;
                    }
                    .quote {
                      color: #666;
                      font-size: 0.9em;
                    }
                  </style>
                </head>
                <body>
                  ${mail.htmlContent.replace(/<script\b[^<]*(?:(?!<\/script>)<[^<]*)*<\/script>/gi, '')}
                </body>
                </html>
              `}
              sandbox="allow-same-origin allow-popups allow-popups-to-escape-sandbox"
              style={{
                width: '100%',
                minHeight: '400px',
                border: 'none',
                backgroundColor: 'transparent'
              }}
              title="Mail content"
              onLoad={(e) => {
                const iframe = e.target as HTMLIFrameElement;
                iframeRef.current = iframe;
                iframeResizeObserver.current?.disconnect();
                iframeResizeObserver.current = null;
                adjustIframeHeight(iframe);

                const content = iframe.contentDocument || iframe.contentWindow?.document;
                if (content?.body && typeof ResizeObserver !== 'undefined') {
                  iframeResizeObserver.current = new ResizeObserver(() => adjustIframeHeight(iframe));
                  iframeResizeObserver.current.observe(content.body);
                  if (content.documentElement) {
                    iframeResizeObserver.current.observe(content.documentElement);
                  }
                }

                setTimeout(() => adjustIframeHeight(iframe), 200);
                setTimeout(() => adjustIframeHeight(iframe), 800);
              }}
            />
          ) : (mail.content && mail.content.trim()) ? (
            <div className="prose prose-sm max-w-none">
              <p className="whitespace-pre-wrap text-sm">{mail.content}</p>
            </div>
          ) : (mail.hasAttachments || (resolvedAttachments?.length ?? 0) > 0) ? (
            <div className="prose prose-sm max-w-none text-muted-foreground italic">
              <div className="flex items-center gap-2 mb-2">
                <Paperclip className="h-4 w-4" />
                <p>Письмо содержит только вложения</p>
              </div>
              <p className="text-sm">Проверьте вложения ниже</p>
            </div>
          ) : (
            <div className="prose prose-sm max-w-none text-muted-foreground">
              <div className="flex items-center gap-2 mb-2">
                <FileText className="h-4 w-4" />
                <p>Текст письма недоступен</p>
              </div>
              <p className="text-sm">
                Возможно, письмо содержит только вложения или было отправлено в нестандартном формате.
              </p>
            </div>
          )}
        </div>

        {/* Attachments */}
        {mail.hasAttachments && attachmentsLoading && (resolvedAttachments?.length ?? 0) === 0 && (
          <>
            <Separator className="my-4" />
            <div className="px-6 pb-6 text-sm text-muted-foreground">Загрузка вложений...</div>
          </>
        )}

        {mail.hasAttachments && attachmentsLoadError && (resolvedAttachments?.length ?? 0) === 0 && (
          <>
            <Separator className="my-4" />
            <div className="px-6 pb-6">
              <p className="text-sm text-destructive mb-2">{attachmentsLoadError}</p>
              <Button variant="outline" size="sm" onClick={() => loadAttachments(mail.id)}>
                Повторить загрузку вложений
              </Button>
            </div>
          </>
        )}

        {resolvedAttachments && resolvedAttachments.length > 0 && (
          <>
            <Separator className="my-4" />
            <div className="px-6 pb-6">
              <h4 className="text-sm font-medium mb-3 flex items-center gap-2">
                <Paperclip className="h-4 w-4" />
                {t('mail.attachments')} ({resolvedAttachments.length})
              </h4>
              <div className="flex flex-wrap gap-2">
                {resolvedAttachments.map((attachment) => {
                  const isDownloading = downloadingAttachments.has(attachment.id);
                  const FileIconComponent = getFileIcon(attachment);
                  return (
                  <div
                    key={attachment.id}
                    className={cn(
                      "flex items-center gap-3 p-3 border rounded-lg transition-colors group cursor-pointer",
                      isDownloading ? "bg-muted/30 border-primary/30" : "hover:bg-muted"
                    )}
                    role="button"
                    tabIndex={0}
                    onClick={() => !isDownloading && handleDownloadAttachment(attachment.id, attachment.name)}
                    onKeyDown={(event) => {
                      if (event.key === 'Enter' || event.key === ' ') {
                        event.preventDefault();
                        !isDownloading && handleDownloadAttachment(attachment.id, attachment.name);
                      }
                    }}
                  >
                    <div className="h-12 w-12 rounded-md bg-muted/50 border overflow-hidden flex items-center justify-center relative">
                      {attachmentPreviews[attachment.id] && attachment.type?.startsWith('image/') ? (
                        <img
                          src={attachmentPreviews[attachment.id]}
                          alt={attachment.name}
                          className="h-full w-full object-cover"
                        />
                      ) : (
                        <FileIconComponent className="h-5 w-5 text-muted-foreground" />
                      )}
                      {isDownloading && (
                        <div className="absolute inset-0 bg-background/70 flex items-center justify-center">
                          <Loader2 className="h-5 w-5 text-primary animate-spin" />
                        </div>
                      )}
                    </div>
                    <div className="flex-1 min-w-0">
                      <span className="text-sm font-medium truncate block max-w-[200px]">
                        {attachment.name}
                      </span>
                      <span className="text-xs text-muted-foreground">
                        {formatFileSize(attachment.size)}
                        {isDownloading && (
                          <span className="ml-2 text-primary font-medium">Загрузка...</span>
                        )}
                      </span>
                    </div>
                    <div className="flex items-center gap-2">
                      <Button
                        variant="ghost"
                        size="icon"
                        className="h-8 w-8"
                        onClick={(e) => {
                          e.stopPropagation();
                          handleSaveToDocs(attachment.id);
                        }}
                        title="Сохранить в Документы"
                      >
                        <Save className="h-4 w-4 text-muted-foreground" />
                      </Button>
                      {attachmentPreviews[attachment.id] && attachment.type === 'application/pdf' && (
                        <button
                          type="button"
                          className="text-xs text-primary hover:underline"
                          onClick={(event) => {
                            event.stopPropagation();
                            window.open(attachmentPreviews[attachment.id], '_blank', 'noopener,noreferrer');
                          }}
                        >
                          Открыть
                        </button>
                      )}
                      {isDownloading ? (
                        <Loader2 className="h-4 w-4 text-primary animate-spin" />
                      ) : (
                        <Download className="h-4 w-4 text-muted-foreground group-hover:text-primary transition-colors" />
                      )}
                    </div>
                  </div>
                  );
                })}
              </div>
            </div>
          </>
        )}

        {threadMails.length > 0 && (
          <>
            <Separator className="my-4" />
            <div className="px-6 pb-20">
              <h4 className="text-sm font-medium mb-3 flex items-center gap-2">
                <List className="h-4 w-4" />
                История переписки ({threadMails.length})
              </h4>
              <div className="space-y-1">
                {threadMails.map((m) => (
                  <div
                    key={m.id}
                    onClick={() => setSelectedMail?.(m)}
                    className="flex items-center justify-between p-2 rounded-md hover:bg-muted cursor-pointer text-sm"
                  >
                    <div className="flex flex-col min-w-0 flex-1">
                      <span className="font-medium truncate">{m.subject}</span>
                      <span className="text-xs text-muted-foreground truncate">
                        {m.sender.name || m.sender.email}
                      </span>
                    </div>
                    <div className="text-xs text-muted-foreground ml-4 whitespace-nowrap">
                      {format(new Date(m.timestamp || Date.now()), 'd MMM, HH:mm', { locale: ru })}
                    </div>
                  </div>
                ))}
              </div>
            </div>
          </>
        )}
      </ScrollArea>

      {/* MAIL-13: Контекстное меню для текста */}
      <DropdownMenu open={contextMenuOpen} onOpenChange={setContextMenuOpen} modal={false}>
        <DropdownMenuTrigger asChild>
          <div className="fixed w-0 h-0" />
        </DropdownMenuTrigger>
        <DropdownMenuContent>
          {selectedText && (
            <>
              <DropdownMenuItem onClick={handleCopy}>
                <Copy className="mr-2 h-4 w-4" />
                Копировать
              </DropdownMenuItem>
              <DropdownMenuItem onClick={() => {
                window.getSelection()?.selectAllChildren(document.querySelector('.prose') || document.body);
              }}>
                <List className="mr-2 h-4 w-4" />
                Выделить всё
              </DropdownMenuItem>
              <DropdownMenuSeparator />
            </>
          )}
          <DropdownMenuItem onClick={handleFindInText}>
            <Search className="mr-2 h-4 w-4" />
            Найти в тексте...
          </DropdownMenuItem>
          {clickedLink && (
            <>
              <DropdownMenuSeparator />
              <DropdownMenuItem onClick={() => {
                window.open(clickedLink, '_blank', 'noopener,noreferrer');
              }}>
                <ExternalLink className="mr-2 h-4 w-4" />
                Перейти по ссылке
              </DropdownMenuItem>
            </>
          )}
        </DropdownMenuContent>
      </DropdownMenu>
    </div>
  );
}

import React from 'react';
import { Button } from '@/components/ui/button';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu';
import { Badge } from '@/components/ui/badge';
import { Filter, Check, ArrowUpDown } from 'lucide-react';
import { cn } from '@/lib/utils';

interface MailFilterSortMenuProps {
  filter: 'all' | 'unread' | 'starred' | 'attachments';
  sort: 'date-desc' | 'date-asc' | 'sender-asc' | 'sender-desc' | 'subject-asc' | 'subject-desc';
  onFilterChange: (filter: 'all' | 'unread' | 'starred' | 'attachments') => void;
  onSortChange: (sort: 'date-desc' | 'date-asc' | 'sender-asc' | 'sender-desc' | 'subject-asc' | 'subject-desc') => void;
}

const filterLabels: Record<string, string> = {
  all: 'Все письма',
  unread: 'Непрочитанные',
  starred: 'С флагом',
  attachments: 'С вложениями',
};

const sortLabels: Record<string, string> = {
  'date-desc': 'Сначала новые',
  'date-asc': 'Сначала старые',
  'sender-asc': 'Автор: от А до Я',
  'sender-desc': 'Автор: от Я до А',
  'subject-asc': 'Тема: от А до Я',
  'subject-desc': 'Тема: от Я до А',
};

export function MailFilterSortMenu({
  filter,
  sort,
  onFilterChange,
  onSortChange,
}: MailFilterSortMenuProps) {
  const activeFiltersCount = filter !== 'all' ? 1 : 0;

  return (
    <div className="flex items-center gap-2 shrink-0">
      {/* MAIL-14: Меню фильтров и сортировки */}
      <DropdownMenu modal={false}>
        <DropdownMenuTrigger asChild>
          <Button variant="outline" size="sm" className="gap-2 relative shrink-0">
            <Filter className="h-4 w-4" />
            Фильтр
            {/* Бейдж всегда занимает место, но невидим когда 0 */}
            <span className="absolute -top-2 -right-2 h-5 w-5 flex items-center justify-center pointer-events-none">
              {activeFiltersCount > 0 && (
                <Badge
                  variant="default"
                  className="h-5 w-5 flex items-center justify-center p-0 text-xs"
                >
                  {activeFiltersCount}
                </Badge>
              )}
            </span>
          </Button>
        </DropdownMenuTrigger>
        <DropdownMenuContent align="start" className="w-56">
          {/* Раздел фильтров */}
          <div className="px-2 py-1.5 text-xs font-semibold text-muted-foreground uppercase">
            Фильтр
          </div>
          {Object.entries(filterLabels).map(([key, label]) => (
            <DropdownMenuItem
              key={key}
              onClick={() => onFilterChange(key as any)}
              className={cn(
                'cursor-pointer',
                filter === key && 'bg-muted font-semibold'
              )}
            >
              {label}
              {filter === key && <Check className="ml-auto h-4 w-4" />}
            </DropdownMenuItem>
          ))}

          <DropdownMenuSeparator />

          {/* Раздел сортировки */}
          <div className="px-2 py-1.5 text-xs font-semibold text-muted-foreground uppercase">
            Сортировка
          </div>
          {Object.entries(sortLabels).map(([key, label]) => (
            <DropdownMenuItem
              key={key}
              onClick={() => onSortChange(key as any)}
              className={cn(
                'cursor-pointer',
                sort === key && 'bg-muted font-semibold'
              )}
            >
              {label}
              {sort === key && <Check className="ml-auto h-4 w-4" />}
            </DropdownMenuItem>
          ))}
        </DropdownMenuContent>
      </DropdownMenu>

      {/* MAIL-15: Индикация активной сортировки */}
      <div className="flex items-center gap-1 text-xs text-muted-foreground shrink-0 min-w-[140px] justify-end">
        <ArrowUpDown className="h-3 w-3 shrink-0" />
        <span className="truncate">{sortLabels[sort]}</span>
      </div>
    </div>
  );
}

