import React, { useState, useEffect } from 'react';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Badge } from '@/components/ui/badge';
import { Switch } from '@/components/ui/switch';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from '@/components/ui/dialog';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import {
  Accordion,
  AccordionContent,
  AccordionItem,
  AccordionTrigger,
} from '@/components/ui/accordion';
import { useTranslation } from '@/lib/i18n';
import { api } from '@/lib/api';
import { toast } from 'sonner';
import { 
  Filter, 
  Plus, 
  Edit2, 
  Trash2, 
  Play, 
  Folder, 
  Star, 
  CheckCircle,
  Tag,
  Forward,
  Trash
} from 'lucide-react';

interface MailFilter {
  id: string;
  filterName: string;
  description?: string;
  matchType: 'all' | 'any';
  targetFolderId?: string;
  applyStar?: boolean;
  applyRead?: boolean;
  applyLabelId?: string;
  deleteMail?: boolean;
  forwardTo?: string;
  isActive: boolean;
  displayOrder?: number;
  conditions?: FilterCondition[];
}

interface FilterCondition {
  id?: string;
  conditionType: string;
  operator: string;
  conditionValue: string;
  isRegex?: boolean;
  displayOrder?: number;
}

interface MailFolder {
  id: string;
  folderName: string;
  folderType: string;
}

const conditionTypes = [
  { value: 'from', label: 'Отправитель' },
  { value: 'to', label: 'Получатель' },
  { value: 'subject', label: 'Тема' },
  { value: 'body', label: 'Текст письма' },
  { value: 'has_attachment', label: 'С вложением' },
  { value: 'size', label: 'Размер' },
  { value: 'date', label: 'Дата' },
];

const operators = [
  { value: 'contains', label: 'Содержит' },
  { value: 'equals', label: 'Равно' },
  { value: 'starts_with', label: 'Начинается с' },
  { value: 'ends_with', label: 'Заканчивается на' },
  { value: 'not_contains', label: 'Не содержит' },
  { value: 'regex', label: 'Регулярное выражение' },
  { value: 'greater_than', label: 'Больше' },
  { value: 'less_than', label: 'Меньше' },
];

const defaultCondition: FilterCondition = {
  conditionType: 'from',
  operator: 'contains',
  conditionValue: '',
};

interface MailFiltersTabProps {
  accountId: string;
}

export function MailFiltersTab({ accountId }: MailFiltersTabProps) {
  const { t } = useTranslation();
  const [filters, setFilters] = useState<MailFilter[]>([]);
  const [folders, setFolders] = useState<MailFolder[]>([]);
  const [loading, setLoading] = useState(false);
  const [dialogOpen, setDialogOpen] = useState(false);
  const [editingFilter, setEditingFilter] = useState<MailFilter | null>(null);
  const [applyingFilter, setApplyingFilter] = useState<string | null>(null);

  // Форма фильтра
  const [filterName, setFilterName] = useState('');
  const [description, setDescription] = useState('');
  const [matchType, setMatchType] = useState<'all' | 'any'>('any');
  const [conditions, setConditions] = useState<FilterCondition[]>([defaultCondition]);
  const [targetFolderId, setTargetFolderId] = useState<string>('');
  const [applyStar, setApplyStar] = useState(false);
  const [applyRead, setApplyRead] = useState(false);
  const [deleteMail, setDeleteMail] = useState(false);
  const [forwardTo, setForwardTo] = useState('');

  useEffect(() => {
    if (accountId) {
      fetchFilters();
      fetchFolders();
    }
  }, [accountId]);

  const fetchFilters = async () => {
    try {
      setLoading(true);
      const response = await api.get(`/mail/filters/${accountId}`);
      setFilters(response);
    } catch (error) {
      console.error('Error fetching filters:', error);
      toast.error('Не удалось загрузить фильтры');
    } finally {
      setLoading(false);
    }
  };

  const fetchFolders = async () => {
    try {
      const response = await api.get(`/mail/folders/${accountId}`);
      setFolders(response);
    } catch (error) {
      console.error('Error fetching folders:', error);
    }
  };

  const handleOpenDialog = (filter?: MailFilter) => {
    if (filter) {
      setEditingFilter(filter);
      setFilterName(filter.filterName);
      setDescription(filter.description || '');
      setMatchType(filter.matchType);
      setConditions(filter.conditions?.length ? filter.conditions : [defaultCondition]);
      setTargetFolderId(filter.targetFolderId || '');
      setApplyStar(filter.applyStar || false);
      setApplyRead(filter.applyRead || false);
      setDeleteMail(filter.deleteMail || false);
      setForwardTo(filter.forwardTo || '');
    } else {
      setEditingFilter(null);
      setFilterName('');
      setDescription('');
      setMatchType('any');
      setConditions([defaultCondition]);
      setTargetFolderId('');
      setApplyStar(false);
      setApplyRead(false);
      setDeleteMail(false);
      setForwardTo('');
    }
    setDialogOpen(true);
  };

  const handleSave = async () => {
    if (!filterName.trim() || conditions.length === 0) {
      toast.error('Заполните название и условия фильтра');
      return;
    }

    try {
      const payload = {
        accountId,
        filterName,
        description,
        matchType,
        targetFolderId: targetFolderId || null,
        applyStar,
        applyRead,
        applyLabelId: null, // TODO: поддержка меток
        deleteMail,
        forwardTo: forwardTo || null,
        is_active: true,
      };

      if (editingFilter) {
        await api.put(`/mail/filters/${editingFilter.id}`, payload);
        toast.success('Фильтр обновлён');
      } else {
        await api.post('/mail/filters', payload);
        toast.success('Фильтр создан');
      }

      setDialogOpen(false);
      fetchFilters();
    } catch (error) {
      console.error('Error saving filter:', error);
      toast.error('Не удалось сохранить фильтр');
    }
  };

  const handleDelete = async (filterId: string) => {
    try {
      await api.delete(`/mail/filters/${filterId}`);
      toast.success('Фильтр удалён');
      fetchFilters();
    } catch (error) {
      toast.error('Не удалось удалить фильтр');
    }
  };

  const handleToggleActive = async (filter: MailFilter) => {
    try {
      await api.put(`/mail/filters/${filter.id}`, {
        ...filter,
        isActive: !filter.isActive,
      });
      toast.success(filter.isActive ? 'Фильтр деактивирован' : 'Фильтр активирован');
      fetchFilters();
    } catch (error) {
      toast.error('Не удалось обновить фильтр');
    }
  };

  const handleApplyFilter = async (filterId: string) => {
    try {
      setApplyingFilter(filterId);
      const response = await api.post(`/mail/filters/${filterId}/apply`, {
        limit: 1000,
        dryRun: false,
      });
      toast.success(`Фильтр применён к ${response.matched} письму(ам)`);
    } catch (error) {
      toast.error('Ошибка при применении фильтра');
    } finally {
      setApplyingFilter(null);
    }
  };

  const addCondition = () => {
    setConditions([...conditions, { ...defaultCondition }]);
  };

  const removeCondition = (index: number) => {
    if (conditions.length > 1) {
      setConditions(conditions.filter((_, i) => i !== index));
    }
  };

  const updateCondition = (index: number, field: keyof FilterCondition, value: any) => {
    const newConditions = [...conditions];
    newConditions[index] = { ...newConditions[index], [field]: value };
    setConditions(newConditions);
  };

  const getActionDescription = (filter: MailFilter) => {
    const actions: string[] = [];

    if (filter.targetFolderId) {
      const folder = folders.find(f => f.id === filter.targetFolderId);
      actions.push(`переместить в ${folder?.folderName || 'папку'}`);
    }

    if (filter.applyRead) actions.push('отметить прочитанным');
    if (filter.applyStar) actions.push('добавить в избранное');
    if (filter.deleteMail) actions.push('удалить');
    if (filter.forwardTo) actions.push(`переслать на ${filter.forwardTo}`);

    return actions.join(', ') || 'Нет действий';
  };

  const getActionIcon = (filter: MailFilter) => {
    if (filter.deleteMail) return <Trash className="h-4 w-4 text-destructive" />;
    if (filter.forwardTo) return <Forward className="h-4 w-4" />;
    if (filter.targetFolderId) return <Folder className="h-4 w-4" />;
    if (filter.applyStar) return <Star className="h-4 w-4" />;
    if (filter.applyRead) return <CheckCircle className="h-4 w-4" />;
    return <Filter className="h-4 w-4" />;
  };

  return (
    <Card>
      <CardHeader>
        <div className="flex items-center justify-between">
          <div>
            <CardTitle className="flex items-center gap-2">
              <Filter className="w-5 h-5" />
              Фильтры почты
            </CardTitle>
            <CardDescription>
              Правила автоматической обработки писем
            </CardDescription>
          </div>
          <Button onClick={() => handleOpenDialog()} size="sm" className="gap-2">
            <Plus className="w-4 h-4" />
            Создать фильтр
          </Button>
        </div>
      </CardHeader>

      <CardContent>
        {loading ? (
          <div className="flex items-center justify-center py-8">
            <div className="text-muted-foreground">Загрузка фильтров...</div>
          </div>
        ) : filters.length === 0 ? (
          <div className="text-center py-8 text-muted-foreground">
            <Filter className="w-12 h-12 mx-auto mb-4 opacity-50" />
            <p>Фильтры не созданы</p>
            <p className="text-sm">Создайте первый фильтр для автоматизации</p>
          </div>
        ) : (
          <Accordion type="single" collapsible className="space-y-2">
            {filters.map((filter) => (
              <AccordionItem key={filter.id} value={filter.id}>
                <AccordionTrigger className="hover:no-underline">
                  <div className="flex items-center gap-3 w-full">
                    {getActionIcon(filter)}
                    <div className="text-left flex-1">
                      <div className="flex items-center gap-2">
                        <span className="font-medium">{filter.filterName}</span>
                        <Badge variant={filter.isActive ? 'default' : 'secondary'}>
                          {filter.isActive ? 'Активен' : 'Неактивен'}
                        </Badge>
                        <Badge variant="outline">
                          {filter.matchType === 'all' ? 'Все условия' : 'Любое условие'}
                        </Badge>
                      </div>
                      <p className="text-sm text-muted-foreground">
                        {filter.description || getActionDescription(filter)}
                      </p>
                    </div>
                  </div>
                </AccordionTrigger>
                <AccordionContent>
                  <div className="space-y-4 pt-4">
                    {/* Условия */}
                    <div>
                      <h4 className="text-sm font-medium mb-2">Условия</h4>
                      <div className="space-y-2">
                        {filter.conditions?.map((condition, idx) => (
                          <div key={idx} className="flex items-center gap-2 text-sm">
                            <Badge variant="outline">
                              {conditionTypes.find(t => t.value === condition.conditionType)?.label}
                            </Badge>
                            <span className="text-muted-foreground">
                              {operators.find(o => o.value === condition.operator)?.label}
                            </span>
                            <span className="font-mono bg-muted px-2 py-0.5 rounded">
                              {condition.conditionValue}
                            </span>
                          </div>
                        ))}
                      </div>
                    </div>

                    {/* Действия */}
                    <div>
                      <h4 className="text-sm font-medium mb-2">Действия</h4>
                      <div className="flex flex-wrap gap-2">
                        {getActionDescription(filter).split(', ').map((action, i) => (
                          <Badge key={i} variant="secondary">{action}</Badge>
                        ))}
                      </div>
                    </div>

                    {/* Кнопки управления */}
                    <div className="flex items-center gap-2 pt-2 border-t">
                      <Button
                        variant="outline"
                        size="sm"
                        onClick={() => handleOpenDialog(filter)}
                      >
                        <Edit2 className="w-3.5 h-3.5 mr-1" />
                        Редактировать
                      </Button>
                      <Button
                        variant="outline"
                        size="sm"
                        onClick={() => handleToggleActive(filter)}
                      >
                        {filter.isActive ? 'Деактивировать' : 'Активировать'}
                      </Button>
                      <Button
                        variant="outline"
                        size="sm"
                        onClick={() => handleApplyFilter(filter.id)}
                        disabled={applyingFilter === filter.id || !filter.isActive}
                      >
                        <Play className="w-3.5 h-3.5 mr-1" />
                        {applyingFilter === filter.id ? 'Применение...' : 'Применить к письмам'}
                      </Button>
                      <Button
                        variant="ghost"
                        size="sm"
                        onClick={() => handleDelete(filter.id)}
                        className="text-destructive hover:text-destructive"
                      >
                        <Trash2 className="w-3.5 h-3.5" />
                      </Button>
                    </div>
                  </div>
                </AccordionContent>
              </AccordionItem>
            ))}
          </Accordion>
        )}
      </CardContent>

      {/* Dialog создания/редактирования */}
      <Dialog open={dialogOpen} onOpenChange={setDialogOpen}>
        <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle>
              {editingFilter ? 'Редактировать фильтр' : 'Создать фильтр'}
            </DialogTitle>
            <DialogDescription>
              Настройте правила автоматической обработки писем
            </DialogDescription>
          </DialogHeader>

          <div className="space-y-4 py-4">
            {/* Название и описание */}
            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-2">
                <Label htmlFor="filterName">Название *</Label>
                <Input
                  id="filterName"
                  value={filterName}
                  onChange={(e) => setFilterName(e.target.value)}
                  placeholder="Например: Письма от босса"
                />
              </div>
              <div className="space-y-2">
                <Label htmlFor="description">Описание</Label>
                <Input
                  id="description"
                  value={description}
                  onChange={(e) => setDescription(e.target.value)}
                  placeholder="Описание фильтра"
                />
              </div>
            </div>

            {/* Тип соответствия */}
            <div className="space-y-2">
              <Label>Тип соответствия</Label>
              <Select value={matchType} onValueChange={(v) => setMatchType(v as 'all' | 'any')}>
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="any">Совпадает хотя бы одно условие</SelectItem>
                  <SelectItem value="all">Совпадают все условия</SelectItem>
                </SelectContent>
              </Select>
            </div>

            {/* Условия */}
            <div className="space-y-2">
              <div className="flex items-center justify-between">
                <Label>Условия</Label>
                <Button
                  type="button"
                  variant="outline"
                  size="sm"
                  onClick={addCondition}
                >
                  <Plus className="w-3.5 h-3.5" />
                  Добавить условие
                </Button>
              </div>
              <div className="space-y-2">
                {conditions.map((condition, idx) => (
                  <div key={idx} className="flex items-center gap-2 p-2 border rounded-md">
                    <Select
                      value={condition.conditionType}
                      onValueChange={(v) => updateCondition(idx, 'conditionType', v)}
                    >
                      <SelectTrigger className="w-[150px]">
                        <SelectValue />
                      </SelectTrigger>
                      <SelectContent>
                        {conditionTypes.map((type) => (
                          <SelectItem key={type.value} value={type.value}>
                            {type.label}
                          </SelectItem>
                        ))}
                      </SelectContent>
                    </Select>

                    <Select
                      value={condition.operator}
                      onValueChange={(v) => updateCondition(idx, 'operator', v)}
                    >
                      <SelectTrigger className="w-[150px]">
                        <SelectValue />
                      </SelectTrigger>
                      <SelectContent>
                        {operators.map((op) => (
                          <SelectItem key={op.value} value={op.value}>
                            {op.label}
                          </SelectItem>
                        ))}
                      </SelectContent>
                    </Select>

                    {condition.conditionType !== 'has_attachment' && (
                      <Input
                        value={condition.conditionValue}
                        onChange={(e) => updateCondition(idx, 'conditionValue', e.target.value)}
                        placeholder="Значение"
                        className="flex-1"
                      />
                    )}

                    {conditions.length > 1 && (
                      <Button
                        type="button"
                        variant="ghost"
                        size="icon"
                        onClick={() => removeCondition(idx)}
                      >
                        <Trash2 className="w-3.5 h-3.5" />
                      </Button>
                    )}
                  </div>
                ))}
              </div>
            </div>

            {/* Действия */}
            <div className="space-y-3">
              <Label>Действия при срабатывании</Label>

              <div className="grid grid-cols-2 gap-4">
                <div className="flex items-center justify-between space-x-2 p-3 border rounded-md">
                  <div className="flex items-center gap-2">
                    <Folder className="w-4 h-4" />
                    <Label htmlFor="targetFolder" className="cursor-pointer">
                      Переместить в папку
                    </Label>
                  </div>
                  <Select value={targetFolderId || ""} onValueChange={setTargetFolderId}>
                    <SelectTrigger className="w-[150px]" id="targetFolder">
                      <SelectValue placeholder="Выбрать папку" />
                    </SelectTrigger>
                    <SelectContent>
                      {folders.map((folder) => (
                        <SelectItem key={folder.id} value={folder.id}>
                          {folder.folderName}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>

                <div className="flex items-center justify-between space-x-2 p-3 border rounded-md">
                  <div className="flex items-center gap-2">
                    <Star className="w-4 h-4" />
                    <Label htmlFor="applyStar" className="cursor-pointer">
                      В избранное
                    </Label>
                  </div>
                  <Switch
                    id="applyStar"
                    checked={applyStar}
                    onCheckedChange={setApplyStar}
                  />
                </div>

                <div className="flex items-center justify-between space-x-2 p-3 border rounded-md">
                  <div className="flex items-center gap-2">
                    <CheckCircle className="w-4 h-4" />
                    <Label htmlFor="applyRead" className="cursor-pointer">
                      Прочитано
                    </Label>
                  </div>
                  <Switch
                    id="applyRead"
                    checked={applyRead}
                    onCheckedChange={setApplyRead}
                  />
                </div>

                <div className="flex items-center justify-between space-x-2 p-3 border rounded-md">
                  <div className="flex items-center gap-2">
                    <Trash className="w-4 h-4 text-destructive" />
                    <Label htmlFor="deleteMail" className="cursor-pointer">
                      Удалить
                    </Label>
                  </div>
                  <Switch
                    id="deleteMail"
                    checked={deleteMail}
                    onCheckedChange={setDeleteMail}
                  />
                </div>
              </div>

              <div className="space-y-2">
                <Label htmlFor="forwardTo">Пересылать на email</Label>
                <Input
                  id="forwardTo"
                  type="email"
                  value={forwardTo}
                  onChange={(e) => setForwardTo(e.target.value)}
                  placeholder="email@example.com"
                />
              </div>
            </div>
          </div>

          <DialogFooter>
            <Button variant="outline" onClick={() => setDialogOpen(false)}>
              Отмена
            </Button>
            <Button onClick={handleSave}>
              {editingFilter ? 'Сохранить' : 'Создать фильтр'}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </Card>
  );
}

import React, { useState, useMemo, useCallback, useEffect } from 'react';
import { cn } from '@/lib/utils';
import { ScrollArea } from '@/components/ui/scroll-area';
import { Badge } from '@/components/ui/badge';
import { Checkbox } from '@/components/ui/checkbox';
import { Star, Paperclip, Loader, FileText, Tag, CheckCircle, Eye, EyeOff, Archive, ShieldAlert, Trash2, X } from 'lucide-react';
import { Mail } from '../types';
import { format } from 'date-fns';
import { ru } from 'date-fns/locale';
import { MailContextMenu } from './MailContextMenu';
import {
  formatMailDate,
  extractLetters,
  getInitials,
  getDisplayName,
  isOfficialEmail,
  getAvatarColor,
} from '../utils/componentUtils';

interface MailListProps {
  mails: Mail[];
  selectedMailId?: string;
  onSelectMail?: (mail: Mail) => void;
  onToggleStar?: (mailId: string) => void;
  loading?: boolean;
  // MAIL-2: Массовые операции
  selectedMailIds?: string[];
  onToggleSelectMail?: (mailId: string) => void;
  onSelectAll?: () => void;
  showSelectAll?: boolean;
  showMassActions?: boolean;
  clearSelection?: () => void;
  handleMassRead?: () => void;
  handleMassUnread?: () => void;
  handleMassArchive?: () => void;
  handleMassSpam?: () => void;
  handleMassDelete?: () => void;
  // MAIL-11: Контекстное меню
  folders?: Array<{ id: string; folderName: string; folderType: string }>;
  labels?: string[];
  onContextMenuAction?: (action: string, mail: Mail, data?: any) => void;
  // MAIL-10: Группировка по датам
  groupByDate?: boolean;
}



export function MailList({
  mails,
  selectedMailId,
  onSelectMail,
  onToggleStar,
  loading = false,
  selectedMailIds = [],
  onToggleSelectMail,
  onSelectAll,
  showSelectAll = false,
  showMassActions = false,
  clearSelection,
  handleMassRead,
  handleMassUnread,
  handleMassArchive,
  handleMassSpam,
  handleMassDelete,
  folders = [],
  labels = [],
  onContextMenuAction,
  groupByDate = true,
}: MailListProps) {
  // MAIL-11: Контекстное меню
  const [contextMenu, setContextMenu] = useState<{
    open: boolean;
    mail: Mail | null;
    x: number;
    y: number;
  }>({ open: false, mail: null, x: 0, y: 0 });

  const handleContextMenu = (e: React.MouseEvent, mail: Mail) => {
    e.preventDefault();
    e.stopPropagation();
    setContextMenu({
      open: true,
      mail,
      x: e.clientX,
      y: e.clientY,
    });
  };

  // Закрываем контекстное меню
  const closeContextMenu = useCallback(() => {
    setContextMenu((prev) => ({ ...prev, open: false }));
  }, []);

  // MAIL-1: Удаление дубликатов по ID
  const uniqueMails = useMemo(() => 
    mails.filter((mail, index, self) =>
      index === self.findIndex((m) => m.id === mail.id)
    ), [mails]
  );

  // MAIL-2: Все письма на странице выбраны
  const allSelected = uniqueMails.length > 0 && uniqueMails.every(mail => selectedMailIds.includes(mail.id));

  // MAIL-10: Группировка писем по датам
  const groupedMails = useMemo(() => {
    if (!groupByDate) {
      return { 'Все': uniqueMails };
    }

    const now = new Date();
    const today = new Date(now.getFullYear(), now.getMonth(), now.getDate());
    const yesterday = new Date(today.getTime() - 86400000);
    const weekAgo = new Date(today.getTime() - (today.getDay() + 7) * 86400000);

    const groups: Record<string, Mail[]> = {
      'Сегодня': [],
      'Вчера': [],
      'Неделя': [],
      'Ранее': [],
    };

    uniqueMails.forEach(mail => {
      const mailDate = new Date(mail.timestamp);
      if (mailDate >= today) {
        groups['Сегодня'].push(mail);
      } else if (mailDate >= yesterday) {
        groups['Вчера'].push(mail);
      } else if (mailDate >= weekAgo) {
        groups['Неделя'].push(mail);
      } else {
        groups['Ранее'].push(mail);
      }
    });

    // Фильтруем пустые группы
    return Object.fromEntries(
      Object.entries(groups).filter(([_, mails]) => mails.length > 0)
    );
  }, [uniqueMails, groupByDate]);

  if (loading) {
    return (
      <div className="flex-1 flex items-center justify-center p-8">
        <Loader className="w-6 h-6 animate-spin text-muted-foreground" />
        <span className="ml-3 text-muted-foreground">Загрузка писем...</span>
      </div>
    );
  }

  if (uniqueMails.length === 0) {
    return (
      <div className="flex-1 flex items-center justify-center p-8 text-muted-foreground h-full">
        <div className="text-center">
          <p className="text-lg font-medium">Нет писем в этой папке</p>
          <p className="text-sm mt-1">Выберите другую папку или синхронизируйте почту</p>
        </div>
      </div>
    );
  }

  return (
    <>
    <ScrollArea className="flex-1 w-full">
      <div className="divide-y divide-border">
        {Object.entries(groupedMails).map(([groupName, groupMails]) => (
          groupMails.length > 0 && (
            <React.Fragment key={groupName}>
              {/* MAIL-10: Заголовок группы в стиле Mail.ru */}
              {groupByDate && (
                <div className="sticky top-0 z-10 bg-background/95 backdrop-blur-sm px-4 py-2">
                  <h5 className="text-xs font-medium text-muted-foreground tracking-wide">
                    {groupName}
                  </h5>
                </div>
              )}

              {groupMails.map((mail, index) => {
                const dateInfo = formatMailDate(mail.timestamp);
                const isOfficial = isOfficialEmail(mail.sender.email);
                const displayName = getDisplayName(mail.sender.name, mail.sender.email);
                const avatarInitials = getInitials(displayName, mail.sender.email);
                const avatarColor = getAvatarColor(mail.sender.email);
                const faviconUrl = mail.sender.avatar || '';
                const isLast = index === groupMails.length - 1;

                return (
                  <div
                    id={`mail-${mail.id}`}
                    key={mail.id}
                    className={cn(
                      'group relative flex items-start gap-3 p-3 cursor-pointer transition-all duration-150',
                      'border-b border-border last:border-b-0',
                      // Массовое выделение
                      selectedMailIds.includes(mail.id) && 'bg-primary/5',
                      // Активное письмо
                      selectedMailId === mail.id && 'bg-primary/15 shadow-sm',
                      // Непрочитанное
                      !mail.isRead && selectedMailId !== mail.id && !selectedMailIds.includes(mail.id) && 'bg-blue-50/50 dark:bg-blue-950/20',
                      // Hover + принудительный стиль при открытом контекстном меню
                      !selectedMailIds.includes(mail.id) && 'hover:bg-primary/10 hover:shadow-[inset_3px_0_0_hsl(var(--primary))]',
                      contextMenu.open && contextMenu.mail?.id === mail.id && !selectedMailIds.includes(mail.id) && 'bg-primary/10 shadow-[inset_3px_0_0_hsl(var(--primary))]'
                    )}
                    onClick={() => onSelectMail?.(mail)}
                    onContextMenu={(e) => handleContextMenu(e, mail)}
                  >
                    {/* Левая часть: аватар с чекбоксом */}
                    <div className="flex items-center gap-1 flex-shrink-0">
                      {/* Аватар отправителя с чекбоксом */}
                      <div 
                        className="relative cursor-pointer"
                        onClick={(e) => {
                          e.stopPropagation();
                          onToggleSelectMail?.(mail.id);
                        }}
                        title={selectedMailIds.includes(mail.id) ? 'Отменить выделение' : 'Выделить письмо'}
                      >
                        <div className={cn(
                          'w-10 h-10 rounded-full flex items-center justify-center text-white text-sm font-medium shadow-sm transition-all duration-150',
                          avatarColor,
                          selectedMailIds.includes(mail.id) && 'brightness-75 ring-2 ring-primary/50'
                        )}>
                          <span className="relative z-0">{avatarInitials}</span>
                          {faviconUrl && (
                            <img
                              src={faviconUrl}
                              alt={mail.sender.name || mail.sender.email}
                              className="absolute inset-0 w-full h-full rounded-full object-cover bg-white"
                              onError={(e) => {
                                (e.currentTarget as HTMLImageElement).style.display = 'none';
                              }}
                            />
                          )}
                        </div>
                        
                        {/* Чекбокс на выделение - по центру логотипа, скрыт по умолчанию */}
                        <div 
                          className="absolute inset-0 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity duration-150 pointer-events-none group-hover:pointer-events-auto"
                        >
                          <Checkbox
                            checked={selectedMailIds.includes(mail.id)}
                            onCheckedChange={() => onToggleSelectMail?.(mail.id)}
                            onClick={(e) => e.stopPropagation()}
                            className="h-5 w-5 border-2 data-[state=checked]:bg-primary data-[state=checked]:border-primary rounded-sm shadow-md bg-background/30"
                          />
                        </div>

                        {/* Индикатор официального письма */}
                        {isOfficial && !selectedMailIds.includes(mail.id) && (
                          <div className="absolute -bottom-0.5 -right-0.5 w-4 h-4 bg-emerald-500 rounded-full flex items-center justify-center border-2 border-background" title="Официальное письмо">
                            <CheckCircle className="w-2.5 h-2.5 text-white" />
                          </div>
                        )}
                      </div>
                    </div>

                    {/* Центральная часть: контент письма */}
                    <div className="flex-1 min-w-0 flex flex-col gap-1">
                      {/* Верхняя строка: отправитель + дата */}
                      <div className="flex items-center justify-between gap-2 mb-1">
                        <div className="flex items-center gap-1.5 min-w-0 flex-1">
                          <span className={cn(
                            'text-sm truncate',
                            !mail.isRead && 'font-semibold text-foreground',
                            mail.isRead && 'text-muted-foreground'
                          )}>
                            {displayName}
                          </span>
                          {/* Индикатор непрочитанного */}
                          {!mail.isRead && (
                            <span className="w-1.5 h-1.5 rounded-full bg-blue-500 flex-shrink-0" title="Не прочитано" />
                          )}
                        </div>
                      </div>

                      {/* Тема письма */}
                      <div className="flex items-center justify-between gap-2">
                        <h4 className={cn(
                          'text-sm truncate leading-tight',
                          !mail.isRead && 'font-semibold text-foreground',
                          mail.isRead && 'text-muted-foreground'
                        )}>
                          {mail.subject || 'Без темы'}
                        </h4>
                        <span
                          className={cn(
                            "text-xs flex-shrink-0 font-medium whitespace-nowrap",
                            !mail.isRead ? "text-muted-foreground" : "text-muted-foreground/80"
                          )}
                          title={dateInfo.title}
                        >
                          {dateInfo.display}
                        </span>
                      </div>

                      {/* Сниппет содержимого */}
                      <p className="text-xs text-muted-foreground truncate leading-relaxed">
                        {mail.content ? mail.content.replace(/<[^>]*>/g, '').slice(0, 150) + '...' : 'Нет содержимого'}
                      </p>

                      {/* Нижняя строка: метки, вложения */}
                      <div className="flex items-center gap-2 mt-0.5 flex-wrap">
                        {/* Метки */}
                        {mail.labels && mail.labels.length > 0 && (
                          <div className="flex items-center gap-1.5">
                            {mail.labels.slice(0, 3).map((label) => (
                              <Badge 
                                key={label} 
                                variant="secondary" 
                                className="text-xs font-normal h-5 px-1.5 bg-secondary/80 hover:bg-secondary transition-colors"
                              >
                                <Tag className="w-2.5 h-2.5 mr-0.5" />
                                {label}
                              </Badge>
                            ))}
                            {mail.labels.length > 3 && (
                              <Badge variant="outline" className="text-xs h-5 px-1.5">
                                +{mail.labels.length - 3}
                              </Badge>
                            )}
                          </div>
                        )}
                        
                        {/* Индикатор вложений */}
                        {mail.hasAttachments && (
                          <div className="flex items-center gap-1.5 text-muted-foreground" title="Есть вложения">
                            <Paperclip className="h-3.5 w-3.5" />
                            {mail.attachments && mail.attachments.length > 0 ? (
                              <div className="flex items-center gap-1">
                                {mail.attachments.slice(0, 2).map((attachment) => {
                                  const name = attachment.name || 'file';
                                  const ext = name.includes('.') ? name.split('.').pop()?.toUpperCase() : '';
                                  const label = ext || (attachment.type?.startsWith('image/') ? 'IMG' : 'FILE');

                                  return (
                                    <span
                                      key={attachment.id}
                                      className="text-[10px] px-1.5 py-0.5 rounded bg-muted/70 border border-border/60 text-muted-foreground"
                                      title={name}
                                    >
                                      {label}
                                    </span>
                                  );
                                })}
                                {mail.attachments.length > 2 && (
                                  <span className="text-[10px] text-muted-foreground">+{mail.attachments.length - 2}</span>
                                )}
                              </div>
                            ) : (
                              <span className="text-[11px] text-muted-foreground">Вложения</span>
                            )}
                          </div>
                        )}

                        {/* Индикатор категории (заказы, счета и т.д.) */}
                        {mail.folder === 'sent' && (
                          <div className="flex items-center gap-1 text-muted-foreground" title="Отправленные">
                            <FileText className="h-3.5 w-3.5" />
                          </div>
                        )}

                        {/* Индикатор ошибки отправки */}
                        {(mail.sendStatus === 'retrying' || mail.sendStatus === 'failed') && (
                          <span
                            className="w-2 h-2 rounded-full bg-red-500 flex-shrink-0"
                            title={mail.sendStatus === 'retrying' ? 'Повторная отправка...' : 'Ошибка отправки'}
                          />
                        )}
                      </div>
                    </div>

                    {/* Правая колонка действий */}
                    <div className="ml-auto flex items-center">
                      <button
                        onClick={(e) => {
                          e.stopPropagation();
                          onToggleStar?.(mail.id);
                        }}
                        className={cn(
                          'p-1.5 rounded-md transition-all duration-150 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary/50',
                          'hover:bg-muted hover:scale-110',
                          mail.isStarred
                            ? 'text-yellow-500 opacity-100'
                            : 'text-muted-foreground/80 opacity-80 group-hover:opacity-100 group-hover:text-foreground'
                        )}
                        title={mail.isStarred ? 'Убрать из избранных' : 'В избранное'}
                        aria-label={mail.isStarred ? 'Убрать из избранных' : 'В избранное'}
                      >
                        <Star className={cn('h-4 w-4', mail.isStarred && 'fill-current')} />
                      </button>
                    </div>

                    {/* Разделитель после последнего элемента в группе */}
                    {isLast && (
                      <div className="absolute bottom-0 left-0 right-0 h-px bg-gradient-to-r from-transparent via-border to-transparent" />
                    )}
                  </div>
                );
              })}
            </React.Fragment>
          )
        ))}

        {/* MAIL-2: Чекбокс "Выделить всё" */}
        {showSelectAll && (
          <div className="p-3 border-t border-border bg-muted/30">
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-2">
                <Checkbox
                  checked={allSelected}
                  onCheckedChange={() => onSelectAll?.()}
                  className="h-4 w-4"
                />
                <span className="text-sm text-muted-foreground">
                  {allSelected ? 'Снять выделение со всех' : 'Выделить все'}
                </span>
              </div>
              <span className="text-xs text-muted-foreground">
                Выбрано: {selectedMailIds.length} из {uniqueMails.length}
              </span>
            </div>
          </div>
        )}
      </div>
    </ScrollArea>

    {/* MAIL-11: Контекстное меню */}
    {contextMenu.open && contextMenu.mail && (
      <MailContextMenu
        mail={contextMenu.mail}
        folders={folders}
        labels={labels}
        onSelectAction={onContextMenuAction || (() => {})}
        onClose={() => setContextMenu({ ...contextMenu, open: false })}
        position={{ x: contextMenu.x, y: contextMenu.y }}
      />
    )}
  </>
);
}

