import React, { useState, useEffect } from 'react';
import { cn } from '@/lib/utils';
import { Button } from '@/components/ui/button';
import { ScrollArea } from '@/components/ui/scroll-area';
import { Badge } from '@/components/ui/badge';
import { Input } from '@/components/ui/input';
import { Progress } from '@/components/ui/progress';
import {
  Inbox,
  Send,
  FileText,
  Trash2,
  Archive,
  Star,
  AlertCircle,
  Clock,
  Plus,
  Folder
} from 'lucide-react';
import { useTranslation } from '@/lib/i18n';
import { api } from '@/lib/api';
import { toast } from 'sonner';
import { showConfirm } from '@/components/ui/confirm-dialog';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { MailFilterSortMenu } from './MailFilterSortMenu';
import { FolderContextMenu } from './FolderContextMenu';
import {
  SYSTEM_FOLDER_TYPES,
  isSystemFolder,
  getCanonicalSystemKey,
  systemFolderNames,
} from '../utils/componentUtils';

interface MailSidebarProps {
  activeFolder: string;
  setActiveFolder: (folder: string) => void;
  selectedAccountId: string;
  onAccountChange: (accountId: string) => void;
  searchQuery?: string;
  onSearchChange?: (query: string) => void;
  showUnreadOnly?: boolean;
  onShowUnreadOnlyChange?: (show: boolean) => void;
  showStarredOnly?: boolean;
  onShowStarredOnlyChange?: (show: boolean) => void;
  accounts?: Array<{ id: string; email: string; displayName?: string; syncFolders?: string[] | null }>;
  folders?: Array<{
    id: string;
    folderName: string;
    folderType: string;
    unseenCount: number;
    totalCount: number;
    displayOrder?: number;
  }>;
  mailFilter?: 'all' | 'unread' | 'starred' | 'attachments';
  onMailFilterChange?: (filter: 'all' | 'unread' | 'starred' | 'attachments') => void;
  mailSort?: 'date-desc' | 'date-asc' | 'sender-asc' | 'sender-desc' | 'subject-asc' | 'subject-desc';
  onMailSortChange?: (sort: 'date-desc' | 'date-asc' | 'sender-asc' | 'sender-desc' | 'subject-asc' | 'subject-desc') => void;
  setViewMode?: (mode: 'list' | 'mail' | 'compose') => void;
  isSyncing?: boolean;
}


const systemFolderIcons: Record<string, React.ReactNode> = {
  inbox: <Inbox className="h-4 w-4" />,
  sent: <Send className="h-4 w-4" />,
  drafts: <FileText className="h-4 w-4" />,
  archive: <Archive className="h-4 w-4" />,
  spam: <AlertCircle className="h-4 w-4" />,
  trash: <Trash2 className="h-4 w-4" />,
  Inbox: <Inbox className="h-4 w-4" />,
  'Sent Mail': <Send className="h-4 w-4" />,
  Drafts: <FileText className="h-4 w-4" />,
  Archive: <Archive className="h-4 w-4" />,
  Spam: <AlertCircle className="h-4 w-4" />,
  Trash: <Trash2 className="h-4 w-4" />,
};


export function MailSidebar({
  activeFolder,
  setActiveFolder,
  selectedAccountId,
  onAccountChange,
  searchQuery = '',
  onSearchChange,
  showUnreadOnly = false,
  onShowUnreadOnlyChange,
  showStarredOnly = false,
  onShowStarredOnlyChange,
  accounts = [],
  folders = [],
  mailFilter = 'all',
  onMailFilterChange,
  mailSort = 'date-desc',
  onMailSortChange,
  setViewMode,
  isSyncing = false,
}: MailSidebarProps) {
  const { t } = useTranslation();
  const [localFolders, setLocalFolders] = useState<any[]>(folders);
  const [foldersLoading, setFoldersLoading] = useState(false);
  const [systemExpanded, setSystemExpanded] = useState(true);
  const [customExpanded, setCustomExpanded] = useState(true);
  const [draggingFolderId, setDraggingFolderId] = useState<string | null>(null);
  const [dragOverFolderId, setDragOverFolderId] = useState<string | null>(null);
  const [folderContextMenu, setFolderContextMenu] = useState<{
    open: boolean;
    folder: any;
    x: number;
    y: number;
  }>({ open: false, folder: null, x: 0, y: 0 });

  const handleFolderContextMenu = (e: React.MouseEvent, folder: any) => {
    e.preventDefault();
    e.stopPropagation();
    setFolderContextMenu({
      open: true,
      folder,
      x: e.clientX,
      y: e.clientY,
    });
  };

  const handleFolderClick = (folderId: string) => {
    setActiveFolder(folderId);
    if (setViewMode) {
      setViewMode('list');
    }
  };

  const handleFolderAction = async (action: string, folderData: any) => {
    console.log('[FolderContextMenu] Action:', action, folderData);

    switch (action) {
      case 'open_folder':
        setActiveFolder(folderData.id);
        break;
      case 'mark_all_read':
        toast.success(`Все письма в папке "${folderData.folderName}" отмечены как прочитанные`);
        break;
      case 'delete_folder':
        if (await showConfirm({
          title: 'Удалить папку',
          description: `Удалить папку "${folderData.folderName}"?`,
          confirmText: 'Удалить',
          variant: 'destructive',
        })) {
          toast.success(`Папка "${folderData.folderName}" удалена`);
        }
        break;
      case 'rename_folder': {
        const newName = prompt('Новое название папки:', folderData.folderName);
        if (newName) {
          toast.success(`Папка переименована в "${newName}"`);
        }
        break;
      }
      case 'create_subfolder': {
        const subfolderName = prompt('Название подпапки:');
        if (subfolderName) {
          toast.success(`Подпапка "${subfolderName}" создана`);
        }
        break;
      }
      case 'clear_folder':
        if (await showConfirm({
          title: 'Очистить папку',
          description: `Удалить все письма из папки "${folderData.folderName}"? Это действие нельзя отменить.`,
          confirmText: 'Удалить всё',
          variant: 'destructive',
        })) {
          try {
            const resp = await api.post(`/mail/folders/${folderData.id}/clear`, {});
            toast.success(`Удалено писем: ${resp.deleted}`);
            // Notify parent to refresh mail list
            window.dispatchEvent(new CustomEvent('mail-folder-cleared', { detail: { folderId: folderData.id } }));
          } catch (error: any) {
            toast.error(error.message || 'Ошибка при очистке папки');
          }
        }
        break;
      default:
        console.warn('Unknown folder action:', action);
    }
  };

  useEffect(() => {
    if (selectedAccountId) {
      fetchFolders();

      const systemExpandedKey = `mail-system-expanded-${selectedAccountId}`;
      const customExpandedKey = `mail-custom-expanded-${selectedAccountId}`;
      const savedSystemExpanded = localStorage.getItem(systemExpandedKey);
      const savedCustomExpanded = localStorage.getItem(customExpandedKey);
      if (savedSystemExpanded !== null) setSystemExpanded(savedSystemExpanded === 'true');
      if (savedCustomExpanded !== null) setCustomExpanded(savedCustomExpanded === 'true');
    }
  }, [selectedAccountId]);

  useEffect(() => {
    if (!selectedAccountId) return;
    localStorage.setItem(`mail-system-expanded-${selectedAccountId}`, String(systemExpanded));
  }, [selectedAccountId, systemExpanded]);

  useEffect(() => {
    if (!selectedAccountId) return;
    localStorage.setItem(`mail-custom-expanded-${selectedAccountId}`, String(customExpanded));
  }, [selectedAccountId, customExpanded]);

  const fetchFolders = async () => {
    try {
      setFoldersLoading(true);
      const response = await api.get(`/mail/folders/${selectedAccountId}`);
      setLocalFolders(response);

      if (!activeFolder && response.length > 0) {
        const systemFolders = response.filter((f: any) => isSystemFolder(f.folderType));
        const inboxFolder = systemFolders.find((f: any) =>
          (f.folderType || '').toLowerCase() === 'inbox' ||
          (f.folderName || '').toLowerCase() === 'inbox'
        ) || systemFolders[0];

        if (inboxFolder) {
          setActiveFolder(inboxFolder.id);
        }
      }
    } catch (error) {
      console.error('Error fetching folders:', error);
    } finally {
      setFoldersLoading(false);
    }
  };

  const activeAccount = accounts.find((a) => a.id === selectedAccountId);

  const isFolderDisabled = (folderName: string) => {
    if (!activeAccount || !activeAccount.syncFolders || activeAccount.syncFolders.length === 0) return false;
    return !activeAccount.syncFolders.includes(folderName);
  };

  const rawSystemFolders = localFolders.filter((f) => isSystemFolder(f.folderType));
  const systemFolderMap = new Map<string, typeof rawSystemFolders[number]>();

  for (const folder of rawSystemFolders) {
    const key = getCanonicalSystemKey(folder);
    const existing = systemFolderMap.get(key);

    if (!existing || ((existing.folderType || '').toLowerCase() === 'system' && (folder.folderType || '').toLowerCase() !== 'system')) {
      systemFolderMap.set(key, folder);
    }
  }

  const systemFolders = Array.from(systemFolderMap.values());
  const customFolders = localFolders.filter((f) => !isSystemFolder(f.folderType));

  const persistFolderOrder = async (orderedFolders: typeof localFolders) => {
    setLocalFolders(orderedFolders);
    try {
      await Promise.all(
        orderedFolders.map((folder, index) =>
          api.put(`/mail/folders/${folder.id}`, { displayOrder: index + 1 })
        )
      );
    } catch (error) {
      console.error('Error saving folder order:', error);
      toast.error('Не удалось сохранить порядок папок');
      await fetchFolders();
    }
  };

  const reorderFolder = async (dragId: string, targetId: string) => {
    if (dragId === targetId) return;

    const isSystem = systemFolders.some((folder) => folder.id === dragId);
    const dragSection = isSystem ? systemFolders : customFolders;
    const targetSection = isSystem ? systemFolders : customFolders;

    if (!targetSection.some((folder) => folder.id === targetId)) return;

    const currentIndex = dragSection.findIndex((folder) => folder.id === dragId);
    const targetIndex = targetSection.findIndex((folder) => folder.id === targetId);
    if (currentIndex === -1 || targetIndex === -1) return;

    const sectionFolders = [...dragSection];
    const [moved] = sectionFolders.splice(currentIndex, 1);
    sectionFolders.splice(targetIndex, 0, moved);

    const orderedIds = isSystem
      ? [...sectionFolders.map((f) => f.id), ...customFolders.map((f) => f.id)]
      : [...systemFolders.map((f) => f.id), ...sectionFolders.map((f) => f.id)];

    const orderedFolders = orderedIds
      .map((id) => localFolders.find((folder) => folder.id === id))
      .filter(Boolean) as typeof localFolders;

    await persistFolderOrder(orderedFolders);
    toast.success('Порядок папок сохранён');
  };

  const renderFolderItem = (folder: any, depth = 0) => {
    const isSelected = activeFolder === folder.id;
    const isDisabled = isFolderDisabled(folder.folderName);
    const canonicalKey = getCanonicalSystemKey(folder);

    return (
      <React.Fragment key={folder.id}>
        <Button
          variant={isSelected ? 'secondary' : 'ghost'}
          className={cn(
            'w-full justify-between text-sm group h-9 px-2',
            isSelected && 'bg-primary/40 font-semibold ring-1 ring-primary/40',
            dragOverFolderId === folder.id && 'ring-1 ring-primary/40',
            folderContextMenu.open && folderContextMenu.folder?.id === folder.id && 'bg-primary/10'
          )}
          style={{ paddingLeft: `${depth * 12 + 8}px` }}
          onClick={() => handleFolderClick(folder.id)}
          onContextMenu={(e) => handleFolderContextMenu(e, { ...folder, accountId: selectedAccountId })}
          draggable
          onDragStart={(e: React.DragEvent<HTMLButtonElement>) => {
            setDraggingFolderId(folder.id);
            e.dataTransfer.setData('text/plain', folder.id);
            e.dataTransfer.effectAllowed = 'move';
          }}
          onDragEnd={() => {
            setDraggingFolderId(null);
            setDragOverFolderId(null);
          }}
          onDragOver={(e: React.DragEvent<HTMLButtonElement>) => {
            e.preventDefault();
            if (draggingFolderId && draggingFolderId !== folder.id) {
              setDragOverFolderId(folder.id);
            }
          }}
          onDrop={async (e) => {
            e.preventDefault();
            const dragId = e.dataTransfer.getData('text/plain');
            if (dragId) await reorderFolder(dragId, folder.id);
          }}
        >
          <div className={cn("flex items-center gap-2 min-w-0", isDisabled && "text-muted-foreground")}>
            {systemFolderIcons[canonicalKey] || systemFolderIcons[folder.folderType] || systemFolderIcons[folder.folderName] || <Folder className="h-4 w-4" />}
            <span className="truncate">
              {systemFolderNames[canonicalKey] || systemFolderNames[folder.folderType] || systemFolderNames[folder.folderName] || folder.folderName}
            </span>
          </div>
          {folder.unseenCount > 0 && (
            <Badge variant="secondary" className="px-1.5 h-5 min-w-[20px] ml-1">
              {folder.unseenCount}
            </Badge>
          )}
        </Button>
        {folder.children?.length > 0 && (
          <div className="space-y-1">
            {folder.children.map((child: any) => renderFolderItem(child, depth + 1))}
          </div>
        )}
      </React.Fragment>
    );
  };

  const buildTree = (flat: any[]) => {
    const map: Record<string, any> = {};
    const roots: any[] = [];
    flat.forEach(f => map[f.id] = { ...f, children: [] });
    flat.forEach(f => {
      if (f.parentFolderId && map[f.parentFolderId]) {
        map[f.parentFolderId].children.push(map[f.id]);
      } else {
        roots.push(map[f.id]);
      }
    });
    return roots;
  };

  const folderTree = buildTree(localFolders);
  const systemTree = folderTree.filter(f => isSystemFolder(f.folderType));
  const customTree = folderTree.filter(f => !isSystemFolder(f.folderType));

  return (
    <>
      <div className="w-64 shrink-0 border-r bg-muted/30 flex flex-col">
        {accounts.length > 0 && (
          <div className="p-3 border-b">
            {accounts.length > 1 ? (
              <DropdownMenu modal={false}>
                <DropdownMenuTrigger asChild>
                  <Button variant="outline" className="w-full justify-start text-sm truncate">
                    {accounts.find(a => a.id === selectedAccountId)?.displayName ||
                      accounts.find(a => a.id === selectedAccountId)?.email ||
                      t('mail.select_account')}
                    <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="ml-auto h-4 w-4 opacity-50"><path d="m6 9 6 6 6-6"/></svg>
                  </Button>
                </DropdownMenuTrigger>
                <DropdownMenuContent className="w-[200px]">
                  {accounts.map((account) => (
                    <DropdownMenuItem
                      key={account.id}
                      onClick={() => onAccountChange(account.id)}
                      className="text-sm"
                    >
                      {account.displayName || account.email}
                    </DropdownMenuItem>
                  ))}
                </DropdownMenuContent>
              </DropdownMenu>
            ) : (
              <Button variant="outline" className="w-full justify-start text-sm truncate" disabled>
                {accounts.find(a => a.id === selectedAccountId)?.displayName ||
                  accounts.find(a => a.id === selectedAccountId)?.email ||
                  t('mail.select_account')}
              </Button>
            )}
          </div>
        )}

        <div className="p-3 border-b">
          <Button
            className="w-full gap-2 bg-primary hover:bg-primary/90 shadow-sm"
            size="sm"
            onClick={() => window.dispatchEvent(new CustomEvent('open-mail-compose'))}
            disabled={!selectedAccountId}
          >
            <svg
              xmlns="http://www.w3.org/2000/svg"
              width="24"
              height="24"
              viewBox="0 0 24 24"
              fill="none"
              stroke="currentColor"
              strokeWidth="2"
              strokeLinecap="round"
              strokeLinejoin="round"
              className="h-4 w-4"
            >
              <path d="M12 3H5a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7"></path>
              <path d="M18.375 2.625a1 1 0 0 1 3 3l-9.013 9.014a2 2 0 0 1-.853.505l-2.873.84a.5.5 0 0 1-.62-.62l.84-2.873a2 2 0 0 1 .506-.852z"></path>
            </svg>
            Написать письмо
          </Button>
        </div>

        <ScrollArea className="flex-1">
          <div className="p-2 space-y-1">
            {systemFolders.length > 0 && (
              <>
                <button
                  className="w-full px-2 py-1 text-xs font-semibold text-muted-foreground uppercase flex items-center justify-between"
                  onClick={() => setSystemExpanded((prev) => !prev)}
                >
                  <span>{t('mail.folders_label')}</span>
                </button>
                {systemExpanded && systemTree.map((folder) => renderFolderItem(folder))}
              </>
            )}

            {customFolders.length > 0 && (
              <>
                <button
                  className="w-full px-2 py-1 text-xs font-semibold text-muted-foreground uppercase mt-4 flex items-center justify-between"
                  onClick={() => setCustomExpanded((prev) => !prev)}
                >
                  <span>{t('mail.custom_folders')}</span>
                </button>
                {customExpanded && customTree.map((folder) => renderFolderItem(folder))}
              </>
            )}
          </div>
        </ScrollArea>

        {/* Узкий футер для отображения фоновой синхронизации */}
        {isSyncing && (
          <div className="h-1 w-full bg-muted/20">
            <Progress
              value={100}
              className="h-1 animate-pulse"
            />
          </div>
        )}
      </div>

      {folderContextMenu.open && folderContextMenu.folder && (
        <div
          className="z-50"
          style={{
            position: 'fixed',
            left: folderContextMenu.x,
            top: folderContextMenu.y,
            pointerEvents: 'auto'
          }}
        >
          <FolderContextMenu
            folder={folderContextMenu.folder}
            onSelectAction={handleFolderAction}
            onClose={() => setFolderContextMenu({ ...folderContextMenu, open: false })}
          />
        </div>
      )}
    </>
  );
}

