import { useState, useEffect, useCallback } from 'react';
import { api } from '@/lib/api';
import { toast } from 'sonner';
import { ApiMailFolder } from '../types';

interface UseMailFoldersReturn {
  folders: ApiMailFolder[];
  activeFolder: string;
  setActiveFolder: (folder: string) => void;
  loading: boolean;
  error: Error | null;
  refetch: () => Promise<void>;
}

/**
 * Хук для управления почтовыми папками
 */
export const useMailFolders = (selectedAccountId: string): UseMailFoldersReturn => {
  const [folders, setFolders] = useState<ApiMailFolder[]>([]);
  const [activeFolder, setActiveFolder] = useState<string>('');
  const [loading, setLoading] = useState<boolean>(false);
  const [error, setError] = useState<Error | null>(null);

  const fetchFolders = useCallback(async () => {
    if (!selectedAccountId) {
      setFolders([]);
      setActiveFolder('');
      return;
    }

    try {
      setLoading(true);
      setError(null);

      console.log(`[MAIL] Fetching folders for account: ${selectedAccountId}`);
      const response = await api.get(`/mail/folders/${selectedAccountId}`);
      console.log(`[MAIL] Got ${response.length} folders from API:`, response);

      setFolders(response);

      if (response.length > 0) {
        // Сначала ищем Inbox
        const inboxFolder = response.find((f: any) => f.folderType === 'inbox');

        // Если Inbox есть и в ней есть письма, выбираем её
        if (inboxFolder && inboxFolder.totalCount > 0) {
          console.log(`[MAIL] Folder selection logic:`);
          console.log(`  - Inbox found: ${inboxFolder.folderName} with ${inboxFolder.totalCount} mails, id: ${inboxFolder.id}`);
          console.log(`  - Selecting folder: ${inboxFolder.id}`);
          setActiveFolder(inboxFolder.id);
          return;
        }

        // Ищем первую папку с письмами (totalCount > 0)
        const folderWithMails = response.find((f: any) => f.totalCount > 0);
        if (folderWithMails) {
          console.log(`[MAIL] Folder selection logic:`);
          console.log(`  - Inbox empty or not found, selecting first folder with mails: ${folderWithMails.folderName} (${folderWithMails.totalCount} mails)`);
          console.log(`  - Selecting folder: ${folderWithMails.id}`);
          setActiveFolder(folderWithMails.id);
          return;
        }

        // Если все папки пустые, выбираем первую системную папку или первую любую
        const systemFolders = response.filter((f: any) => f.folderType === 'system');
        const folderToSelect = inboxFolder?.id || systemFolders[0]?.id || response[0].id;

        console.log(`[MAIL] Folder selection logic:`);
        console.log(`  - Inbox found: ${inboxFolder?.folderName || 'no'}`);
        console.log(`  - System folders: ${systemFolders.length}`);
        console.log(`  - All folders empty, selecting: ${folderToSelect}`);
        console.log(`[MAIL] Setting activeFolder to: ${folderToSelect}`);

        setActiveFolder(folderToSelect);
      } else {
        setActiveFolder('');
      }
    } catch (err) {
      console.error('Error fetching folders:', err);
      setError(err instanceof Error ? err : new Error('Failed to fetch folders'));
      toast.error('Не удалось загрузить папки');
    } finally {
      setLoading(false);
    }
  }, [selectedAccountId]);

  // Загрузка папок при изменении selectedAccountId
  useEffect(() => {
    fetchFolders();
  }, [fetchFolders]);

  const handleSetActiveFolder = useCallback((folder: string) => {
    setActiveFolder(folder);
  }, []);

  return {
    folders,
    activeFolder,
    setActiveFolder: handleSetActiveFolder,
    loading,
    error,
    refetch: fetchFolders,
  };
};

import { useState, useEffect, useCallback, useMemo } from 'react';
import { api } from '@/lib/api';
import { toast } from 'sonner';
import { Mail, MailFilterType, MailSortType } from '../types';
import { transformMailData, filterAndSortMails } from '../utils/mailUtils';

interface UseMailsProps {
  selectedAccountId: string;
  activeFolder: string;
  includeSubfolders: boolean;
  searchQuery?: string;
  showUnreadOnly?: boolean;
  showStarredOnly?: boolean;
}

interface UseMailsReturn {
  mails: Mail[];
  filteredMails: Mail[];
  selectedMail: Mail | null;
  setSelectedMail: (mail: Mail | null) => void;
  loading: boolean;
  error: Error | null;
  searchQuery: string;
  setSearchQuery: (query: string) => void;
  mailFilter: MailFilterType;
  setMailFilter: (filter: MailFilterType) => void;
  mailSort: MailSortType;
  setMailSort: (sort: MailSortType) => void;
  refetch: () => Promise<void>;
  markAsRead: (mailId: string, isRead: boolean) => Promise<void>;
  toggleStar: (mailId: string) => Promise<void>;
  isSearching: boolean;
}

/**
 * Хук для работы с письмами (загрузка, фильтрация, сортировка)
 */
export const useMails = ({
  selectedAccountId,
  activeFolder,
  includeSubfolders,
  searchQuery: initialSearchQuery = '',
  showUnreadOnly = false,
  showStarredOnly = false,
}: UseMailsProps): UseMailsReturn => {
  const [mails, setMails] = useState<Mail[]>([]);
  const [selectedMail, setSelectedMail] = useState<Mail | null>(null);
  const [loading, setLoading] = useState<boolean>(false);
  const [error, setError] = useState<Error | null>(null);
  const [searchQuery, setSearchQuery] = useState<string>(initialSearchQuery);
  const [mailFilter, setMailFilter] = useState<MailFilterType>('all');
  const [mailSort, setMailSort] = useState<MailSortType>('date-desc');
  const [isSearching, setIsSearching] = useState<boolean>(false);

  // Загрузка писем
  const fetchMails = useCallback(async () => {
    console.log(`[MAIL] useEffect triggered`);
    console.log(`  - activeFolder: ${activeFolder} (${typeof activeFolder})`);
    console.log(`  - selectedAccountId: ${selectedAccountId} (${typeof selectedAccountId})`);
    console.log(`  - searchQuery: ${searchQuery}`);

    if (!activeFolder || !selectedAccountId) {
      console.log(`[MAIL] Skipping: missing activeFolder or selectedAccountId`);
      setMails([]);
      setSelectedMail(null);
      return;
    }

    try {
      setLoading(true);
      setMails([]); // Clear old mails immediately
      setSelectedMail(null);

      const params: any = {
        limit: 50,
        offset: 0,
      };

      // Если есть поисковый запрос - используем полнотекстовый поиск
      if (searchQuery && searchQuery.trim().length > 2) {
        setIsSearching(true);
        params.searchQuery = searchQuery.trim();
        params.accountId = selectedAccountId;
        params.folderId = activeFolder;
        params.includeSubfolders = includeSubfolders;

        console.log(`[MAIL] Full-text search with query: "${searchQuery}"`);
        console.log(`[MAIL] Search params:`, params);
      } else {
        setIsSearching(false);
        params.accountId = selectedAccountId;
        params.folderId = activeFolder;
        params.includeSubfolders = includeSubfolders;

        // Добавляем фильтры
        if (showUnreadOnly) {
          params.isRead = false;
        }
        if (showStarredOnly) {
          params.isStarred = true;
        }
      }

      console.log(`[MAIL] Fetching mails from API with params:`, JSON.stringify(params));

      const response = await api.get('/mail', { params });

      console.log(`[MAIL] API response:`, response);
      console.log(`[MAIL] Got ${Array.isArray(response) ? response.length : response?.mails?.length || 0} mails`);

      // Логируем первое письмо для отладки
      const firstMail = Array.isArray(response) ? response[0] : (response?.mails?.[0]);
      if (firstMail) {
        console.log('[MAIL] First mail date field:', firstMail.date);
        console.log('[MAIL] First mail full object:', firstMail);
      }

      const mailsArray = Array.isArray(response) ? response : (response?.mails || []);

      if (mailsArray.length > 0) {
        const transformedData = transformMailData(mailsArray);
        console.log(`[MAIL] Transformed ${transformedData.length} mails`);
        console.log(`[MAIL] First mail folderId:`, transformedData[0]?.folder);
        setMails(transformedData);
        // Не предвыбираем первое письмо, чтобы список не выглядел как hover/active по умолчанию.
        setSelectedMail(null);
      } else {
        console.log(`[MAIL] No mails found`);
        setMails([]);
        setSelectedMail(null);
      }
    } catch (err) {
      console.error('[MAIL] Error fetching mails:', err);
      setError(err instanceof Error ? err : new Error('Failed to fetch mails'));
      toast.error('Не удалось загрузить письма');
      setMails([]);
      setSelectedMail(null);
    } finally {
      setLoading(false);
    }
  }, [activeFolder, selectedAccountId, searchQuery, includeSubfolders, showUnreadOnly, showStarredOnly]);

  // Дебаунс загрузки при изменении searchQuery
  useEffect(() => {
    const timeoutId = setTimeout(() => {
      fetchMails();
    }, searchQuery ? 300 : 0);

    return () => clearTimeout(timeoutId);
  }, [fetchMails, searchQuery]);

  // Фильтрация и сортировка писем (мемоизировано)
  const filteredMails = useMemo(() => {
    return filterAndSortMails(mails, {
      searchQuery,
      mailFilter,
      mailSort,
    });
  }, [mails, searchQuery, mailFilter, mailSort]);

  // Отметка письма как прочитанного/непрочитанного
  const markAsRead = useCallback(async (mailId: string, isRead: boolean) => {
    const targetMail = mails.find((mail) => mail.id === mailId);
    if (!targetMail) return;

    // Оптимистичное обновление
    setMails((prev) => prev.map((mail) =>
      mail.id === mailId ? { ...mail, isRead } : mail
    ));
    setSelectedMail((prev) =>
      prev?.id === mailId ? { ...prev, isRead } : prev
    );

    try {
      await api.patch(`/mail/${mailId}/read`, { isRead });
      toast.success(isRead ? 'Отмечено как прочитанное' : 'Отмечено как непрочитанное');
    } catch (err) {
      // Откат при ошибке
      setMails((prev) => prev.map((mail) =>
        mail.id === mailId ? { ...mail, isRead: targetMail.isRead } : mail
      ));
      setSelectedMail((prev) =>
        prev?.id === mailId ? { ...prev, isRead: targetMail.isRead } : prev
      );
      toast.error('Ошибка при обновлении статуса');
    }
  }, [mails]);

  // Переключение избранного
  const toggleStar = useCallback(async (mailId: string) => {
    const targetMail = mails.find((mail) => mail.id === mailId);
    if (!targetMail) return;

    const nextStarred = !targetMail.isStarred;

    // Оптимистичное обновление
    setMails((prev) => prev.map((mail) =>
      mail.id === mailId ? { ...mail, isStarred: nextStarred } : mail
    ));
    setSelectedMail((prev) =>
      prev?.id === mailId ? { ...prev, isStarred: nextStarred } : prev
    );

    try {
      await api.patch(`/mail/${mailId}/star`, { isStarred: nextStarred });
      toast.success(nextStarred ? 'Добавлено в избранное' : 'Удалено из избранного');
    } catch (err) {
      // Откат при ошибке
      setMails((prev) => prev.map((mail) =>
        mail.id === mailId ? { ...mail, isStarred: targetMail.isStarred } : mail
      ));
      setSelectedMail((prev) =>
        prev?.id === mailId ? { ...prev, isStarred: targetMail.isStarred } : prev
      );
      toast.error('Ошибка при обновлении избранного');
    }
  }, [mails]);

  // Загрузка детальной информации о письме
  const loadMailDetails = useCallback(async (mail: Mail) => {
    if (!mail?.id) {
      setSelectedMail(null);
      return;
    }

    // Показываем письмо сразу, затем догружаем полные данные (включая вложения)
    setSelectedMail(mail);

    try {
      const response = await api.get(`/mail/${mail.id}`);
      const [detailedMail] = transformMailData([response]);
      if (detailedMail) {
        setSelectedMail(detailedMail);
        // Бэкенд автоматически помечает письмо прочитанным при открытии.
        // Обновляем локальный state списка, чтобы индикатор «непрочитанное» сразу пропал.
        setMails(prev => prev.map(m => m.id === mail.id ? { ...m, isRead: true } : m));
      }
    } catch (err) {
      console.error('[Mail] Failed to load detailed mail:', err);
    }
  }, []);

  const handleSetSelectedMail = useCallback((mail: Mail | null) => {
    if (mail) {
      loadMailDetails(mail);
    } else {
      setSelectedMail(null);
    }
  }, [loadMailDetails]);

  return {
    mails,
    filteredMails,
    selectedMail,
    setSelectedMail: handleSetSelectedMail,
    loading,
    error,
    searchQuery,
    setSearchQuery,
    mailFilter,
    setMailFilter,
    mailSort,
    setMailSort,
    refetch: fetchMails,
    markAsRead,
    toggleStar,
    isSearching,
  };
};

import { useEffect, useState } from "react";
import { useSearchParams } from "react-router-dom";
import { AppLayout } from "@/components/layout/AppLayout";
import { useTranslation } from "@/lib/i18n";
import { api } from "@/lib/api";
import { MailSidebar, MailList, MailDisplay, MailCompose, MailAccountSettings, MailSyncProgress } from "../components";
import { Mail as MailType } from "../types";
import { MailContextMenu } from "../components/MailContextMenu";
import { MailFilterSortMenu } from "../components/MailFilterSortMenu";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";
import { Eye, EyeOff, Archive, ShieldAlert, Trash2, X, Search } from "lucide-react";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/components/ui/alert-dialog";
import { toast } from "sonner";

// Импорт кастомных хуков
import { useMailAccounts } from "../hooks/useMailAccounts";
import { useMailFolders } from "../hooks/useMailFolders";
import { useMails } from "../hooks/useMails";
import { useMailSelection } from "../hooks/useMailSelection";
import { useMailView } from "../hooks/useMailView";
import { useMailSettings } from "../hooks/useMailSettings";
import { useWebSocket } from "@/hooks/useWebSocket";

export default function Mail() {
  const { t } = useTranslation();
  const [searchParams, setSearchParams] = useSearchParams();

  // Состояние для диалога подтверждения удаления
  const [deleteConfirmDialog, setDeleteConfirmDialog] = useState<{
    open: boolean;
    mail: MailType | null;
  }>({ open: false, mail: null });

  // Хук для управления аккаунтами
  const {
    accounts,
    selectedAccountId,
    setSelectedAccountId,
    includeSubfolders,
    setIncludeSubfolders,
    loading: accountsLoading,
    refetch: refetchAccounts,
  } = useMailAccounts();

  // Хук для управления папками
  const {
    folders,
    activeFolder,
    setActiveFolder,
    loading: foldersLoading,
    refetch: refetchFolders,
  } = useMailFolders(selectedAccountId);

  // Хук для управления письмами
  const {
    mails,
    filteredMails,
    selectedMail,
    setSelectedMail,
    loading: mailsLoading,
    searchQuery,
    setSearchQuery,
    mailFilter,
    setMailFilter,
    mailSort,
    setMailSort,
    refetch: refetchMails,
    markAsRead,
    toggleStar,
    isSearching,
  } = useMails({
    selectedAccountId,
    activeFolder,
    includeSubfolders,
  });

  // Хук для массовых операций
  const {
    selectedMailIds,
    toggleSelectMail,
    selectAll,
    clearSelection,
    isAllSelected,
    showMassActions,
    handleMassDelete,
    handleMassRead,
    handleMassUnread,
    handleMassArchive,
    handleMassSpam,
  } = useMailSelection({
    mails: filteredMails,
    folders,
    onMailsUpdated: refetchMails,
  });

  // Хук для управления режимом просмотра
  const {
    viewMode,
    setViewMode,
    composeOpen,
    setComposeOpen,
    settingsAccountId,
    replyToMail,
    setReplyToMail,
    forwardMail,
    setForwardMail,
    handleReply,
    handleForward,
    handleCloseCompose,
    handleCloseSettings,
    handleOpenSettings,
  } = useMailView();

  // Открываем настройки если есть параметр в URL
  useEffect(() => {
    const settingsParam = searchParams.get('settings');
    if (settingsParam) {
      if (settingsParam === 'new') {
        handleOpenSettings();
      } else {
        handleOpenSettings(settingsParam);
      }
      // Удаляем параметр из URL после обработки
      const newParams = new URLSearchParams(searchParams);
      newParams.delete('settings');
      setSearchParams(newParams, { replace: true });
    }
  }, [searchParams]);

  // Хук для настроек
  const { mailListWidth, setMailListWidth } = useMailSettings();

  // WebSocket подключение
  const { isConnected, lastMessage, syncStatus } = useWebSocket({
    userId: undefined, // TODO: получить из контекста авторизации
    onNewMail: (data) => {
      console.log('[Mail] New mail notification:', data);
      // Можно автоматически обновить список писем
    },
    onSyncStatus: (data) => {
      console.log('[Mail] Sync status:', data);
      if (data.status === 'completed') {
        // Обновляем письма после завершения синхронизации
        refetchMails();
      }
    },
    autoReconnect: true,
    reconnectInterval: 5000
  });

  // Обработчик смены аккаунта
  const handleAccountChange = (accountId: string) => {
    console.log(`[MAIL] handleAccountChange: ${accountId}`);
    const nextAccount = accounts.find((account) => account.id === accountId);
    setSelectedAccountId(accountId);
    setIncludeSubfolders(Boolean(nextAccount?.includeSubfolders));
    setActiveFolder(''); // Reset folder when changing account
    setSelectedMail(null);
    refetchMails(); // Всегда перезагружаем письма
    refetchFolders(); // Всегда перезагружаем папки
  };

  // Обработчик отправки письма
  const handleMailSent = () => {
    refetchMails();
  };

  // Слушаем событие очистки папки
  useEffect(() => {
    const handleFolderCleared = (event: CustomEvent) => {
      const { folderId } = event.detail;
      if (folderId === activeFolder) {
        setActiveFolder('');
        refetchMails();
      } else {
        refetchMails();
      }
    };

    window.addEventListener('mail-folder-cleared', handleFolderCleared as EventListener);
    return () => window.removeEventListener('mail-folder-cleared', handleFolderCleared as EventListener);
  }, [activeFolder, refetchMails, setActiveFolder]);

  // Обработчик действий контекстного меню
  const handleContextMenuAction = async (action: string, mail: MailType, data?: any) => {
    console.log('[Mail] Context menu action:', action, 'mailId:', mail.id, 'data:', data);

    switch (action) {
      case 'open':
        setSelectedMail(mail);
        setViewMode('mail');
        break;

      case 'reply':
        handleReply(mail);
        break;

      case 'replyAll': {
        const allRecipients: string[] = [];
        if (typeof mail.sender === 'object' && mail.sender?.email) {
          allRecipients.push(mail.sender.email);
        }
        if (mail.recipients) {
          mail.recipients.forEach(r => {
            if (!allRecipients.includes(r)) allRecipients.push(r);
          });
        }
        handleReply({ ...mail, recipients: allRecipients });
        break;
      }

      case 'forward':
        handleForward(mail);
        break;

      case 'markRead':
        try {
          await markAsRead(mail.id, data);
        } catch (error) {
          console.error('Error marking as read:', error);
          toast.error('Ошибка при изменении статуса прочтения');
        }
        break;

      case 'moveToFolder':
        try {
          console.log('[Mail] Moving mail to folder:', mail.id, data);
          await api.patch(`/mail/${mail.id}/move`, { folderId: data });
          toast.success('Письмо перемещено');
          refetchMails();
        } catch (error) {
          console.error('Error moving to folder:', error);
          toast.error('Ошибка при перемещении письма');
        }
        break;

      case 'delete':
        console.log('[Mail] Delete action triggered for mail:', mail.id);
        setDeleteConfirmDialog({ open: true, mail });
        break;

      case 'spam': {
        const spamFolder = folders.find(f => f.folderType === 'spam')
          || folders.find(f => f.folderName.toLowerCase().includes('spam'));
        if (!spamFolder) {
          toast.error('Папка "Спам" не найдена');
          return;
        }
        try {
          await api.patch(`/mail/${mail.id}/move`, { folderId: spamFolder.id });
          toast.success('Письмо перемещено в спам');
          refetchMails();
        } catch (error) {
          console.error('Error moving to spam:', error);
          toast.error('Ошибка при перемещении в спам');
        }
        break;
      }

      case 'addLabel':
        toast.info('Функция меток в разработке');
        break;

      case 'createLabel':
        toast.info('Функция создания меток в разработке');
        break;

      case 'print':
        window.print();
        break;

      default:
        console.warn('[Mail] Unknown context menu action:', action);
        toast.warning('Неизвестное действие');
    }
  };

  const handleArchive = async (mail: MailType) => {
    const archiveFolder = folders.find(f => f.folderType === 'archive')
      || folders.find(f => f.folderName.toLowerCase().includes('archive') || f.folderName.toLowerCase().includes('all mail'));
    if (!archiveFolder) {
      toast.error('Папка "Архив" не найдена');
      return;
    }

    try {
      await api.patch(`/mail/${mail.id}/move`, { folderId: archiveFolder.id });
      toast.success('Письмо архивировано');
      refetchMails();
    } catch (error) {
      console.error('Error archiving mail:', error);
      toast.error('Ошибка при архивировании');
    }
  };

  const handleDelete = async (mail: MailType) => {
    const trashFolder = folders.find(f => f.folderType === 'trash')
      || folders.find(f => f.folderName.toLowerCase().includes('trash') || f.folderName.toLowerCase().includes('корзин'));
    if (trashFolder && mail.folder !== 'trash') {
      // Переместить в корзину
      try {
        await api.patch(`/mail/${mail.id}/move`, { folderId: trashFolder.id });
        toast.success('Письмо перемещено в корзину');
        refetchMails();
      } catch (error) {
        console.error('Error moving to trash:', error);
        toast.error('Ошибка при перемещении в корзину');
      }
    } else {
      // Уже в корзине - удалить окончательно
      setDeleteConfirmDialog({ open: true, mail });
    }
  };

  // Подтверждение удаления из диалога
  const confirmDelete = async () => {
    const mail = deleteConfirmDialog.mail;
    if (!mail) return;

    try {
      await api.delete(`/mail/${mail.id}`);
      toast.success('Письмо удалено');
      refetchMails();

      // Если письмо было открыто — закрываем
      if (selectedMail?.id === mail.id) {
        setSelectedMail(null);
      }
    } catch (error) {
      console.error('Error deleting mail:', error);
      toast.error(`Ошибка удаления: ${error instanceof Error ? error.message : 'неизвестная ошибка'}`);
    } finally {
      setDeleteConfirmDialog({ open: false, mail: null });
    }
  };

  // Отмена удаления
  const cancelDelete = () => {
    setDeleteConfirmDialog({ open: false, mail: null });
  };

  // Состояние загрузки
  const loading = accountsLoading || foldersLoading || mailsLoading;

  // Если нет аккаунтов
  if (!selectedAccountId && accounts.length === 0) {
    return (
      <AppLayout title={t('mail.title')} breadcrumbs={[{ label: t('mail.title') }]}>
        <div className="flex h-[calc(100vh-8rem)] items-center justify-center">
          <div className="text-center">
            <h2 className="text-xl font-semibold mb-2">{t('mail.no_accounts')}</h2>
            <p className="text-muted-foreground mb-4">
              {t('mail.account_not_configured')}
            </p>
          </div>
        </div>
      </AppLayout>
    );
  }

  return (
    <AppLayout
      title={t('mail.title')}
      breadcrumbs={[{ label: t('mail.title') }]}
      actions={
        <div className="flex items-center gap-2 w-full sm:w-auto">
          <div className="relative flex-1 sm:w-64">
            <Search className="absolute left-2.5 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
            <Input
              placeholder={t('mail.search_placeholder')}
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="h-9 pl-9 pr-8 text-sm"
            />
            {searchQuery && (
              <button
                onClick={() => setSearchQuery('')}
                className="absolute right-2 top-1/2 -translate-y-1/2 text-muted-foreground hover:text-foreground"
              >
                <X className="h-3.5 w-3.5" />
              </button>
            )}
          </div>
          <MailFilterSortMenu
            filter={mailFilter}
            sort={mailSort}
            onFilterChange={setMailFilter}
            onSortChange={setMailSort}
          />
        </div>
      }
    >
      <div
          className="flex h-[calc(100vh-8rem)] w-full min-w-0 border rounded-lg overflow-hidden bg-background shadow-sm"
          data-mail-container
        >
          <MailSidebar
            activeFolder={activeFolder}
            setActiveFolder={setActiveFolder}
            selectedAccountId={selectedAccountId}
            onAccountChange={handleAccountChange}
            searchQuery={searchQuery}
            onSearchChange={setSearchQuery}
            accounts={accounts}
            folders={folders}
            // Фильтры и сортировка
            mailFilter={mailFilter}
            onMailFilterChange={setMailFilter}
            mailSort={mailSort}
            onMailSortChange={setMailSort}
            // Режим просмотра
            setViewMode={setViewMode}
            // Фоновая синхронизация
            isSyncing={syncStatus?.status === 'progress' || syncStatus?.status === 'counting'}
          />

          {/* Основная область: контент + футер */}
          <div className="flex flex-1 flex-col min-w-0 overflow-hidden">
            {/* Контейнер списка писем */}
            {viewMode === 'list' && (
              <div
                className="flex flex-1 min-w-0 w-full flex-col overflow-hidden"
              >
                <MailList
                mails={filteredMails}
                selectedMailId={selectedMail?.id}
                onSelectMail={(mail) => {
                  setSelectedMail(mail);
                  setViewMode('mail');
                }}
                onToggleStar={toggleStar}
                loading={loading}
                // Массовые операции
                selectedMailIds={selectedMailIds}
                onToggleSelectMail={toggleSelectMail}
                onSelectAll={selectAll}
                showSelectAll={true}
                // Контекстное меню
                folders={folders}
                labels={[]}
                onContextMenuAction={handleContextMenuAction}
              />
            </div>
            )}

            {/* Контейнер просмотра письма */}
            {viewMode === 'mail' && (
              <div className="flex-1 flex flex-col overflow-hidden w-full min-w-0">
                <MailDisplay
                  mail={selectedMail || undefined}
                  folders={folders}
                  onReply={handleReply}
                  onForward={handleForward}
                  onArchive={handleArchive}
                  onDelete={handleDelete}
                  onMailUpdate={refetchMails}
                  setViewMode={setViewMode}
                  filteredMails={filteredMails}
                  selectedMail={selectedMail}
                  setSelectedMail={setSelectedMail}
                />
              </div>
            )}

            {/* Контейнер написания письма */}
            {viewMode === 'compose' && composeOpen && (
              <div className="flex-1 flex flex-col overflow-hidden w-full min-w-0">
                <MailCompose
                  open={composeOpen}
                  variant="page"
                  onClose={handleCloseCompose}
                  accountId={selectedAccountId}
                  onSent={() => {
                    handleMailSent();
                    handleCloseCompose();
                  }}
                  replyTo={replyToMail ? {
                    subject: replyToMail.subject,
                    sender: typeof replyToMail.sender === 'object' ? replyToMail.sender?.name : replyToMail.sender,
                    senderEmail: typeof replyToMail.sender === 'object' ? replyToMail.sender?.email : (typeof replyToMail.sender === 'string' ? replyToMail.sender : ''),
                    content: replyToMail.content,
                    date: replyToMail.timestamp,
                    recipients: replyToMail.recipients
                  } : undefined}
                />
              </div>
            )}

            {/* Контейнер настроек почтового аккаунта */}
            {viewMode === 'settings' && (
              <div className="flex-1 flex flex-col overflow-hidden w-full min-w-0">
                <MailAccountSettings
                  accountId={settingsAccountId || undefined}
                  variant="page"
                  onCancel={handleCloseSettings}
                  onSave={() => {
                    refetchAccounts();
                    handleCloseSettings();
                  }}
                />
              </div>
            )}

            {/* Футер — bulk actions и прогресс синхронизации */}
            {(showMassActions && selectedMailIds.length > 0) || (syncStatus && (syncStatus.status === 'progress' || syncStatus.status === 'counting' || syncStatus.status === 'completed' || syncStatus.status === 'error')) ? (
              <div className="shrink-0 w-full min-w-0 border-t bg-muted/30">
                {/* Bulk actions menu */}
                {showMassActions && selectedMailIds.length > 0 && (
                  <div className="px-3 py-2 border-b bg-muted/50 flex items-center justify-between gap-2">
                    <div className="flex items-center gap-2">
                      <span className="text-sm font-medium">
                        Выбрано: {selectedMailIds.length}
                      </span>
                    </div>
                    <div className="flex items-center gap-1">
                      <Button
                        variant="outline"
                        size="sm"
                        onClick={handleMassRead}
                        title="Отметить как прочитанное"
                      >
                        <Eye className="h-4 w-4" />
                      </Button>
                      <Button
                        variant="outline"
                        size="sm"
                        onClick={handleMassUnread}
                        title="Отметить как непрочитанное"
                      >
                        <EyeOff className="h-4 w-4" />
                      </Button>
                      <Button
                        variant="outline"
                        size="sm"
                        onClick={handleMassArchive}
                        title="В архив"
                      >
                        <Archive className="h-4 w-4" />
                      </Button>
                      <Button
                        variant="outline"
                        size="sm"
                        onClick={handleMassSpam}
                        title="В спам"
                      >
                        <ShieldAlert className="h-4 w-4" />
                      </Button>
                      <Button
                        variant="outline"
                        size="sm"
                        onClick={handleMassDelete}
                        className="text-destructive hover:text-destructive"
                        title="Удалить"
                      >
                        <Trash2 className="h-4 w-4" />
                      </Button>
                      <Button
                        variant="ghost"
                        size="sm"
                        onClick={clearSelection}
                        title="Снять выделение"
                      >
                        <X className="h-4 w-4" />
                      </Button>
                    </div>
                  </div>
                )}

                {/* Sync progress */}
                {syncStatus && (syncStatus.status === 'progress' || syncStatus.status === 'counting' || syncStatus.status === 'completed' || syncStatus.status === 'error') && (
                  <MailSyncProgress
                    status={syncStatus.status}
                    progress={syncStatus.progress || 0}
                    message={syncStatus.message || ''}
                    folderName={syncStatus.folderName}
                    folderProgress={syncStatus.folderProgress}
                    processedEmails={syncStatus.processedEmails}
                    totalEmailsToProcess={syncStatus.totalEmailsToProcess}
                    emailsSynced={syncStatus.emailsSynced}
                    attachmentsDownloaded={syncStatus.attachmentsDownloaded}
                    folderCounts={syncStatus.folderCounts}
                  />
                )}
              </div>
            ) : null}
          </div>
        </div>

        {/* Диалог подтверждения удаления */}
        <AlertDialog open={deleteConfirmDialog.open} onOpenChange={(open) => !open && cancelDelete()}>
          <AlertDialogContent>
            <AlertDialogHeader>
              <AlertDialogTitle>Удалить письмо?</AlertDialogTitle>
              <AlertDialogDescription>
                {deleteConfirmDialog.mail?.subject || 'Без темы'} будет удалено. Это действие нельзя отменить.
              </AlertDialogDescription>
            </AlertDialogHeader>
            <AlertDialogFooter>
              <AlertDialogCancel onClick={cancelDelete}>Отмена</AlertDialogCancel>
              <AlertDialogAction onClick={confirmDelete} className="bg-destructive text-destructive-foreground hover:bg-destructive/90">
                Удалить
              </AlertDialogAction>
            </AlertDialogFooter>
          </AlertDialogContent>
        </AlertDialog>
      </AppLayout>
    );
}

export interface Mail {
  id: string;
  subject: string;
  sender: {
    name: string;
    email: string;
    avatar?: string;
  };
  recipients: string[];
  content: string;
  htmlContent?: string;
  timestamp: string;
  folder: 'inbox' | 'sent' | 'drafts' | 'trash' | 'archive' | 'spam';
  isRead: boolean;
  isStarred: boolean;
  hasAttachments: boolean;
  attachments?: Attachment[];
  labels?: string[];
  // Дополнительные поля для улучшенного отображения
  categoryId?: string; // Для категорий (заказы, счета и т.д.)
  isOfficial?: boolean; // Для официальных писем (гос. органы, банки)
  sendStatus?: 'pending' | 'retrying' | 'failed' | 'sent'; // Статус отправки для писем в "Отправленных"
}

export interface Attachment {
  id: string;
  name: string;
  size: number;
  type: string;
  url: string;
}

export interface MailFolder {
  id: string;
  name: string;
  icon: string;
  count: number;
  unreadCount: number;
}

export interface MailFilters {
  search: string;
  folder: string;
  labels: string[];
  dateRange?: {
    from: Date;
    to: Date;
  };
}

// Типы для API (используются в transformMailData)
export interface MailApiItem {
  id?: string;
  subject?: string;
  sender?: string | { name: string; email: string; avatar?: string };
  senderEmail?: string;
  sender_email?: string;
  avatar?: string;
  content?: string;
  date?: string;
  timestamp?: string;
  read?: boolean;
  isRead?: boolean;
  label?: string;
  folder?: string;
  folderId?: string;
  folder_id?: string;
  isStarred?: boolean;
  is_starred?: boolean;
  hasAttachments?: boolean;
  has_attachments?: boolean;
  attachments?: any[];
  htmlContent?: string;
  html_content?: string;
  sendStatus?: 'pending' | 'retrying' | 'failed' | 'sent';
}

export interface MailAccount {
  id: string;
  email: string;
  displayName?: string;
  accountType?: string;
  isDefault?: boolean;
  isActive?: boolean;
  includeSubfolders?: boolean;
  syncFolders?: string[] | null;
}

export interface ApiMailFolder {
  id: string;
  folderName: string;
  folderType: string;
  unseenCount: number;
  totalCount: number;
  displayOrder?: number;
}

// Типы для фильтрации и сортировки
export type MailFilterType = 'all' | 'unread' | 'starred' | 'attachments';
export type MailSortType = 'date-desc' | 'date-asc' | 'sender-asc' | 'sender-desc' | 'subject-asc' | 'subject-desc';

// Тип для WebSocket событий
export interface MailSyncStatus {
  status: 'completed' | 'in_progress' | 'failed';
  accountId: string;
  folderId?: string;
  processed?: number;
  total?: number;
}

// Тип для контекстного меню
export type MailContextMenuAction =
  | 'open'
  | 'reply'
  | 'replyAll'
  | 'forward'
  | 'markRead'
  | 'moveToFolder'
  | 'delete'
  | 'spam'
  | 'addLabel'
  | 'createLabel'
  | 'print';

import { Mail, Attachment, MailApiItem, MailFilterType, MailSortType } from '../types';

/**
 * Трансформирует вложение из формата API в формат фронтенда
 */
export const transformAttachment = (attachment: any): Attachment => ({
  id: attachment?.id || '',
  name: attachment?.name || attachment?.filename || 'attachment',
  size: Number(attachment?.size ?? attachment?.file_size ?? 0),
  type: attachment?.type || attachment?.content_type || '',
  url: attachment?.url || attachment?.stored_path || '',
});

/**
 * Трансформирует данные письма из формата API в формат фронтенда
 */
export const transformMailData = (data: MailApiItem[]): Mail[] => {
  return data.map((item, index) => {
    // Обработка даты - пробуем разные форматы
    let timestamp = new Date().toISOString();
    const rawDate = item.timestamp || item.date;
    if (rawDate) {
      try {
        // Пробуем распарсить дату
        let dateStr = rawDate;

        // Если дата в формате "2025-09-12 10:40:26.000+03" (без T), заменяем пробел на T
        if (typeof dateStr === 'string' && dateStr.includes(' ') && !dateStr.includes('T')) {
          dateStr = dateStr.replace(' ', 'T');
        }

        const parsedDate = new Date(dateStr);

        if (!isNaN(parsedDate.getTime())) {
          timestamp = parsedDate.toISOString();
        } else {
          console.warn('Invalid date format:', rawDate);
        }
      } catch (error) {
        console.warn('Error parsing date:', rawDate, error);
      }
    }

    const attachments = Array.isArray(item.attachments)
      ? item.attachments.map(transformAttachment)
      : [];

    const hasAttachmentsFlag = item.hasAttachments ?? item.has_attachments;
    const hasAttachments = Boolean(hasAttachmentsFlag) || attachments.length > 0;

    // Определяем отправителя
    let senderName = '';
    let senderEmail = '';
    let avatar = undefined;

    if (item.sender && typeof item.sender === 'object') {
      senderName = (item.sender as any).name || '';
      senderEmail = (item.sender as any).email || '';
      avatar = (item.sender as any).avatar;
    } else if (typeof item.sender === 'string') {
      senderName = item.sender;
      senderEmail = item.senderEmail || item.sender_email || '';
    } else {
      // Если sender не определен или null/undefined
      senderName = '';
      senderEmail = item.senderEmail || item.sender_email || '';
    }

    return {
      id: item.id || `temp-${index}`,
      subject: item.subject || '',
      sender: {
        name: senderName,
        email: senderEmail,
        avatar,
      },
      recipients: [],
      content: item.content || '',
      htmlContent: item.htmlContent || item.html_content || undefined,
      timestamp,
      folder: (item.folder || item.folderId || item.folder_id || 'inbox') as Mail['folder'],
      isRead: Boolean(item.isRead ?? item.read),
      isStarred: Boolean(item.isStarred ?? item.is_starred),
      hasAttachments,
      attachments,
      labels: item.label ? [item.label] : [],
      sendStatus: item.sendStatus || undefined,
    };
  });
};

/**
 * Фильтрует и сортирует письма согласно заданным параметрам
 */
export const filterAndSortMails = (
  mails: Mail[],
  options: {
    searchQuery?: string;
    mailFilter?: MailFilterType;
    mailSort?: MailSortType;
  }
): Mail[] => {
  const { searchQuery = '', mailFilter = 'all', mailSort = 'date-desc' } = options;

  return mails
    .filter(mail => {
      // Фильтр по типу
      if (mailFilter === 'unread' && mail.isRead) return false;
      if (mailFilter === 'starred' && !mail.isStarred) return false;
      if (mailFilter === 'attachments' && !mail.hasAttachments) return false;

      // Поиск по отправителю, теме, содержимому
      if (searchQuery.trim()) {
        const query = searchQuery.toLowerCase();
        const senderName = mail.sender.name?.toLowerCase() || '';
        const senderEmail = mail.sender.email?.toLowerCase() || '';
        const subject = mail.subject?.toLowerCase() || '';
        const content = mail.content?.toLowerCase() || '';

        const matchesSearch = 
          senderName.includes(query) ||
          senderEmail.includes(query) ||
          subject.includes(query) ||
          content.includes(query);

        if (!matchesSearch) return false;
      }

      return true;
    })
    .sort((a, b) => {
      // Сортировка
      const dateA = new Date(a.timestamp).getTime();
      const dateB = new Date(b.timestamp).getTime();
      const senderA = (a.sender.name || a.sender.email || '').toLowerCase();
      const senderB = (b.sender.name || b.sender.email || '').toLowerCase();
      const subjectA = (a.subject || '').toLowerCase();
      const subjectB = (b.subject || '').toLowerCase();

      switch (mailSort) {
        case 'date-desc':
          return dateB - dateA;
        case 'date-asc':
          return dateA - dateB;
        case 'sender-asc':
          return senderA.localeCompare(senderB);
        case 'sender-desc':
          return senderB.localeCompare(senderA);
        case 'subject-asc':
          return subjectA.localeCompare(subjectB);
        case 'subject-desc':
          return subjectB.localeCompare(subjectA);
        default:
          return 0;
      }
    });
};

/**
 * Форматирует размер файла в читаемый вид
 */
export const formatFileSize = (bytes: number): string => {
  if (bytes === 0) return '0 Bytes';
  const k = 1024;
  const sizes = ['Bytes', 'KB', 'MB', 'GB'];
  const i = Math.floor(Math.log(bytes) / Math.log(k));
  return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
};

/**
 * Извлекает домен из email адреса
 */
export const getEmailDomain = (email: string): string => {
  const atIndex = email.indexOf('@');
  return atIndex !== -1 ? email.substring(atIndex + 1) : '';
};

/**
 * Форматирует дату в относительное время (например, "2 часа назад")
 */
export const formatRelativeTime = (dateString: string): string => {
  const date = new Date(dateString);
  const now = new Date();
  const diffMs = now.getTime() - date.getTime();
  const diffMinutes = Math.floor(diffMs / (1000 * 60));
  const diffHours = Math.floor(diffMs / (1000 * 60 * 60));
  const diffDays = Math.floor(diffMs / (1000 * 60 * 60 * 24));

  if (diffMinutes < 1) return 'только что';
  if (diffMinutes < 60) return `${diffMinutes} мин. назад`;
  if (diffHours < 24) return `${diffHours} ч. назад`;
  if (diffDays === 1) return 'вчера';
  if (diffDays < 7) return `${diffDays} дн. назад`;

  // Для более старых дат используем форматирование даты
  return date.toLocaleDateString('ru-RU', {
    day: 'numeric',
    month: 'short',
    year: diffDays > 365 ? 'numeric' : undefined,
  });
};

