import React, { useState, useEffect } from "react";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Label } from "@/components/ui/label";
import { Checkbox } from "@/components/ui/checkbox";
import { Badge } from "@/components/ui/badge";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { useTranslation } from "@/lib/i18n";
import { Mail, Plus, Edit2, Trash2, Loader, Power, PowerOff, RefreshCw, ChevronLeft } from "lucide-react";
import { toast } from "sonner";
import { api } from "@/lib/api";
import { MailAccountSettings } from "@/modules/mail/components/MailAccountSettings";
import { showConfirm } from "@/components/ui/confirm-dialog";

interface MailAccount {
  id: string;
  email: string;
  displayName?: string;
  accountType: string;
  imapHost?: string;
  imapPort?: number;
  smtpHost?: string;
  smtpPort?: number;
  useTls?: boolean;
  isDefault: boolean;
  isActive: boolean;
  lastSync?: string;
  hasPassword?: boolean;
  syncEnabled?: boolean;
  syncIntervalMinutes?: number;
  includeSubfolders?: boolean;
  syncFolders?: string[] | null;
  imapFolders?: string[];
  folderMailCounts?: { folderName: string; folderId: string; mailCount: number }[];
}

export function ProfileMailTab() {
  const { t } = useTranslation();
  const [accounts, setAccounts] = useState<MailAccount[]>([]);
  const [selectedAccountId, setSelectedAccountId] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);
  const [testingId, setTestingId] = useState<string | null>(null);
  const [togglingId, setTogglingId] = useState<string | null>(null);
  const [syncingId, setSyncingId] = useState<string | null>(null);

  // Состояние для редактирования/добавления аккаунта
  const [editingAccountId, setEditingAccountId] = useState<string | null>(null);
  const [showSettings, setShowSettings] = useState(false);

  // Состояние диалога отключения синхронизации папки
  const [folderDisableDialog, setFolderDisableDialog] = useState<{
    isOpen: boolean;
    account: MailAccount | null;
    folderName: string | null;
    folderId: string | null;
    mailCount: number;
    syncAll: boolean;
  }>({ isOpen: false, account: null, folderName: null, folderId: null, mailCount: 0, syncAll: false });

  const openSettings = (accountId?: string) => {
    setEditingAccountId(accountId || null);
    setShowSettings(true);
  };

  const closeSettings = () => {
    setShowSettings(false);
    setEditingAccountId(null);
    fetchAccounts(); // Обновляем список после сохранения
  };

  useEffect(() => {
    fetchAccounts();
  }, []);

  const fetchAccounts = async () => {
    try {
      setLoading(true);
      const response = await api.get("/mail/accounts");

      const accountsWithFolders = await Promise.all(response.map(async (account: MailAccount) => {
        try {
          const [foldersResp, statsResp] = await Promise.all([
            api.get(`/mail/folders/${account.id}`),
            api.get(`/mail/folders/${account.id}/stats`).catch(() => [])
          ]);
          const folderNames = foldersResp.map((f: any) => f.folderName || f.folder_name);
          return { 
            ...account, 
            imapFolders: folderNames,
            folderMailCounts: statsResp || []
          };
        } catch {
          return account;
        }
      }));

      setAccounts(accountsWithFolders);
      if (accountsWithFolders.length > 0 && !selectedAccountId) {
        setSelectedAccountId(accountsWithFolders[0].id);
      }
    } catch (error) {
      console.error("Error fetching mail accounts:", error);
      toast.error("Не удалось загрузить аккаунты");
    } finally {
      setLoading(false);
    }
  };

  const getNextSyncTime = (account: MailAccount) => {
    if (!account.syncEnabled || !account.lastSync || !account.syncIntervalMinutes) return null;
    const last = new Date(account.lastSync);
    if (Number.isNaN(last.getTime())) return null;
    return new Date(last.getTime() + account.syncIntervalMinutes * 60 * 1000);
  };

  const handleSyncNow = async (accountId: string) => {
    try {
      setSyncingId(accountId);
      await api.post(`/mail/accounts/${accountId}/sync`, { background: false });
      // Тост "Синхронизация завершена" придёт через WebSocket
      fetchAccounts();
    } catch (error) {
      console.error("Error syncing account:", error);
      toast.error("Ошибка синхронизации");
    } finally {
      setSyncingId(null);
    }
  };

  const handleSyncEnabledChange = async (account: MailAccount, enabled: boolean) => {
    const prevEnabled = account.syncEnabled;
    setAccounts((prev) => prev.map((item) => item.id === account.id ? { ...item, syncEnabled: enabled } : item));
    try {
      await api.put(`/mail/accounts/${account.id}`, { syncEnabled: enabled });
      toast.success(enabled ? "Авто-синхронизация включена" : "Авто-синхронизация выключена");
      fetchAccounts();
    } catch (error) {
      console.error("Error updating sync enabled:", error);
      setAccounts((prev) => prev.map((item) => item.id === account.id ? { ...item, syncEnabled: prevEnabled } : item));
      toast.error("Не удалось обновить авто-синхронизацию");
    }
  };

  const handleSyncIntervalChange = async (account: MailAccount, minutes: number) => {
    if (!Number.isFinite(minutes) || minutes <= 0) {
      toast.error("Интервал должен быть больше 0");
      return;
    }

    const prevMinutes = account.syncIntervalMinutes;
    setAccounts((prev) => prev.map((item) => item.id === account.id ? { ...item, syncIntervalMinutes: minutes } : item));
    try {
      await api.put(`/mail/accounts/${account.id}`, { syncIntervalMinutes: minutes });
      toast.success("Интервал синхронизации обновлен");
      fetchAccounts();
    } catch (error) {
      console.error("Error updating sync interval:", error);
      setAccounts((prev) => prev.map((item) => item.id === account.id ? { ...item, syncIntervalMinutes: prevMinutes } : item));
      toast.error("Не удалось обновить интервал синхронизации");
    }
  };

  const handleSyncFoldersChange = async (account: MailAccount, folder: string) => {
    const currentSyncFolders = account.syncFolders || [];
    const allFolders = account.imapFolders || [];

    // Определяем: сейчас синхронизируются все папки?
    const syncAll = currentSyncFolders.length === 0;
    const isSyncing = syncAll || currentSyncFolders.includes(folder);

    // Если пытаемся отключить синхронизацию
    if (isSyncing) {
      // Получаем количество писем в папке
      const folderStats = account.folderMailCounts?.find(s => s.folderName === folder);
      const mailCount = folderStats?.mailCount || 0;
      const folderId = folderStats?.folderId || null;

      // Открываем кастомный диалог
      setFolderDisableDialog({
        isOpen: true,
        account,
        folderName: folder,
        folderId,
        mailCount,
        syncAll
      });
    } else {
      // Включаем папку: просто добавляем в список
      let newFolders = [...currentSyncFolders, folder];

      // Если включили все папки - сохраняем null (режим "все папки")
      if (newFolders.length >= allFolders.length) {
        newFolders = [];
      }

      // Optimistic update
      setAccounts((prev) => prev.map((item) =>
        item.id === account.id ? { ...item, syncFolders: newFolders.length > 0 ? newFolders : null } : item
      ));

      try {
        await api.put(`/mail/accounts/${account.id}`, { syncFolders: newFolders.length > 0 ? newFolders : null });
        toast.success(`Синхронизация папки "${folder}" включена`);
      } catch (error) {
        console.error("Error updating sync folders:", error);
        setAccounts((prev) => prev.map((item) =>
          item.id === account.id ? { ...item, syncFolders: currentSyncFolders } : item
        ));
        toast.error("Не удалось обновить папки синхронизации");
      }
    }
  };

  const executeFolderDisable = async (deleteEmails: boolean) => {
    const { account, folderName, folderId, mailCount, syncAll } = folderDisableDialog;
    if (!account || !folderName) return;

    setFolderDisableDialog(prev => ({ ...prev, isOpen: false }));

    const currentSyncFolders = account.syncFolders || [];
    const allFolders = account.imapFolders || [];

    // 1. Очищаем письма, если нужно
    if (deleteEmails && folderId && mailCount > 0) {
      try {
        await api.post(`/mail/folders/${folderId}/clear`, {});
        toast.success(`Папка "${folderName}" очищена (${mailCount} писем удалено)`);
      } catch (error) {
        console.error('Error clearing folder:', error);
        toast.error('Не удалось очистить папку');
      }
    }

    // 2. Отключаем папку в настройках
    const newFolders = syncAll
      ? allFolders.filter(f => f !== folderName)
      : currentSyncFolders.filter(f => f !== folderName);

    setAccounts((prev) => prev.map((item) =>
      item.id === account.id ? { ...item, syncFolders: newFolders.length > 0 ? newFolders : null } : item
    ));

    try {
      await api.put(`/mail/accounts/${account.id}`, { syncFolders: newFolders.length > 0 ? newFolders : null });
      toast.success(`Синхронизация папки "${folderName}" отключена`);
      fetchAccounts();
    } catch (error) {
      console.error("Error updating sync folders:", error);
      setAccounts((prev) => prev.map((item) =>
        item.id === account.id ? { ...item, syncFolders: currentSyncFolders } : item
      ));
      toast.error("Не удалось отключить синхронизацию");
    }
  };

  const handleIncludeSubfoldersChange = async (account: MailAccount, enabled: boolean) => {
    const prevEnabled = account.includeSubfolders;
    setAccounts((prev) => prev.map((item) => item.id === account.id ? { ...item, includeSubfolders: enabled } : item));
    try {
      await api.put(`/mail/accounts/${account.id}`, { includeSubfolders: enabled });
      toast.success(enabled ? "Подпапки включены" : "Подпапки выключены");
      fetchAccounts();
    } catch (error) {
      console.error("Error updating include subfolders:", error);
      setAccounts((prev) => prev.map((item) => item.id === account.id ? { ...item, includeSubfolders: prevEnabled } : item));
      toast.error("Не удалось обновить подпапки");
    }
  };

  const handleDelete = async (id: string) => {
    try {
      await api.delete(`/mail/accounts/${id}`);
      toast.success("Аккаунт удалён");
      fetchAccounts();
    } catch (error) {
      console.error("Error deleting account:", error);
      toast.error("Не удалось удалить аккаунт");
    }
  };

  const handleTest = async (id: string) => {
    try {
      setTestingId(id);
      await api.post(`/mail/accounts/${id}/test`, {});
      toast.success("Подключение успешно!");
    } catch (error: any) {
      console.error("Error testing account:", error);
      const errorMessage = error.response?.data?.details ||
                          error.response?.data?.error ||
                          "Не удалось подключиться";

      if (errorMessage.includes("credential") || errorMessage.includes("password")) {
        toast.error("Недостаточно данных для теста. Отредактируйте аккаунт и введите пароль.");
      } else {
        toast.error(errorMessage);
      }
    } finally {
      setTestingId(null);
    }
  };

  const handleToggleActive = async (id: string, currentActive: boolean) => {
    try {
      setTogglingId(id);
      const newStatus = !currentActive;

      await api.put(`/mail/accounts/${id}`, { isActive: newStatus });
      toast.success(currentActive ? "Аккаунт деактивирован" : "Аккаунт активирован");
      fetchAccounts();
    } catch (error: any) {
      console.error("Error toggling account:", error);
      const errorMessage = error.response?.data?.error || error.message || "Не удалось изменить статус аккаунта";
      toast.error(errorMessage);
    } finally {
      setTogglingId(null);
    }
  };

  return (
    <>
      {showSettings ? (
        <div className="flex flex-col h-[calc(100vh-12rem)]">
          <div className="mb-4">
            <Button
              variant="ghost"
              size="sm"
              onClick={closeSettings}
              className="gap-2"
            >
              <ChevronLeft className="w-4 h-4" />
              Назад к аккаунтам
            </Button>
          </div>
          <MailAccountSettings
            accountId={editingAccountId || undefined}
            variant="page"
            onCancel={closeSettings}
            onSave={closeSettings}
          />
        </div>
      ) : (
        <Card>
          <CardHeader>
            <div className="flex items-center justify-between">
              <div>
                <CardTitle className="flex items-center gap-2">
                  <Mail className="w-5 h-5" />
                  Почтовые аккаунты
                </CardTitle>
                <CardDescription>
                  Управляйте вашими почтовыми аккаунтами и их настройками
                </CardDescription>
              </div>
              <Button 
                size="sm" 
                className="gap-2"
                onClick={() => openSettings()}
              >
                <Plus className="w-4 h-4" />
                Добавить аккаунт
              </Button>
            </div>
          </CardHeader>

          <CardContent>
            {loading ? (
              <div className="flex items-center justify-center py-8">
                <Loader className="w-6 h-6 animate-spin text-muted-foreground" />
              </div>
            ) : accounts.length === 0 ? (
              <div className="text-center py-8 text-muted-foreground">
                <Mail className="w-12 h-12 mx-auto mb-4 opacity-50" />
                <p>У вас ещё нет добавленных аккаунтов</p>
              </div>
            ) : (
              <div className="space-y-3">
                {accounts.map((account) => (
                  <Card key={account.id} className="p-4">
                    <div className="flex items-start justify-between">
                      <div className="flex-1">
                        <div className="flex items-center gap-2 mb-2">
                          <h4 className="font-semibold">{account.displayName || account.email}</h4>
                          {account.isDefault && (
                            <Badge variant="outline" className="text-xs">
                              По умолчанию
                            </Badge>
                          )}
                          {account.isActive ? (
                            <Badge variant="outline" className="text-xs bg-green-50 text-green-700">
                              Активен
                            </Badge>
                          ) : (
                            <Badge variant="outline" className="text-xs bg-red-50 text-red-700">
                              Неактивен
                            </Badge>
                          )}
                        </div>
                        <p className="text-sm text-muted-foreground">{account.email}</p>
                        <p className="text-xs text-muted-foreground mt-1">
                          Тип: {account.accountType}
                        </p>
                        {account.lastSync && (
                          <p className="text-xs text-muted-foreground">
                            Последняя синхронизация: {new Date(account.lastSync).toLocaleString("ru-RU")}
                          </p>
                        )}
                        <div className="mt-2 flex flex-wrap items-center gap-3 text-xs text-muted-foreground">
                          <div className="flex items-center gap-2">
                            <Checkbox
                              id={`sync-enabled-${account.id}`}
                              checked={Boolean(account.syncEnabled)}
                              onCheckedChange={(checked) => handleSyncEnabledChange(account, checked as boolean)}
                            />
                            <label
                              htmlFor={`sync-enabled-${account.id}`}
                              className="cursor-pointer select-none"
                            >
                              Авто-синхронизация
                            </label>
                          </div>

                          <div className="flex items-center gap-2">
                            <Checkbox
                              id={`include-subfolders-${account.id}`}
                              checked={Boolean(account.includeSubfolders)}
                              onCheckedChange={(checked) => handleIncludeSubfoldersChange(account, checked as boolean)}
                            />
                            <label
                              htmlFor={`include-subfolders-${account.id}`}
                              className="cursor-pointer select-none"
                            >
                              Включать подпапки
                            </label>
                          </div>

                          <div className="flex items-center gap-2">
                            <span>Интервал:</span>
                            <select
                              className="h-7 rounded-md border border-input bg-background px-2 text-xs"
                              value={account.syncIntervalMinutes ?? 5}
                              onChange={(e) => handleSyncIntervalChange(account, Number(e.target.value))}
                              disabled={!account.syncEnabled}
                            >
                              <option value={5}>5 мин</option>
                              <option value={10}>10 мин</option>
                              <option value={15}>15 мин</option>
                              <option value={30}>30 мин</option>
                              <option value={60}>60 мин</option>
                            </select>
                          </div>

                          {getNextSyncTime(account) && (
                            <span>
                              След. синхр.: {getNextSyncTime(account)?.toLocaleString("ru-RU")}
                            </span>
                          )}
                        </div>

                        {account.imapFolders && account.imapFolders.length > 0 && (
                          <div className="mt-2 pt-2 border-t">
                            <Label className="text-xs mb-2 block">Папки для синхронизации:</Label>
                            <div className="flex flex-wrap gap-1.5">
                              {account.imapFolders.map((folder: string) => {
                                // Если syncFolders не установлен или пустой - синхронизируем все
                                const syncAll = !account.syncFolders || account.syncFolders.length === 0;
                                const isSyncing = syncAll || account.syncFolders.includes(folder);

                                // Получаем количество писем
                                const folderStats = account.folderMailCounts?.find(s => s.folderName === folder);
                                const mailCount = folderStats?.mailCount || 0;

                                return (
                                  <button
                                    key={folder}
                                    onClick={() => handleSyncFoldersChange(account, folder)}
                                    className={`
                                      inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-xs font-medium
                                      transition-colors cursor-pointer border
                                      ${isSyncing 
                                        ? 'bg-green-50 text-green-700 border-green-200 hover:bg-green-100' 
                                        : 'bg-red-50 text-red-700 border-red-200 hover:bg-red-100'
                                      }
                                    `}
                                    title={isSyncing ? 'Нажмите чтобы отключить' : 'Нажмите чтобы включить'}
                                  >
                                    <span>{folder}</span>
                                    {mailCount > 0 && (
                                      <span className={`
                                        text-[10px] px-1 py-0.5 rounded-full
                                        ${isSyncing 
                                          ? 'bg-green-200 text-green-800' 
                                          : 'bg-red-200 text-red-800'
                                        }
                                      `}>
                                        {mailCount}
                                      </span>
                                    )}
                                  </button>
                                );
                              })}
                            </div>
                          </div>
                        )}
                      </div>

                      <div className="flex gap-2">
                        <Button
                          variant="ghost"
                          size="sm"
                          onClick={() => handleSyncNow(account.id)}
                          disabled={syncingId === account.id}
                          className="text-blue-600 hover:text-blue-700 hover:bg-blue-50 [&_svg]:text-current"
                          title="Синхронизировать"
                        >
                          {syncingId === account.id ? (
                            <Loader className="w-4 h-4 animate-spin" />
                          ) : (
                            <RefreshCw className="w-4 h-4" />
                          )}
                        </Button>
                        <Button
                          variant="ghost"
                          size="sm"
                          onClick={() => handleToggleActive(account.id, account.isActive)}
                          disabled={togglingId === account.id}
                          className={`transition-all ${
                            account.isActive
                              ? "text-green-600 hover:text-green-700 hover:bg-green-50"
                              : "text-red-600 hover:text-red-700 hover:bg-red-50"
                          } [&_svg]:text-current`}
                          title={account.isActive ? "Деактивировать" : "Активировать"}
                        >
                          {togglingId === account.id ? (
                            <Loader className="w-4 h-4 animate-spin" />
                          ) : account.isActive ? (
                            <Power className="w-4 h-4" />
                          ) : (
                            <PowerOff className="w-4 h-4" />
                          )}
                        </Button>
                        <Button
                          variant="ghost"
                          size="sm"
                          onClick={() => handleTest(account.id)}
                          disabled={testingId === account.id}
                          className="[&_svg]:text-current"
                          title="Проверить подключение"
                        >
                          {testingId === account.id ? (
                            <Loader className="w-4 h-4 animate-spin" />
                          ) : (
                            <Mail className="w-4 h-4 text-blue-600" />
                          )}
                        </Button>
                        <Button
                          variant="ghost"
                          size="sm"
                          onClick={() => openSettings(account.id)}
                          className="[&_svg]:text-current"
                          title="Редактировать"
                        >
                          <Edit2 className="w-4 h-4" />
                        </Button>
                        <Button
                          variant="ghost"
                          size="sm"
                          onClick={() => handleDelete(account.id)}
                          className="text-red-600 hover:text-red-700 hover:bg-red-50 [&_svg]:text-current"
                          title="Удалить"
                        >
                          <Trash2 className="w-4 h-4" />
                        </Button>
                      </div>
                    </div>
                  </Card>
                ))}
              </div>
            )}
          </CardContent>
        </Card>
      )}

      {/* Кастомный диалог для отключения синхронизации папки */}
      <Dialog 
        open={folderDisableDialog.isOpen} 
        onOpenChange={(open) => !open && setFolderDisableDialog(prev => ({ ...prev, isOpen: false }))}
      >
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Отключить синхронизацию папки</DialogTitle>
            <DialogDescription>
              Вы отключаете синхронизацию папки <strong>"{folderDisableDialog.folderName}"</strong>.
              {folderDisableDialog.mailCount > 0 && (
                <span className="block mt-2 text-amber-600 bg-amber-50 p-2 rounded text-sm border border-amber-200">
                  В базе данных сохранено <strong>{folderDisableDialog.mailCount}</strong> писем из этой папки. 
                  Что с ними сделать?
                </span>
              )}
            </DialogDescription>
          </DialogHeader>

          <DialogFooter className="flex flex-col sm:flex-row sm:justify-start gap-2 sm:gap-0 mt-4">
            <Button
              variant="outline"
              onClick={() => setFolderDisableDialog(prev => ({ ...prev, isOpen: false }))}
              className="sm:order-1 order-3 w-full sm:w-auto"
            >
              Отмена
            </Button>
            <div className="flex-1" />
            <Button
              variant="outline"
              onClick={() => executeFolderDisable(false)}
              className="sm:order-2 order-1 w-full sm:w-auto hover:bg-slate-100"
            >
              Оставить письма
            </Button>
            {folderDisableDialog.mailCount > 0 ? (
              <Button
                variant="destructive"
                onClick={() => executeFolderDisable(true)}
                className="sm:order-3 order-2 w-full sm:w-auto"
              >
                Отключить и удалить
              </Button>
            ) : (
              <Button
                variant="destructive"
                onClick={() => executeFolderDisable(false)}
                className="sm:order-3 order-2 w-full sm:w-auto"
              >
                Отключить
              </Button>
            )}
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </>
  );
}

// frontend/src/modules/profile/hooks/useProfilePage.ts
import { useState, useEffect } from "react";
import { api } from "@/lib/api";
import { useToast } from "@/hooks/use-toast";
import { useTranslation } from "@/lib/i18n";

export interface ProfileData {
  name: string;
  email: string;
  phone: string;
  position: string;
  nickname: string;
  telegramToken: string;
  initials: string;
}

export interface PasswordData {
  current: string;
  new: string;
  confirm: string;
}

export interface NotificationsData {
  email: boolean;
  push: boolean;
  tasks: boolean;
  projects: boolean;
  contractors: boolean;
}

export function useProfilePage() {
  const { t } = useTranslation();
  const { toast } = useToast();
  const [loading, setLoading] = useState(true);

  const [profile, setProfile] = useState<ProfileData>({
    name: "", email: "", phone: "", position: "",
    nickname: "", telegramToken: "", initials: "UNK",
  });

  const [passwords, setPasswords] = useState<PasswordData>({
    current: "", new: "", confirm: "",
  });

  const [notifications, setNotifications] = useState<NotificationsData>({
    email: true, push: true, tasks: true, projects: true, contractors: false,
  });

  useEffect(() => {
    const fetchProfile = async () => {
      try {
        const [userData, notificationSettings] = await Promise.all([
          api.get("/users/me"),
          api.get("/user-settings/notifications"),
        ]);
        setProfile({
          name:          userData.name || "",
          email:         userData.email || "",
          phone:         userData.phone || "",
          position:      userData.employeePositionName || userData.employee_position_name || userData.department || "",
          nickname:      userData.nickname || "",
          telegramToken: userData.employeeTelegramId || userData.employee_telegram_id || userData.telegramToken || userData.telegram_token || "",
          initials:      userData.initials || "U",
        });
        if (notificationSettings) setNotifications(notificationSettings);
      } catch {
        toast({ title: t('profile.errors.title'), description: t('profile.errors.load_profile'), variant: "destructive" });
      } finally {
        setLoading(false);
      }
    };
    fetchProfile();
  }, [toast]);

  const handleProfileSave = async () => {
    try {
      await api.put("/users/me", {
        name: profile.name, email: profile.email, phone: profile.phone,
        nickname: profile.nickname, telegramToken: profile.telegramToken,
      });
      toast({ title: t("general.toast.success.profile_saved"), description: t("general.toast.success.profile_updated") });
    } catch {
      toast({ title: t('profile.errors.title'), description: t('profile.errors.save_profile'), variant: "destructive" });
    }
  };

  const handlePasswordChange = async () => {
    if (passwords.new !== passwords.confirm) {
      toast({ title: t("general.toast.error.title"), description: t("general.toast.error.passwords_dont_match"), variant: "destructive" });
      return;
    }
    if (passwords.new.length < 4) {
      toast({ title: t("general.toast.error.title"), description: t("general.toast.error.password_too_short"), variant: "destructive" });
      return;
    }
    try {
      await api.put("/users/me/change-password", { currentPassword: passwords.current, newPassword: passwords.new });
      setPasswords({ current: "", new: "", confirm: "" });
      toast({ title: t("general.toast.success.password_changed"), description: t("general.toast.success.password_updated") });
    } catch {
      toast({ title: t('profile.errors.title'), description: t('profile.errors.change_password'), variant: "destructive" });
    }
  };

  const handleNotificationsSave = async () => {
    try {
      await api.post("/user-settings", { key: "notifications", value: notifications });
      toast({ title: t("general.toast.success.notifications_saved"), description: t("general.toast.success.notifications_updated") });
    } catch {
      toast({ title: t('profile.errors.title'), description: t('profile.errors.save_notifications'), variant: "destructive" });
    }
  };

  // Split name into firstName/lastName for UI
  const nameParts = profile.name.split(" ");
  const lastName  = nameParts.length > 1 ? nameParts[0] : "";
  const firstName = nameParts.length > 1 ? nameParts.slice(1).join(" ") : nameParts[0];
  const setLastName  = (val: string) => setProfile((p) => ({ ...p, name: `${val} ${firstName}`.trim() }));
  const setFirstName = (val: string) => setProfile((p) => ({ ...p, name: `${lastName} ${val}`.trim() }));

  return {
    loading,
    profile, setProfile,
    passwords, setPasswords,
    notifications, setNotifications,
    lastName, firstName, setLastName, setFirstName,
    handleProfileSave, handlePasswordChange, handleNotificationsSave,
  };
}

