import { useState, useEffect, useRef, useCallback } from "react";
import {
  Sheet,
  SheetContent,
  SheetHeader,
  SheetTitle,
  SheetDescription,
  SheetFooter,
} from "@/components/ui/sheet";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Button } from "@/components/ui/button";
import { useTranslation } from "@/lib/i18n";
import { CheckCircle2, Trash2, FolderKanban, Info, ListChecks, DollarSign, Wallet, CheckSquare } from "lucide-react";
import { OpenProjectTaskSheetRequest, Project, ProjectTask } from "../types";
import { ProjectGeneralTab } from "./tabs/ProjectGeneralTab";
import { ProjectTasksTab } from "./tabs/ProjectTasksTab";
import { ProjectStagesTab } from "./tabs/ProjectStagesTab";
import { ProjectRevenuesTab } from "./tabs/ProjectRevenuesTab";
import { ProjectExpensesTab } from "./tabs/ProjectExpensesTab";
import { Contractor, ContractorSheet } from "@/modules/contractors";
import { api } from "@/lib/api";
import { useSheetTabs } from "@/hooks/useSheetTabs";
import { useSheetWidth } from "@/hooks/useSheetWidth";
import { SheetTabSettings } from "@/components/shared";
import type { ReferenceData } from "../hooks/useProjectsPage.types";
import { useProjectSheet } from "../hooks/useProjectSheet";

interface ProjectSheetProps {
  project: Project | null;
  allProjects?: Project[];
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onSave: (project: Project) => void;
  onDelete?: (id: number) => void;
  contractors: Contractor[];
  onAddContractor?: () => void;
  references?: ReferenceData;
  onOpenTaskSheet?: (request: OpenProjectTaskSheetRequest) => void;
}

export function ProjectSheet({
  project,
  allProjects = [],
  open,
  onOpenChange,
  onSave,
  onDelete,
  contractors,
  references,
  onOpenTaskSheet,
}: ProjectSheetProps) {
  const { t } = useTranslation();

  // Project Sheet Width Control
  const {
    width: sheetWidth,
    setCustomWidth: setSheetCustomWidth,
    getWidthClass,
    getWidthValue,
  } = useSheetWidth('project-sheet', 'lg');

  const sheetRef = useRef<HTMLDivElement>(null);
  const resizeHandleRef = useRef<HTMLDivElement>(null);
  const startXRef = useRef(0);
  const startWidthRef = useRef(0);

  // Resize handler
  const handleMouseDown = useCallback((e: React.MouseEvent) => {
    e.preventDefault();
    e.stopPropagation();

    startXRef.current = e.clientX;
    startWidthRef.current = sheetWidth.customWidth || getWidthValue();

    const handleMouseMove = (moveEvent: MouseEvent) => {
      const deltaX = startXRef.current - moveEvent.clientX;
      const newWidth = Math.max(400, Math.min(startWidthRef.current + deltaX, Math.min(window.innerWidth * 0.9, 1600)));
      setSheetCustomWidth(newWidth);
    };

    const handleMouseUp = () => {
      document.removeEventListener('mousemove', handleMouseMove);
      document.removeEventListener('mouseup', handleMouseUp);
      document.body.style.cursor = '';
      document.body.style.userSelect = '';
    };

    document.addEventListener('mousemove', handleMouseMove);
    document.addEventListener('mouseup', handleMouseUp);
    document.body.style.cursor = 'col-resize';
    document.body.style.userSelect = 'none';
  }, [sheetWidth.customWidth, setSheetCustomWidth, getWidthValue]);

  // Use custom hook for project sheet logic
  const {
    formData,
    projectTasks,
    setProjectTasks,
    contractorSheetOpen,
    pendingContractorName,
    handleInputChange,
    handleCreateContractor,
    handleContractorSaved,
    handleContractorSheetOpenChange,
    handleCreateTask,
    handleEditTask,
  } = useProjectSheet({
    project,
    open,
    references,
    onOpenTaskSheet,
  });

  // Tab Management with Persistence
  const { tabs, toggleTab, moveTab } = useSheetTabs([
    { id: "general", label: "sheet.tabs.overview", icon: Info, visible: true },
    { id: "tasks", label: "sheet.tabs.tasks", icon: CheckSquare, visible: true },
    { id: "stages", label: "sheet.tabs.stages", icon: ListChecks, visible: true },
    { id: "revenues", label: "sheet.tabs.revenues", icon: DollarSign, visible: true },
    { id: "expenses", label: "sheet.tabs.expenses", icon: Wallet, visible: true },
  ], "project-sheet");

  const [activeTab, setActiveTab] = useState("general");

  // Ensure active tab is visible
  useEffect(() => {
    const currentTab = tabs.find(t => t.id === activeTab);
    if (currentTab && !currentTab.visible) {
      const firstVisible = tabs.find(t => t.visible);
      if (firstVisible) setActiveTab(firstVisible.id);
    }
  }, [tabs, activeTab]);

  const handleSave = () => {
    const newProject: Project = {
      id: project?.id || 0,
      parentId: formData.parentId || null,
      name: formData.name || "New Project",
      client: formData.client || "Client",
      manager: formData.manager || "Unassigned",
      status: formData.status || "pending",
      stage: formData.stage || "todo",
      priority: formData.priority || "Medium",
      budget: formData.budget || 0,
      budgetUsed: formData.budgetUsed || 0,
      deadline: formData.deadline || "",
      tasksCount: formData.tasksCount || 0,
      completedTasks: formData.completedTasks || 0,
      subProjects: formData.subProjects || []
    };
    onSave(newProject);
    onOpenChange(false);
  };

  const handleDelete = () => {
    if (project && onDelete) {
      onDelete(project.id);
    }
    onOpenChange(false);
  };

  return (
    <>
      <Sheet open={open} onOpenChange={onOpenChange}>
        <SheetContent 
          ref={sheetRef}
          className={`w-full ${getWidthClass()} flex flex-col h-full p-0 gap-0`}
          style={sheetWidth.customWidth ? { width: `${sheetWidth.customWidth}px`, maxWidth: `${sheetWidth.customWidth}px`, transition: 'none' } : undefined}
        >
          {/* Resize Handle (левый край) */}
          <div
            ref={resizeHandleRef}
            className="absolute left-0 top-0 bottom-0 w-1 cursor-col-resize hover:bg-primary/20 transition-colors z-[100]"
            onMouseDown={handleMouseDown}
            title={t('projects.sheet.width.drag_to_resize')}
            style={{ 
              pointerEvents: 'auto',
              touchAction: 'none',
            }}
          />

          <div className="p-4 border-b border-border">
            <div className="flex items-center justify-between">
              <SheetHeader className="flex-1">
                <SheetTitle className="text-xl font-semibold">
                  {project ? t('projects.edit_project') : t('projects.new_project')}
                </SheetTitle>
                <SheetDescription className="flex items-center gap-2">
                  <FolderKanban className="w-4 h-4" />
                  {t('task_sheet.description')}
                </SheetDescription>
              </SheetHeader>
            </div>

            <div className="flex items-center gap-2 mt-6">
              <Tabs value={activeTab} onValueChange={setActiveTab} className="w-full">
                <TabsList className="w-full justify-start">
                  {tabs.map(tab => {
                    if (!tab.visible) return null;
                    const Icon = tab.icon;
                    return (
                      <TabsTrigger key={tab.id} value={tab.id} className="gap-2">
                        <Icon className="w-3.5 h-3.5" />
                        {t(tab.label)}
                      </TabsTrigger>
                    );
                  })}
                </TabsList>
              </Tabs>

              <SheetTabSettings
                tabs={tabs}
                onToggle={toggleTab}
                onMove={moveTab}
              />
            </div>
          </div>

          <div className="flex-1 overflow-y-auto p-6">
            {activeTab === "general" && (
              <ProjectGeneralTab
                formData={formData}
                handleChange={handleInputChange}
                contractors={contractors}
                onCreateContractor={handleCreateContractor}
                references={references}
                allProjects={allProjects}
                currentProjectId={project?.id}
              />
            )}

            {activeTab === "tasks" && (
              <ProjectTasksTab
                tasks={projectTasks}
                onAddTask={handleCreateTask}
                onEditTask={handleEditTask}
                onToggleStatus={async (task) => {
                  const newStatus = task.status === "Done" ? "To Do" : "Done";

                  // Optimistic update
                  setProjectTasks(prev =>
                    prev.map(t => t.id === task.id ? { ...t, status: newStatus } : t)
                  );

                  // Sync with server
                  try {
                    await api.put(`/tasks/${task.id}`, { ...task, status: newStatus });
                  } catch (error) {

                    // Rollback on error
                    setProjectTasks(prev =>
                      prev.map(t => t.id === task.id ? { ...t, status: task.status } : t)
                    );
                  }
                }}
              />
            )}

            {activeTab === "stages" && project && (
              <ProjectStagesTab projectId={project.id} />
            )}

            {activeTab === "revenues" && project && (
              <ProjectRevenuesTab projectId={project.id} />
            )}

            {activeTab === "expenses" && project && (
              <ProjectExpensesTab projectId={project.id} />
            )}
          </div>

          <SheetFooter className="p-6 border-t border-border mt-auto bg-background">
            <div className="flex items-center justify-between w-full">
              {project ? (
                <Button
                  variant="ghost"
                  className="text-destructive hover:text-destructive hover:bg-destructive/10 gap-2"
                  onClick={handleDelete}
                >
                  <Trash2 className="w-4 h-4" />
                  {t('common.delete')}
                </Button>
              ) : <div />}
              <div className="flex gap-2">
                <Button variant="outline" onClick={() => onOpenChange(false)}>
                  {t('common.cancel')}
                </Button>
                <Button onClick={handleSave} className="gap-2">
                  <CheckCircle2 className="w-4 h-4" />
                  {t('common.save')}
                </Button>
              </div>
            </div>
          </SheetFooter>
        </SheetContent>
      </Sheet>

      <ContractorSheet
        open={contractorSheetOpen}
        onOpenChange={handleContractorSheetOpenChange}
        contractor={null}
        onSave={handleContractorSaved}
        initialName={pendingContractorName}
      />
    </>
  );
}

import { useState, useEffect } from 'react';
import { useTranslation } from '@/lib/i18n';
import { Button } from '@/components/ui/button';
import { Plus } from 'lucide-react';
import type { PaymentScheduleItem, CreatePaymentScheduleItemDTO, UpdatePaymentScheduleItemDTO } from '../../types';
import { usePaymentSchedule } from '../../hooks/usePaymentSchedule';
import { useDataTable } from '@/hooks/useDataTable';
import { format } from 'date-fns';

import { PaymentScheduleSummary } from './payments/PaymentScheduleSummary';
import { PaymentScheduleTable } from './payments/PaymentScheduleTable';
import { PaymentScheduleDialogs } from './payments/PaymentScheduleDialogs';

interface PaymentScheduleTabProps {
  projectId?: number;
}

export function PaymentScheduleTab({ projectId }: PaymentScheduleTabProps) {
  const { t } = useTranslation();

  const table = useDataTable<any>({
    initialData: [],
    initialColumns: {
      name: true,
      amount: true,
      paid: true,
      dueDate: true,
      status: true,
    },
    storageKey: `project-payments-table-${projectId}`,
  });
  const {
    payments,
    summary,
    isLoading,
    createPayment,
    updatePayment,
    deletePayment,
    markAsPaid,
    loadPayments,
    loadSummary,
  } = usePaymentSchedule({ projectId });

  const [isDialogOpen, setIsDialogOpen] = useState(false);
  const [editingPayment, setEditingPayment] = useState<PaymentScheduleItem | null>(null);
  const [isPaidDialogOpen, setIsPaidDialogOpen] = useState(false);
  const [paymentToMark, setPaymentToMark] = useState<PaymentScheduleItem | null>(null);

  const [formData, setFormData] = useState<CreatePaymentScheduleItemDTO>({
    name: '',
    description: '',
    amount: 0,
    currency: 'RUB',
    dueDate: format(new Date(), 'dd.MM.yyyy'),
    paymentMethod: 'bank',
  });

  const [paidData, setPaidData] = useState({
    paidAmount: 0,
    paymentDate: format(new Date(), 'dd.MM.yyyy'),
    paymentReference: '',
  });

  useEffect(() => {
    if (projectId) {
      loadPayments();
      loadSummary();
    }
  }, [projectId, loadPayments, loadSummary]);

  const handleOpenCreate = () => {
    setEditingPayment(null);
    setFormData({
      name: '',
      description: '',
      amount: 0,
      currency: 'RUB',
      dueDate: format(new Date(), 'dd.MM.yyyy'),
      paymentMethod: 'bank',
    });
    setIsDialogOpen(true);
  };

  const handleOpenEdit = (payment: PaymentScheduleItem) => {
    setEditingPayment(payment);
    setFormData({
      name: payment.name,
      description: payment.description || '',
      amount: payment.amount,
      currency: payment.currency,
      dueDate: payment.dueDate,
      paymentMethod: payment.paymentMethod,
    });
    setIsDialogOpen(true);
  };

  const handleOpenPaid = (payment: PaymentScheduleItem) => {
    setPaymentToMark(payment);
    setPaidData({
      paidAmount: payment.amount,
      paymentDate: format(new Date(), 'dd.MM.yyyy'),
      paymentReference: '',
    });
    setIsPaidDialogOpen(true);
  };

  const handleSave = async () => {
    if (!formData.name || !formData.amount || !formData.dueDate) return;

    if (editingPayment) {
      await updatePayment(editingPayment.id, formData as UpdatePaymentScheduleItemDTO);
    } else {
      await createPayment(formData);
    }
    setIsDialogOpen(false);
  };

  const handleDelete = async (payment: PaymentScheduleItem) => {
    if (confirm(t('projects.payments.confirm_delete', { name: payment.name }))) {
      await deletePayment(payment.id);
    }
  };

  const handleMarkAsPaid = async () => {
    if (!paymentToMark) return;
    await markAsPaid(paymentToMark.id, paidData);
    setIsPaidDialogOpen(false);
  };

  if (!projectId) {
    return (
      <div className="flex items-center justify-center h-48 text-muted-foreground">
        {t('projects.payments.no_project_selected')}
      </div>
    );
  }

  if (isLoading && payments.length === 0) {
    return (
      <div className="flex items-center justify-center h-48 text-muted-foreground">
        {t('common.loading')}
      </div>
    );
  }

  return (
    <div className="space-y-4">
      <PaymentScheduleSummary summary={summary} />

      <PaymentScheduleTable
        payments={payments}
        onOpenPaid={handleOpenPaid}
        onOpenEdit={handleOpenEdit}
        onDelete={handleDelete}
        columnWidths={table.columnWidths}
        onColumnResize={table.setColumnWidth}
      />

      <div className="flex justify-end">
        <Button onClick={handleOpenCreate} className="gap-2">
          <Plus className="w-4 h-4" />
          {t('projects.payments.add')}
        </Button>
      </div>

      <PaymentScheduleDialogs
        isDialogOpen={isDialogOpen}
        setIsDialogOpen={setIsDialogOpen}
        editingPayment={editingPayment}
        formData={formData}
        setFormData={setFormData}
        handleSave={handleSave}
        isPaidDialogOpen={isPaidDialogOpen}
        setIsPaidDialogOpen={setIsPaidDialogOpen}
        paidData={paidData}
        setPaidData={setPaidData}
        handleMarkAsPaid={handleMarkAsPaid}
      />
    </div>
  );
}

