import { useState, useEffect, useCallback } from 'react';
import { useTranslation } from '@/lib/i18n';
import { Button } from '@/components/ui/button';
import { Plus } from 'lucide-react';
import { useProjectStages } from '../../hooks/useProjectStages';
import { useProjectRevenues } from '../../hooks/useProjectRevenues';
import { useDataTable } from '@/hooks/useDataTable';
import { api } from '@/lib/api';
import { format } from 'date-fns';
import type { ProjectRevenue, CreateProjectRevenueDTO, UpdateProjectRevenueDTO } from '../../types';

import { ProjectRevenuesSummary } from './revenues/ProjectRevenuesSummary';
import { ProjectRevenuesTable } from './revenues/ProjectRevenuesTable';
import { ProjectRevenuesDialogs } from './revenues/ProjectRevenuesDialogs';

interface ProjectRevenuesTabProps {
  projectId?: number;
}

export function ProjectRevenuesTab({ projectId }: ProjectRevenuesTabProps) {
  const { t } = useTranslation();

  const table = useDataTable<any>({
    initialData: [],
    initialColumns: {
      invoice: true,
      stage: true,
      amount: true,
      vat: true,
      plannedDate: true,
      notes: true,
    },
    storageKey: `project-revenues-table-${projectId}`,
  });
  const {
    revenues,
    summary,
    isLoading,
    createRevenue,
    updateRevenue,
    deleteRevenue,
    markAsReceived,
    loadRevenues,
    loadSummary,
  } = useProjectRevenues({ projectId });

  const { stages, loadStages } = useProjectStages({ projectId });

  const [isDialogOpen, setIsDialogOpen] = useState(false);
  const [editingRevenue, setEditingRevenue] = useState<ProjectRevenue | null>(null);
  const [vatRateOptions, setVatRateOptions] = useState<number[]>([0, 5, 10, 20, 22]);
  const [defaultVatRate, setDefaultVatRate] = useState(22);

  const loadDefaultVatRate = useCallback(async () => {
    try {
      const defaultsRes = await api.get('/finance/settings/defaults');
      const defaultTaxRegimeId = defaultsRes.data?.defaultTaxRegimeId;

      if (defaultTaxRegimeId) {
        const regimeRes = await api.get(`/finance/settings/tax-regimes/${defaultTaxRegimeId}`);
        const regime = regimeRes.data;

        if (regime && regime.hasVat && regime.defaultVatRate) {
          setDefaultVatRate(regime.defaultVatRate);
        }
      }

      const ratesRes = await api.get('/finance/settings/tax-rates');
      const rates = ratesRes.data || [];
      const vatRates = rates
        .filter((r: any) => r.taxType === 'vat' && r.isActive)
        .map((r: any) => parseFloat(r.rate))
        .filter((rate: number, idx: number, arr: number[]) => arr.indexOf(rate) === idx)
        .sort((a: number, b: number) => a - b);

      if (!vatRates.includes(20)) {
        vatRates.unshift(20);
      }

      if (vatRates.length > 0) {
        setVatRateOptions(vatRates);
      }
    } catch (error) {
      setVatRateOptions([20, 22]);
    }
  }, []);

  useEffect(() => {
    if (projectId) {
      loadRevenues();
      loadSummary();
      loadStages();
      loadDefaultVatRate();
    }
  }, [projectId, loadRevenues, loadSummary, loadStages, loadDefaultVatRate]);

  const [formData, setFormData] = useState<CreateProjectRevenueDTO>({
    name: '',
    description: '',
    amount: 0,
    currency: 'RUB',
    vatRate: 22,
    plannedDate: format(new Date(), 'dd.MM.yyyy'),
    isTaxable: true,
  });

  const handleOpenCreate = () => {
    setEditingRevenue(null);
    setFormData({
      name: '',
      description: '',
      amount: 0,
      currency: 'RUB',
      vatRate: defaultVatRate,
      plannedDate: format(new Date(), 'dd.MM.yyyy'),
      isTaxable: true,
    });
    setIsDialogOpen(true);
  };

  const handleOpenEdit = (revenue: ProjectRevenue) => {
    setEditingRevenue(revenue);
    setFormData({
      name: revenue.name,
      description: revenue.description || '',
      amount: revenue.amount,
      currency: revenue.currency,
      vatRate: revenue.vatRate || defaultVatRate,
      plannedDate: revenue.plannedDate,
      isTaxable: revenue.isTaxable,
    });
    setIsDialogOpen(true);
  };

  const handleSave = async () => {
    if (!formData.name || !formData.amount || !formData.plannedDate) return;

    if (editingRevenue) {
      await updateRevenue(editingRevenue.id, formData as UpdateProjectRevenueDTO);
    } else {
      await createRevenue(formData);
    }

    setIsDialogOpen(false);
  };

  const handleDelete = async (revenue: ProjectRevenue) => {
    if (confirm(t('projects.revenues.confirm_delete', { name: revenue.name }))) {
      await deleteRevenue(revenue.id);
    }
  };

  const handleMarkAsReceived = async (revenue: ProjectRevenue) => {
    await markAsReceived(revenue.id, format(new Date(), 'dd.MM.yyyy'));
  };

  if (!projectId) {
    return (
      <div className="flex items-center justify-center h-48 text-muted-foreground">
        {t('projects.revenues.no_project_selected')}
      </div>
    );
  }

  if (isLoading && revenues.length === 0) {
    return (
      <div className="flex items-center justify-center h-48 text-muted-foreground">
        {t('common.loading')}
      </div>
    );
  }

  return (
    <div className="space-y-4">
      <ProjectRevenuesSummary summary={summary} />

      <ProjectRevenuesTable 
        revenues={revenues}
        stages={stages}
        onUpdateRevenue={updateRevenue}
        onMarkAsReceived={handleMarkAsReceived}
        onOpenEdit={handleOpenEdit}
        onDelete={handleDelete}
        columnWidths={table.columnWidths}
        onColumnResize={table.setColumnWidth}
      />

      <div className="flex justify-end">
        <Button onClick={handleOpenCreate} className="gap-2">
          <Plus className="w-4 h-4" />
          {t('projects.revenues.add')}
        </Button>
      </div>

      <ProjectRevenuesDialogs 
        isDialogOpen={isDialogOpen}
        setIsDialogOpen={setIsDialogOpen}
        editingRevenue={editingRevenue}
        formData={formData}
        setFormData={setFormData}
        handleSave={handleSave}
        vatRateOptions={vatRateOptions}
      />
    </div>
  );
}

import { useState, useEffect } from 'react';
import { useTranslation } from '@/lib/i18n';
import { Button } from '@/components/ui/button';
import { Plus } from 'lucide-react';
import { api } from '@/lib/api';
import { toast } from 'sonner';
import { format } from 'date-fns';
import type { ProjectStage, CreateProjectStageDTO, UpdateProjectStageDTO, ProjectTask } from '../../types';
import { useProjectStages } from '../../hooks/useProjectStages';
import { useDataTable } from '@/hooks/useDataTable';

import { ProjectStagesSummary } from './stages/ProjectStagesSummary';
import { ProjectStagesTable } from './stages/ProjectStagesTable';
import { ProjectStagesDialogs } from './stages/ProjectStagesDialogs';

interface ProjectStagesTabProps {
  projectId?: number;
}

export function ProjectStagesTab({ projectId }: ProjectStagesTabProps) {
  const { t } = useTranslation();

  const table = useDataTable<ProjectStage>({
    initialData: [],
    initialColumns: {
      name: true,
      dates: true,
      progress: true,
      budget: true,
      status: true,
    },
    storageKey: `project-stages-table-${projectId}`,
  });
  const {
    stages,
    summary,
    isLoading,
    createStage,
    updateStage,
    deleteStage,
    completeStage,
    reorderStage,
    loadStages,
    loadSummary,
  } = useProjectStages({ projectId });

  const [isDialogOpen, setIsDialogOpen] = useState(false);
  const [editingStage, setEditingStage] = useState<ProjectStage | null>(null);
  const [formData, setFormData] = useState<CreateProjectStageDTO & { isCompleted?: boolean; progress?: number }>({
    name: '',
    description: '',
    startDate: format(new Date(), 'dd.MM.yyyy'),
    endDate: format(new Date(), 'dd.MM.yyyy'),
    budget: 0,
    isCompleted: false,
    progress: 0,
  });

  const [expandedStageIds, setExpandedStageIds] = useState<Set<number>>(new Set());

  const toggleStageExpand = (stageId: number) => {
    const newExpanded = new Set(expandedStageIds);
    if (newExpanded.has(stageId)) {
      newExpanded.delete(stageId);
    } else {
      newExpanded.add(stageId);
    }
    setExpandedStageIds(newExpanded);
  };

  const [isTaskDialogOpen, setIsTaskDialogOpen] = useState(false);
  const [selectedStageId, setSelectedStageId] = useState<number | null>(null);
  const [editingTask, setEditingTask] = useState<ProjectTask | null>(null);
  const [taskFormData, setTaskFormData] = useState({
    title: '',
    priority: 'Medium',
    dueDate: format(new Date(), 'dd.MM.yyyy'),
    status: 'To Do',
    assignee: '',
  });
  const [isCreatingTask, setIsCreatingTask] = useState(false);

  useEffect(() => {
    const handleTaskUpdate = () => {
      if (projectId) {
        loadStages();
        loadSummary();
      }
    };
    window.addEventListener('task:updated', handleTaskUpdate);
    window.addEventListener('task:created', handleTaskUpdate);
    return () => {
      window.removeEventListener('task:updated', handleTaskUpdate);
      window.removeEventListener('task:created', handleTaskUpdate);
    };
  }, [projectId, loadStages, loadSummary]);

  const handleOpenAddTask = (stageId: number) => {
    setSelectedStageId(stageId);
    setEditingTask(null);
    setTaskFormData({
      title: '',
      priority: 'Medium',
      dueDate: format(new Date(), 'dd.MM.yyyy'),
      status: 'To Do',
      assignee: '',
    });
    setIsTaskDialogOpen(true);
  };

  const handleOpenEditTask = (task: ProjectTask) => {
    setEditingTask(task);
    setTaskFormData({
      title: task.title,
      priority: task.priority,
      dueDate: task.dueDate || format(new Date(), 'dd.MM.yyyy'),
      status: task.status,
      assignee: task.assignee || '',
    });
    setIsTaskDialogOpen(true);
  };

  const handleDeleteTask = async (task: ProjectTask) => {
    if (confirm(t('tasks.confirm.delete_task').replace('{0}', task.title))) {
      try {
        await api.delete(`/tasks/${task.id}`);
        toast.success(t('projects.stages.toast.task_deleted'));
        await loadStages();
        await loadSummary();
      } catch {
        toast.error(t('projects.stages.error.delete'));
      }
    }
  };

  const handleSaveTask = async () => {
    if (!taskFormData.title || !selectedStageId || !projectId) return;

    setIsCreatingTask(true);
    try {
      if (editingTask && editingTask.id) {
        await api.put(`/tasks/${editingTask.id}`, {
          title: taskFormData.title,
          priority: taskFormData.priority,
          dueDate: taskFormData.dueDate,
          status: taskFormData.status,
          assignee: taskFormData.assignee || undefined,
          projectId,
          stageId: selectedStageId,
        });
        toast.success(t('projects.stages.toast.task_updated'));
      } else {
        await api.post('/tasks', {
          title: taskFormData.title,
          priority: taskFormData.priority,
          dueDate: taskFormData.dueDate,
          projectId,
          stageId: selectedStageId,
          project: `project-${projectId}`,
          status: taskFormData.status,
          assignee: taskFormData.assignee || undefined,
        });
        toast.success(t('projects.stages.toast.task_created'));
      }
      setIsTaskDialogOpen(false);
      await loadStages();
      await loadSummary();
    } catch {
      toast.error(editingTask ? t('projects.stages.error.update') : t('projects.stages.error.create_task'));
    } finally {
      setIsCreatingTask(false);
    }
  };

  const handleOpenCreate = () => {
    setEditingStage(null);
    setFormData({
      name: '',
      description: '',
      startDate: format(new Date(), 'dd.MM.yyyy'),
      endDate: format(new Date(), 'dd.MM.yyyy'),
      plannedStartDate: '',
      plannedEndDate: '',
      budget: 0,
    });
    setIsDialogOpen(true);
  };

  const handleOpenEdit = (stage: ProjectStage) => {
    setEditingStage(stage);
    setFormData({
      name: stage.name,
      description: stage.description || '',
      startDate: stage.startDate,
      endDate: stage.endDate,
      plannedStartDate: stage.plannedStartDate || '',
      plannedEndDate: stage.plannedEndDate || '',
      budget: stage.budget || 0,
      isCompleted: stage.isCompleted,
      progress: stage.progress,
    });
    setIsDialogOpen(true);
  };

  const handleSaveStage = async () => {
    if (!formData.name || !formData.startDate || !formData.endDate) return;

    if (editingStage) {
      if (formData.isCompleted && !editingStage.isCompleted) {
        const stageWithTasks = stages.find(s => s.id === editingStage.id);
        const tasks = ((stageWithTasks as any)?.tasks || []) as ProjectTask[];
        const unfinishedTasks = tasks.filter(t => t.status !== 'Done');

        if (unfinishedTasks.length > 0) {
          toast.error(t('projects.stages.error.unfinished_tasks', { count: unfinishedTasks.length }));
          return;
        }
      }

      if (formData.isCompleted && !editingStage.isCompleted) {
        const currentStageIndex = stages.findIndex(s => s.id === editingStage.id);
        if (currentStageIndex > 0) {
          const prevStage = stages[currentStageIndex - 1];
          if (prevStage && !prevStage.isCompleted) {
            toast.error(t('projects.stages.error.prev_stage_not_completed', { name: prevStage.name }));
            return;
          }
        }
      }

      const updateData: UpdateProjectStageDTO = {
        name: formData.name,
        description: formData.description,
        startDate: formData.startDate,
        endDate: formData.endDate,
        plannedStartDate: formData.plannedStartDate,
        plannedEndDate: formData.plannedEndDate,
        budget: formData.budget,
        isCompleted: formData.isCompleted,
        progress: formData.isCompleted ? 100 : (editingStage.progress || 0),
      };
      const updated = await updateStage(editingStage.id, updateData);
      if (updated) await loadStages();
    } else {
      const created = await createStage(formData);
      if (created && created.id) await loadStages();
    }
    setIsDialogOpen(false);
  };

  const handleDelete = async (stage: ProjectStage) => {
    if (confirm(t('projects.stages.confirm_delete', { name: stage.name }))) {
      await deleteStage(stage.id);
    }
  };

  const handleComplete = async (stage: ProjectStage) => {
    const stageWithTasks = stages.find(s => s.id === stage.id);
    const tasks = ((stageWithTasks as any)?.tasks || []) as ProjectTask[];
    const unfinishedTasks = tasks.filter(t => t.status !== 'Done');

    if (unfinishedTasks.length > 0) {
      toast.error(t('projects.stages.error.unfinished_tasks', { count: unfinishedTasks.length }));
      return;
    }

    const currentStageIndex = stages.findIndex(s => s.id === stage.id);
    if (currentStageIndex > 0) {
      const prevStage = stages[currentStageIndex - 1];
      if (prevStage && !prevStage.isCompleted) {
        toast.error(t('projects.stages.error.prev_stage_not_completed', { name: prevStage.name }));
        return;
      }
    }
    await completeStage(stage.id, 100);
  };

  const handleMoveUp = async (stage: ProjectStage) => {
    const currentIndex = stages.findIndex(s => s.id === stage.id);
    if (currentIndex > 0) await reorderStage(stage.id, currentIndex - 1);
  };

  const handleMoveDown = async (stage: ProjectStage) => {
    const currentIndex = stages.findIndex(s => s.id === stage.id);
    if (currentIndex < stages.length - 1) await reorderStage(stage.id, currentIndex + 1);
  };

  if (!projectId) {
    return (
      <div className="flex items-center justify-center h-48 text-muted-foreground">
        {t('projects.stages.no_project_selected')}
      </div>
    );
  }

  if (isLoading && stages.length === 0) {
    return (
      <div className="flex items-center justify-center h-48 text-muted-foreground">
        {t('common.loading')}
      </div>
    );
  }

  return (
    <div className="space-y-4">
      <ProjectStagesSummary summary={summary} />

      <ProjectStagesTable 
        stages={stages}
        expandedStageIds={expandedStageIds}
        toggleStageExpand={toggleStageExpand}
        handleOpenAddTask={handleOpenAddTask}
        handleOpenEditTask={handleOpenEditTask}
        handleDeleteTask={handleDeleteTask}
        handleMoveUp={handleMoveUp}
        handleMoveDown={handleMoveDown}
        handleOpenEdit={handleOpenEdit}
        handleComplete={handleComplete}
        handleDelete={handleDelete}
        columnWidths={table.columnWidths}
        onColumnResize={table.setColumnWidth}
      />

      <div className="flex justify-end">
        <Button onClick={handleOpenCreate} className="gap-2">
          <Plus className="w-4 h-4" />
          {t('projects.stages.add')}
        </Button>
      </div>

      <ProjectStagesDialogs 
        isDialogOpen={isDialogOpen}
        setIsDialogOpen={setIsDialogOpen}
        editingStage={editingStage}
        formData={formData}
        setFormData={setFormData}
        handleSaveStage={handleSaveStage}
        isTaskDialogOpen={isTaskDialogOpen}
        setIsTaskDialogOpen={setIsTaskDialogOpen}
        editingTask={editingTask}
        taskFormData={taskFormData}
        setTaskFormData={setTaskFormData}
        handleSaveTask={handleSaveTask}
        isCreatingTask={isCreatingTask}
      />
    </div>
  );
}

import React, { useState } from 'react';
import { useTranslation } from '@/lib/i18n';
import { Button } from '@/components/ui/button';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
  TableFooter,
} from '@/components/ui/table';
import { SortableTableHead } from '@/components/shared/SortableTableHead';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu';
import { Badge } from '@/components/ui/badge';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { MoreVertical, Trash2, CheckCircle2, DollarSign, FileCheck, Save, X, Plus } from 'lucide-react';
import { DatePicker } from '@/components/ui/date-picker';
import { MoneyInput } from '@/components/ui/MoneyInput';
import { cn } from '@/lib/utils';
import { toast } from 'sonner';
import { format } from 'date-fns';
import { formatDate, formatMoney } from '../utils';
import type { ProjectExpense, ProjectStage, ExpenseCategory, ExpenseCategoryKey, UpdateProjectExpenseDTO, CreateProjectExpenseDTO } from '../../../types';

interface ProjectExpensesTableProps {
  expenses: ProjectExpense[];
  stages: ProjectStage[];
  categories: ExpenseCategory[];
  createExpense: (data: CreateProjectExpenseDTO) => Promise<any>;
  updateExpense: (id: number, data: UpdateProjectExpenseDTO) => Promise<any>;
  deleteExpense: (id: number) => Promise<boolean>;
  approveExpense: (id: number) => Promise<any>;
  markAsPaid: (id: number, paymentId?: number, actualDate?: string) => Promise<any>;
  columnWidths?: Record<string, number>;
  onColumnResize?: (key: string, width: number) => void;
}

type EditingField = 'name' | 'amount' | 'category' | 'plannedDate' | 'stageId' | null;

interface EditingRow {
  id: number;
  field: EditingField;
  value: any;
}

export const ProjectExpensesTable = ({
  expenses,
  stages,
  categories,
  createExpense,
  updateExpense,
  deleteExpense,
  approveExpense,
  markAsPaid,
  columnWidths,
  onColumnResize,
}: ProjectExpensesTableProps) => {
  const { t } = useTranslation();

  const [editingRow, setEditingRow] = useState<EditingRow | null>(null);
  const [newExpense, setNewExpense] = useState<Partial<ProjectExpense>>({
    name: '',
    amount: 0,
    category: 'materials',
    plannedDate: format(new Date(), 'dd.MM.yyyy'),
  });
  const [isAdding, setIsAdding] = useState(false);

  // Получение названия и цвета категории
  const getCategoryName = (category?: ExpenseCategoryKey | null) => {
    if (!category) return '—';
    const categoryObj = categories.find(c => c.id === category);
    return categoryObj?.name || category;
  };
  const getCategoryColor = (category?: ExpenseCategoryKey | null) => {
    if (!category) return 'transparent';
    const categoryObj = categories.find(c => c.id === category);
    return categoryObj?.color || 'transparent';
  };

  // Статус расхода
  const getStatusBadge = (expense: ProjectExpense) => {
    if (expense.isPaid) {
      return (
        <Badge variant="default" className="bg-green-600">
          {t('projects.expenses.status.paid')}
        </Badge>
      );
    }
    if (expense.isApproved) {
      return (
        <Badge variant="secondary" className="bg-blue-100 text-blue-800">
          {t('projects.expenses.status.approved')}
        </Badge>
      );
    }
    return (
      <Badge variant="outline">
        {t('projects.expenses.status.pending')}
      </Badge>
    );
  };

  // Редактирование
  const handleStartEdit = (expense: ProjectExpense, field: EditingField) => {
    setEditingRow({
      id: expense.id,
      field,
      value: expense[field as keyof ProjectExpense],
    });
  };

  const handleSaveEdit = async () => {
    if (!editingRow) return;
    const updateData: UpdateProjectExpenseDTO = {
      [editingRow.field!]: editingRow.value,
    };
    await updateExpense(editingRow.id, updateData);
    setEditingRow(null);
  };

  const handleCancelEdit = () => {
    setEditingRow(null);
  };

  // Добавление
  const handleAddExpense = async () => {
    if (!newExpense.name || !newExpense.amount) {
      toast.error(t('projects.expenses.error.required_fields'));
      return;
    }
    await createExpense({
      name: newExpense.name!,
      amount: newExpense.amount!,
      category: newExpense.category || 'materials',
      plannedDate: newExpense.plannedDate!,
    });
    setNewExpense({
      name: '',
      amount: 0,
      category: 'materials',
      plannedDate: format(new Date(), 'dd.MM.yyyy'),
    });
    setIsAdding(false);
  };

  return (
    <>
      <div className="border rounded-lg overflow-hidden">
        <Table>
          <TableHeader>
            <TableRow>
              <TableHead className="w-[60px]">№</TableHead>
              <SortableTableHead
                label={t('projects.stages.field.name')}
                width={columnWidths?.name}
                onResize={(w) => onColumnResize?.('name', w)}
                className="w-[120px]"
                onSort={() => {}}
                direction={null}
              />
              <SortableTableHead
                label={t('projects.expenses.table.category')}
                width={columnWidths?.category}
                onResize={(w) => onColumnResize?.('category', w)}
                className="w-[180px]"
                onSort={() => {}}
                direction={null}
              />
              <SortableTableHead
                label={t('projects.expenses.table.amount')}
                width={columnWidths?.amount}
                onResize={(w) => onColumnResize?.('amount', w)}
                className="w-[140px]"
                onSort={() => {}}
                direction={null}
              />
              <SortableTableHead
                label={t('projects.expenses.field.planned_date')}
                width={columnWidths?.plannedDate}
                onResize={(w) => onColumnResize?.('plannedDate', w)}
                className="w-[150px]"
                onSort={() => {}}
                direction={null}
              />
              <SortableTableHead
                label={t('projects.expenses.table.status')}
                width={columnWidths?.status}
                onResize={(w) => onColumnResize?.('status', w)}
                className="w-[120px]"
                onSort={() => {}}
                direction={null}
              />
              <TableHead className="w-[100px] text-right">{t('common.actions')}</TableHead>
            </TableRow>
          </TableHeader>
          <TableBody>
            {isAdding && (
              <TableRow key="new-expense" className="bg-muted/50">
                <TableCell className="py-2 font-medium">{expenses.length + 1}</TableCell>
                <TableCell>
                  <Select
                    value={newExpense.stageId?.toString() || ''}
                    onValueChange={(v) => setNewExpense({ ...newExpense, stageId: v ? parseInt(v) : undefined })}
                  >
                    <SelectTrigger>
                      <SelectValue placeholder={t('common.not_selected')} />
                    </SelectTrigger>
                    <SelectContent>
                      {stages.map(s => (
                        <SelectItem key={s.id} value={s.id.toString()}>{s.name}</SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </TableCell>
                <TableCell>
                  <Select
                    value={newExpense.category}
                    onValueChange={(v) => setNewExpense({ ...newExpense, category: v as ExpenseCategoryKey })}
                  >
                    <SelectTrigger><SelectValue /></SelectTrigger>
                    <SelectContent>
                      {categories.map((cat) => (
                        <SelectItem key={cat.id} value={cat.id}>{cat.name}</SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </TableCell>
                <TableCell>
                  <MoneyInput
                    value={newExpense.amount || 0}
                    onValueChange={(v) => setNewExpense({ ...newExpense, amount: v })}
                  />
                </TableCell>
                <TableCell>
                  <DatePicker
                    value={newExpense.plannedDate || format(new Date(), 'dd.MM.yyyy')}
                    onChange={(v) => setNewExpense({ ...newExpense, plannedDate: v })}
                  />
                </TableCell>
                <TableCell>
                  <div className="flex gap-1">
                    <Button size="sm" onClick={handleAddExpense}>
                      <CheckCircle2 className="w-4 h-4" />
                    </Button>
                    <Button size="sm" variant="ghost" onClick={() => setIsAdding(false)}>
                      <X className="w-4 h-4" />
                    </Button>
                  </div>
                </TableCell>
              </TableRow>
            )}

            {expenses.length === 0 && !isAdding ? (
              <TableRow>
                <TableCell colSpan={7} className="h-24 text-center text-muted-foreground">
                  {t('projects.expenses.empty')}
                </TableCell>
              </TableRow>
            ) : (
              expenses.map((expense, index) => {
                const isEditing = editingRow?.id === expense.id;
                const editingField = isEditing ? editingRow.field : null;

                return (
                  <TableRow
                    key={expense.id}
                    className={cn(
                      expense.isPaid && 'bg-green-50',
                      expense.isApproved && !expense.isPaid && 'bg-blue-50'
                    )}
                  >
                    <TableCell className="py-2 font-medium">{index + 1}</TableCell>

                    <TableCell className="py-2">
                      {isEditing && editingField === 'stageId' ? (
                        <div className="flex items-center gap-2">
                          <Select
                            value={editingRow.value?.toString() || ''}
                            onValueChange={(v) => setEditingRow({ ...editingRow, value: v ? parseInt(v) : undefined })}
                          >
                            <SelectTrigger>
                              <SelectValue placeholder={t('common.not_selected')} />
                            </SelectTrigger>
                            <SelectContent>
                              {stages.map(s => (
                                <SelectItem key={s.id} value={s.id.toString()}>{s.name}</SelectItem>
                              ))}
                            </SelectContent>
                          </Select>
                          <Button size="icon" variant="ghost" onClick={handleSaveEdit}><Save className="w-4 h-4" /></Button>
                          <Button size="icon" variant="ghost" onClick={handleCancelEdit}><X className="w-4 h-4" /></Button>
                        </div>
                      ) : (
                        <Select
                          value={expense.stageId?.toString() || ''}
                          onValueChange={(v) => updateExpense(expense.id, { stageId: v ? parseInt(v) : undefined })}
                        >
                          <SelectTrigger className="w-[150px]">
                            <SelectValue placeholder={t('common.not_selected')} />
                          </SelectTrigger>
                          <SelectContent>
                            {stages.map(s => (
                              <SelectItem key={s.id} value={s.id.toString()}>{s.name}</SelectItem>
                            ))}
                          </SelectContent>
                        </Select>
                      )}
                    </TableCell>

                    <TableCell className="py-2">
                      {isEditing && editingField === 'category' ? (
                        <div className="flex items-center gap-2">
                          <Select
                            value={editingRow.value}
                            onValueChange={(v) => setEditingRow({ ...editingRow, value: v })}
                          >
                            <SelectTrigger><SelectValue /></SelectTrigger>
                            <SelectContent>
                              {categories.map((cat) => (
                                <SelectItem key={cat.id} value={cat.id}>{cat.name}</SelectItem>
                              ))}
                            </SelectContent>
                          </Select>
                          <Button size="icon" variant="ghost" onClick={handleSaveEdit}><Save className="w-4 h-4" /></Button>
                          <Button size="icon" variant="ghost" onClick={handleCancelEdit}><X className="w-4 h-4" /></Button>
                        </div>
                      ) : (
                        <div 
                          className="cursor-pointer hover:bg-muted/50 p-1 rounded flex items-center gap-2"
                          onClick={() => handleStartEdit(expense, 'category')}
                        >
                          <div className="w-3 h-3 rounded" style={{ backgroundColor: getCategoryColor(expense.category) }} />
                          {getCategoryName(expense.category)}
                        </div>
                      )}
                    </TableCell>

                    <TableCell className="py-2">
                      {isEditing && editingField === 'amount' ? (
                        <div className="flex items-center gap-2">
                          <MoneyInput
                            value={editingRow.value}
                            onValueChange={(v) => setEditingRow({ ...editingRow, value: v })}
                          />
                          <Button size="icon" variant="ghost" onClick={handleSaveEdit}><Save className="w-4 h-4" /></Button>
                          <Button size="icon" variant="ghost" onClick={handleCancelEdit}><X className="w-4 h-4" /></Button>
                        </div>
                      ) : (
                        <div 
                          className="cursor-pointer hover:bg-muted/50 p-1 rounded font-medium"
                          onClick={() => handleStartEdit(expense, 'amount')}
                        >
                          {formatMoney(expense.amount)}
                        </div>
                      )}
                    </TableCell>

                    <TableCell className="py-2">
                      {isEditing && editingField === 'plannedDate' ? (
                        <div className="flex items-center gap-2">
                          <DatePicker
                            value={editingRow.value}
                            onChange={(v) => setEditingRow({ ...editingRow, value: v })}
                          />
                          <Button size="icon" variant="ghost" onClick={handleSaveEdit}><Save className="w-4 h-4" /></Button>
                          <Button size="icon" variant="ghost" onClick={handleCancelEdit}><X className="w-4 h-4" /></Button>
                        </div>
                      ) : (
                        <div 
                          className="cursor-pointer hover:bg-muted/50 p-1 rounded"
                          onClick={() => handleStartEdit(expense, 'plannedDate')}
                        >
                          {formatDate(expense.plannedDate)}
                          {expense.actualDate && (
                            <p className="text-xs text-green-600 mt-1">
                              {t('projects.expenses.actual_on')}: {formatDate(expense.actualDate)}
                            </p>
                          )}
                        </div>
                      )}
                    </TableCell>

                    <TableCell className="py-2">
                      {getStatusBadge(expense)}
                    </TableCell>

                    <TableCell className="py-2">
                      <div className="flex items-center justify-end gap-1">
                        <DropdownMenu>
                          <DropdownMenuTrigger asChild>
                            <Button variant="ghost" size="icon">
                              <MoreVertical className="w-4 h-4" />
                            </Button>
                          </DropdownMenuTrigger>
                          <DropdownMenuContent align="end">
                            {!expense.isApproved && (
                              <DropdownMenuItem onClick={() => approveExpense(expense.id)}>
                                <FileCheck className="w-4 h-4 mr-2" />
                                {t('projects.expenses.actions.approve')}
                              </DropdownMenuItem>
                            )}
                            {!expense.isPaid && expense.isApproved && (
                              <DropdownMenuItem onClick={() => markAsPaid(expense.id)}>
                                <DollarSign className="w-4 h-4 mr-2" />
                                {t('projects.expenses.actions.mark_paid')}
                              </DropdownMenuItem>
                            )}
                            <DropdownMenuSeparator />
                            <DropdownMenuItem 
                              onClick={() => deleteExpense(expense.id)}
                              className="text-destructive"
                            >
                              <Trash2 className="w-4 h-4 mr-2" />
                              {t('projects.expenses.actions.delete')}
                            </DropdownMenuItem>
                          </DropdownMenuContent>
                        </DropdownMenu>
                      </div>
                    </TableCell>
                  </TableRow>
                );
              })
            )}
          </TableBody>
          <TableFooter>
            <TableRow className="font-semibold bg-muted/50">
              <TableCell colSpan={3}>ИТОГО:</TableCell>
              <TableCell>{formatMoney(expenses.reduce((sum, e) => sum + (parseFloat(String(e.amount)) || 0), 0))}</TableCell>
              <TableCell colSpan={3}></TableCell>
            </TableRow>
          </TableFooter>
        </Table>
      </div>

      <div className="flex justify-end mt-4">
        <Button onClick={() => setIsAdding(true)} className="gap-2" disabled={isAdding}>
          <Plus className="w-4 h-4" />
          {t('projects.expenses.add')}
        </Button>
      </div>
    </>
  );
};

