import React from 'react';
import { useTranslation } from '@/lib/i18n';
import { Button } from '@/components/ui/button';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
  TableFooter,
} from '@/components/ui/table';
import { SortableTableHead } from '@/components/shared/SortableTableHead';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { MoreVertical, Edit, Trash2, CheckCircle2 } from 'lucide-react';
import { cn } from '@/lib/utils';
import { formatDate, formatMoney } from '../utils';
import type { ProjectRevenue, ProjectStage } from '../../../types';

interface ProjectRevenuesTableProps {
  revenues: ProjectRevenue[];
  stages: ProjectStage[];
  onUpdateRevenue: (id: number, data: any) => void;
  onMarkAsReceived: (revenue: ProjectRevenue) => void;
  onOpenEdit: (revenue: ProjectRevenue) => void;
  onDelete: (revenue: ProjectRevenue) => void;
  columnWidths?: Record<string, number>;
  onColumnResize?: (key: string, width: number) => void;
}

export const ProjectRevenuesTable = ({
  revenues,
  stages,
  onUpdateRevenue,
  onMarkAsReceived,
  onOpenEdit,
  onDelete,
  columnWidths,
  onColumnResize,
}: ProjectRevenuesTableProps) => {
  const { t } = useTranslation();

  const getPaymentDelay = (plannedDate?: string, actualDate?: string) => {
    if (!plannedDate || !actualDate) return null;
    try {
      const [dayP, monthP, yearP] = plannedDate.split('.');
      const planned = new Date(parseInt(yearP), parseInt(monthP) - 1, parseInt(dayP));
      const [dayA, monthA, yearA] = actualDate.split('.');
      const actual = new Date(parseInt(yearA), parseInt(monthA) - 1, parseInt(dayA));
      const diffTime = actual.getTime() - planned.getTime();
      const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
      return diffDays > 0 ? diffDays : null;
    } catch {
      return null;
    }
  };

  return (
    <div className="border rounded-lg overflow-hidden">
      <div className="max-h-[calc(100vh-300px)] overflow-y-auto">
        <Table>
          <TableHeader>
            <TableRow>
              <TableHead className="w-[60px]">№</TableHead>
              <SortableTableHead
                label={t('projects.revenues.table.invoice_name')}
                width={columnWidths?.invoice}
                onResize={(w) => onColumnResize?.('invoice', w)}
                className="min-w-[180px]"
                onSort={() => {}}
                direction={null}
              />
              <SortableTableHead
                label={t('projects.stages.field.name')}
                width={columnWidths?.stage}
                onResize={(w) => onColumnResize?.('stage', w)}
                className="w-[120px]"
                onSort={() => {}}
                direction={null}
              />
              <SortableTableHead
                label={t('projects.revenues.table.amount')}
                width={columnWidths?.amount}
                onResize={(w) => onColumnResize?.('amount', w)}
                className="w-[140px]"
                onSort={() => {}}
                direction={null}
              />
              <SortableTableHead
                label={t('projects.revenues.field.vat_rate')}
                width={columnWidths?.vat}
                onResize={(w) => onColumnResize?.('vat', w)}
                className="w-[100px]"
                onSort={() => {}}
                direction={null}
              />
              <SortableTableHead
                label={t('projects.revenues.field.planned_date')}
                width={columnWidths?.plannedDate}
                onResize={(w) => onColumnResize?.('plannedDate', w)}
                className="w-[140px]"
                onSort={() => {}}
                direction={null}
              />
              <SortableTableHead
                label={t('projects.revenues.table.notes')}
                width={columnWidths?.notes}
                onResize={(w) => onColumnResize?.('notes', w)}
                className="min-w-[150px]"
                onSort={() => {}}
                direction={null}
              />
              <TableHead className="w-[80px] text-right">{t('common.actions')}</TableHead>
            </TableRow>
          </TableHeader>
          <TableBody>
            {revenues.length === 0 ? (
              <TableRow>
                <TableCell colSpan={8} className="h-24 text-center text-muted-foreground">
                  {t('projects.revenues.empty')}
                </TableCell>
              </TableRow>
            ) : (
              revenues.filter((revenue): revenue is typeof revenue => revenue && revenue.id !== undefined).map((revenue, index) => {
                const paymentDelay = getPaymentDelay(revenue?.plannedDate, revenue?.actualDate);
                const isOverdue = revenue.status === 'overdue';

                return (
                  <TableRow
                    key={revenue.id}
                    className={cn(
                      isOverdue && 'bg-red-50',
                      revenue.status === 'received' && 'bg-green-50'
                    )}
                  >
                    <TableCell className="py-2 font-medium">{index + 1}</TableCell>

                    <TableCell className="py-2" style={{ width: columnWidths?.invoice }}>
                      <div className="font-medium">
                        {revenue.name.startsWith('inv-') ? `Счёт ${revenue.name}` : `Счёт #${revenue.name}`}
                      </div>
                    </TableCell>

                    <TableCell className="py-2" style={{ width: columnWidths?.stage }}>
                      <Select
                        value={revenue.stageId?.toString() || ''}
                        onValueChange={(v) => {
                          onUpdateRevenue(revenue.id, { stageId: v ? parseInt(v) : undefined });
                        }}
                      >
                        <SelectTrigger className="w-[150px]">
                          <SelectValue placeholder={t('common.not_selected')} />
                        </SelectTrigger>
                        <SelectContent>
                          {stages.map(s => (
                            <SelectItem key={s.id} value={s.id.toString()}>
                              {s.name}
                            </SelectItem>
                          ))}
                        </SelectContent>
                      </Select>
                    </TableCell>

                    <TableCell className="py-2 font-medium" style={{ width: columnWidths?.amount }}>
                      {formatMoney(revenue.amount)}
                    </TableCell>

                    <TableCell className="py-2" style={{ width: columnWidths?.vat }}>
                      {revenue.isTaxable && revenue.vatRate ? (
                        <span className="font-medium">{revenue.vatRate}%</span>
                      ) : (
                        <span className="text-muted-foreground">Без НДС</span>
                      )}
                    </TableCell>

                    <TableCell className="py-2" style={{ width: columnWidths?.plannedDate }}>
                      <div className={cn(
                        isOverdue && 'text-red-600 font-medium',
                        revenue.status === 'received' && 'text-green-600'
                      )}>
                        {revenue.plannedDate ? formatDate(revenue.plannedDate, false) : '—'}
                      </div>
                    </TableCell>

                    <TableCell className="py-2" style={{ width: columnWidths?.notes }}>
                      {revenue.actualDate ? (
                        <div>
                          <p className="text-sm text-green-700">
                            {t('projects.revenues.tooltip.paid_on', { date: formatDate(revenue.actualDate, false) })}
                          </p>
                          {paymentDelay && (
                            <p className="text-xs text-red-600 mt-1">
                              {t('projects.revenues.tooltip.overdue_by_days', { days: paymentDelay })}
                            </p>
                          )}
                        </div>
                      ) : revenue.status === 'received' ? (
                        <p className="text-sm text-green-700 font-medium">
                          {t('projects.revenues.tooltip.received')}
                        </p>
                      ) : isOverdue ? (
                        <p className="text-sm text-red-600 font-medium">
                          {t('projects.revenues.tooltip.expired')}
                        </p>
                      ) : revenue.status === 'invoiced' ? (
                        <p className="text-sm text-blue-700">
                          {t('projects.revenues.tooltip.invoiced')}
                        </p>
                      ) : (
                        <p className="text-sm text-muted-foreground">
                          {t('projects.revenues.tooltip.expected')}
                        </p>
                      )}
                    </TableCell>

                    <TableCell className="py-2">
                      <div className="flex items-center justify-end gap-1">
                        <DropdownMenu>
                          <DropdownMenuTrigger asChild>
                            <Button variant="ghost" size="icon">
                              <MoreVertical className="w-4 h-4" />
                            </Button>
                          </DropdownMenuTrigger>
                          <DropdownMenuContent align="end">
                            {revenue.status !== 'received' && revenue.status !== 'cancelled' && (
                              <DropdownMenuItem onClick={() => onMarkAsReceived(revenue)}>
                                <CheckCircle2 className="w-4 h-4 mr-2" />
                                {t('projects.revenues.actions.mark_received')}
                              </DropdownMenuItem>
                            )}
                            <DropdownMenuSeparator />
                            <DropdownMenuItem onClick={() => onOpenEdit(revenue)}>
                              <Edit className="w-4 h-4 mr-2" />
                              {t('common.edit')}
                            </DropdownMenuItem>
                            <DropdownMenuSeparator />
                            <DropdownMenuItem
                              onClick={() => onDelete(revenue)}
                              className="text-destructive"
                            >
                              <Trash2 className="w-4 h-4 mr-2" />
                              {t('common.delete')}
                            </DropdownMenuItem>
                          </DropdownMenuContent>
                        </DropdownMenu>
                      </div>
                    </TableCell>
                  </TableRow>
                );
              })
            )}
          </TableBody>
          <TableFooter>
            <TableRow className="font-semibold bg-muted/50">
              <TableCell colSpan={3}>ИТОГО:</TableCell>
              <TableCell>{formatMoney(revenues.reduce((sum, r) => sum + (parseFloat(String(r.amount)) || 0), 0))}</TableCell>
              <TableCell>{formatMoney(revenues.reduce((sum, r) => sum + (parseFloat(String(r.vatAmount)) || 0), 0))}</TableCell>
              <TableCell colSpan={3}></TableCell>
            </TableRow>
          </TableFooter>
        </Table>
      </div>
    </div>
  );
};

