            </DialogTitle>
            <DialogDescription>
              {t('projects.stages.description')}
            </DialogDescription>
          </DialogHeader>

          <div className="grid gap-4">
            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-2">
                <Label>{t('projects.stages.field.name')} *</Label>
