                          </Badge>
                        ) : stage.progress > 0 ? (
                          <Badge variant="secondary" className="bg-blue-100 text-blue-800">
                            {t('projects.stages.status.in_progress')}
                          </Badge>
                        ) : (
                          <Badge variant="outline">
                            {t('projects.stages.status.pending')}
                          </Badge>
                        )}
                      </div>
                    </TableCell>

                    <TableCell className="py-2">
                      <div className="flex items-center justify-end gap-1">
                        <DropdownMenu>
                          <DropdownMenuTrigger asChild>
                            <Button variant="ghost" size="icon">
                              <MoreVertical className="w-4 h-4" />
                            </Button>
                          </DropdownMenuTrigger>
                          <DropdownMenuContent align="end">
                            <DropdownMenuItem onClick={() => handleMoveUp(stage)} disabled={index === 0}>
                              {t('projects.stages.actions.move_up')}
                            </DropdownMenuItem>
                            <DropdownMenuItem onClick={() => handleMoveDown(stage)} disabled={index === stages.length - 1}>
                              {t('projects.stages.actions.move_down')}
                            </DropdownMenuItem>
                            <DropdownMenuSeparator />
                            <DropdownMenuItem onClick={() => handleOpenEdit(stage)}>
                              <Edit className="w-4 h-4 mr-2" />
                              {t('common.edit')}
                            </DropdownMenuItem>
                            {!stage.isCompleted && (
                              <DropdownMenuItem onClick={() => handleComplete(stage)}>
                                <CheckCircle2 className="w-4 h-4 mr-2" />
                                {t('projects.stages.actions.complete')}
                              </DropdownMenuItem>
                            )}
                            <DropdownMenuSeparator />
                            <DropdownMenuItem 
                              onClick={() => handleDelete(stage)}
                              className="text-destructive"
                            >
                              <Trash2 className="w-4 h-4 mr-2" />
                              {t('common.delete')}
                            </DropdownMenuItem>
                          </DropdownMenuContent>
                        </DropdownMenu>
                      </div>
                    </TableCell>
                  </TableRow>

                  {isExpanded && (
                    <TableRow className="bg-muted/20">
                      <TableCell colSpan={7} className="p-0">
                        <div className="p-4 border-t">
                          <div className="flex items-center justify-between mb-3">
                            <div className="flex items-center gap-2">
                              <CheckSquare className="w-4 h-4 text-muted-foreground" />
                              <h4 className="text-sm font-medium">{t('projects.stages.tasks')}</h4>
                              <Badge variant="secondary">{tasks.length}</Badge>
                            </div>
                            <Button size="sm" variant="outline" className="h-8" onClick={() => handleOpenAddTask(stage.id)}>
                              <Plus className="w-3 h-3 mr-1" />
                              {t('projects.stages.add_task')}
                            </Button>
                          </div>

                          {tasks.length === 0 ? (
                            <p className="text-sm text-muted-foreground text-center py-4">
                              {t('projects.stages.no_tasks')}
                            </p>
                          ) : (
                            <div className="space-y-2">
                              {tasks.filter((task: ProjectTask) => task && task.id).map((task: ProjectTask) => (
                                <div
                                  key={task.id}
                                  className="flex items-center justify-between p-2 bg-background rounded border hover:bg-muted/50 transition-colors"
                                >
                                  <div className="flex items-center gap-3 flex-1">
                                    {getPriorityIcon(task.priority)}
                                    <span className="text-sm font-medium">{task.title}</span>
                                    {task.assignee && (
                                      <div className="flex items-center gap-1 text-xs text-muted-foreground">
                                        <Users className="w-3 h-3" />
                                        {task.assignee}
                                      </div>
                                    )}
                                  </div>
                                  <div className="flex items-center gap-2">
                                    {task.dueDate && (
                                      <span className="text-xs text-muted-foreground">
                                        {formatDate(task.dueDate)}
                                      </span>
                                    )}
                                    {getTaskStatusBadge(task)}
                                    <DropdownMenu>
                                      <DropdownMenuTrigger asChild>
                                        <Button variant="ghost" size="icon" className="h-6 w-6">
                                          <MoreVertical className="w-3 h-3" />
                                        </Button>
                                      </DropdownMenuTrigger>
                                      <DropdownMenuContent align="end">
                                        <DropdownMenuItem onClick={() => handleOpenEditTask(task)}>
                                          <Edit className="w-3 h-3 mr-2" />
                                          {t('common.edit')}
                                        </DropdownMenuItem>
                                        <DropdownMenuItem
                                          onClick={() => handleDeleteTask(task)}
                                          className="text-destructive"
                                        >
                                          <Trash2 className="w-3 h-3 mr-2" />
                                          {t('common.delete')}
                                        </DropdownMenuItem>
                                      </DropdownMenuContent>
                                    </DropdownMenu>
                                  </div>
                                </div>
                              ))}
                            </div>
                          )}
                        </div>
                      </TableCell>
                    </TableRow>
                  )}
                </Fragment>
              );
            })
          )}
        </TableBody>
      </Table>
    </div>
  );
};

