// frontend/src/modules/projects/hooks/useProjectExpenses.ts
import { useState, useEffect, useCallback } from 'react';
import { toast } from 'sonner';
import { useTranslation } from '@/lib/i18n';
import { api } from '@/lib/api';
import { projectsApi } from '../api';
import type {
  ProjectExpense,
  CreateProjectExpenseDTO,
  UpdateProjectExpenseDTO,
  ProjectExpensesSummary,
  ExpenseCategory,
} from '../types';

interface UseProjectExpensesOptions {
  projectId?: number;
  enabled?: boolean;
}

interface UseProjectExpensesReturn {
  // Данные
  expenses: ProjectExpense[];
  categories: ExpenseCategory[];
  summary: ProjectExpensesSummary | null;
  isLoading: boolean;
  isError: boolean;

  // CRUD операции
  loadExpenses: () => Promise<void>;
  loadCategories: () => Promise<void>;
  loadSummary: () => Promise<void>;
  createExpense: (data: CreateProjectExpenseDTO) => Promise<ProjectExpense | null>;
  updateExpense: (expenseId: number, data: UpdateProjectExpenseDTO) => Promise<ProjectExpense | null>;
  deleteExpense: (expenseId: number) => Promise<boolean>;
  approveExpense: (expenseId: number) => Promise<ProjectExpense | null>;
  markAsPaid: (expenseId: number, paymentId?: number, actualDate?: string) => Promise<ProjectExpense | null>;

  // Состояния
  refresh: () => void;
}

/**
 * Хук для управления расходами проекта
 */
export function useProjectExpenses(options: UseProjectExpensesOptions = {}): UseProjectExpensesReturn {
  const { projectId, enabled = true } = options;
  const { t } = useTranslation();

  const [expenses, setExpenses] = useState<ProjectExpense[]>([]);
  const [categories, setCategories] = useState<ExpenseCategory[]>([]);
  const [summary, setSummary] = useState<ProjectExpensesSummary | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [isError, setIsError] = useState(false);
  const [refreshKey, setRefreshKey] = useState(0);

  /**
   * Загрузить категории расходов из Finance
   */
  const loadCategories = useCallback(async () => {
    try {
      const response = await api.get('/finance/categories?kind=expense');
      setCategories(response.data || []);
    } catch (error) {
      console.error('Failed to load expense categories:', error);
    }
  }, []);

  /**
   * Загрузить все расходы
   */
  const loadExpenses = useCallback(async () => {
    if (!projectId) return;

    setIsLoading(true);
    setIsError(false);

    try {
      const response = await projectsApi.getProjectExpenses(projectId);
      setExpenses(response || []);
    } catch (error) {
      console.error('Failed to load project expenses:', error);
      setIsError(true);
      toast.error(t('projects.expenses.error.load'));
      setExpenses([]);
    } finally {
      setIsLoading(false);
    }
  }, [projectId, t]);

  /**
   * Загрузить сводку
   */
  const loadSummary = useCallback(async () => {
    if (!projectId) return;

    try {
      const response = await projectsApi.getProjectExpensesSummary(projectId);
      setSummary(response || null);
    } catch (error) {
      console.error('Failed to load expenses summary:', error);
    }
  }, [projectId]);

  /**
   * Создать расход
   */
  const createExpense = useCallback(async (
    data: CreateProjectExpenseDTO
  ): Promise<ProjectExpense | null> => {
    if (!projectId) {
      toast.error(t('projects.expenses.error.no_project'));
      return null;
    }

    try {
      const response = await projectsApi.createExpense(projectId, data);
      const newExpense = response.data;

      setExpenses(prev => [...prev, newExpense]);
      loadSummary();

      toast.success(t('projects.expenses.toast.created'));
      return newExpense;
    } catch (error) {
      console.error('Failed to create expense:', error);
      toast.error(t('projects.expenses.error.create'));
      return null;
    }
  }, [projectId, t, loadSummary]);

  /**
   * Обновить расход
   */
  const updateExpense = useCallback(async (
    expenseId: number,
    data: UpdateProjectExpenseDTO
  ): Promise<ProjectExpense | null> => {
    if (!projectId) return null;

    try {
      const response = await projectsApi.updateExpense(projectId, expenseId, data);
      const updatedExpense = response.data;

      setExpenses(prev => prev.map(e => e.id === expenseId ? updatedExpense : e));
      loadSummary();

      toast.success(t('projects.expenses.toast.updated'));
      return updatedExpense;
    } catch (error) {
      console.error('Failed to update expense:', error);
      toast.error(t('projects.expenses.error.update'));
      return null;
    }
  }, [projectId, t, loadSummary]);

  /**
   * Удалить расход
   */
  const deleteExpense = useCallback(async (expenseId: number): Promise<boolean> => {
    if (!projectId) return false;

    try {
      await projectsApi.deleteExpense(projectId, expenseId);
      setExpenses(prev => prev.filter(e => e.id !== expenseId));
      loadSummary();

      toast.success(t('projects.expenses.toast.deleted'));
      return true;
    } catch (error) {
      console.error('Failed to delete expense:', error);
      toast.error(t('projects.expenses.error.delete'));
      return false;
    }
  }, [projectId, t, loadSummary]);

  /**
   * Утвердить расход
   */
  const approveExpense = useCallback(async (
    expenseId: number
  ): Promise<ProjectExpense | null> => {
    if (!projectId) return null;

    try {
      const response = await projectsApi.approveExpense(projectId, expenseId);
      const approvedExpense = response.data;

      setExpenses(prev => prev.map(e => e.id === expenseId ? approvedExpense : e));
      loadSummary();

      toast.success(t('projects.expenses.toast.approved'));
      return approvedExpense;
    } catch (error) {
      console.error('Failed to approve expense:', error);
      toast.error(t('projects.expenses.error.approve'));
      return null;
    }
  }, [projectId, t, loadSummary]);

  /**
   * Отметить расход как оплаченный
   */
  const markAsPaid = useCallback(async (
    expenseId: number,
    paymentId?: number,
    actualDate?: string
  ): Promise<ProjectExpense | null> => {
    if (!projectId) return null;

    try {
      const response = await projectsApi.markExpensePaid(projectId, expenseId, paymentId, actualDate);
      const paidExpense = response.data;

      setExpenses(prev => prev.map(e => e.id === expenseId ? paidExpense : e));
      loadSummary();

      toast.success(t('projects.expenses.toast.paid'));
      return paidExpense;
    } catch (error) {
      console.error('Failed to mark expense as paid:', error);
      toast.error(t('projects.expenses.error.mark_paid'));
      return null;
    }
  }, [projectId, t, loadSummary]);

  /**
   * Принудительное обновление
   */
  const refresh = useCallback(() => {
    setRefreshKey(prev => prev + 1);
  }, []);

  // Автозагрузка
  useEffect(() => {
    if (enabled && projectId) {
      loadExpenses();
      loadSummary();
      loadCategories();
    }
  }, [enabled, projectId, refreshKey, loadExpenses, loadSummary, loadCategories]);

  return {
    // Данные
    expenses,
    categories,
    summary,
    isLoading,
    isError,

    // CRUD операции
    loadExpenses,
    loadCategories,
    loadSummary,
    createExpense,
    updateExpense,
    deleteExpense,
    approveExpense,
    markAsPaid,

    // Состояния
    refresh,
  };
}

