  deleteRevenue: (revenueId: number) => Promise<boolean>;
  markAsReceived: (revenueId: number, actualDate?: string) => Promise<ProjectRevenue | null>;

  // Состояния
  refresh: () => void;
}

/**
 * Хук для управления доходами проекта
 */
export function useProjectRevenues(options: UseProjectRevenuesOptions = {}): UseProjectRevenuesReturn {
  const { projectId, enabled = true } = options;
  const { t } = useTranslation();

  const [revenues, setRevenues] = useState<ProjectRevenue[]>([]);
  const [summary, setSummary] = useState<ProjectRevenuesSummary | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [isError, setIsError] = useState(false);
  const [refreshKey, setRefreshKey] = useState(0);

  /**
   * Загрузить все доходы
   */
  const loadRevenues = useCallback(async () => {
    if (!projectId) return;

    setIsLoading(true);

    try {
      const response = await projectsApi.getRevenues(projectId);
      setRevenues(response || []);
    } catch (error) {
      toast.error(t('projects.revenues.error.load'));
      setRevenues([]);
    } finally {
      setIsLoading(false);
    }
  }, [projectId, t]);

  /**
   * Загрузить сводку
   */
  const loadSummary = useCallback(async () => {
    if (!projectId) return;

    try {
      const response = await projectsApi.getRevenuesSummary(projectId);
      setSummary(response || null);
