  const createRevenue = useCallback(async (
    data: CreateProjectRevenueDTO
  ): Promise<ProjectRevenue | null> => {
    if (!projectId) {
      toast.error(t('projects.revenues.error.no_project'));
      return null;
    }

    try {
      const response = await projectsApi.createRevenue(projectId, data);
