      loadSummary();

      toast.success(t('projects.revenues.toast.deleted'));
      return true;
    } catch (error) {
      toast.error(t('projects.revenues.error.delete'));
      return false;
    }
  }, [projectId, t, loadSummary]);

  /**
   * Отметить доход как полученный
   */
  const markAsReceived = useCallback(async (
    revenueId: number,
    actualDate?: string
  ): Promise<ProjectRevenue | null> => {
    if (!projectId) return null;

    try {
      const response = await projectsApi.markAsReceived(projectId, revenueId, actualDate);
      const receivedRevenue = response.data;

      setRevenues(prev => prev.map(r => r.id === revenueId ? receivedRevenue : r));
      loadSummary();

      toast.success(t('projects.revenues.toast.received'));
      return receivedRevenue;
    } catch (error) {
      toast.error(t('projects.revenues.error.mark_received'));
      return null;
    }
  }, [projectId, t, loadSummary]);

  /**
   * Принудительное обновление
   */
  const refresh = useCallback(() => {
    setRefreshKey(prev => prev + 1);
  }, []);

  // Автозагрузка
  useEffect(() => {
    if (enabled && projectId) {
      loadRevenues();
      loadSummary();
    }
  }, [enabled, projectId, refreshKey, loadRevenues, loadSummary]);

  return {
    // Данные
    revenues,
    summary,
    isLoading,
    isError,

    // CRUD операции
    loadRevenues,
    loadSummary,
    createRevenue,
    updateRevenue,
    deleteRevenue,
    markAsReceived,

    // Состояния
    refresh,
  };
}

