// frontend/src/modules/projects/hooks/useProjectStages.ts
import { useState, useEffect, useCallback } from 'react';
import { toast } from 'sonner';
import { useTranslation } from '@/lib/i18n';
import { projectsApi } from '../api';
import type {
  ProjectStage,
  CreateProjectStageDTO,
  UpdateProjectStageDTO,
  ProjectStagesSummary,
} from '../types';

interface UseProjectStagesOptions {
  projectId?: number;
  enabled?: boolean; // Автозагрузка при монтировании
}

interface UseProjectStagesReturn {
  // Данные
  stages: ProjectStage[];
  summary: ProjectStagesSummary | null;
  isLoading: boolean;
  isError: boolean;

  // CRUD операции
  loadStages: () => Promise<void>;
  loadSummary: () => Promise<void>;
  createStage: (data: CreateProjectStageDTO) => Promise<ProjectStage | null>;
  updateStage: (stageId: number, data: UpdateProjectStageDTO) => Promise<ProjectStage | null>;
  deleteStage: (stageId: number) => Promise<boolean>;
  completeStage: (stageId: number, progress?: number) => Promise<ProjectStage | null>;
  reorderStage: (stageId: number, orderIndex: number) => Promise<ProjectStage | null>;

  // Состояния
  refresh: () => void;
}

/**
 * Хук для управления этапами проекта
 */
export function useProjectStages(options: UseProjectStagesOptions = {}): UseProjectStagesReturn {
  const { projectId, enabled = true } = options;
  const { t } = useTranslation();

  const [stages, setStages] = useState<ProjectStage[]>([]);
  const [summary, setSummary] = useState<ProjectStagesSummary | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [isError, setIsError] = useState(false);
  const [refreshKey, setRefreshKey] = useState(0);

  /**
   * Загрузить все этапы проекта
   */
  const loadStages = useCallback(async () => {
    if (!projectId) return;

    setIsLoading(true);
    setIsError(false);

    try {
      const response = await projectsApi.getStages(projectId);
      console.log('Loaded stages for project', projectId, ':', response?.length, 'stages');
      setStages(response || []);
    } catch (error) {
      console.error('Failed to load stages for project', projectId, ':', error);
      setIsError(true);
      toast.error(t('projects.stages.error.load'));
      setStages([]);
    } finally {
      setIsLoading(false);
    }
  }, [projectId, t]);

  /**
   * Загрузить сводку по этапам
   */
  const loadSummary = useCallback(async () => {
    if (!projectId) return;

    try {
      const response = await projectsApi.getStagesSummary(projectId);
      setSummary(response || null);
    } catch (error) {
      console.error('Failed to load stages summary:', error);
    }
  }, [projectId]);

  /**
   * Создать новый этап
   */
  const createStage = useCallback(async (
    data: CreateProjectStageDTO
  ): Promise<ProjectStage | null> => {
    if (!projectId) {
      toast.error(t('projects.stages.error.no_project'));
      return null;
    }

    try {
      const response = await projectsApi.createStage(projectId, data);
      const newStage = response.data;

      if (newStage && newStage.id) {
        // Обновляем локальный кэш
        setStages(prev => [...prev, newStage]);
        await loadSummary(); // Обновить сводку

        toast.success(t('projects.stages.toast.created'));
        return newStage;
      } else {
        // Если что-то пошло не так, перезагружаем данные
        await loadStages();
        await loadSummary();
        return null;
      }
    } catch (error) {
      console.error('Failed to create stage:', error);
      toast.error(t('projects.stages.error.create'));
      return null;
    }
  }, [projectId, t, loadSummary, loadStages]);

  /**
   * Обновить этап
   */
  const updateStage = useCallback(async (
    stageId: number,
    data: UpdateProjectStageDTO
  ): Promise<ProjectStage | null> => {
    if (!projectId) return null;

    try {
      const response = await projectsApi.updateStage(projectId, stageId, data);
      const updatedStage = response.data;

      setStages(prev => prev.map(s => s.id === stageId ? updatedStage : s));
      loadSummary();

      toast.success(t('projects.stages.toast.updated'));
      return updatedStage;
    } catch (error) {
      console.error('Failed to update stage:', error);
      toast.error(t('projects.stages.error.update'));
      return null;
    }
  }, [projectId, t, loadSummary]);

  /**
   * Удалить этап
   */
  const deleteStage = useCallback(async (stageId: number): Promise<boolean> => {
    if (!projectId) return false;

    try {
      await projectsApi.deleteStage(projectId, stageId);
      setStages(prev => prev.filter(s => s.id !== stageId));
      loadSummary();

      toast.success(t('projects.stages.toast.deleted'));
      return true;
    } catch (error) {
      console.error('Failed to delete stage:', error);
      toast.error(t('projects.stages.error.delete'));
      return false;
    }
  }, [projectId, t, loadSummary]);

  /**
   * Завершить этап
   */
  const completeStage = useCallback(async (
    stageId: number,
    progress?: number
  ): Promise<ProjectStage | null> => {
    if (!projectId) return null;

    try {
      const response = await projectsApi.completeStage(projectId, stageId, progress);
      const completedStage = response.data;

      setStages(prev => prev.map(s => s.id === stageId ? completedStage : s));
      loadSummary();

      toast.success(t('projects.stages.toast.completed'));
      return completedStage;
    } catch (error) {
      console.error('Failed to complete stage:', error);
      toast.error(t('projects.stages.error.complete'));
      return null;
    }
  }, [projectId, t, loadSummary]);

  /**
   * Переместить этап (изменить порядок)
   */
  const reorderStage = useCallback(async (
    stageId: number,
    orderIndex: number
  ): Promise<ProjectStage | null> => {
    if (!projectId) return null;

    try {
      const response = await projectsApi.reorderStage(projectId, stageId, orderIndex);
      const reorderedStage = response.data;

      // Обновляем порядок в списке
      setStages(prev => {
        const newStages = [...prev];
        const index = newStages.findIndex(s => s.id === stageId);
        if (index !== -1) {
          newStages[index] = reorderedStage;
        }
        // Сортируем по orderIndex
        return newStages.sort((a, b) => a.orderIndex - b.orderIndex);
      });

      toast.success(t('projects.stages.toast.reordered'));
      return reorderedStage;
    } catch (error) {
      console.error('Failed to reorder stage:', error);
      toast.error(t('projects.stages.error.reorder'));
      return null;
    }
  }, [projectId, t]);

  /**
   * Принудительное обновление данных
   */
  const refresh = useCallback(() => {
    setRefreshKey(prev => prev + 1);
  }, []);

  // Автозагрузка при монтировании
  useEffect(() => {
    if (enabled && projectId) {
      loadStages();
      loadSummary();
    }
  }, [enabled, projectId, refreshKey, loadStages, loadSummary]);

  return {
    // Данные
    stages,
    summary,
    isLoading,
    isError,

    // CRUD операции
    loadStages,
    loadSummary,
    createStage,
    updateStage,
    deleteStage,
    completeStage,
    reorderStage,

    // Состояния
    refresh,
  };
}

