// frontend/src/modules/projects/hooks/useProjectsPage.ts
import { useState, useMemo, useEffect } from "react";
import { useSearchParams } from "react-router-dom";
import { useTranslation } from "@/lib/i18n";
import { useSettings } from "@/hooks/use-settings";
import { useDataTable } from "@/hooks/useDataTable";
import { usePersistedTab } from "@/hooks/usePersistedTab";
import { parseRowsPerPage } from "@/lib/utils";
import { List, LayoutGrid, GanttChart, Users } from "lucide-react";
import { Project, ProjectTask, OpenProjectTaskSheetRequest } from "../types";
import type { TaskReference } from "@/lib/types";
import type { ReferenceData } from "./useProjectsPage.types";
import { useProjectData } from "./useProjectData";
import { useProjectCRUD } from "./useProjectCRUD";
import { useProjectFilters } from "./useProjectFilters";
import { useProjectTasks } from "./useProjectTasks";
import { useProjectDragAndDrop } from "./useProjectDragAndDrop";
import { toast } from "sonner";

export type { ReferenceData };

export function useProjectsPage() {
  const { t } = useTranslation();
  const { getStatusesByModule, getPrioritiesByModule, getQuickActionsByModule } = useSettings();

  // Data fetching
  const {
    projects,
    loading,
    references,
    contractors,
  } = useProjectData();

  // Table state
  const table = useDataTable<Project>({
    initialData: [],
    initialColumns: {
      name: true,
      client: true,
      manager: true,
      status: true,
      priority: true,
      budget: true,
    },
    initialTabs: [
      { id: "list", label: "projects.tabs.list", icon: List, visible: true },
      { id: "board", label: "projects.tabs.board", icon: LayoutGrid, visible: true },
      { id: "gantt", label: "projects.tabs.gantt", icon: GanttChart, visible: true },
      { id: "resources", label: "projects.tabs.resources", icon: Users, visible: true },
    ],
    storageKey: "projects-table",
  });

  // Projects state management
  const [projectsState, setProjectsState] = useState<Project[]>([]);

  useEffect(() => {
    if (projects.length > 0) {
      setProjectsState(projects);
    }
  }, [projects]);

  // CRUD operations
  const crud = useProjectCRUD(
    projectsState,
    setProjectsState,
    table.selectedIds as Set<number>,
    table.clearSelection
  );

  // Filters
  const filters = useProjectFilters({
    projects: projectsState,
    searchQuery: table.searchQuery,
  });

  // Tasks
  const tasks = useProjectTasks();

  // Drag and Drop
  const dragAndDrop = useProjectDragAndDrop(projectsState, setProjectsState);

  // Tabs and persistence
  const [activeTab, setActiveTab] = usePersistedTab<string>("tab:projects", "list");

  const projectActions = getQuickActionsByModule("projects");

  // ── URL param: open sheet for ?edit=id ─────────────────────────
  const [searchParams, setSearchParams] = useSearchParams();
  useEffect(() => {
    const edit = searchParams.get("edit");
    if (edit && projectsState.length > 0) {
      const target = projectsState.find((p) => p.id === parseInt(edit, 10));
      if (target) {
        crud.setSelectedProject(target);
        crud.setSheetOpen(true);
        searchParams.delete("edit");
        setSearchParams(searchParams, { replace: true });
      }
    }
  }, [projectsState, searchParams, setSearchParams]); // eslint-disable-line react-hooks/exhaustive-deps

  // ── Sorted and filtered projects ─────────────────────────────────
  const sortedProjects = useMemo(() => {
    if (!table.sortConfig) return filters.filteredProjects;
    return [...filters.filteredProjects].sort((a, b) => {
      const key = table.sortConfig!.key as keyof Project;
      const direction = table.sortConfig!.direction;
      const aVal = String(a[key] ?? "");
      const bVal = String(b[key] ?? "");
      return direction === "asc" ? aVal.localeCompare(bVal) : bVal.localeCompare(aVal);
    });
  }, [filters.filteredProjects, table.sortConfig]);

  const perPage = parseRowsPerPage(table.rowsPerPage);
  const paginatedProjects = sortedProjects.slice((table.currentPage - 1) * perPage, table.currentPage * perPage);
  const totalBudget = projectsState.reduce((acc, p) => acc + (Number(p.budget) || 0), 0);

  // Reset page when filters change
  useEffect(() => { table.setCurrentPage(1); }, [table.searchQuery, filters.statusFilter, filters.priorityFilter, filters.managerFilter]); // eslint-disable-line react-hooks/exhaustive-deps

  // ── Quick actions ──────────────────────────────────────────────
  const handleQuickAction = (action: string, project: Project) => {
    switch (action) {
      case "create_project":
        crud.handleAddProject();
        break;
      case "create_task":
        tasks.openQuickTaskSheet(project.name, references);
        break;
      case "assign_manager":
      case "change_status":
      case "edit":
        crud.handleEditProject(project);
        break;
      case "export_report":
        toast.info(t("general.toast.info.export_report").replace("{0}", project.name));
        break;
      case "view_tasks":
        toast.info(t("general.toast.info.view_tasks").replace("{0}", project.name));
        break;
      case "schedule_meeting":
        toast.info(t("general.toast.info.go_to_calendar").replace("{0}", project.name));
        break;
      case "delete":
        if (confirm(`Удалить проект "${project.name}"?`)) crud.handleDeleteProject(project.id);
        break;
      default:
        toast.info(
          t("general.toast.info.project_action_completed")
            .replace("{0}", action)
            .replace("{1}", project.name)
        );
    }
  };

  return {
    t,
    projects: projectsState,
    loading,
    activeTab,
    setActiveTab,
    references,
    contractors,
    statusFilter: filters.statusFilter,
    setStatusFilter: filters.setStatusFilter,
    priorityFilter: filters.priorityFilter,
    setPriorityFilter: filters.setPriorityFilter,
    managerFilter: filters.managerFilter,
    setManagerFilter: filters.setManagerFilter,
    rowsPerPage: table.rowsPerPage,
    setRowsPerPage: table.setRowsPerPage,
    currentPage: table.currentPage,
    setCurrentPage: table.setCurrentPage,
    projectActions,
    table,
    sheetOpen: crud.sheetOpen,
    setSheetOpen: crud.setSheetOpen,
    selectedProject: crud.selectedProject,
    setSelectedProject: crud.setSelectedProject,
    bulkEditOpen: crud.bulkEditOpen,
    setBulkEditOpen: crud.setBulkEditOpen,
    sortedProjects,
    paginatedProjects,
    totalBudget,
    getStatusesByModule,
    getPrioritiesByModule,
    handleAddProject: crud.handleAddProject,
    handleEditProject: crud.handleEditProject,
    handleSaveProject: crud.handleSaveProject,
    handleDeleteProject: crud.handleDeleteProject,
    handleBulkDelete: crud.handleBulkDelete,
    handleBulkEdit: crud.handleBulkEdit,
    handleQuickAction,
    handleDragStart: dragAndDrop.handleDragStart,
    handleDragOver: dragAndDrop.handleDragOver,
    handleDrop: dragAndDrop.handleDrop,
    handleSaveTask: tasks.handleSaveTask,
    handleDeleteTask: tasks.handleDeleteTask,
    taskSheetState: tasks.taskSheetState,
    setTaskSheetState: tasks.closeTaskSheet,
    openProjectTaskSheet: tasks.openProjectTaskSheet,
  };
}

