import { useTranslation } from '@/lib/i18n';
import { useState, useEffect, useCallback } from 'react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Badge } from '@/components/ui/badge';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle, DialogFooter } from '@/components/ui/dialog';
import { toast } from 'sonner';
import { Plus, Trash2, Pencil, Star, Landmark, Wallet } from 'lucide-react';
import { api } from '@/lib/api';
import { cn } from '@/lib/utils';

interface Currency { id: string; name: string; symbol: string; }
interface CompanyAccount {
  id: number;
  name: string;
  description: string;
  currency_id: string;
  account_type: string;
  bank_name: string;
  account_number: string;
  is_default: boolean;
  is_active: boolean;
  currency_name?: string;
  currency_symbol?: string;
}

// db.js converts snake_case → camelCase; normalize to snake_case for our interface
// eslint-disable-next-line @typescript-eslint/no-explicit-any
const normalizeAccount = (a: any): CompanyAccount => ({
  id: a.id,
  name: a.name ?? '',
  description: a.description ?? '',
  currency_id: a.currencyId ?? a.currency_id ?? 'RUB',
  account_type: a.accountType ?? a.account_type ?? 'bank',
  bank_name: a.bankName ?? a.bank_name ?? '',
  account_number: a.accountNumber ?? a.account_number ?? '',
  is_default: a.isDefault ?? a.is_default ?? false,
  is_active: a.isActive ?? a.is_active ?? true,
  currency_name: a.currencyName ?? a.currency_name,
  currency_symbol: a.currencySymbol ?? a.currency_symbol,
});

const ACCOUNT_TYPES = [
  { value: 'bank', label: 'Расчётный счёт' },
  { value: 'cash', label: 'Касса' },
  { value: 'card', label: 'Карта' },
  { value: 'virtual', label: 'Виртуальный' },
];

const EMPTY_FORM = {
  name: '', description: '', currency_id: 'RUB', account_type: 'bank',
  bank_name: '', account_number: '', is_default: false, is_active: true,
};

export function CompanyAccountEditor() {
  const { t } = useTranslation();
  const [accounts, setAccounts] = useState<CompanyAccount[]>([]);
  const [currencies, setCurrencies] = useState<Currency[]>([]);
  const [loading, setLoading] = useState(true);
  const [dialogOpen, setDialogOpen] = useState(false);
  const [editingId, setEditingId] = useState<number | null>(null);
  const [form, setForm] = useState(EMPTY_FORM);
  const [saving, setSaving] = useState(false);

  const load = useCallback(async () => {
    try {
      const [acc, cur] = await Promise.all([
        api.get('/company/accounts'),
        api.get('/references/currencies'),
      ]);
      setAccounts(Array.isArray(acc) ? acc.map(normalizeAccount) : []);
      setCurrencies(cur);
    } catch {
      toast.error(t('generated.oshibka_zagruzki'));
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => { load(); }, [load]);

  const openAdd = () => {
    setEditingId(null);
    setForm(EMPTY_FORM);
    setDialogOpen(true);
  };

  const openEdit = (a: CompanyAccount) => {
    setEditingId(a.id);
    setForm({
      name: a.name,
      // don't expose internal marker in the visible description field
      description: a.description === '__from_profile__' ? '' : (a.description || ''),
      currency_id: a.currency_id, account_type: a.account_type,
      bank_name: a.bank_name || '', account_number: a.account_number || '',
      is_default: a.is_default, is_active: a.is_active,
    });
    setDialogOpen(true);
  };

  const handleSave = async () => {
    if (!form.name.trim()) { toast.error(t('generated.nazvanie_obyazatel_no')); return; }
    setSaving(true);
    try {
      if (editingId) {
        const res = await api.put(`/company/accounts/${editingId}`, form);
        const normalized = normalizeAccount(res);
        setAccounts(prev => prev.map(a =>
          a.id === editingId ? normalized : (form.is_default ? { ...a, is_default: false } : a)
        ));
      } else {
        const res = await api.post('/company/accounts', form);
        const normalized = normalizeAccount(res);
        setAccounts(prev => [
          ...(form.is_default ? prev.map(a => ({ ...a, is_default: false })) : prev),
          normalized,
        ]);
      }
      setDialogOpen(false);
      toast.success(editingId ? t('generated.schet_obnovlen') : t('generated.schet_dobavlen'));
    } catch (e: any) {
      toast.error(e?.message || t('settings.validation.error'));
    } finally {
      setSaving(false);
    }
  };

  const handleDelete = async (id: number) => {
    try {
      await api.delete(`/company/accounts/${id}`);
      setAccounts(prev => prev.filter(a => a.id !== id));
      toast.success(t('generated.schet_udalen'));
    } catch {
      toast.error(t('generated.oshibka_udaleniya'));
    }
  };

  const typeLabel = (t: string) => ACCOUNT_TYPES.find(x => x.value === t)?.label ?? t;

  if (loading) return <div className="py-8 text-center text-muted-foreground">{t('generated.zagruzka')}</div>;

  return (
    <div className="space-y-3">
      {accounts.map(a => (
        <div key={a.id} className={cn(
          "flex items-center gap-3 px-4 py-3 rounded-lg border",
          !a.is_active && "opacity-50",
          a.is_default && "border-primary/40 bg-primary/5"
        )}>
          <div className="text-muted-foreground">
            {a.account_type === 'cash' ? <Wallet className="h-5 w-5" /> : <Landmark className="h-5 w-5" />}
          </div>
          <div className="flex-1 min-w-0">
            <div className="flex items-center gap-2">
              <span className="font-medium text-sm">{a.name}</span>
              {a.is_default && <Badge variant="outline" className="text-[10px] h-4 px-1 border-primary text-primary">{t('generated.osnovnoy')}</Badge>}
              {!a.is_active && <Badge variant="secondary" className="text-[10px] h-4 px-1">{t('generated.neaktiven')}</Badge>}
              {a.description === '__from_profile__' && <Badge variant="secondary" className="text-[10px] h-4 px-1">{t('generated.iz_rekvizitov')}</Badge>}
            </div>
            <div className="text-xs text-muted-foreground mt-0.5">
              {typeLabel(a.account_type)}
              {a.bank_name && ` · ${a.bank_name}`}
              {a.account_number && ` · ${a.account_number}`}
            </div>
          </div>
          <Badge variant="secondary" className="font-mono">
            {a.currency_symbol} {a.currency_id}
          </Badge>
          <div className="flex gap-1">
            <Button size="icon" variant="ghost" className="h-7 w-7" onClick={() => openEdit(a)}><Pencil className="h-3.5 w-3.5" /></Button>
            <Button size="icon" variant="ghost" className="h-7 w-7 text-destructive" onClick={() => handleDelete(a.id)}>
              <Trash2 className="h-3.5 w-3.5" />
            </Button>
          </div>
        </div>
      ))}

      <Button variant="outline" className="w-full" size="sm" onClick={openAdd}>
        <Plus className="h-4 w-4 mr-2" /> {t('generated.dobavit_schet')}
      </Button>

      <Dialog open={dialogOpen} onOpenChange={setDialogOpen}>
        <DialogContent className="max-w-md">
          <DialogHeader>
            <DialogTitle>{editingId ? t('settings.company.accounts.edit_account') : t('settings.company.accounts.new_account')}</DialogTitle>
            <DialogDescription>
              {editingId ? t('general.generated.izmenite_informatsiyu_o_bankovskom_schete') : t('general.generated.dobavte_novyy_bankovskiy_schet_dlya_kompanii')}
            </DialogDescription>
          </DialogHeader>

          <div className="space-y-3 py-2">
            <div className="space-y-1.5">
              <Label>{t('generated.nazvanie')}</Label>
              <Input value={form.name} onChange={e => setForm(p => ({ ...p, name: e.target.value }))} placeholder={t('generated.raschetnyy_schet_rub')} />
            </div>
            <div className="grid grid-cols-2 gap-3">
              <div className="space-y-1.5">
                <Label>{t('generated.valyuta')}</Label>
                <Select value={form.currency_id} onValueChange={v => setForm(p => ({ ...p, currency_id: v }))}>
                  <SelectTrigger><SelectValue /></SelectTrigger>
                  <SelectContent>
                    {currencies.map(c => (
                      <SelectItem key={c.id} value={c.id}>{c.symbol} {c.id} — {c.name}</SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
              <div className="space-y-1.5">
                <Label>{t('generated.tip')}</Label>
                <Select value={form.account_type} onValueChange={v => setForm(p => ({ ...p, account_type: v }))}>
                  <SelectTrigger><SelectValue /></SelectTrigger>
                  <SelectContent>
                    {ACCOUNT_TYPES.map(t => <SelectItem key={t.value} value={t.value}>{t.label}</SelectItem>)}
                  </SelectContent>
                </Select>
              </div>
            </div>
            <div className="space-y-1.5">
              <Label>{t('generated.bank')}</Label>
              <Input value={form.bank_name} onChange={e => setForm(p => ({ ...p, bank_name: e.target.value }))} placeholder='ПАО "Сбербанк"' />
            </div>
            <div className="space-y-1.5">
              <Label>{t('generated.nomer_scheta')}</Label>
              <Input value={form.account_number} onChange={e => setForm(p => ({ ...p, account_number: e.target.value }))} placeholder="40702810..." maxLength={25} />
            </div>
            <div className="space-y-1.5">
              <Label>{t('generated.opisanie')}</Label>
              <Input value={form.description} onChange={e => setForm(p => ({ ...p, description: e.target.value }))} placeholder={t('generated.neobyazatel_no')} />
            </div>
            <div className="flex items-center gap-4 pt-1">
              <label className="flex items-center gap-2 cursor-pointer text-sm">
                <input type="checkbox" className="rounded" checked={form.is_default}
                  onChange={e => setForm(p => ({ ...p, is_default: e.target.checked }))} />
                <Star className="h-3.5 w-3.5 text-muted-foreground" /> {t('generated.osnovnoy')}
              </label>
              <label className="flex items-center gap-2 cursor-pointer text-sm">
                <input type="checkbox" className="rounded" checked={form.is_active}
                  onChange={e => setForm(p => ({ ...p, is_active: e.target.checked }))} />
                {t('generated.aktiven')}
              </label>
            </div>
          </div>

          <DialogFooter>
            <Button variant="outline" onClick={() => setDialogOpen(false)}>{t('generated.otmena')}</Button>
            <Button onClick={handleSave} disabled={saving}>{saving ? 'Сохранение...' : 'Сохранить'}</Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

import { useTranslation } from '@/lib/i18n';
import { useState, useEffect, useCallback } from 'react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Separator } from '@/components/ui/separator';
import { toast } from 'sonner';
import { Save, Building2 } from 'lucide-react';
import { api } from '@/lib/api';

interface CompanyProfile {
  id?: number;
  full_name: string;
  short_name: string;
  legal_address: string;
  actual_address: string;
  inn: string;
  kpp: string;
  ogrn: string;
  bik: string;
  bank_account: string;
  corr_account: string;
  bank_name: string;
  phone: string;
  email: string;
  website: string;
}

const EMPTY: CompanyProfile = {
  full_name: '', short_name: '', legal_address: '', actual_address: '',
  inn: '', kpp: '', ogrn: '', bik: '',
  bank_account: '', corr_account: '', bank_name: '',
  phone: '', email: '', website: '',
};

// db.js converts snake_case → camelCase; map back to snake_case for local state
// eslint-disable-next-line @typescript-eslint/no-explicit-any
const fromApi = (res: any): CompanyProfile => ({
  id: res.id,
  full_name: res.fullName ?? res.full_name ?? '',
  short_name: res.shortName ?? res.short_name ?? '',
  legal_address: res.legalAddress ?? res.legal_address ?? '',
  actual_address: res.actualAddress ?? res.actual_address ?? '',
  inn: res.inn ?? '',
  kpp: res.kpp ?? '',
  ogrn: res.ogrn ?? '',
  bik: res.bik ?? '',
  bank_account: res.bankAccount ?? res.bank_account ?? '',
  corr_account: res.corrAccount ?? res.corr_account ?? '',
  bank_name: res.bankName ?? res.bank_name ?? '',
  phone: res.phone ?? '',
  email: res.email ?? '',
  website: res.website ?? '',
});

export function CompanyProfileEditor() {
  const { t } = useTranslation();
  const [data, setData] = useState<CompanyProfile>(EMPTY);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);

  const load = useCallback(async () => {
    try {
      const res = await api.get('/company/profile');
      if (res && (res.id || res.fullName || res.full_name)) {
        setData({ ...EMPTY, ...fromApi(res) });
      }
    } catch {
      toast.error(t('generated.oshibka_zagruzki_rekvizitov'));
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => { load(); }, [load]);

  const set = (field: keyof CompanyProfile) => (e: React.ChangeEvent<HTMLInputElement>) =>
    setData(prev => ({ ...prev, [field]: e.target.value }));

  const syncAccountFromProfile = async (profile: CompanyProfile) => {
    if (!profile.bank_account) return;
    try {
      const accounts: Array<{
        id: number;
        description?: string;
        accountNumber?: string;
        account_number?: string;
      }> = await api.get('/company/accounts');

      const profileAccount = accounts.find(
        a => a.description === '__from_profile__' ||
             (a.accountNumber ?? a.account_number) === profile.bank_account
      );

      const payload = {
        name: profile.bank_name
          ? `${profile.bank_name} (${t('settings.company.bank_account')})`
          : t('settings.company.bank_account'),
        description: '__from_profile__',
        account_type: 'bank',
        bank_name: profile.bank_name,
        account_number: profile.bank_account,
        currency_id: 'RUB',
        is_active: true,
      };

      if (profileAccount) {
        await api.put(`/company/accounts/${profileAccount.id}`, payload);
      } else {
        await api.post('/company/accounts', { ...payload, is_default: accounts.length === 0 });
      }
    } catch {
      // not critical — profile was saved successfully
    }
  };

  const handleSave = async () => {
    setSaving(true);
    try {
      const res = await api.put('/company/profile', data);
      const saved = { ...EMPTY, ...fromApi(res) };
      setData(saved);
      await syncAccountFromProfile(saved);
      toast.success(t('generated.rekvizity_sohraneny'));
    } catch {
      toast.error(t('generated.oshibka_sohraneniya'));
    } finally {
      setSaving(false);
    }
  };

  if (loading) return <div className="py-8 text-center text-muted-foreground">{t('generated.zagruzka')}</div>;

  return (
    <div className="space-y-6 max-w-2xl">
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-2 text-muted-foreground text-sm">
          <Building2 className="h-4 w-4" />
          {t('generated.dannye_ispol_zuyutsya_pri_formirovanii_s')}
        </div>
        <Button onClick={handleSave} disabled={saving} size="sm">
          <Save className="h-4 w-4 mr-2" />
          {saving ? 'Сохранение...' : 'Сохранить'}
        </Button>
      </div>

      <div className="grid grid-cols-1 gap-4">
        <div className="space-y-2">
          <Label>{t('generated.polnoe_naimenovanie')}</Label>
          <Input value={data.full_name} onChange={set('full_name')} placeholder='ООО "Название компании"' />
        </div>
        <div className="space-y-2">
          <Label>{t('generated.kratkoe_naimenovanie')}</Label>
          <Input value={data.short_name} onChange={set('short_name')} placeholder='ООО "Название"' />
        </div>
      </div>

      <Separator />
      <p className="text-xs font-semibold text-muted-foreground uppercase tracking-wider">{t('generated.rekvizity')}</p>

      <div className="grid grid-cols-3 gap-4">
        <div className="space-y-2">
          <Label>{t('generated.inn')}</Label>
          <Input value={data.inn} onChange={set('inn')} placeholder="7700000000" maxLength={12} />
        </div>
        <div className="space-y-2">
          <Label>{t('generated.kpp')}</Label>
          <Input value={data.kpp} onChange={set('kpp')} placeholder="770001001" maxLength={9} />
        </div>
        <div className="space-y-2">
          <Label>{t('generated.ogrn')}</Label>
          <Input value={data.ogrn} onChange={set('ogrn')} placeholder="1027700000000" maxLength={15} />
        </div>
      </div>

      <Separator />
      <p className="text-xs font-semibold text-muted-foreground uppercase tracking-wider">{t('generated.bankovskie_rekvizity')}</p>

      <div className="grid grid-cols-2 gap-4">
        <div className="space-y-2">
          <Label>{t('generated.nazvanie_banka')}</Label>
          <Input value={data.bank_name} onChange={set('bank_name')} placeholder='ПАО "Сбербанк"' />
        </div>
        <div className="space-y-2">
          <Label>{t('generated.bik')}</Label>
          <Input value={data.bik} onChange={set('bik')} placeholder="044525225" maxLength={9} />
        </div>
        <div className="space-y-2">
          <Label>{t('generated.raschetnyy_schet')}</Label>
          <Input value={data.bank_account} onChange={set('bank_account')} placeholder="40702810000000000000" maxLength={20} />
        </div>
        <div className="space-y-2">
          <Label>{t('generated.korrespondentskiy_schet')}</Label>
          <Input value={data.corr_account} onChange={set('corr_account')} placeholder="30101810400000000225" maxLength={20} />
        </div>
      </div>

      <Separator />
      <p className="text-xs font-semibold text-muted-foreground uppercase tracking-wider">{t('generated.adresa_i_kontakty')}</p>

      <div className="grid grid-cols-1 gap-4">
        <div className="space-y-2">
          <Label>{t('generated.yuridicheskiy_adres')}</Label>
          <Input value={data.legal_address} onChange={set('legal_address')} placeholder={t('generated.g_moskva_ul_primernaya_d_1')} />
        </div>
        <div className="space-y-2">
          <Label>{t('generated.fakticheskiy_adres')}</Label>
          <Input value={data.actual_address} onChange={set('actual_address')} placeholder={t('generated.sovpadaet_s_yuridicheskim')} />
        </div>
        <div className="grid grid-cols-2 gap-4">
          <div className="space-y-2">
            <Label>{t('generated.telefon')}</Label>
            <Input value={data.phone} onChange={set('phone')} placeholder="+7 (495) 000-00-00" />
          </div>
          <div className="space-y-2">
            <Label>Email</Label>
            <Input value={data.email} onChange={set('email')} placeholder="info@company.ru" type="email" />
          </div>
          <div className="space-y-2">
            <Label>{t('generated.sayt')}</Label>
            <Input value={data.website} onChange={set('website')} placeholder="https://company.ru" />
          </div>
        </div>
      </div>
    </div>
  );
}

