import { useState, useEffect } from 'react';
import { useTranslation } from '@/lib/i18n';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import { Switch } from '@/components/ui/switch';
import { Badge } from '@/components/ui/badge';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { Plus, Edit, Trash2, Save } from 'lucide-react';
import { api } from '@/lib/api';
import { toast } from 'sonner';
import { format } from 'date-fns';

interface TaxRegime {
  id: number;
  code: string;
  name: string;
  description?: string;
  isActive: boolean;
  hasVat: boolean;
  hasProfitTax: boolean;
  hasUsnTax: boolean;
  hasInsurance: boolean;
  hasNdfl: boolean;
  defaultVatRate: number;
  defaultProfitTaxRate: number;
  defaultUsnRate: number;
  defaultInsuranceRate: number;
  defaultNdflRate: number;
}

interface TaxRate {
  id: number;
  taxRegimeId: number;
  taxType: string;
  name: string;
  rate: number;
  isFixed: boolean;
  fixedAmount?: number;
  description?: string;
  isActive: boolean;
  effectiveFrom?: string;
  effectiveTo?: string;
}

export function FinanceTaxSettings() {
  const { t } = useTranslation();

  const [taxRegimes, setTaxRegimes] = useState<TaxRegime[]>([]);
  const [taxRates, setTaxRates] = useState<TaxRate[]>([]);
  const [isLoading, setIsLoading] = useState(true);

  // Dialog states
  const [isRegimeDialogOpen, setIsRegimeDialogOpen] = useState(false);
  const [editingRegime, setEditingRegime] = useState<TaxRegime | null>(null);
  const [isRateDialogOpen, setIsRateDialogOpen] = useState(false);
  const [editingRate, setEditingRate] = useState<TaxRate | null>(null);

  const [rateFormData, setRateFormData] = useState<Partial<TaxRate>>({
    taxRegimeId: 1,
    taxType: 'vat',
    name: '',
    rate: 20,
    isFixed: false,
    isActive: true,
    effectiveFrom: format(new Date(), 'dd.MM.yyyy'),
    effectiveTo: '',
  });

  const [regimeFormData, setRegimeFormData] = useState<Partial<TaxRegime>>({
    code: '',
    name: '',
    description: '',
    isActive: true,
    hasVat: false,
    hasProfitTax: false,
    hasUsnTax: false,
    hasInsurance: false,
    hasNdfl: false,
    defaultVatRate: 20,
    defaultProfitTaxRate: 20,
    defaultUsnRate: 6,
    defaultInsuranceRate: 30,
    defaultNdflRate: 13,
  });

  // Load data
  useEffect(() => {
    loadData();
  }, []);

  const loadData = async () => {
    setIsLoading(true);
    try {
      console.log('Loading tax regimes...');
      const regimesRes = await api.get('/finance/settings/tax-regimes');
      console.log('Regimes loaded:', regimesRes);

      console.log('Loading tax rates...');
      const ratesRes = await api.get('/finance/settings/tax-rates');
      console.log('Rates loaded:', ratesRes);

      setTaxRegimes(Array.isArray(regimesRes) ? regimesRes : []);
      setTaxRates(Array.isArray(ratesRes) ? ratesRes : []);
    } catch (error) {
      console.error('Error loading tax settings:', error);
      toast.error(t('settings.tax.error.load') + ': ' + (error instanceof Error ? error.message : 'Unknown error'));
    } finally {
      setIsLoading(false);
    }
  };

  // Save regime
  const handleSaveRegime = async () => {
    if (!regimeFormData.code || !regimeFormData.name) {
      toast.error(t('settings.tax.error.required_fields'));
      return;
    }

    try {
      if (editingRegime) {
        await api.put(`/finance/settings/tax-regimes/${editingRegime.id}`, regimeFormData);
        toast.success(t('settings.tax.toast.regime_updated'));
      } else {
        await api.post('/finance/settings/tax-regimes', regimeFormData);
        toast.success(t('settings.tax.toast.regime_created'));
      }

      setIsRegimeDialogOpen(false);
      loadData();
    } catch (error) {
      console.error('Error saving regime:', error);
      toast.error(t('settings.tax.error.save_regime'));
    }
  };

  // Edit regime
  const handleEditRegime = (regime: TaxRegime) => {
    setEditingRegime(regime);
    setRegimeFormData({
      code: regime.code,
      name: regime.name,
      description: regime.description,
      isActive: regime.isActive,
      hasVat: regime.hasVat,
      hasProfitTax: regime.hasProfitTax,
      hasUsnTax: regime.hasUsnTax,
      hasInsurance: regime.hasInsurance,
      hasNdfl: regime.hasNdfl,
      defaultVatRate: regime.defaultVatRate,
      defaultProfitTaxRate: regime.defaultProfitTaxRate,
      defaultUsnRate: regime.defaultUsnRate,
      defaultInsuranceRate: regime.defaultInsuranceRate,
      defaultNdflRate: regime.defaultNdflRate,
    });
    setIsRegimeDialogOpen(true);
  };

  // Delete regime
  const handleDeleteRegime = async (regime: TaxRegime) => {
    if (!confirm(t('settings.tax.confirm_delete_regime', { name: regime.name }))) {
      return;
    }

    try {
      await api.delete(`/finance/settings/tax-regimes/${regime.id}`);
      toast.success(t('settings.tax.toast.regime_deleted'));
      loadData();
    } catch (error) {
      console.error('Error deleting regime:', error);
      toast.error(t('settings.tax.error.delete_regime'));
    }
  };

  const getTaxTypes = (regime: TaxRegime) => {
    const types = [];
    if (regime.hasVat) types.push(`НДС (${regime.defaultVatRate}%)`);
    if (regime.hasProfitTax) types.push(`Прибыль (${regime.defaultProfitTaxRate}%)`);
    if (regime.hasUsnTax) types.push(`УСН (${regime.defaultUsnRate}%)`);
    if (regime.hasInsurance) types.push(`Взносы (${regime.defaultInsuranceRate}%)`);
    if (regime.hasNdfl) types.push(`НДФЛ (${regime.defaultNdflRate}%)`);
    return types;
  };

  return (
    <div className="space-y-6">
      {/* Tax Regimes */}
      <Card>
        <CardHeader>
          <div className="flex items-center justify-between">
            <div>
              <CardTitle>{t('settings.tax.regimes.title')}</CardTitle>
              <CardDescription>{t('settings.tax.regimes.description')}</CardDescription>
            </div>
            <Button onClick={() => {
              setEditingRegime(null);
              setRegimeFormData({
                code: '',
                name: '',
                description: '',
                isActive: true,
                hasVat: false,
                hasProfitTax: false,
                hasUsnTax: false,
                hasInsurance: false,
                hasNdfl: false,
                defaultVatRate: 20,
                defaultProfitTaxRate: 20,
                defaultUsnRate: 6,
                defaultInsuranceRate: 30,
                defaultNdflRate: 13,
              });
              setIsRegimeDialogOpen(true);
            }}>
              <Plus className="w-4 h-4 mr-2" />
              {t('settings.tax.regimes.add')}
            </Button>
          </div>
        </CardHeader>
        <CardContent>
          <Table>
            <TableHeader>
              <TableRow>
                <TableHead>{t('settings.tax.regimes.table.code')}</TableHead>
                <TableHead>{t('settings.tax.regimes.table.name')}</TableHead>
                <TableHead>{t('settings.tax.regimes.table.taxes')}</TableHead>
                <TableHead>{t('settings.tax.regimes.table.active')}</TableHead>
                <TableHead className="text-right">{t('common.actions')}</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {taxRegimes.length === 0 ? (
                <TableRow>
                  <TableCell colSpan={5} className="h-24 text-center text-muted-foreground">
                    {isLoading ? 'Загрузка...' : t('settings.tax.regimes.empty')}
                  </TableCell>
                </TableRow>
              ) : (
                taxRegimes.map((regime) => (
                  <TableRow key={regime.id}>
                    <TableCell className="font-medium">{regime.code}</TableCell>
                    <TableCell>{regime.name}</TableCell>
                    <TableCell>
                      <div className="flex flex-wrap gap-1">
                        {getTaxTypes(regime).map((type, i) => (
                          <Badge key={i} variant="secondary">{type}</Badge>
                        ))}
                      </div>
                    </TableCell>
                    <TableCell>
                      <Badge variant={regime.isActive ? 'default' : 'secondary'}>
                        {regime.isActive ? t('common.yes') : t('common.no')}
                      </Badge>
                    </TableCell>
                    <TableCell className="text-right">
                      <div className="flex justify-end gap-1">
                        <Button variant="ghost" size="icon" onClick={() => handleEditRegime(regime)}>
                          <Edit className="w-4 h-4" />
                        </Button>
                        <Button variant="ghost" size="icon" onClick={() => handleDeleteRegime(regime)}>
                          <Trash2 className="w-4 h-4 text-destructive" />
                        </Button>
                      </div>
                    </TableCell>
                  </TableRow>
                ))
              )}
            </TableBody>
          </Table>
        </CardContent>
      </Card>

      {/* Tax Rates */}
      <Card>
        <CardHeader>
          <div className="flex items-center justify-between">
            <div>
              <CardTitle>{t('settings.tax.rates.title')}</CardTitle>
              <CardDescription>{t('settings.tax.rates.description')}</CardDescription>
            </div>
            <Button onClick={() => window.open('/finance/settings/tax-rates', '_blank')}>
              <Plus className="w-4 h-4 mr-2" />
              Добавить ставку
            </Button>
          </div>
        </CardHeader>
        <CardContent>
          <Table>
            <TableHeader>
              <TableRow>
                <TableHead>{t('settings.tax.rates.table.regime')}</TableHead>
                <TableHead>{t('settings.tax.rates.table.type')}</TableHead>
                <TableHead>{t('settings.tax.rates.table.name')}</TableHead>
                <TableHead>{t('settings.tax.rates.table.rate')}</TableHead>
                <TableHead>Действует с</TableHead>
                <TableHead>Действует по</TableHead>
                <TableHead>{t('settings.tax.rates.table.active')}</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {taxRates.length === 0 ? (
                <TableRow>
                  <TableCell colSpan={5} className="h-24 text-center text-muted-foreground">
                    {t('settings.tax.rates.empty')}
                  </TableCell>
                </TableRow>
              ) : (
                taxRates.map((rate) => {
                  const regime = taxRegimes.find(r => r.id === rate.taxRegimeId);
                  const isValidNow = !rate.effectiveFrom || new Date(rate.effectiveFrom) <= new Date();
                  const isValidUntil = !rate.effectiveTo || new Date(rate.effectiveTo) >= new Date();
                  const isCurrentlyActive = rate.isActive && isValidNow && isValidUntil;

                  return (
                    <TableRow key={rate.id} className={!isCurrentlyActive ? 'opacity-50' : ''}>
                      <TableCell>{regime?.code || '—'}</TableCell>
                      <TableCell>{rate.taxType}</TableCell>
                      <TableCell>{rate.name}</TableCell>
                      <TableCell>{rate.isFixed ? `${rate.fixedAmount} ₽` : `${rate.rate}%`}</TableCell>
                      <TableCell className="text-sm">{rate.effectiveFrom ? new Date(rate.effectiveFrom).toLocaleDateString('ru-RU') : '—'}</TableCell>
                      <TableCell className="text-sm">{rate.effectiveTo ? new Date(rate.effectiveTo).toLocaleDateString('ru-RU') : '∞'}</TableCell>
                      <TableCell>
                        <Badge variant={isCurrentlyActive ? 'default' : 'secondary'}>
                          {isCurrentlyActive ? t('common.yes') : t('common.no')}
                        </Badge>
                      </TableCell>
                    </TableRow>
                  );
                })
              )}
            </TableBody>
          </Table>
        </CardContent>
      </Card>

      {/* Regime Dialog */}
      <Dialog open={isRegimeDialogOpen} onOpenChange={setIsRegimeDialogOpen}>
        <DialogContent className="max-w-3xl max-h-[90vh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle>
              {editingRegime 
                ? t('settings.tax.regimes.edit_title', { name: editingRegime.name })
                : t('settings.tax.regimes.create_title')}
            </DialogTitle>
            <DialogDescription>
              {t('settings.tax.regimes.description')}
            </DialogDescription>
          </DialogHeader>

          <div className="grid gap-4">
            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-2">
                <Label>{t('settings.tax.regimes.field.code')} *</Label>
                <Input
                  value={regimeFormData.code}
                  onChange={(e) => setRegimeFormData({ ...regimeFormData, code: e.target.value })}
                  placeholder="OSN, USN_INCOME, etc."
                />
              </div>

              <div className="space-y-2">
                <Label>{t('settings.tax.regimes.field.name')} *</Label>
                <Input
                  value={regimeFormData.name}
                  onChange={(e) => setRegimeFormData({ ...regimeFormData, name: e.target.value })}
                  placeholder={t('settings.tax.regimes.placeholder.name')}
                />
              </div>
            </div>

            <div className="space-y-2">
              <Label>{t('settings.tax.regimes.field.description')}</Label>
              <Textarea
                value={regimeFormData.description}
                onChange={(e) => setRegimeFormData({ ...regimeFormData, description: e.target.value })}
                rows={2}
              />
            </div>

            <div className="space-y-2">
              <Label>{t('settings.tax.regimes.field.active')}</Label>
              <Switch
                checked={regimeFormData.isActive}
                onCheckedChange={(v) => setRegimeFormData({ ...regimeFormData, isActive: v })}
              />
            </div>

            <div className="border rounded-lg p-4 space-y-4">
              <h4 className="font-medium">{t('settings.tax.regimes.field.taxes')}</h4>

              <div className="grid grid-cols-2 gap-4">
                <div className="flex items-center justify-between space-x-2">
                  <Label htmlFor="vat" className="flex flex-col">
                    <span>НДС</span>
                    <span className="text-xs text-muted-foreground">VAT</span>
                  </Label>
                  <Switch
                    id="vat"
                    checked={regimeFormData.hasVat}
                    onCheckedChange={(v) => setRegimeFormData({ ...regimeFormData, hasVat: v })}
                  />
                </div>

                <div className="flex items-center justify-between space-x-2">
                  <Label htmlFor="profit" className="flex flex-col">
                    <span>Налог на прибыль</span>
                    <span className="text-xs text-muted-foreground">Profit tax</span>
                  </Label>
                  <Switch
                    id="profit"
                    checked={regimeFormData.hasProfitTax}
                    onCheckedChange={(v) => setRegimeFormData({ ...regimeFormData, hasProfitTax: v })}
                  />
                </div>

                <div className="flex items-center justify-between space-x-2">
                  <Label htmlFor="usn" className="flex flex-col">
                    <span>УСН</span>
                    <span className="text-xs text-muted-foreground">Simplified</span>
                  </Label>
                  <Switch
                    id="usn"
                    checked={regimeFormData.hasUsnTax}
                    onCheckedChange={(v) => setRegimeFormData({ ...regimeFormData, hasUsnTax: v })}
                  />
                </div>

                <div className="flex items-center justify-between space-x-2">
                  <Label htmlFor="insurance" className="flex flex-col">
                    <span>Страховые взносы</span>
                    <span className="text-xs text-muted-foreground">Insurance</span>
                  </Label>
                  <Switch
                    id="insurance"
                    checked={regimeFormData.hasInsurance}
                    onCheckedChange={(v) => setRegimeFormData({ ...regimeFormData, hasInsurance: v })}
                  />
                </div>

                <div className="flex items-center justify-between space-x-2">
                  <Label htmlFor="ndfl" className="flex flex-col">
                    <span>НДФЛ</span>
                    <span className="text-xs text-muted-foreground">Personal income tax</span>
                  </Label>
                  <Switch
                    id="ndfl"
                    checked={regimeFormData.hasNdfl}
                    onCheckedChange={(v) => setRegimeFormData({ ...regimeFormData, hasNdfl: v })}
                  />
                </div>
              </div>
            </div>

            <div className="border rounded-lg p-4 space-y-4">
              <h4 className="font-medium">{t('settings.tax.regimes.field.rates')}</h4>

              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-2">
                  <Label>{t('settings.tax.regimes.field.vat_rate')}</Label>
                  <Input
                    type="number"
                    value={regimeFormData.defaultVatRate}
                    onChange={(e) => setRegimeFormData({ ...regimeFormData, defaultVatRate: parseFloat(e.target.value) || 0 })}
                  />
                </div>

                <div className="space-y-2">
                  <Label>{t('settings.tax.regimes.field.profit_tax_rate')}</Label>
                  <Input
                    type="number"
                    value={regimeFormData.defaultProfitTaxRate}
                    onChange={(e) => setRegimeFormData({ ...regimeFormData, defaultProfitTaxRate: parseFloat(e.target.value) || 0 })}
                  />
                </div>

                <div className="space-y-2">
                  <Label>{t('settings.tax.regimes.field.usn_rate')}</Label>
                  <Input
                    type="number"
                    value={regimeFormData.defaultUsnRate}
                    onChange={(e) => setRegimeFormData({ ...regimeFormData, defaultUsnRate: parseFloat(e.target.value) || 0 })}
                  />
                </div>

                <div className="space-y-2">
                  <Label>{t('settings.tax.regimes.field.insurance_rate')}</Label>
                  <Input
                    type="number"
                    value={regimeFormData.defaultInsuranceRate}
                    onChange={(e) => setRegimeFormData({ ...regimeFormData, defaultInsuranceRate: parseFloat(e.target.value) || 0 })}
                  />
                </div>

                <div className="space-y-2">
                  <Label>{t('settings.tax.regimes.field.ndfl_rate')}</Label>
                  <Input
                    type="number"
                    value={regimeFormData.defaultNdflRate}
                    onChange={(e) => setRegimeFormData({ ...regimeFormData, defaultNdflRate: parseFloat(e.target.value) || 0 })}
                  />
                </div>
              </div>
            </div>
          </div>

          <DialogFooter>
            <Button variant="outline" onClick={() => setIsRegimeDialogOpen(false)}>
              {t('common.cancel')}
            </Button>
            <Button onClick={handleSaveRegime}>
              <Save className="w-4 h-4 mr-2" />
              {t('common.save')}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

