import { useState, useEffect, useCallback } from 'react';
import { Mail, Send, Save, CheckCircle2, AlertCircle, RefreshCw, MessageSquare, Database, Key, BarChart2 } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Card, CardContent, CardDescription, CardHeader, CardTitle, CardFooter } from '@/components/ui/card';
import { Switch } from '@/components/ui/switch';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { useTranslation } from '@/lib/i18n';
import { api } from '@/lib/api';
import { toast } from 'sonner';

export function IntegrationsEditor() {
  const { t } = useTranslation();
  const [loading, setLoading] = useState(true);

  // Email State
  const [emailConfig, setEmailConfig] = useState({
    host: 'smtp.example.com',
    port: '587',
    user: '',
    password: '',
    secure: false,
    from: 'TITAN CRM <no-reply@titan.com>'
  });
  const [testingEmail, setTestingEmail] = useState(false);

  // Telegram State
  const [telegramConfig, setTelegramConfig] = useState({
    botToken: '',
    enabled: false
  });
  const [testChatId, setTestChatId] = useState('');
  const [testingTelegram, setTestingTelegram] = useState(false);

  // Enrichment API Keys
  const [dadataKey, setDadataKey] = useState('');
  const [apifnsKey, setApifnsKey] = useState('');
  const [priorityService, setPriorityService] = useState<'dadata' | 'apifns'>('dadata');
  const [savingEnrichment, setSavingEnrichment] = useState(false);

  // api-fns.ru статистика
  type ApiFnsStat = Record<string, number>;
  const [apifnsStat, setApifnsStat] = useState<ApiFnsStat | null>(null);
  const [loadingStat, setLoadingStat] = useState(false);
  const [statError, setStatError] = useState<string | null>(null);

  // DaData статистика
  interface DadataStat {
    today: {
      total: number;
      successful: number;
      remaining: number;
      limit: number;
    };
    daily: Array<{ date: string; total: number; successful: number }>;
  }
  const [dadataStat, setDadataStat] = useState<DadataStat | null>(null);
  const [loadingDadataStat, setLoadingDadataStat] = useState(false);
  const [dadataStatError, setDadataStatError] = useState<string | null>(null);

    const loadSettings = useCallback(async () => {
    try {
        setLoading(true);
        const settings = await api.get('/system-settings');
        if (settings.email_config) setEmailConfig(settings.email_config);
        if (settings.telegram_config) setTelegramConfig(settings.telegram_config);
        if (settings.dadata_api_key)  setDadataKey(settings.dadata_api_key);
        if (settings.apifns_api_key)  setApifnsKey(settings.apifns_api_key);
        if (settings.enrichment_priority_service) setPriorityService(settings.enrichment_priority_service);
    } catch (e) {
        console.error(e);
        toast.error(t('generated.oshibka_zagruzki_nastroek'));
    } finally {
        setLoading(false);
    }
    }, [t]);

    useEffect(() => {
        loadSettings();
    }, [loadSettings]);

  const saveEmailSettings = async () => {
      try {
          await api.post('/system-settings', { key: 'email_config', value: emailConfig });
          toast.success(t('settings.integrations.save_settings'));
      } catch (e) {
          toast.error(t('generated.oshibka_sohraneniya'));
      }
  };

  const saveTelegramSettings = async () => {
      try {
          await api.post('/system-settings', { key: 'telegram_config', value: telegramConfig });
          toast.success(t('settings.integrations.save_settings'));
      } catch (e) {
          toast.error(t('generated.oshibka_sohraneniya'));
      }
  };

  const saveEnrichmentSettings = async () => {
    setSavingEnrichment(true);
    try {
      await Promise.all([
        api.post('/system-settings', { key: 'dadata_api_key',  value: dadataKey }),
        api.post('/system-settings', { key: 'apifns_api_key', value: apifnsKey }),
        api.post('/system-settings', { key: 'enrichment_priority_service', value: priorityService }),
      ]);
      toast.success(t('generated.klyuchi_api_sohraneny'));
    } catch {
      toast.error(t('generated.oshibka_sohraneniya'));
    } finally {
      setSavingEnrichment(false);
    }
  };

  const loadApiFnsStat = async () => {
    setLoadingStat(true);
    setStatError(null);
    try {
      const data = await api.get('/system-settings/apifns/stat');
      // Ищем объект stat в ответе
      const statObj: ApiFnsStat =
        data?.items?.[0]?.stat ??
        data?.stat ??
        (typeof data === 'object' && !Array.isArray(data) ? data : null);
      setApifnsStat(statObj);
    } catch (e: unknown) {
      setStatError(e instanceof Error ? e.message : 'Ошибка загрузки статистики');
    } finally {
      setLoadingStat(false);
    }
  };

  const loadDadataStat = async () => {
    setLoadingDadataStat(true);
    setDadataStatError(null);
    try {
      const data = await api.get('/system-settings/dadata/stat');
      setDadataStat(data);
    } catch (e: unknown) {
      setDadataStatError(e instanceof Error ? e.message : 'Ошибка загрузки статистики');
    } finally {
      setLoadingDadataStat(false);
    }
  };

  const testEmail = async () => {
      setTestingEmail(true);
      try {
          const res = await api.post('/system-settings/test/email', emailConfig);
          if (res.success) {
              toast.success(res.message);
          } else {
              toast.error(res.error);
          }
      } catch (e: unknown) {
          toast.error(e instanceof Error ? e.message : t('generated.oshibka_podklyucheniya'));
      } finally {
          setTestingEmail(false);
      }
  };

  const testTelegram = async () => {
      if (!telegramConfig.botToken) {
          toast.error(t('generated.vvedite_token_bota'));
          return;
      }
      setTestingTelegram(true);
      try {
          const res = await api.post('/system-settings/test/telegram', { 
              botToken: telegramConfig.botToken,
              chatId: testChatId // Send Chat ID if user entered one
          });

          if (res.success) {
              toast.success(res.message);
          } else {
              toast.error(res.error);
          }
      } catch (e: unknown) {
          toast.error(e instanceof Error ? e.message : t('generated.oshibka_proverki'));
      } finally {
          setTestingTelegram(false);
      }
  };

  if (loading) {
      return <div className="flex justify-center p-8"><RefreshCw className="animate-spin w-6 h-6 text-primary" /></div>;
  }

  return (
    <div className="space-y-6">

      {/* Email / SMTP Settings */}
      <Card>
        <CardHeader>
          <div className="flex items-center gap-2">
            <div className="p-2 bg-blue-100 rounded-lg text-blue-600">
                <Mail className="w-5 h-5" />
            </div>
            <div>
                <CardTitle>{t('settings.integrations.email_title')}</CardTitle>
                <CardDescription>{t('settings.integrations.email_desc')}</CardDescription>
            </div>
          </div>
        </CardHeader>
        <CardContent className="space-y-4">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div className="space-y-2">
                    <Label>{t('settings.integrations.host')}</Label>
                    <Input 
                        value={emailConfig.host} 
                        onChange={(e) => setEmailConfig({...emailConfig, host: e.target.value})} 
                        placeholder="smtp.gmail.com"
                    />
                </div>
                <div className="space-y-2">
                    <Label>{t('settings.integrations.port')}</Label>
                    <Input 
                        value={emailConfig.port} 
                        onChange={(e) => setEmailConfig({...emailConfig, port: e.target.value})} 
                        placeholder="587"
                    />
                </div>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div className="space-y-2">
                    <Label>{t('settings.integrations.user')}</Label>
                    <Input 
                        value={emailConfig.user} 
                        onChange={(e) => setEmailConfig({...emailConfig, user: e.target.value})} 
                        placeholder="user@example.com"
                    />
                </div>
                <div className="space-y-2">
                    <Label>{t('settings.integrations.password')}</Label>
                    <Input 
                        type="password"
                        value={emailConfig.password} 
                        onChange={(e) => setEmailConfig({...emailConfig, password: e.target.value})} 
                        placeholder="••••••••"
                    />
                </div>
            </div>
            <div className="space-y-2">
                <Label>{t('settings.integrations.from')}</Label>
                <Input 
                    value={emailConfig.from} 
                    onChange={(e) => setEmailConfig({...emailConfig, from: e.target.value})} 
                    placeholder="TITAN CRM <no-reply@titan.com>"
                />
            </div>
            <div className="flex items-center space-x-2">
                <Switch 
                    id="secure" 
                    checked={emailConfig.secure}
                    onCheckedChange={(c) => setEmailConfig({...emailConfig, secure: c})}
                />
                <Label htmlFor="secure">{t('settings.integrations.secure')}</Label>
            </div>
        </CardContent>
        <CardFooter className="flex justify-between border-t p-4 bg-muted/10">
            <Button variant="outline" onClick={testEmail} disabled={testingEmail}>
                {testingEmail ? <RefreshCw className="w-4 h-4 mr-2 animate-spin" /> : <CheckCircle2 className="w-4 h-4 mr-2" />}
                {t('settings.integrations.test_connection')}
            </Button>
            <Button onClick={saveEmailSettings}>
                <Save className="w-4 h-4 mr-2" />
                {t('settings.integrations.save_settings')}
            </Button>
        </CardFooter>
      </Card>

      {/* Telegram Bot Settings */}
      <Card>
        <CardHeader>
          <div className="flex items-center gap-2">
            <div className="p-2 bg-sky-100 rounded-lg text-sky-600">
                <Send className="w-5 h-5" />
            </div>
            <div>
                <CardTitle>{t('settings.integrations.telegram_title')}</CardTitle>
                <CardDescription>{t('settings.integrations.telegram_desc')}</CardDescription>
            </div>
          </div>
        </CardHeader>
        <CardContent className="space-y-6">
            <div className="space-y-2">
                <Label>{t('settings.integrations.bot_token')}</Label>
                <Input 
                    type="password"
                    value={telegramConfig.botToken} 
                    onChange={(e) => setTelegramConfig({...telegramConfig, botToken: e.target.value})} 
                    placeholder="123456789:AAH..."
                />
                <p className="text-xs text-muted-foreground">{t('generated.poluchite_token_u_botfather')}</p>
            </div>

            <div className="p-4 bg-muted/30 rounded-lg space-y-3 border">
                <h4 className="text-sm font-medium flex items-center gap-2">
                    <MessageSquare className="w-4 h-4" />
                    {t('generated.proverka_dostavki_soobscheniy')}
                </h4>
                <div className="flex gap-2">
                    <Input 
                        value={testChatId}
                        onChange={(e) => setTestChatId(e.target.value)}
                        placeholder={t('generated.vash_chat_id_naprimer_12345678')}
                        className="bg-background"
                    />
                    <Button variant="secondary" onClick={testTelegram} disabled={testingTelegram}>
                        {testingTelegram ? <RefreshCw className="w-4 h-4 animate-spin" /> : t('settings.integrations.send_test')}
                    </Button>
                </div>
                <p className="text-xs text-muted-foreground">
                    {t('generated.pered_testom_obyazatel_no_nazhmite')} <b>Start</b> {t('generated.v_vashem_bote_v_telegram_inache_soobsche')}
                </p>
            </div>

            <div className="flex items-center space-x-2">
                <Switch 
                    id="tg-enabled" 
                    checked={telegramConfig.enabled}
                    onCheckedChange={(c) => setTelegramConfig({...telegramConfig, enabled: c})}
                />
                <Label htmlFor="tg-enabled">{t('settings.integrations.bot_enabled')}</Label>
            </div>
        </CardContent>
        <CardFooter className="flex justify-end border-t p-4 bg-muted/10">
            <Button onClick={saveTelegramSettings}>
                <Save className="w-4 h-4 mr-2" />
                {t('settings.integrations.save_settings')}
            </Button>
        </CardFooter>
      </Card>

      {/* Обогащение данных контрагентов */}
      <Card>
        <CardHeader>
          <div className="flex items-center gap-2">
            <div className="p-2 bg-emerald-100 rounded-lg text-emerald-600">
              <Database className="w-5 h-5" />
            </div>
            <div>
              <CardTitle>{t('generated.obogaschenie_dannyh_kontragentov')}</CardTitle>
              <CardDescription>
                {t('generated.api_klyuchi_dlya_avtomaticheskogo_obnovl')}
              </CardDescription>
            </div>
          </div>
        </CardHeader>
        <CardContent className="space-y-5">
          {/* Приоритетный сервис */}
          <div className="space-y-2">
            <Label className="flex items-center gap-1.5 font-medium">
              <Database className="w-3.5 h-3.5 text-primary" />
              Приоритетный сервис обогащения
            </Label>
            <Select value={priorityService} onValueChange={(v) => setPriorityService(v as 'dadata' | 'apifns')}>
              <SelectTrigger className="w-full sm:w-[300px]">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="dadata">
                  <div className="flex items-center gap-2">
                    <span className="font-medium">DaData</span>
                    <span className="text-xs text-muted-foreground">(приоритет, лучшее качество)</span>
                  </div>
                </SelectItem>
                <SelectItem value="apifns">
                  <div className="flex items-center gap-2">
                    <span className="font-medium">api-fns.ru</span>
                    <span className="text-xs text-muted-foreground">(официальный ЕГРЮЛ/ЕГРИП)</span>
                  </div>
                </SelectItem>
              </SelectContent>
            </Select>
            <p className="text-xs text-muted-foreground">
              Система будет сначала обращаться к выбранному сервису. Если он недоступен — попробует второй.
            </p>
          </div>

          <div className="space-y-2">
            <Label className="flex items-center gap-1.5">
              <Key className="w-3.5 h-3.5 text-muted-foreground" />
              {t('generated.dadata_api_klyuch')}
            </Label>
            <Input
              type="password"
              value={dadataKey}
              onChange={e => setDadataKey(e.target.value)}
              placeholder={t('generated.vstav_te_klyuch_s_dadata_ru_profile_info')}
            />
            <p className="text-xs text-muted-foreground">
              {t('generated.registratsiya_na')} <span className="font-medium">dadata.ru</span> {t('generated.10_000_zaprosov_den_besplatno_daet_polno')}
            </p>
          </div>
          <div className="space-y-2">
            <Label className="flex items-center gap-1.5">
              <Key className="w-3.5 h-3.5 text-muted-foreground" />
              api-fns.ru — API ключ
            </Label>
            <Input
              type="password"
              value={apifnsKey}
              onChange={e => setApifnsKey(e.target.value)}
              placeholder="40ed5a28..."
            />
            <p className="text-xs text-muted-foreground">
              Официальный ЕГРЮЛ/ЕГРИП. Бесплатный тест — 100 запросов по каждому методу.
            </p>
          </div>

          {/* Статистика DaData */}
          {dadataKey && (
          <div className="rounded-lg border bg-muted/30 p-4 space-y-3">
            <div className="flex items-center justify-between">
              <h4 className="text-sm font-medium flex items-center gap-2">
                <BarChart2 className="w-4 h-4 text-blue-600" />
                Использование запросов DaData
              </h4>
              <Button
                variant="outline"
                size="sm"
                onClick={loadDadataStat}
                disabled={loadingDadataStat || !dadataKey}
              >
                {loadingDadataStat
                  ? <RefreshCw className="w-3.5 h-3.5 animate-spin" />
                  : <RefreshCw className="w-3.5 h-3.5" />}
                <span className="ml-1.5">Обновить</span>
              </Button>
            </div>

            {dadataStatError && (
              <div className="flex items-center gap-2 text-sm text-destructive">
                <AlertCircle className="w-4 h-4 shrink-0" />
                {dadataStatError}
              </div>
            )}

            {dadataStat && !dadataStatError && (
              <div className="space-y-3">
                {/* Сегодня */}
                <div className="rounded-lg border bg-background p-3 space-y-2">
                  <div className="flex items-center justify-between">
                    <span className="text-sm font-medium">Сегодня</span>
                    <span className={`text-xs font-semibold px-2 py-0.5 rounded-full ${
                      dadataStat.today.total >= dadataStat.today.limit
                        ? 'bg-red-100 text-red-700'
                        : dadataStat.today.total / dadataStat.today.limit >= 0.8
                        ? 'bg-amber-100 text-amber-700'
                        : 'bg-emerald-100 text-emerald-700'
                    }`}>
                      Осталось {dadataStat.today.remaining.toLocaleString()}
                    </span>
                  </div>
                  <div className="flex items-center gap-2 text-sm">
                    <div className="flex-1">
                      <div className="h-2 bg-muted rounded-full overflow-hidden">
                        <div
                          className={`h-full transition-all ${
                            dadataStat.today.total >= dadataStat.today.limit
                              ? 'bg-red-500'
                              : dadataStat.today.total / dadataStat.today.limit >= 0.8
                              ? 'bg-amber-500'
                              : 'bg-blue-500'
                          }`}
                          style={{ width: `${Math.min(100, (dadataStat.today.total / dadataStat.today.limit) * 100)}%` }}
                        />
                      </div>
                    </div>
                    <span className="text-xs text-muted-foreground whitespace-nowrap">
                      {dadataStat.today.total.toLocaleString()} / {dadataStat.today.limit.toLocaleString()}
                    </span>
                  </div>
                </div>

                {/* Последние 7 дней */}
                {dadataStat.daily.length > 0 && (
                  <div>
                    <div className="text-xs text-muted-foreground mb-2">Последние 7 дней</div>
                    <div className="grid grid-cols-7 gap-1">
                      {dadataStat.daily.map((day, i) => (
                        <div key={i} className="bg-background rounded border px-2 py-1 text-center">
                          <div className="text-xs font-medium">
                            {new Date(day.date).toLocaleDateString('ru-RU', { day: 'numeric', month: 'short' })}
                          </div>
                          <div className="text-xs text-muted-foreground">
                            {day.total}
                          </div>
                        </div>
                      ))}
                    </div>
                  </div>
                )}
              </div>
            )}

            {!dadataStat && !dadataStatError && !loadingDadataStat && (
              <p className="text-xs text-muted-foreground">Нажмите "Обновить" для загрузки статистики</p>
            )}
          </div>
          )}

          {/* Статистика api-fns.ru */}
          <div className="rounded-lg border bg-muted/30 p-4 space-y-3">
            <div className="flex items-center justify-between">
              <h4 className="text-sm font-medium flex items-center gap-2">
                <BarChart2 className="w-4 h-4 text-emerald-600" />
                Использование запросов api-fns.ru
              </h4>
              <Button
                variant="outline"
                size="sm"
                onClick={loadApiFnsStat}
                disabled={loadingStat || !apifnsKey}
              >
                {loadingStat
                  ? <RefreshCw className="w-3.5 h-3.5 animate-spin" />
                  : <RefreshCw className="w-3.5 h-3.5" />}
                <span className="ml-1.5">Обновить</span>
              </Button>
            </div>

            {statError && (
              <div className="flex items-center gap-2 text-sm text-destructive">
                <AlertCircle className="w-4 h-4 shrink-0" />
                {statError}
              </div>
            )}

            {apifnsStat && !statError && (
              <div className="grid grid-cols-2 sm:grid-cols-4 gap-2">
                {Object.entries(apifnsStat).map(([method, statValue]) => {
                  // statValue can be a number or an object like { used: number, total: number }
                  const displayValue = typeof statValue === 'number' 
                    ? statValue 
                    : typeof statValue === 'object' && statValue !== null
                      ? ('used' in statValue ? (statValue as any).used : JSON.stringify(statValue))
                      : statValue;

                  return (
                    <div key={method} className="bg-background rounded border px-3 py-2 text-center">
                      <div className="text-lg font-bold tabular-nums">{displayValue}</div>
                      <div className="text-xs text-muted-foreground font-mono">{method}</div>
                    </div>
                  );
                })}
              </div>
            )}

            {!apifnsStat && !statError && !loadingStat && (
              <p className="text-xs text-muted-foreground">
                Нажмите «Обновить» чтобы загрузить статистику использования запросов.
              </p>
            )}
          </div>
        </CardContent>
        <CardFooter className="flex justify-end border-t p-4 bg-muted/10">
          <Button onClick={saveEnrichmentSettings} disabled={savingEnrichment}>
            {savingEnrichment ? <RefreshCw className="w-4 h-4 mr-2 animate-spin" /> : <Save className="w-4 h-4 mr-2" />}
            Сохранить ключи
          </Button>
        </CardFooter>
      </Card>

    </div>
  );
}

