interface ModuleSettingsEditorProps {
  moduleId: string;
  moduleName: string;
}

export function ModuleSettingsEditor({ moduleId, moduleName }: ModuleSettingsEditorProps) {
  const { settings, isLoading, error } = useModuleSettings(moduleId);
  const saveModuleSetting = useSaveModuleSetting();
  const [editedSettings, setEditedSettings] = useState<ModuleSettings>(settings);
  const [isDirty, setIsDirty] = useState(false);

  React.useEffect(() => {
    setEditedSettings(settings);
    setIsDirty(false);
  }, [settings]);

  const handleNestedChange = (parentKey: string, childKey: string, value: unknown) => {
    setEditedSettings((prev) => ({
      ...prev,
      [parentKey]: {
        ...(typeof prev[parentKey] === "object" ? prev[parentKey] : {}),
        [childKey]: value,
      },
    }));
    setIsDirty(true);
  };

  const handleSave = async () => {
    try {
      for (const [key, value] of Object.entries(editedSettings)) {
        if (JSON.stringify(value) !== JSON.stringify(settings[key])) {
          await saveModuleSetting.mutateAsync({ moduleId, key, value });
        }
      }
      setIsDirty(false);
    } catch (err) {
      console.error("Error saving settings:", err);
    }
  };

  if (isLoading) {
    return (
      <div className="flex items-center justify-center py-12">
        <Loader2 className="h-6 w-6 animate-spin text-muted-foreground" />
      </div>
    );
  }

  if (error) {
    return (
      <Alert variant="destructive">
        <AlertCircle className="h-4 w-4" />
        <AlertDescription>
          Ошибка при загрузке настроек модуля: {error instanceof Error ? error.message : "Unknown error"}
        </AlertDescription>
      </Alert>
    );
  }

  return (
    <div className="space-y-6">
      {Object.entries(editedSettings).map(([groupKey, groupValue]) => {
        if (typeof groupValue !== "object" || groupValue === null || Array.isArray(groupValue)) return null;
        const groupLabel = GROUP_LABELS[groupKey] ?? groupKey;
        return (
          <Card key={groupKey}>
            <CardHeader className="pb-3">
              <CardTitle className="text-base">{groupLabel}</CardTitle>
            </CardHeader>
            <CardContent className="space-y-4">
              {Object.entries(groupValue as Record<string, unknown>).map(([fieldKey, fieldValue]) => (
                <SettingField
                  key={fieldKey}
                  fieldKey={fieldKey}
                  value={fieldValue}
                  onChange={(newValue) => handleNestedChange(groupKey, fieldKey, newValue)}
                />
              ))}
            </CardContent>
          </Card>
        );
      })}

      <div className="flex gap-2">
        <Button onClick={handleSave} disabled={!isDirty || saveModuleSetting.isPending}>
          {saveModuleSetting.isPending ? (
            <><Loader2 className="mr-2 h-4 w-4 animate-spin" />Сохранение...</>
          ) : (
            <><Save className="mr-2 h-4 w-4" />Сохранить</>
          )}
        </Button>
        <Button
          variant="outline"
          onClick={() => { setEditedSettings(settings); setIsDirty(false); }}
          disabled={!isDirty}
        >
          Отменить
        </Button>
      </div>

      {saveModuleSetting.isError && (
        <Alert variant="destructive">
          <AlertCircle className="h-4 w-4" />
          <AlertDescription>Ошибка при сохранении настроек</AlertDescription>
        </Alert>
      )}
    </div>
  );
}

interface SettingFieldProps {
  fieldKey: string;
  value: unknown;
  onChange: (value: unknown) => void;
}

function SettingField({ fieldKey, value, onChange }: SettingFieldProps) {
  const label = FIELD_LABELS[fieldKey] ?? fieldKey.replace(/([A-Z])/g, ' $1').trim();

  // Массивы и вложенные объекты не редактируются напрямую
  if (Array.isArray(value) || (typeof value === 'object' && value !== null)) return null;

  if (typeof value === "boolean") {
    return (
      <div className="flex items-center justify-between py-1">
        <Label htmlFor={fieldKey} className="font-normal cursor-pointer">{label}</Label>
        <Switch id={fieldKey} checked={value} onCheckedChange={onChange} />
      </div>
    );
  }

  if (typeof value === "number") {
    return (
      <div className="flex items-center justify-between gap-4">
        <Label htmlFor={fieldKey} className="font-normal flex-1">{label}</Label>
        <Input
          id={fieldKey}
          type="number"
          value={value}
          onChange={(e) => onChange(Number(e.target.value))}
          className="w-32 text-right"
        />
      </div>
    );
  }

  if (typeof value === "string") {
    return (
      <div className="flex items-center justify-between gap-4">
        <Label htmlFor={fieldKey} className="font-normal flex-1">{label}</Label>
        <Input
          id={fieldKey}
          type="text"
          value={value}
          onChange={(e) => onChange(e.target.value)}
          className="w-48"
        />
      </div>
    );
  }

  return null;
}

