import { useState, useEffect, useCallback } from 'react';
import { Plus, Trash2, Edit2, Check, X, Users } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Textarea } from '@/components/ui/textarea';
import { Badge } from '@/components/ui/badge';
import { Switch } from '@/components/ui/switch';
import { useTranslation } from '@/lib/i18n';
import { api } from '@/lib/api';
import { cn } from '@/lib/utils';
import { toast } from 'sonner';

interface Role {
  id: string;
  name: string;
  description?: string;
  permissions: string[];
  userCount?: number;
  createdAt?: string;
}

interface Permission {
    id: string;
    name: string;
}

interface RoleEditorProps {
  selectedModule: string;
}

export function RoleEditor({ selectedModule }: RoleEditorProps) {
  const { t } = useTranslation();
  
  // Получение переведённого названия права
  const getPermissionName = (permissionId: string, permission?: Permission) => {
    // Пробуем получить перевод из settings.permissions.permission_names
    const translationKey = `settings.permissions.permission_names.${permissionId}`;
    const translatedName = t(translationKey);
    
    // Если перевод есть, используем его
    if (translatedName && !translatedName.startsWith(translationKey)) {
      return translatedName;
    }
    
    // Иначе используем name из availablePermissions или возвращаем id
    return permission?.name || permissionId;
  };
  const [roles, setRoles] = useState<Role[]>([]);
  const [availablePermissions, setAvailablePermissions] = useState<Permission[]>([]);
  const [loading, setLoading] = useState(true);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editData, setEditData] = useState<Partial<Role>>({});
  const [isAdding, setIsAdding] = useState(false);
  const [newRole, setNewRole] = useState<Partial<Role>>({
    permissions: []
  });

  const loadData = useCallback(async () => {
    try {
      setLoading(true);
      const [rolesData, permissionsData] = await Promise.all([
          api.get('/roles'),
          api.get('/permissions')
      ]);
      
      // Гарантированно парсим permissions как массив
      const parsedRoles = (rolesData || []).map((role: any) => {
        let perms = role.permissions;
        if (typeof perms === 'string') {
          try { perms = JSON.parse(perms); } catch (e) { perms = []; }
        }
        if (!Array.isArray(perms)) perms = [];
        return { ...role, permissions: perms };
      });
      
      console.log('[RoleEditor] Загружены роли:', parsedRoles.map(r => ({ id: r.id, name: r.name, permsCount: r.permissions.length })));
      setRoles(parsedRoles);
      setAvailablePermissions(permissionsData);
    } catch (error) {
      console.error('Failed to load roles:', error);
      toast.error(t('generated.oshibka_zagruzki_roley'));
    } finally {
      setLoading(false);
    }
  }, [t]);

  useEffect(() => {
    loadData();
  }, [loadData]);

  const handleEdit = (role: Role) => {
    setEditingId(role.id);
    // Убедимся что permissions - массив
    const permissions = Array.isArray(role.permissions) 
      ? [...role.permissions] 
      : (typeof role.permissions === 'string' ? JSON.parse(role.permissions) : []);
    setEditData({ 
      id: role.id,
      name: role.name, 
      description: role.description,
      permissions
    });
  };

  const handleSaveEdit = async () => {
    if (!editData.name?.trim()) return;

    try {
      const updated = await api.put(`/roles/${editingId}`, editData);
      
      // Парсим permissions
      const perms = typeof updated.permissions === 'string' 
        ? JSON.parse(updated.permissions) 
        : (Array.isArray(updated.permissions) ? updated.permissions : []);
      
      setRoles(roles.map(r => r.id === editingId ? { ...updated, permissions: perms } : r));
      setEditingId(null);
      setEditData({});
      toast.success(t('generated.rol_obnovlena'));
    } catch (error) {
      console.error('Failed to update role:', error);
      toast.error(t('generated.oshibka_obnovleniya'));
    }
  };

  const handleCancelEdit = () => {
    setEditingId(null);
    setEditData({});
  };

  const handleAdd = async () => {
    if (!newRole.name?.trim()) return;

    try {
      const created = await api.post('/roles', newRole);
      
      // Парсим permissions
      const perms = typeof created.permissions === 'string' 
        ? JSON.parse(created.permissions) 
        : (Array.isArray(created.permissions) ? created.permissions : []);
      
      setRoles([...roles, { ...created, permissions: perms }]);
      setNewRole({ permissions: [] });
      setIsAdding(false);
      toast.success(t('generated.rol_sozdana'));
    } catch (error) {
      console.error('Failed to create role:', error);
      toast.error(t('generated.oshibka_sozdaniya'));
    }
  };

  const handleDelete = async (id: string) => {
    if (!confirm(t('generated.vy_uvereny_chto_hotite_udalit_etu_rol'))) return;
    
    try {
      await api.delete(`/roles/${id}`);
      setRoles(roles.filter(r => r.id !== id));
      toast.success(t('generated.rol_udalena'));
    } catch (error: unknown) {
      console.error('Failed to delete role:', error);
      toast.error(error instanceof Error ? error.message : t('generated.oshibka_udaleniya'));
    }
  };

  const togglePermission = (permissionId: string, context: 'new' | 'edit') => {
    if (context === 'new') {
      const currentPermissions = newRole.permissions || [];
      const updated = currentPermissions.includes(permissionId)
        ? currentPermissions.filter(p => p !== permissionId)
        : [...currentPermissions, permissionId];
      setNewRole({ ...newRole, permissions: updated });
    } else {
      const currentPermissions = editData.permissions || [];
      const updated = currentPermissions.includes(permissionId)
        ? currentPermissions.filter(p => p !== permissionId)
        : [...currentPermissions, permissionId];
      setEditData({ ...editData, permissions: updated });
    }
  };

  const hasPermission = (permissionId: string, role: Role | Partial<Role>) => {
    const perms = role.permissions || [];
    
    // Проверяем глобальный wildcard
    if (perms.includes('*')) return true;
    
    // Проверяем точное совпадение
    if (perms.includes(permissionId)) return true;
    
    // Проверяем wildcard модуля (например 'users.*' покрывает 'users.read', 'users.write')
    const [resource] = permissionId.split('.');
    const wildcardPermission = `${resource}.*`;
    if (perms.includes(wildcardPermission)) return true;
    
    return false;
  };

  const getRoleColor = (roleName: string) => {
    if(!roleName) return 'bg-gray-100 text-gray-800';
    switch (roleName.toLowerCase()) {
      case t('generated.rol_administrator').toLowerCase():
      case t('settings.users.admin').toLowerCase():
      case 'admin':
      case 'administrator':
        return 'bg-red-100 text-red-800';
      case t('generated.rol_menedzher').toLowerCase():
      case t('settings.users.manager').toLowerCase():
      case 'manager':
        return 'bg-blue-100 text-blue-800';
      case t('generated.rol_polzovatel').toLowerCase():
      case t('settings.users.user').toLowerCase():
      case 'user':
        return 'bg-green-100 text-green-800';
      default: return 'bg-gray-100 text-gray-800';
    }
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center py-8">
        <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary"></div>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <h3 className="text-lg font-medium">
          {t('generated.upravlenie_rolyami')}
        </h3>
        <Button
          variant="outline"
          size="sm"
          onClick={() => setIsAdding(true)}
          disabled={isAdding}
        >
          <Plus className="w-4 h-4 mr-1" />
          {t('generated.dobavit_rol')}
        </Button>
      </div>

      {/* Add new role form */}
      {isAdding && (
        <div className="p-4 rounded-lg border border-primary bg-primary/5 space-y-4">
          <h4 className="font-medium">{t('generated.novaya_rol')}</h4>
          <div className="space-y-3">
            <Input
              value={newRole.name || ''}
              onChange={(e) => setNewRole({ ...newRole, name: e.target.value })}
              placeholder={t('generated.nazvanie_roli')}
            />
            <Textarea
              value={newRole.description || ''}
              onChange={(e) => setNewRole({ ...newRole, description: e.target.value })}
              placeholder={t('generated.opisanie_roli')}
              rows={2}
            />
            
            <div>
              <h5 className="text-sm font-medium mb-2">{t('generated.prava_dostupa')}</h5>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-2 max-h-60 overflow-y-auto">
                {availablePermissions.map(permission => (
                  <div key={permission.id} className="flex items-center space-x-2">
                    <Switch
                      checked={hasPermission(permission.id, newRole)}
                      onCheckedChange={() => togglePermission(permission.id, 'new')}
                    />
                    <span className="text-sm" title={permission.id}>{getPermissionName(permission.id, permission)}</span>
                  </div>
                ))}
              </div>
            </div>
          </div>
          
          <div className="flex gap-2">
            <Button variant="outline" size="sm" onClick={handleAdd}>
              <Check className="w-4 h-4 mr-1 text-green-500" />
              {t('generated.sohranit')}
            </Button>
            <Button variant="ghost" size="sm" onClick={() => setIsAdding(false)}>
              <X className="w-4 h-4 mr-1 text-destructive" />
              {t('generated.otmena')}
            </Button>
          </div>
        </div>
      )}

      {/* Roles list */}
      <div className="space-y-3">
        {roles.map(role => (
          <div
            key={role.id}
            className="p-4 rounded-lg border border-border bg-card"
          >
            {editingId === role.id ? (
              <div className="space-y-4">
                <Input
                  value={editData.name || ''}
                  onChange={(e) => setEditData({ ...editData, name: e.target.value })}
                  placeholder={t('generated.nazvanie_roli')}
                />
                <Textarea
                  value={editData.description || ''}
                  onChange={(e) => setEditData({ ...editData, description: e.target.value })}
                  placeholder={t('generated.opisanie_roli')}
                  rows={2}
                />
                
                <div>
                  <h5 className="text-sm font-medium mb-2">{t('generated.prava_dostupa')}</h5>
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-2 max-h-60 overflow-y-auto">
                    {availablePermissions.map(permission => (
                      <div key={permission.id} className="flex items-center space-x-2">
                        <Switch
                          checked={hasPermission(permission.id, editData)}
                          onCheckedChange={() => togglePermission(permission.id, 'edit')}
                        />
                        <span className="text-sm" title={permission.id}>{getPermissionName(permission.id, permission)}</span>
                      </div>
                    ))}
                  </div>
                </div>
                
                <div className="flex gap-2">
                  <Button variant="outline" size="sm" onClick={handleSaveEdit}>
                    <Check className="w-4 h-4 mr-1 text-green-500" />
                    {t('generated.sohranit')}
                  </Button>
                  <Button variant="ghost" size="sm" onClick={handleCancelEdit}>
                    <X className="w-4 h-4 mr-1 text-destructive" />
                    {t('generated.otmena')}
                  </Button>
                </div>
              </div>
            ) : (
              <div className="flex items-start justify-between">
                <div className="flex-1">
                  <div className="flex items-center gap-2 mb-2">
                    <h4 className="font-medium">{role.name}</h4>
                    <Badge className={cn("text-xs", getRoleColor(role.name))}>
                      {(role.permissions || []).length} {t('generated.prav')}
                    </Badge>
                    <Badge variant="outline" className="text-xs">
                      <Users className="w-3 h-3 mr-1" />
                      {role.userCount || 0} {t('generated.pol_zovateley')}
                    </Badge>
                  </div>
                  {role.description && (
                    <p className="text-sm text-muted-foreground mb-3">{role.description}</p>
                  )}
                  
                  <div className="flex flex-wrap gap-1">
                    {(role.permissions || []).slice(0, 5).map(permissionId => {
                      const permission = availablePermissions.find(p => p.id === permissionId);
                      return (
                        <Badge key={permissionId} variant="secondary" className="text-xs" title={permissionId}>
                          {permission ? getPermissionName(permissionId, permission) : permissionId}
                        </Badge>
                      );
                    })}
                    {(role.permissions || []).length > 5 && (
                      <Badge variant="secondary" className="text-xs">
                        +{(role.permissions || []).length - 5} {t('generated.esche')}
                      </Badge>
                    )}
                  </div>
                </div>
                
                <div className="flex items-center gap-1 ml-4">
                  <Button variant="ghost" size="icon" onClick={() => handleEdit(role)}>
                    <Edit2 className="w-4 h-4" />
                  </Button>
                  <Button variant="ghost" size="icon" onClick={() => handleDelete(role.id)}>
                    <Trash2 className="w-4 h-4 text-destructive" />
                  </Button>
                </div>
              </div>
            )}
          </div>
        ))}

        {roles.length === 0 && !isAdding && (
          <p className="text-center text-muted-foreground py-8">
            {t('generated.roli_ne_naydeny')}
          </p>
        )}
      </div>
    </div>
  );
}

