import { useTranslation } from '@/lib/i18n';
import { useState, useEffect } from 'react';
import { Search, RefreshCw, X, CheckCircle2 } from 'lucide-react';
import { Input } from '@/components/ui/input';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Checkbox } from '@/components/ui/checkbox';
import { api } from '@/lib/api';
import { toast } from 'sonner';
import { EnrichFieldDiff } from './types';

export function IndividualEnrichSection() {
  const { t } = useTranslation();
  const [query, setQuery]               = useState('');
  const [contractors, setContractors]   = useState<{ id: number; name: string; inn?: string }[]>([]);
  const [loadingList, setLoadingList]   = useState(false);
  const [selected, setSelected]         = useState<{ id: number; name: string; inn?: string } | null>(null);
  const [searching, setSearching]       = useState(false);
  const [diff, setDiff]                 = useState<Record<string, EnrichFieldDiff> | null>(null);
  const [raw, setRaw]                   = useState<Record<string, unknown> | null>(null);
  const [source, setSource]             = useState<string | null>(null);
  const [fieldSel, setFieldSel]         = useState<Set<string>>(new Set());
  const [applying, setApplying]         = useState(false);

  // поиск по нашей БД
  useEffect(() => {
    if (!query.trim()) { setContractors([]); return; }
    const t = setTimeout(async () => {
      setLoadingList(true);
      try {
        const data = await api.get(`/contractors?search=${encodeURIComponent(query)}&limit=20`);
        setContractors(Array.isArray(data) ? data : (data.contractors ?? data.data ?? []));
      } catch { setContractors([]); }
      finally { setLoadingList(false); }
    }, 350);
    return () => clearTimeout(t);
  }, [query]);

  const lookup = async (c: { id: number; name: string; inn?: string }) => {
    setSelected(c);
    setDiff(null);
    setRaw(null);
    setSource(null);
    setFieldSel(new Set());
    setSearching(true);
    try {
      const data = await api.get(`/enrichment/lookup/${c.id}`);
      setDiff(data.diff ?? null);
      setRaw(data.raw ?? null);
      setSource(data.source ?? null);
      const changed = Object.entries(data.diff ?? {})
        .filter(([, v]) => (v as EnrichFieldDiff).changed).map(([k]) => k);
      setFieldSel(new Set(changed));
    } catch (e: unknown) {
      toast.error(t('generated.oshibka_poiska') + (e instanceof Error ? e.message : String(e)));
    } finally { setSearching(false); }
  };

  const apply = async () => {
    if (!selected || !raw || fieldSel.size === 0) return;
    setApplying(true);
    try {
      await api.post(`/enrichment/apply/${selected.id}`, {
        fields: Array.from(fieldSel), source: source ?? 'admin', data: raw,
      });
      toast.success(t('generated.dannye_kontragenta_obnovleny'));
      setDiff(null); setRaw(null); setSource(null); setFieldSel(new Set());
    } catch (e: unknown) {
      toast.error(t('generated.oshibka') + (e instanceof Error ? e.message : String(e)));
    } finally { setApplying(false); }
  };

  const toggle = (field: string) => {
    setFieldSel(prev => { const n = new Set(prev); n.has(field) ? n.delete(field) : n.add(field); return n; });
  };

  const changedRows = Object.entries(diff ?? {}).filter(([, v]) => v.changed);
  const sameRows    = Object.entries(diff ?? {}).filter(([, v]) => !v.changed && v.fetched);

  return (
    <div className="space-y-4">
      {/* Поиск по нашей БД */}
      <div className="relative">
        <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
        <Input
          value={query}
          onChange={e => setQuery(e.target.value)}
          placeholder={t('generated.nachnite_vvodit_nazvanie_inn_ili_ogrn')}
          className="pl-9"
        />
      </div>

      {loadingList && <p className="text-xs text-muted-foreground px-1">{t('generated.poisk')}</p>}

      {contractors.length > 0 && !selected && (
        <div className="border border-border rounded-lg overflow-hidden">
          {contractors.map(c => (
            <button
              key={c.id}
              onClick={() => lookup(c)}
              className="w-full flex items-center justify-between px-4 py-2.5 text-sm hover:bg-muted/50 border-b border-border last:border-0 text-left"
            >
              <span className="font-medium truncate">{c.name}</span>
              {c.inn && <span className="text-xs text-muted-foreground ml-3 shrink-0">ИНН {c.inn}</span>}
            </button>
          ))}
        </div>
      )}

      {selected && (
        <div className="space-y-3">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-2">
              <Badge variant="secondary" className="text-xs">{t('generated.vybran')}</Badge>
              <span className="text-sm font-medium">{selected.name}</span>
              {selected.inn && <span className="text-xs text-muted-foreground">ИНН {selected.inn}</span>}
            </div>
            <Button variant="ghost" size="sm" onClick={() => { setSelected(null); setDiff(null); setQuery(''); }}>
              <X className="w-4 h-4" />
            </Button>
          </div>

          {searching && (
            <div className="flex items-center gap-2 text-sm text-muted-foreground py-4">
              <RefreshCw className="w-4 h-4 animate-spin" /> {t('generated.ischem_dannye_v_reestre')}
            </div>
          )}

          {diff && (
            <div className="space-y-3">
              <div className="flex items-center gap-2 text-sm text-muted-foreground">
                {t('generated.istochnik')} <Badge variant="outline" className="text-xs">{source}</Badge>
                {changedRows.length > 0 && <span className="text-emerald-600 ml-1">· {changedRows.length} отличий</span>}
              </div>

              {changedRows.length > 0 ? (
                <>
                  <div className="rounded-md border border-border overflow-hidden text-xs">
                    <table className="w-full">
                      <thead>
                        <tr className="border-b bg-muted/40">
                          <th className="w-10 px-3 py-2">
                            <Checkbox
                              checked={changedRows.length > 0 && changedRows.every(([f]) => fieldSel.has(f))}
                              onCheckedChange={checked => {
                                if (checked) setFieldSel(new Set(changedRows.map(([f]) => f)));
                                else setFieldSel(new Set());
                              }}
                            />
                          </th>
                          <th className="px-3 py-2 text-left text-muted-foreground font-medium">{t('generated.pole')}</th>
                          <th className="px-3 py-2 text-left text-muted-foreground font-medium">{t('generated.seychas_v_bd')}</th>
                          <th className="px-3 py-2 text-left text-muted-foreground font-medium">{t('generated.naydeno')}</th>
                        </tr>
                      </thead>
                      <tbody>
                        {changedRows.map(([field, v]) => (
                          <tr
                            key={field}
                            className={`border-b last:border-0 cursor-pointer hover:bg-muted/30 ${fieldSel.has(field) ? 'bg-emerald-500/5' : ''}`}
                            onClick={() => toggle(field)}
                          >
                            <td className="px-3 py-2" onClick={e => e.stopPropagation()}>
                              <Checkbox checked={fieldSel.has(field)} onCheckedChange={() => toggle(field)} />
                            </td>
                            <td className="px-3 py-2 font-medium text-muted-foreground whitespace-nowrap">{v.label}</td>
                            <td className="px-3 py-2 text-muted-foreground/60 max-w-[120px] truncate">{v.current || <span className="italic">{t('generated.pusto')}</span>}</td>
                            <td className="px-3 py-2 text-emerald-600 font-medium max-w-[160px] truncate">{v.fetched}</td>
                          </tr>
                        ))}
                        {sameRows.map(([field, v]) => (
                          <tr key={field} className="border-b last:border-0 opacity-40">
                            <td className="px-3 py-2"><Checkbox checked={false} disabled /></td>
                            <td className="px-3 py-2 font-medium text-muted-foreground whitespace-nowrap">{v.label}</td>
                            <td className="px-3 py-2 text-muted-foreground/60 max-w-[120px] truncate" colSpan={2}>
                              {v.fetched} <span className="italic">{t('generated.sovpadaet')}</span>
                            </td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>

                  <Button
                    onClick={apply}
                    disabled={applying || fieldSel.size === 0}
                    className="w-full gap-2 bg-emerald-600 hover:bg-emerald-700 text-white"
                  >
                    {applying ? <RefreshCw className="w-4 h-4 animate-spin" /> : <CheckCircle2 className="w-4 h-4" />}
                    Сохранить выбранные поля в БД ({fieldSel.size} из {changedRows.length})
                  </Button>
                </>
              ) : (
                <div className="text-center py-6 text-muted-foreground text-sm">
                  <CheckCircle2 className="w-8 h-8 mx-auto mb-2 text-emerald-500 opacity-60" />
                  {t('generated.vse_dannye_aktual_ny')}
                </div>
              )}
            </div>
          )}
        </div>
      )}
    </div>
  );
}

// frontend/src/modules/settings/components/system/enrichment/useBatchEnrich.ts
import { useState, useCallback, useEffect, useRef } from "react";
import { useTranslation } from "@/lib/i18n";
import { api } from "@/lib/api";
import { toast } from "sonner";
import { EnrichResult, SelectionMap, JobStatus, ENRICH_JOB_KEY } from "./types";

export function useBatchEnrich() {
  const { t } = useTranslation();
  const [jobId, setJobId] = useState<string | null>(() =>
    localStorage.getItem(ENRICH_JOB_KEY),
  );
  const [jobStatus, setJobStatus] = useState<JobStatus>("idle");
  const [progress, setProgress] = useState(0);
  const [total, setTotal] = useState(0);
  const [skipCount, setSkipCount] = useState(0);
  const [currentName, setCurrentName] = useState<string | null>(null);
  const [results, setResults] = useState<EnrichResult[]>([]);
  const [selection, setSelection] = useState<SelectionMap>({});
  const [applying, setApplying] = useState(false);
  const [expandedId, setExpandedId] = useState<number | null>(null);
  const [skipFull, setSkipFull] = useState(true);
  const pollRef = useRef<ReturnType<typeof setInterval> | null>(null);

  const autoSelect = (res: EnrichResult[]) => {
    const sel: SelectionMap = {};
    for (const r of res) {
      if (r.diff) {
        const changed = Object.entries(r.diff)
          .filter(([, v]) => v.changed)
          .map(([k]) => k);
        if (changed.length) sel[r.contractorId] = new Set(changed);
      }
    }
    setSelection(sel);
  };

  const stopPolling = () => {
    if (pollRef.current) {
      clearInterval(pollRef.current);
      pollRef.current = null;
    }
  };

  const startPolling = useCallback(
    (id: string) => {
      stopPolling();
      pollRef.current = setInterval(async () => {
        try {
          const data = await api.get(`/enrichment/batch-lookup/status/${id}`);
          const freshResults: EnrichResult[] = data.results ?? [];
          setProgress(data.progress ?? 0);
          setTotal(data.total ?? 0);
          setSkipCount(data.skipCount ?? 0);
          setCurrentName(data.currentName ?? null);
          setResults(freshResults);
          setJobStatus(data.status as JobStatus);
          if (freshResults.length > 0) {
            const currentIds = new Set(freshResults.map((r) => r.contractorId));
            setSelection((prev) => {
              const cleaned: SelectionMap = {};
              for (const [idStr, set] of Object.entries(prev)) {
                if (currentIds.has(Number(idStr))) cleaned[Number(idStr)] = set;
              }
              return cleaned;
            });
          }
          if (
            data.status === "done" ||
            data.status === "error" ||
            data.status === "paused"
          ) {
            stopPolling();
            if (data.status === "done" || data.status === "paused")
              autoSelect(data.results ?? []);
            if (data.status === "error")
              toast.error(t("generated.oshibka_zadachi") + data.error);
            if (data.status === "paused")
              toast.info(
                t("generated.zadacha_ostanovlena_nazhmite_prodolzhit"),
              );
          }
        } catch {
          /* сервер недоступен — ждём */
        }
      }, 1500);
    },
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [],
  );

  useEffect(() => {
    const savedId = localStorage.getItem(ENRICH_JOB_KEY);
    if (savedId) {
      api
        .get(`/enrichment/batch-lookup/status/${savedId}`)
        .then((data) => {
          setProgress(data.progress ?? 0);
          setTotal(data.total ?? 0);
          setSkipCount(data.skipCount ?? 0);
          setResults(data.results ?? []);
          setJobStatus(data.status as JobStatus);
          setCurrentName(data.currentName ?? null);
          if (data.status === "running" || data.status === "pending") {
            setJobId(savedId);
            startPolling(savedId);
          } else if (data.status === "done" || data.status === "paused") {
            autoSelect(data.results ?? []);
          }
        })
        .catch(() => localStorage.removeItem(ENRICH_JOB_KEY));
    }
    return () => stopPolling();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const cancelTracking = () => {
    stopPolling();
    localStorage.removeItem(ENRICH_JOB_KEY);
    setJobId(null);
    setJobStatus("idle");
    setProgress(0);
    setTotal(0);
    setSkipCount(0);
    setCurrentName(null);
    setResults([]);
    setSelection({});
  };

  const run = async () => {
    try {
      const data = await api.post("/enrichment/batch-lookup/start", {
        skipFull,
      });
      if (!data.jobId) {
        toast.error(data.message ?? t('settings.enrichment.no_inn'));
        return;
      }
      localStorage.setItem(ENRICH_JOB_KEY, data.jobId);
      setJobId(data.jobId);
      setJobStatus("pending");
      setProgress(0);
      setTotal(data.total ?? 0);
      setSkipCount(0);
      setResults([]);
      setSelection({});
      setExpandedId(null);
      startPolling(data.jobId);
    } catch (e: unknown) {
      const err = e as {
        status?: number;
        jobId?: string;
        error?: string;
        paused?: boolean;
      };
      if (err.status === 409 && err.jobId) {
        if (err.paused) {
          localStorage.setItem(ENRICH_JOB_KEY, err.jobId);
          setJobId(err.jobId);
          const data = await api.get(
            `/enrichment/batch-lookup/status/${err.jobId}`,
          );
          const res = data.results ?? [];
          setProgress(data.progress ?? 0);
          setTotal(data.total ?? 0);
          setSkipCount(data.skipCount ?? 0);
          setResults(res);
          setJobStatus("paused");
          autoSelect(res);
          toast.info(
            t("generated.est_priostanovlennaya_zadacha_prodolzhit"),
          );
        } else {
          toast.info(
            t("generated.podklyuchaemsya_k_aktivnoy_zadache"),
          );
          localStorage.setItem(ENRICH_JOB_KEY, err.jobId);
          setJobId(err.jobId);
          setJobStatus("running");
          startPolling(err.jobId);
        }
        return;
      }
      if ((err as { status?: number }).status === 409) {
        if (
          confirm(t("generated.v_baze_est_zavisshaya_zadacha_obogaschen"))
        ) {
          await api.post("/enrichment/batch-lookup/reset", {});
          cancelTracking();
          toast.info(t("generated.zadacha_sbroshena_nazhmite_zapustit_snov"));
        }
        return;
      }
      toast.error(
        t("generated.oshibka_zapuska") +
          (e instanceof Error ? e.message : String(e)),
      );
    }
  };

  const stopJob = async () => {
    try {
      await api.post("/enrichment/batch-lookup/stop", {});
      stopPolling();
      setJobStatus("paused");
      toast.info(t("generated.zadacha_budet_ostanovlena_posle_tekusche"));
    } catch (e: unknown) {
      toast.error(
        t("generated.oshibka") +
          (e instanceof Error ? e.message : String(e)),
      );
    }
  };

  const finishJob = async () => {
    if (!confirm(t("generated.zavershit_zadachu_tekuschie_naydennye_iz")))
      return;
    try {
      await api.post("/enrichment/batch-lookup/finish", {});
      stopPolling();
      setJobStatus("done");
      toast.success(t("generated.zadacha_zavershena_mozhno_sohranit_nayde"));
    } catch (e: unknown) {
      toast.error(
        t("generated.oshibka") +
          (e instanceof Error ? e.message : String(e)),
      );
    }
  };

  const continueJob = async () => {
    try {
      const data = await api.post("/enrichment/batch-lookup/continue", {
        skipFull,
      });
      if (!data.jobId) {
        toast.error(data.message ?? t('settings.enrichment.no_task'));
        return;
      }
      setJobStatus("pending");
      setTotal(data.total ?? 0);
      toast.success(t("generated.zadacha_vozobnovlena"));
      startPolling(data.jobId);
    } catch (e: unknown) {
      toast.error(
        t("generated.oshibka") +
          (e instanceof Error ? e.message : String(e)),
      );
    }
  };

  const resetJob = async () => {
    if (!confirm(t("generated.sbrosit_zavisshuyu_zadachu_i_zapustit_za")))
      return;
    try {
      await api.post("/enrichment/batch-lookup/reset", {});
      cancelTracking();
      toast.success(t("generated.zadacha_sbroshena"));
    } catch (e: unknown) {
      toast.error(
        t("generated.oshibka_sbrosa") +
          (e instanceof Error ? e.message : String(e)),
      );
    }
  };

  const toggleField = (contractorId: number, field: string) => {
    setSelection((prev) => {
      const n = { ...prev };
      const s = new Set(n[contractorId] ?? []);
      s.has(field) ? s.delete(field) : s.add(field);
      n[contractorId] = s;
      return n;
    });
  };

  const toggleAll = (contractorId: number, fields: string[]) => {
    setSelection((prev) => {
      const s = prev[contractorId] ?? new Set();
      const all = fields.every((f) => s.has(f));
      return {
        ...prev,
        [contractorId]: all ? new Set() : new Set(fields),
      };
    });
  };

  const applySelected = async () => {
    const items: {
      contractorId: number;
      fields: string[];
      source: string;
      data: Record<string, unknown>;
    }[] = [];
    for (const r of results) {
      const fields = Array.from(selection[r.contractorId] ?? []);
      if (fields.length && r.raw)
        items.push({
          contractorId: r.contractorId,
          fields,
          source: r.source ?? "admin-batch",
          data: r.raw,
        });
    }
    if (!items.length) {
      toast.error(t("generated.net_vybrannyh_izmeneniy"));
      return;
    }
    setApplying(true);
    try {
      const res = await api.post("/enrichment/batch-apply", { items });
      const savedCount = items.length;
      toast.success(
        `Сохранено: ${savedCount} контрагентов. Обновленных полей: ${res.applied}${res.errors?.length ? `, ошибок: ${res.errors.length}` : ""}`,
      );
      setResults([]);
      setSelection({});
      toast.info(t('settings.enrichment.excluded'));
    } catch (e: unknown) {
      toast.error(
        t("generated.oshibka") +
          (e instanceof Error ? e.message : String(e)),
      );
    } finally {
      setApplying(false);
    }
  };

  const withChanges = results.filter((r) => r.changedCount && r.changedCount > 0);
  const withErrors = results.filter((r) => r.error);
  const noChanges = results.filter(
    (r) => !r.error && (!r.changedCount || r.changedCount === 0),
  );
  const totalSelected = withChanges.reduce(
    (s, r) => s + (selection[r.contractorId]?.size ?? 0),
    0,
  );
  const isRunning = jobStatus === "running" || jobStatus === "pending";
  const isPaused = jobStatus === "paused";
  const pct = total > 0 ? Math.round((progress / total) * 100) : 0;

  void jobId; // suppress unused warning

  return {
    t,
    jobStatus,
    progress,
    total,
    skipCount,
    currentName,
    results,
    selection,
    applying,
    expandedId,
    setExpandedId,
    skipFull,
    setSkipFull,
    withChanges,
    withErrors,
    noChanges,
    totalSelected,
    isRunning,
    isPaused,
    pct,
    run,
    stopJob,
    finishJob,
    continueJob,
    resetJob,
    cancelTracking,
    toggleField,
    toggleAll,
    applySelected,
  };
}

import { CheckCircle2, XCircle, AlertCircle } from 'lucide-react';
import { format } from 'date-fns';
import { ru } from 'date-fns/locale';

export function StatusDot({ status }: { status: string }) {
  if (status === 'ok') return <CheckCircle2 className="w-4 h-4 text-green-500" />;
  if (status === 'error') return <XCircle className="w-4 h-4 text-red-500" />;
  return <AlertCircle className="w-4 h-4 text-yellow-500" />;
}

export function LevelBadge({ level }: { level: string }) {
  const variants: Record<string, string> = {
    error:   'bg-red-100 text-red-700 border-red-200',
    warn:    'bg-yellow-100 text-yellow-700 border-yellow-200',
    warning: 'bg-yellow-100 text-yellow-700 border-yellow-200',
    info:    'bg-blue-100 text-blue-700 border-blue-200',
    debug:   'bg-gray-100 text-gray-600 border-gray-200',
    http:    'bg-purple-100 text-purple-700 border-purple-200',
  };
  const cls = variants[level?.toLowerCase()] ?? 'bg-gray-100 text-gray-600';
  return (
    <span className={`inline-flex items-center px-1.5 py-0.5 rounded text-xs font-medium border ${cls}`}>
      {level}
    </span>
  );
}

export function formatDate(d: string | null | undefined) {
  if (!d) return '—';
  try { return format(new Date(d), 'dd.MM.yy HH:mm', { locale: ru }); } catch { return d; }
}

export function ProgressBar({ value }: { value: number }) {
  const color = value > 85 ? 'bg-red-500' : value > 60 ? 'bg-yellow-500' : 'bg-green-500';
  return (
    <div className="w-full bg-muted rounded-full h-2 mt-1">
      <div className={`h-2 rounded-full ${color} transition-all`} style={{ width: `${Math.min(value, 100)}%` }} />
    </div>
  );
}

