import { useState, useEffect, useCallback } from "react";
import { toast } from "sonner";
import { useTranslation } from "@/lib/i18n";
import {
  StatusItem,
  TagItem,
  PriorityItem,
  QuickAction,
  RelationshipTypeItem,
  UserSettings,
  Theme,
} from "../types/settings.types";
import { settingsService } from "../api/settingsService";

const STORAGE_KEYS = {
  theme: 'titan_theme',
  accentColor: 'titan_accent_color',
  sidebarCollapsed: 'titan_sidebar_collapsed',
};

interface UseSettingsReturn {
  // Data
  statuses: StatusItem[];
  tags: TagItem[];
  priorities: PriorityItem[];
  quickActions: QuickAction[];
  relationshipTypes: RelationshipTypeItem[];
  
  // UI State
  theme: Theme;
  accentColor: string;
  sidebarCollapsed: boolean;
  
  // Loading
  loading: boolean;
  error: Error | null;
  
  // Actions
  setTheme: (theme: Theme) => void;
  setAccentColor: (color: string) => void;
  setSidebarCollapsed: (collapsed: boolean) => void;
  refreshData: () => Promise<void>;
}

export function useSettings(): UseSettingsReturn {
  const { t } = useTranslation();
  
  // Data states
  const [statuses, setStatuses] = useState<StatusItem[]>([]);
  const [tags, setTags] = useState<TagItem[]>([]);
  const [priorities, setPriorities] = useState<PriorityItem[]>([]);
  const [quickActions, setQuickActions] = useState<QuickAction[]>([]);
  const [relationshipTypes, setRelationshipTypes] = useState<RelationshipTypeItem[]>([]);
  
  // UI states from localStorage
  const [theme, setThemeState] = useState<Theme>(() => 
    (localStorage.getItem(STORAGE_KEYS.theme) as Theme) || 'light'
  );
  const [accentColor, setAccentColorState] = useState<string>(() => 
    localStorage.getItem(STORAGE_KEYS.accentColor) || 'blue'
  );
  const [sidebarCollapsed, setSidebarCollapsedState] = useState(() => {
    const saved = localStorage.getItem(STORAGE_KEYS.sidebarCollapsed);
    return saved === 'true';
  });
  
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<Error | null>(null);

  const setTheme = useCallback((newTheme: Theme) => {
    setThemeState(newTheme);
    document.documentElement.classList.toggle('dark', newTheme === 'dark');
    localStorage.setItem(STORAGE_KEYS.theme, newTheme);
    settingsService.updateUserSetting(STORAGE_KEYS.theme, newTheme).catch(console.error);
  }, []);

  const setAccentColor = useCallback((newColor: string) => {
    setAccentColorState(newColor);
    localStorage.setItem(STORAGE_KEYS.accentColor, newColor);
    settingsService.updateUserSetting(STORAGE_KEYS.accentColor, newColor).catch(console.error);
  }, []);

  const setSidebarCollapsed = useCallback((collapsed: boolean) => {
    setSidebarCollapsedState(collapsed);
    localStorage.setItem(STORAGE_KEYS.sidebarCollapsed, String(collapsed));
    settingsService.updateUserSetting(STORAGE_KEYS.sidebarCollapsed, collapsed).catch(console.error);
  }, []);

  const refreshData = useCallback(async () => {
    try {
      setLoading(true);
      const [
        statusesData,
        tagsData,
        prioritiesData,
        quickActionsData,
        relationshipTypesData,
      ] = await Promise.all([
        settingsService.getStatuses(),
        settingsService.getTags(),
        settingsService.getPriorities(),
        settingsService.getQuickActions(),
        settingsService.getRelationshipTypes(),
      ]);
      
      setStatuses(statusesData);
      setTags(tagsData);
      setPriorities(prioritiesData);
      setQuickActions(quickActionsData);
      setRelationshipTypes(relationshipTypesData);
      setError(null);
    } catch (err) {
      setError(err instanceof Error ? err : new Error(String(err)));
      toast.error(t("general.toast.error.settings_load"));
    } finally {
      setLoading(false);
    }
  }, [t]);

  useEffect(() => {
    refreshData();
  }, [refreshData]);

  return {
    statuses,
    tags,
    priorities,
    quickActions,
    relationshipTypes,
    theme,
    accentColor,
    sidebarCollapsed,
    loading,
    error,
    setTheme,
    setAccentColor,
    setSidebarCollapsed,
    refreshData,
  };
}

import { Task } from "../types";
import { useTranslation } from "@/lib/i18n";

import {
  Table,
  TableBody,
  TableCell,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { Checkbox } from "@/components/ui/checkbox";
import { Avatar, AvatarFallback } from "@/components/ui/avatar";
import { StatusBadge, PriorityBadge } from "@/components/ui/status-system";
import { Button } from "@/components/ui/button";
import { QuickActionsMenu } from "@/components/ui/QuickActionsMenu";
import { SortableTableHead, TableUtilityHead } from "@/components/shared";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { MoreHorizontal, Calendar, ChevronRight, ChevronDown } from "lucide-react";
import { useState, Fragment, useCallback } from "react";
import { QuickAction } from "@/lib/settings-data";
import { useColumnDrag } from "@/hooks/useColumnDrag";

interface ReferenceOption {
    id: string;
    name: string;
}

interface TaskReferences {
    priorities?: ReferenceOption[];
    taskStatuses?: ReferenceOption[];
}

interface TaskListProps {
  tasks: Task[];
  selectedIds: Set<string | number>;
  visibleColumns: Record<string, boolean>;
  columnOrder?: string[];
  columnWidths?: Record<string, number>;
  onReorderColumn?: (fromKey: string, toKey: string) => void;
  onColumnResize?: (key: string, width: number) => void;
  sortConfig: { key: keyof Task; direction: 'asc' | 'desc' } | null;
  toggleSelection: (id: string) => void;
  toggleAllSelection: () => void;
  onSort: (key: keyof Task) => void;
  onEdit: (task: Task) => void;
  onDelete: (id: string) => void;
  onStatusChange: (id: string, status: Task['status']) => void;
  completedTaskId: string | null;
    references?: TaskReferences;
  quickActions: QuickAction[];
  onAction: (action: string, itemId: string | number) => void;
}

export function TaskList({
  tasks,
  selectedIds,
  visibleColumns,
  columnOrder,
  columnWidths,
  onReorderColumn,
  onColumnResize,
  sortConfig,
  toggleSelection,
  toggleAllSelection,
  onSort,
  onEdit,
  onDelete,
  onStatusChange,
  completedTaskId,
  references,
  quickActions,
  onAction
}: TaskListProps) {
  const { t } = useTranslation();
  const [expandedIds, setExpandedIds] = useState<Set<string>>(new Set());

  const handleReorder = useCallback((from: string, to: string) => {
    onReorderColumn?.(from, to);
  }, [onReorderColumn]);
  const { dragging, dragOver, onColumnMouseDown, onColumnMouseEnter } = useColumnDrag(handleReorder);

  const TASK_COLUMN_ORDER = ['id', 'title', 'status', 'priority', 'assignee', 'dueDate'];
  const effectiveColumnOrder = columnOrder ?? TASK_COLUMN_ORDER;

  const taskColumnLabels: Record<string, string> = {
    id: t('tasks.table.id'),
    title: t('tasks.table.title'),
    status: t('common.status'),
    priority: t('common.priority'),
    assignee: t('tasks.table.assignee'),
    dueDate: t('tasks.table.due_date'),
  };
  const taskSortKeys: Record<string, keyof Task> = {
    id: 'identifier', title: 'title', status: 'status',
    priority: 'priority', assignee: 'assignee', dueDate: 'dueDate',
  };

  const toggleExpand = (id: string) => {
    setExpandedIds(prev => {
        const newSet = new Set(prev);
        if (newSet.has(id)) newSet.delete(id);
        else newSet.add(id);
        return newSet;
    });
  };

  const renderRow = (task: Task) => {
    const hasSubTasks = task.subTasks && task.subTasks.length > 0;
    const isExpanded = expandedIds.has(task.id);

    return (
        <Fragment key={task.id}>
            <TableRow 
                className={`group hover:bg-muted/50 cursor-pointer transition-all duration-300 ${
                    completedTaskId === task.id ? "bg-green-50" : ""
                } ${selectedIds.has(task.id) ? "bg-muted" : ""}`}
                onClick={() => onEdit(task)}
            >
            <TableCell onClick={(e) => e.stopPropagation()}>
                <div className="flex items-center gap-2">
                    <Checkbox 
                        checked={selectedIds.has(task.id)}
                        onCheckedChange={() => toggleSelection(task.id)}
                    />
                    {hasSubTasks && (
                        <Button 
                            variant="ghost" 
                            size="icon" 
                            className="h-6 w-6"
                            onClick={(e) => {
                                e.stopPropagation();
                                toggleExpand(task.id);
                            }}
                        >
                            {isExpanded ? <ChevronDown className="h-4 w-4" /> : <ChevronRight className="h-4 w-4" />}
                        </Button>
                    )}
                </div>
            </TableCell>
            {effectiveColumnOrder.filter(key => visibleColumns[key]).map(key => {
                switch (key) {
                  case 'id': return (
                    <TableCell key="id" className={`font-mono text-xs text-muted-foreground ${task.status === "Done" ? "line-through opacity-60" : ""}`}>
                        {task.identifier}
                    </TableCell>
                  );
                  case 'title': return (
                    <TableCell key="title">
                        <div className="flex flex-col gap-0.5">
                        <span className={`font-medium text-sm text-foreground transition-all ${task.status === "Done" ? "line-through opacity-60 text-muted-foreground" : ""}`}>
                            {task.title}
                        </span>
                        <span className="text-xs text-muted-foreground">{task.project}</span>
                        </div>
                    </TableCell>
                  );
                  case 'status': return (
                    <TableCell key="status">
                        <StatusBadge statusId={task.status} />
                    </TableCell>
                  );
                  case 'priority': return (
                    <TableCell key="priority">
                        <PriorityBadge priorityId={task.priority} />
                    </TableCell>
                  );
                  case 'assignee': return (
                    <TableCell key="assignee">
                        <div className="flex items-center gap-2">
                        <Avatar className="h-6 w-6">
                            <AvatarFallback className="text-[10px] bg-primary/10 text-primary">
                            {task.assigneeInitials}
                            </AvatarFallback>
                        </Avatar>
                        <span className="text-sm text-muted-foreground group-hover:text-foreground transition-colors">
                            {task.assignee}
                        </span>
                        </div>
                    </TableCell>
                  );
                  case 'dueDate': return (
                    <TableCell key="dueDate">
                        <div className="flex items-center gap-2 text-sm text-muted-foreground">
                        <Calendar className="w-3.5 h-3.5" />
                        {task.dueDate}
                        </div>
                    </TableCell>
                  );
                  default: return null;
                }
              })}
            <TableCell onClick={(e) => e.stopPropagation()}>
                <div className="flex items-center gap-1">
                    <QuickActionsMenu
                        itemId={task.id}
                        itemName={task.title}
                        options={quickActions}
                        onAction={onAction}
                    />
                    <DropdownMenu>
                    <DropdownMenuTrigger asChild>
                        <Button variant="ghost" size="icon" className="h-8 w-8 opacity-0 group-hover:opacity-100 transition-opacity">
                        <MoreHorizontal className="w-4 h-4 text-muted-foreground" />
                        </Button>
                    </DropdownMenuTrigger>
                    <DropdownMenuContent align="end">
                        <DropdownMenuLabel>{t('common.actions')}</DropdownMenuLabel>
                        <DropdownMenuItem onClick={() => onEdit(task)}>{t('generated.redaktirovat')}</DropdownMenuItem>
                        <DropdownMenuItem onClick={() => onStatusChange(task.id, task.status === "Done" ? "To Do" : "Done")}>
                            {task.status === "Done" ? t('tasks.return_to_work') : t('tasks.complete')}
                        </DropdownMenuItem>
                    </DropdownMenuContent>
                    </DropdownMenu>
                </div>
            </TableCell>
            </TableRow>
            {isExpanded && task.subTasks?.map(sub => (
                <TableRow key={sub.id} className="bg-muted/10 hover:bg-muted/20">
                    <TableCell></TableCell>
                    <TableCell colSpan={effectiveColumnOrder.filter(key => visibleColumns[key]).length + 1} className="text-sm text-muted-foreground pl-8">
                        <div className="flex items-center gap-2">
                            <div className="w-2 h-2 border-l border-b border-muted-foreground/30 rounded-bl-sm"></div>
                            <span className={sub.completed ? "line-through opacity-50" : ""}>{sub.title}</span>
                        </div>
                    </TableCell>
                </TableRow>
            ))}
        </Fragment>
    );
  };

  return (
    <Table>
        <TableHeader className="sticky top-0 bg-background z-10">
        <TableRow>
            <TableUtilityHead className="w-16">
                <Checkbox 
                    checked={selectedIds.size === tasks.length && tasks.length > 0}
                    onCheckedChange={toggleAllSelection}
                />
            </TableUtilityHead>
            {effectiveColumnOrder.filter(key => visibleColumns[key]).map(key => (
                <SortableTableHead
                    key={key}
                    label={taskColumnLabels[key] ?? key}
                    onSort={() => onSort(taskSortKeys[key] ?? key as any)}
                    direction={sortConfig?.key === (taskSortKeys[key] ?? key) ? sortConfig.direction : null}
                    columnKey={key}
                    isDragging={dragging === key}
                    isDragOver={dragOver === key}
                    onColumnMouseDown={onColumnMouseDown}
                    onColumnMouseEnter={onColumnMouseEnter}
                    width={columnWidths?.[key]}
                    onResize={onColumnResize ? (w) => onColumnResize(key, w) : undefined}
                    className={key === 'id' ? 'w-[100px]' : key === 'title' ? 'min-w-[300px]' : undefined}
                />
            ))}
            <TableUtilityHead className="w-10" />
        </TableRow>
        </TableHeader>
        <TableBody>
        {tasks.map((task) => renderRow(task))}
        </TableBody>
    </Table>
  );
}

