import { useState, useEffect, useCallback } from "react";
import { toast } from "sonner";
import { useTranslation } from "@/lib/i18n";
import { Task } from "../types/task.types";
import { CreateTaskRequest } from "../types/api.types";
import { taskService } from "../api/taskService";

interface UseTasksReturn {
  tasks: Task[];
  loading: boolean;
  error: Error | null;
  fetchTasks: () => Promise<void>;
  createTask: (data: Partial<Task>) => Promise<Task | null>;
  updateTask: (id: string, data: Partial<Task>) => Promise<Task | null>;
  deleteTask: (id: string) => Promise<boolean>;
}

export function useTasks(): UseTasksReturn {
  const { t } = useTranslation();
  const [tasks, setTasks] = useState<Task[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<Error | null>(null);

  const fetchTasks = useCallback(async () => {
    try {
      setLoading(true);
      const data = await taskService.getAll();
      setTasks(data);
      setError(null);
    } catch (err) {
      setError(err instanceof Error ? err : new Error(String(err)));
      toast.error(t("general.toast.error.task_load"));
    } finally {
      setLoading(false);
    }
  }, [t]);

  const createTask = useCallback(
    async (data: Partial<Task>): Promise<Task | null> => {
      try {
        const newTask = await taskService.create(data as unknown as CreateTaskRequest);
        setTasks((prev) => [newTask, ...prev]);
        toast.success(t("general.toast.success.task_created"));
        return newTask;
      } catch (err) {
        toast.error(t("general.toast.error.task_save"));
        return null;
      }
    },
    [t]
  );

  const updateTask = useCallback(
    async (id: string, data: Partial<Task>): Promise<Task | null> => {
      try {
        const updatedTask = await taskService.update(id, { id, ...data });
        setTasks((prev) =>
          prev.map((t) => (t.id === id ? updatedTask : t))
        );
        toast.success(t("general.toast.success.task_updated"));
        return updatedTask;
      } catch (err) {
        toast.error(t("general.toast.error.task_save"));
        return null;
      }
    },
    [t]
  );

  const deleteTask = useCallback(
    async (id: string): Promise<boolean> => {
      try {
        await taskService.delete(id);
        setTasks((prev) => prev.filter((t) => t.id !== id));
        toast.success(t("general.toast.success.task_deleted"));
        return true;
      } catch (err) {
        toast.error(t("general.toast.error.task_delete"));
        return false;
      }
    },
    [t]
  );

  useEffect(() => {
    fetchTasks();
  }, [fetchTasks]);

  return {
    tasks,
    loading,
    error,
    fetchTasks,
    createTask,
    updateTask,
    deleteTask,
  };
}

import { api } from '@/lib/api';

export interface StepCondition {
  field: string;
  operator: string;
  value?: string;
}

export interface WorkflowStep {
  id?: string;
  workflow_id?: string;
  step_order: number;
  module: string;
  action: string;
  action_config: Record<string, any>;
  condition?: StepCondition | null;
  delay_seconds: number;
  on_fail: 'stop' | 'retry' | 'skip';
}

export interface Workflow {
  id?: string;
  name: string;
  description: string;
  trigger_type: 'schedule' | 'event' | 'webhook';
  trigger_config: Record<string, any>;
  status: 'draft' | 'active' | 'paused';
  steps?: WorkflowStep[];
  created_at?: string;
  updated_at?: string;
}

export interface RegistryAction {
  name: string;
  label: string;
  module: string;
  inputSchema: Record<string, any>;
  outputSchema?: {
    properties: Record<string, { type: string, label: string }>;
  };
}

// NOTE: api.ts already prepends /api, so paths here start with /workflows (not /api/workflows)
// api.get() returns the parsed JSON directly, not { data }

export const fetchWorkflows = async (): Promise<Workflow[]> => {
  const result = await api.get('/workflows');
  return result ?? [];
};

export const fetchWorkflowById = async (id: string): Promise<Workflow> => {
  const result = await api.get(`/workflows/${id}`);
  return result;
};

export const createWorkflow = async (workflowData: Partial<Workflow>): Promise<Workflow> => {
  const result = await api.post('/workflows', workflowData);
  return result;
};

export const updateWorkflow = async (id: string, workflowData: Partial<Workflow>): Promise<Workflow> => {
  const result = await api.put(`/workflows/${id}`, workflowData);
  return result;
};

export const deleteWorkflow = async (id: string): Promise<void> => {
  await api.delete(`/workflows/${id}`);
};

export const fetchRegistryActions = async (): Promise<RegistryAction[]> => {
  const result = await api.get('/workflows/registry/actions');
  return result ?? [];
};

import React, { useState } from 'react';
import { useSortable } from '@dnd-kit/sortable';
import { CSS } from '@dnd-kit/utilities';
import { GripVertical, Trash2, ChevronDown, ChevronUp, GitBranch } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Card, CardHeader, CardContent } from '@/components/ui/card';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Badge } from '@/components/ui/badge';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Switch } from '@/components/ui/switch';
import { useTranslation } from '@/lib/i18n';
import { RegistryAction, WorkflowStep, StepCondition } from '../api/workflowAPI';
import { VariablePicker } from './VariablePicker';

interface ExtendedStep extends WorkflowStep {
  id?: string;
  condition?: StepCondition | null;
}

interface StepConfigItemProps {
  step: ExtendedStep;
  index: number;
  allSteps: WorkflowStep[];
  availableActions: RegistryAction[];
  onUpdate: (index: number, updated: Partial<ExtendedStep>) => void;
  onRemove: (index: number) => void;
}

const OPERATOR_KEYS = [
  'exists', 'not_exists', 'equals', 'not_equals',
  'contains', 'not_contains', 'regex', 'gt', 'gte', 'lt', 'lte'
];

export const StepConfigItem: React.FC<StepConfigItemProps> = ({
  step, index, allSteps, availableActions, onUpdate, onRemove
}) => {
  const { t } = useTranslation();
  const [expanded, setExpanded]         = useState(true);
  const [showCondition, setShowCondition] = useState(!!step.condition?.field);

  const {
    attributes, listeners, setNodeRef, transform, transition, isDragging
  } = useSortable({ id: step.id || `step-${index}` });

  const style = {
    transform: CSS.Transform.toString(transform),
    transition,
    zIndex: isDragging ? 10 : 1,
    opacity: isDragging ? 0.85 : 1,
  };

  const config                = step.action_config || {};
  const modules               = Array.from(new Set(availableActions.map(a => a.module)));
  const currentModuleActions  = availableActions.filter(a => a.module === step.module);
  const currentActionDef      = currentModuleActions.find(a => a.name === step.action);
  const hasCondition          = showCondition && !!step.condition?.field;
  const needsValue            = !['exists', 'not_exists'].includes(step.condition?.operator || '');

  const toggleCondition = (enabled: boolean) => {
    setShowCondition(enabled);
    onUpdate(index, { condition: enabled ? { field: '', operator: 'exists', value: '' } : null } as any);
  };

  const updateCondition = (patch: Partial<StepCondition>) => {
    const current = step.condition || { field: '', operator: 'exists', value: '' };
    onUpdate(index, { condition: { ...current, ...patch } } as any);
  };

  return (
    <Card
      ref={setNodeRef}
      style={style}
      className={`relative mb-3 border transition-shadow ${isDragging ? 'shadow-xl border-primary' : 'shadow-sm'}`}
    >
      {/* Header */}
      <CardHeader className="p-3 flex flex-row items-center justify-between bg-slate-50 dark:bg-slate-900 rounded-t-lg border-b">
        <div className="flex items-center gap-2">
          <div {...attributes} {...listeners}
            className="cursor-move p-1.5 hover:bg-slate-200 dark:hover:bg-slate-700 rounded text-slate-400"
          >
            <GripVertical className="w-4 h-4" />
          </div>

          <Badge variant="outline" className="font-mono text-xs px-2">{index + 1}</Badge>

          <span className="font-semibold text-sm">
            {step.module && step.action
              ? `${step.module} → ${currentActionDef?.label || step.action}`
              : t('workflows.editor.new_step')}
          </span>

          {hasCondition && (
            <Badge variant="secondary" className="gap-1 text-xs">
              <GitBranch className="w-3 h-3" /> IF
            </Badge>
          )}
        </div>

        <div className="flex items-center gap-1">
          <Button variant="ghost" size="sm"
            onClick={() => setExpanded(e => !e)}
            className="px-2 h-8 text-muted-foreground"
          >
            {expanded ? <ChevronUp className="w-4 h-4" /> : <ChevronDown className="w-4 h-4" />}
          </Button>
          <Button variant="ghost" size="sm"
            onClick={() => onRemove(index)}
            className="text-red-500 hover:text-red-700 hover:bg-red-50 px-2 h-8"
          >
            <Trash2 className="w-4 h-4" />
          </Button>
        </div>
      </CardHeader>

      {expanded && (
        <CardContent className="p-4 space-y-4">
          {/* Module + Action */}
          <div className="grid grid-cols-2 gap-3">
            <div className="space-y-1.5">
              <Label>{t('workflows.editor.field.module')}</Label>
              <Select
                value={step.module}
                onValueChange={(val) => onUpdate(index, { module: val, action: '', action_config: {} })}
              >
                <SelectTrigger>
                  <SelectValue placeholder={t('workflows.editor.placeholder.module')} />
                </SelectTrigger>
                <SelectContent>
                  {modules.map(m => (
                    <SelectItem key={m} value={m}>{m.toUpperCase()}</SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            <div className="space-y-1.5">
              <Label>{t('workflows.editor.field.action')}</Label>
              <Select
                value={step.action}
                onValueChange={(val) => onUpdate(index, { action: val, action_config: {} })}
                disabled={!step.module}
              >
                <SelectTrigger>
                  <SelectValue placeholder={t('workflows.editor.placeholder.action')} />
                </SelectTrigger>
                <SelectContent>
                  {currentModuleActions.map(a => (
                    <SelectItem key={a.name} value={a.name}>{a.label}</SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
          </div>

          {/* Dynamic config from inputSchema */}
          {currentActionDef?.inputSchema?.properties && (
            <div className="bg-slate-50 dark:bg-slate-900/50 p-3 rounded-lg border space-y-3">
              <p className="text-xs font-medium text-muted-foreground uppercase tracking-wide">
                {t('workflows.editor.config_section')}
              </p>
              {Object.entries(currentActionDef.inputSchema.properties || {}).map(([key, schema]: [string, any]) => (
                <div key={key} className="space-y-1">
                  <Label className="text-xs">{schema.label || key}</Label>
                  {schema.type === 'boolean' ? (
                    <div className="flex items-center gap-2">
                      <Switch
                        checked={!!config[key]}
                        onCheckedChange={(checked) => onUpdate(index, {
                          action_config: { ...config, [key]: checked }
                        })}
                      />
                      <span className="text-xs text-muted-foreground">{schema.label}</span>
                    </div>
                  ) : (
                    <div className="flex gap-1">
                      <Input
                        placeholder={schema.placeholder || schema.default?.toString() || t('workflows.editor.placeholder.config_var')}
                        value={config[key] ?? (schema.default !== undefined ? schema.default : '')}
                        onChange={(e) => onUpdate(index, {
                          action_config: { ...config, [key]: e.target.value }
                        })}
                        className="text-sm font-mono"
                      />
                      <VariablePicker
                        currentIndex={index}
                        steps={allSteps}
                        availableActions={availableActions}
                        onSelect={(variable) => {
                          const currentVal = config[key] ?? '';
                          onUpdate(index, {
                            action_config: { ...config, [key]: currentVal + variable }
                          });
                        }}
                      />
                    </div>
                  )}
                  {schema.description && (
                    <p className="text-xs text-muted-foreground">{schema.description}</p>
                  )}
                </div>
              ))}
            </div>
          )}

          {/* Condition block */}
          <div className="border rounded-lg p-3 space-y-3 bg-amber-50/50 dark:bg-amber-900/10 border-amber-200 dark:border-amber-900">
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-2">
                <GitBranch className="w-4 h-4 text-amber-600" />
                <Label className="text-sm font-medium text-amber-800 dark:text-amber-300">
                  {t('workflows.editor.field.condition')}
                </Label>
              </div>
              <Switch checked={showCondition} onCheckedChange={toggleCondition} />
            </div>

            {showCondition && (
              <div className="space-y-2">
                <p className="text-xs text-muted-foreground">{t('workflows.editor.condition_hint')}</p>

                <div className="space-y-1.5">
                  <Label className="text-xs">{t('workflows.editor.field.cond_field')}</Label>
                  <div className="flex gap-1">
                    <Input
                      placeholder={t('workflows.editor.placeholder.cond_field')}
                      value={step.condition?.field || ''}
                      onChange={(e) => updateCondition({ field: e.target.value })}
                      className="font-mono text-sm"
                    />
                    <VariablePicker
                      currentIndex={index}
                      steps={allSteps}
                      availableActions={availableActions}
                      onSelect={(variable) => {
                        const currentVal = step.condition?.field || '';
                        // Remove braces for field path
                        const cleanVar = variable.replace('{{', '').replace('}}', '');
                        updateCondition({ field: currentVal + cleanVar });
                      }}
                    />
                  </div>
                </div>

                <div className="grid grid-cols-2 gap-2">
                  <div className="space-y-1.5">
                    <Label className="text-xs">{t('workflows.editor.field.cond_op')}</Label>
                    <Select
                      value={step.condition?.operator || 'exists'}
                      onValueChange={(val) => updateCondition({ operator: val })}
                    >
                      <SelectTrigger className="text-xs h-9">
                        <SelectValue />
                      </SelectTrigger>
                      <SelectContent>
                        {OPERATOR_KEYS.map(op => (
                          <SelectItem key={op} value={op} className="text-xs">
                            {t(`workflows.condition_operators.${op}`)}
                          </SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                  </div>

                  {needsValue && (
                    <div className="space-y-1.5">
                      <Label className="text-xs">{t('workflows.editor.field.cond_value')}</Label>
                      <Input
                        placeholder={t('workflows.editor.placeholder.cond_value')}
                        value={step.condition?.value || ''}
                        onChange={(e) => updateCondition({ value: e.target.value })}
                        className="text-sm"
                      />
                    </div>
                  )}
                </div>
              </div>
            )}
          </div>

          {/* Delay + on_fail */}
          <div className="grid grid-cols-2 gap-3">
            <div className="space-y-1.5">
              <Label className="text-xs">{t('workflows.editor.field.delay')}</Label>
              <Input
                type="number"
                min="0"
                value={step.delay_seconds || 0}
                onChange={(e) => onUpdate(index, { delay_seconds: parseInt(e.target.value) || 0 })}
              />
            </div>
            <div className="space-y-1.5">
              <Label className="text-xs">{t('workflows.editor.field.on_fail')}</Label>
              <Select
                value={step.on_fail || 'skip'}
                onValueChange={(val: any) => onUpdate(index, { on_fail: val })}
              >
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="stop">{t('workflows.editor.on_fail.stop')}</SelectItem>
                  <SelectItem value="skip">{t('workflows.editor.on_fail.skip')}</SelectItem>
                  <SelectItem value="retry">{t('workflows.editor.on_fail.retry')}</SelectItem>
                </SelectContent>
              </Select>
            </div>
          </div>
        </CardContent>
      )}
    </Card>
  );
};

