import React, { useEffect, useState } from 'react';
import { useQuery, useMutation } from '@tanstack/react-query';
import {
  DndContext,
  closestCenter,
  KeyboardSensor,
  PointerSensor,
  useSensor,
  useSensors,
  DragEndEvent
} from '@dnd-kit/core';
import {
  arrayMove,
  SortableContext,
  sortableKeyboardCoordinates,
  verticalListSortingStrategy
} from '@dnd-kit/sortable';
import { Plus, Save, Loader2, Play } from 'lucide-react';
import { Sheet, SheetContent, SheetHeader, SheetTitle, SheetDescription, SheetFooter } from '@/components/ui/sheet';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Textarea } from '@/components/ui/textarea';
import { ScrollArea } from '@/components/ui/scroll-area';
import { Badge } from '@/components/ui/badge';
import { toast } from 'sonner';
import { useTranslation } from '@/lib/i18n';

import {
  fetchWorkflowById,
  fetchRegistryActions,
  createWorkflow,
  updateWorkflow,
  Workflow,
  WorkflowStep
} from '../api/workflowAPI';
import { StepConfigItem } from './StepConfigItem';

interface WorkflowEditorSheetProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  workflowId: string | null;
  onSave: () => void;
}

export const WorkflowEditorSheet: React.FC<WorkflowEditorSheetProps> = ({
  open,
  onOpenChange,
  workflowId,
  onSave
}) => {
  const { t } = useTranslation();

  const [formData, setFormData] = useState<Partial<Workflow>>({
    name: '',
    description: '',
    trigger_type: 'webhook',
    trigger_config: {},
    status: 'draft',
    steps: []
  });

  const { data: registryActions = [] } = useQuery({
    queryKey: ['workflow-registry-actions'],
    queryFn: fetchRegistryActions,
    enabled: open,
  });

  const { data: existingWorkflow, isFetching } = useQuery({
    queryKey: ['workflow', workflowId],
    queryFn: () => fetchWorkflowById(workflowId!),
    enabled: !!workflowId && open,
  });

  useEffect(() => {
    if (workflowId && existingWorkflow && open) {
      const mappedSteps = (existingWorkflow.steps || []).map((s, i) => ({
        ...s,
        id: (s as any).id || `temp-${i}`,
      }));
      setFormData({ ...existingWorkflow, steps: mappedSteps });
    } else if (!workflowId && open) {
      setFormData({
        name: '',
        description: '',
        trigger_type: 'webhook',
        trigger_config: {},
        status: 'draft',
        steps: []
      });
    }
  }, [workflowId, existingWorkflow, open]);

  const saveMutation = useMutation({
    mutationFn: (data: Partial<Workflow>) => {
      const payloadToSave = {
        ...data,
        steps: data.steps?.map((s, i) => {
          const { id, ...rest } = s as any;
          return {
            ...rest,
            step_order: i + 1,
            condition: rest.condition?.field ? rest.condition : null,
          };
        })
      };
      if (workflowId) return updateWorkflow(workflowId, payloadToSave);
      return createWorkflow(payloadToSave);
    },
    onSuccess: () => {
      toast.success(workflowId ? t('workflows.toast.updated') : t('workflows.toast.created'));
      onSave();
    },
    onError: (err: any) => {
      toast.error(t('workflows.toast.save_error'), { description: err.message });
    }
  });

  const sensors = useSensors(
    useSensor(PointerSensor),
    useSensor(KeyboardSensor, { coordinateGetter: sortableKeyboardCoordinates })
  );

  const handleDragEnd = (event: DragEndEvent) => {
    const { active, over } = event;
    if (over && active.id !== over.id) {
      const oldIndex = formData.steps?.findIndex((s: any) => s.id === active.id) || 0;
      const newIndex = formData.steps?.findIndex((s: any) => s.id === over.id) || 0;
      setFormData({ ...formData, steps: arrayMove(formData.steps || [], oldIndex, newIndex) });
    }
  };

  const addStep = () => {
    setFormData(prev => ({
      ...prev,
      steps: [
        ...(prev.steps || []),
        {
          id: `new-${Date.now()}`,
          step_order: (prev.steps?.length || 0) + 1,
          module: '',
          action: '',
          action_config: {},
          condition: null,
          delay_seconds: 0,
          on_fail: 'skip'
        } as any
      ]
    }));
  };

  const updateStep = (index: number, updated: Partial<WorkflowStep>) => {
    const newSteps = [...(formData.steps || [])];
    newSteps[index] = { ...newSteps[index], ...updated };
    setFormData({ ...formData, steps: newSteps });
  };

  const removeStep = (index: number) => {
    const newSteps = [...(formData.steps || [])];
    newSteps.splice(index, 1);
    setFormData({ ...formData, steps: newSteps });
  };

  const handleTriggerTypeChange = (val: 'schedule' | 'event' | 'webhook') => {
    setFormData({
      ...formData,
      trigger_type: val,
      trigger_config: {} // сбрасываем конфигурацию при смене типа триггера
    });
  };

  const handleSaveClick = () => {
    if (!formData.name) {
      toast.error(t('workflows.errors.name_required'));
      return;
    }
    saveMutation.mutate(formData);
  };

  return (
    <Sheet open={open} onOpenChange={onOpenChange}>
      <SheetContent className="w-[95vw] sm:max-w-xl md:max-w-2xl flex flex-col h-full bg-slate-50 dark:bg-zinc-950 p-0">
        <SheetHeader className="p-6 pb-4 border-b bg-white dark:bg-zinc-900 shrink-0">
          <SheetTitle>{t(workflowId ? 'workflows.editor.title_edit' : 'workflows.editor.title_new')}</SheetTitle>
          <SheetDescription>{t('workflows.editor.subtitle')}</SheetDescription>
        </SheetHeader>

        {isFetching ? (
          <div className="flex-1 flex items-center justify-center">
            <Loader2 className="w-8 h-8 animate-spin text-primary" />
          </div>
        ) : (
          <ScrollArea className="flex-1 h-full px-6 py-4">
            <div className="space-y-6 pb-20">

              {/* General Settings */}
              <div className="space-y-4 p-5 bg-white dark:bg-zinc-900 rounded-xl shadow-sm border">
                <h3 className="font-semibold flex items-center gap-2">
                  <Play className="w-4 h-4" />
                  {t('workflows.editor.section_general')}
                </h3>

                <div className="space-y-2">
                  <Label>{t('workflows.editor.field.name')}</Label>
                  <Input
                    placeholder={t('workflows.editor.placeholder.name')}
                    value={formData.name || ''}
                    onChange={e => setFormData({ ...formData, name: e.target.value })}
                  />
                </div>

                <div className="space-y-2">
                  <Label>{t('workflows.editor.field.description')}</Label>
                  <Textarea
                    placeholder={t('workflows.editor.placeholder.description')}
                    value={formData.description || ''}
                    onChange={e => setFormData({ ...formData, description: e.target.value })}
                  />
                </div>

                <div className="grid grid-cols-2 gap-4">
                  <div className="space-y-2">
                    <Label>{t('workflows.editor.field.trigger_type')}</Label>
                    <Select
                      value={formData.trigger_type}
                      onValueChange={handleTriggerTypeChange}
                    >
                      <SelectTrigger><SelectValue /></SelectTrigger>
                      <SelectContent>
                        <SelectItem value="webhook">{t('workflows.editor.trigger_options.webhook')}</SelectItem>
                        <SelectItem value="schedule">{t('workflows.editor.trigger_options.schedule')}</SelectItem>
                        <SelectItem value="event">{t('workflows.editor.trigger_options.event')}</SelectItem>
                      </SelectContent>
                    </Select>
                  </div>
                  <div className="space-y-2">
                    <Label>{t('workflows.editor.field.status')}</Label>
                    <Select
                      value={formData.status}
                      onValueChange={(val: any) => setFormData({ ...formData, status: val })}
                    >
                      <SelectTrigger><SelectValue /></SelectTrigger>
                      <SelectContent>
                        <SelectItem value="draft">{t('workflows.editor.status_options.draft')}</SelectItem>
                        <SelectItem value="active">{t('workflows.editor.status_options.active')}</SelectItem>
                        <SelectItem value="paused">{t('workflows.editor.status_options.paused')}</SelectItem>
                      </SelectContent>
                    </Select>
                  </div>
                </div>

                {formData.trigger_type === 'schedule' && (
                  <div className="space-y-2">
                    <Label>{t('workflows.editor.field.cron')}</Label>
                    <Input
                      placeholder={t('workflows.editor.placeholder.cron')}
                      value={formData.trigger_config?.cron || ''}
                      onChange={e => setFormData({ ...formData, trigger_config: { ...formData.trigger_config, cron: e.target.value } })}
                    />
                    <p className="text-xs text-muted-foreground">{t('workflows.editor.placeholder.cron_hint')}</p>
                  </div>
                )}

                {formData.trigger_type === 'webhook' && workflowId && (
                  <div className="space-y-2">
                    <Label>{t('workflows.editor.field.webhook_url')}</Label>
                    <Input
                      readOnly
                      value={`${window.location.origin}/api/workflows/${workflowId}/webhook`}
                      className="font-mono text-xs text-slate-500 bg-slate-50"
                    />
                  </div>
                )}
              </div>

              {/* Steps Section */}
              <div className="space-y-4">
                <div className="flex justify-between items-center px-1">
                  <h3 className="font-semibold text-lg">{t('workflows.editor.section_steps')}</h3>
                  <Badge variant="secondary" className="font-mono">
                    {formData.steps?.length || 0} {t('workflows.editor.steps_count')}
                  </Badge>
                </div>

                {formData.steps?.length === 0 ? (
                  <div className="text-center p-8 bg-white border border-dashed rounded-xl dark:bg-zinc-900">
                    <p className="text-muted-foreground mb-4">{t('workflows.editor.no_steps_description')}</p>
                    <Button variant="outline" onClick={addStep}>
                      <Plus className="w-4 h-4 mr-2" />
                      {t('workflows.editor.add_step')}
                    </Button>
                  </div>
                ) : (
                  <DndContext sensors={sensors} collisionDetection={closestCenter} onDragEnd={handleDragEnd}>
                    <SortableContext
                      items={(formData.steps || []).map((s: any) => s.id)}
                      strategy={verticalListSortingStrategy}
                    >
                      {(formData.steps || []).map((step: any, index: number) => (
                        <StepConfigItem
                          key={step.id}
                          step={step}
                          index={index}
                          allSteps={formData.steps || []}
                          availableActions={registryActions}
                          onUpdate={updateStep}
                          onRemove={removeStep}
                        />
                      ))}
                    </SortableContext>
                  </DndContext>
                )}

                {formData.steps && formData.steps.length > 0 && (
                  <Button
                    variant="outline"
                    className="w-full border-dashed py-6 text-muted-foreground hover:text-primary hover:border-primary"
                    onClick={addStep}
                  >
                    <Plus className="w-5 h-5 mr-2" />
                    {t('workflows.editor.add_another_step')}
                  </Button>
                )}
              </div>
            </div>
          </ScrollArea>
        )}

        <SheetFooter className="p-4 border-t bg-white dark:bg-zinc-900 shrink-0">
          <div className="w-full flex justify-between items-center">
            <Button variant="ghost" onClick={() => onOpenChange(false)}>
              {t('workflows.actions.cancel')}
            </Button>
            <Button onClick={handleSaveClick} disabled={saveMutation.isPending || isFetching}>
              {saveMutation.isPending && <Loader2 className="w-4 h-4 mr-2 animate-spin" />}
              <Save className="w-4 h-4 mr-2" />
              {t('workflows.actions.save')}
            </Button>
          </div>
        </SheetFooter>
      </SheetContent>
    </Sheet>
  );
};

import React, { useState, useMemo } from 'react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { Network, Plus, Play, Pause, Pencil, Trash2, AlertCircle, FileCode2, Clock, CheckCircle2 } from 'lucide-react';
import { AppLayout } from '@/components/layout/AppLayout';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Skeleton } from '@/components/ui/skeleton';
import { useTranslation } from '@/lib/i18n';
import { toast } from 'sonner';
import { fetchWorkflows, deleteWorkflow, Workflow } from '../api/workflowAPI';
import { WorkflowEditorSheet } from '../components/WorkflowEditorSheet';
import { useDataTable } from '@/hooks/useDataTable';
import { DataTableToolbar, TableFooterPagination, SortableTableHead } from '@/components/shared';
import { Table, TableBody, TableCell, TableHeader, TableRow } from '@/components/ui/table';
import { Checkbox } from '@/components/ui/checkbox';

const STATUS_CONFIG = {
  active:  { labelKey: 'workflows.status.active',  variant: 'default'   as const, icon: Play,     className: 'bg-green-500 hover:bg-green-600 text-white' },
  paused:  { labelKey: 'workflows.status.paused',  variant: 'secondary' as const, icon: Pause,    className: '' },
  draft:   { labelKey: 'workflows.status.draft',   variant: 'outline'   as const, icon: FileCode2, className: '' },
};

const TRIGGER_TYPE_KEYS: Record<string, string> = {
  webhook:  'workflows.trigger_type.webhook',
  schedule: 'workflows.trigger_type.schedule',
  event:    'workflows.trigger_type.event',
};

export const WorkflowsPage: React.FC = () => {
  const { t } = useTranslation();
  const qc = useQueryClient();
  const [isEditorOpen, setIsEditorOpen]       = useState(false);
  const [selectedWorkflowId, setSelectedId]   = useState<string | null>(null);

  const { data: workflowsRaw = [], isLoading, error, refetch } = useQuery({
    queryKey: ['workflows'],
    queryFn: fetchWorkflows,
    retry: false,
  });

  const workflows = useMemo(() => workflowsRaw as (Workflow & { id: string })[], [workflowsRaw]);

  const deleteMutation = useMutation({
    mutationFn: deleteWorkflow,
    onSuccess: () => {
      toast.success(t('workflows.toast.deleted'));
      qc.invalidateQueries({ queryKey: ['workflows'] });
    },
    onError: (e: any) => toast.error(t('workflows.toast.delete_error'), { description: e.message }),
  });

  const handleCreate = () => {
    setSelectedId(null);
    setIsEditorOpen(true);
  };

  const handleEdit = (id: string) => {
    setSelectedId(id);
    setIsEditorOpen(true);
  };

  const StatusBadge = ({ status }: { status: string }) => {
    const cfg = STATUS_CONFIG[status as keyof typeof STATUS_CONFIG] || STATUS_CONFIG.draft;
    const Icon = cfg.icon;
    return (
      <Badge variant={cfg.variant} className={`gap-1 text-xs ${cfg.className}`}>
        <Icon className="w-3 h-3" />
        {t(cfg.labelKey)}
      </Badge>
    );
  };

  const {
    searchQuery, setSearchQuery, selectedIds, toggleSelection, toggleAllSelection, clearSelection,
    visibleColumns, columnOrder, sortConfig, handleSort, toggleColumnVisibility, moveColumn, reorderColumn,
    columnWidths, setColumnWidth, rowsPerPage, setRowsPerPage, currentPage, setCurrentPage
  } = useDataTable<Workflow & { id: string }>({
    initialData: [],
    initialColumns: { name: true, trigger: true, status: true, steps: true },
    storageKey: 'workflows-table',
  });

  const columnLabels: Record<string, string> = {
    name: t('workflows.table.name'),
    trigger: t('workflows.table.trigger'),
    status: t('workflows.table.status'),
    steps: t('workflows.table.steps'),
  };

  const filteredWorkflows = useMemo(() => {
    return workflows.filter(wf => 
      wf.name.toLowerCase().includes(searchQuery.toLowerCase()) || 
      (wf.description && wf.description.toLowerCase().includes(searchQuery.toLowerCase()))
    );
  }, [workflows, searchQuery]);

  const paginatedWorkflows = useMemo(() => {
    const start = (currentPage - 1) * Number(rowsPerPage);
    return filteredWorkflows.slice(start, start + Number(rowsPerPage));
  }, [filteredWorkflows, currentPage, rowsPerPage]);

  const handleBulkDelete = async () => {
    if (confirm(t('workflows.actions.confirm_delete_bulk'))) {
      for (const id of selectedIds) {
        await deleteMutation.mutateAsync(id as string);
      }
      clearSelection();
    }
  };

  return (
    <AppLayout
      title={t('workflows.title')}
      subtitle={t('workflows.subtitle')}
      breadcrumbs={[{ label: t('workflows.title') }]}
      actions={
        <Button onClick={handleCreate} className="gap-2">
          <Plus className="w-4 h-4" />
          {t('workflows.new_workflow')}
        </Button>
      }
    >
      {error ? (
        <div className="bg-red-50 text-red-600 p-4 rounded-lg flex items-center gap-3 border border-red-200">
          <AlertCircle className="w-5 h-5 shrink-0" />
          <div>
            <p className="font-medium">{t('workflows.errors.load_failed')}</p>
            <p className="text-sm opacity-75">{(error as any)?.message}</p>
          </div>
          <Button variant="outline" size="sm" className="ml-auto border-red-300" onClick={() => refetch()}>
            {t('workflows.actions.retry')}
          </Button>
        </div>
      ) : (
        <div className="titan-card flex flex-col flex-1 overflow-hidden">
          <div className="px-4 py-2 border-b">
            <DataTableToolbar
                searchQuery={searchQuery}
                onSearchChange={setSearchQuery}
                searchPlaceholder={t('workflows.search_placeholder')}
                selectedCount={selectedIds.size}
                onCancelSelection={clearSelection}
                onBulkDelete={handleBulkDelete}
                visibleColumns={visibleColumns}
                onToggleColumn={toggleColumnVisibility}
                columnLabels={columnLabels}
                columnOrder={columnOrder}
                onMoveColumn={moveColumn}
            />
          </div>

          <div className="flex-1 overflow-auto">
            <Table>
              <TableHeader className="sticky top-0 bg-background z-10 shadow-sm">
                <TableRow>
                  <SortableTableHead 
                    label={
                      <div className="w-10 flex items-center justify-center">
                        <Checkbox 
                          checked={selectedIds.size === paginatedWorkflows.length && paginatedWorkflows.length > 0} 
                          onCheckedChange={() => toggleAllSelection(paginatedWorkflows)} 
                        />
                      </div>
                    } 
                    onSort={() => {}} 
                    className="w-12 px-0"
                  />
                  {columnOrder.filter(key => visibleColumns[key]).map(key => (
                    <SortableTableHead
                      key={key}
                      label={columnLabels[key]}
                      onSort={() => handleSort(key as keyof Workflow)}
                      direction={sortConfig?.key === key ? sortConfig.direction : null}
                      width={columnWidths?.[key]}
                      onResize={(w) => setColumnWidth(key, w)}
                      columnKey={key}
                      className={key === 'name' ? 'min-w-[200px]' : ''}
                    />
                  ))}
                  <SortableTableHead label={t('common.actions')} onSort={() => {}} className="text-right w-[100px]" />
                </TableRow>
              </TableHeader>
              <TableBody>
                {isLoading ? (
                  Array.from({ length: 3 }).map((_, i) => (
                    <TableRow key={i}>
                      <TableCell><Skeleton className="h-4 w-4" /></TableCell>
                      <TableCell colSpan={columnOrder.filter(k => visibleColumns[k]).length + 1}>
                        <Skeleton className="h-6 w-full" />
                      </TableCell>
                    </TableRow>
                  ))
                ) : paginatedWorkflows.length === 0 ? (
                  <TableRow>
                    <TableCell colSpan={columnOrder.filter(k => visibleColumns[k]).length + 2} className="h-32 text-center">
                      <Network className="w-12 h-12 mx-auto mb-4 opacity-20" />
                      <h3 className="text-lg font-medium mb-1">{t('workflows.list.empty_title')}</h3>
                      <p className="text-sm text-muted-foreground">{t('workflows.list.empty_description')}</p>
                    </TableCell>
                  </TableRow>
                ) : paginatedWorkflows.map((wf) => (
                  <TableRow key={wf.id} className="group cursor-pointer" onClick={() => handleEdit(wf.id)}>
                    <TableCell onClick={e => e.stopPropagation()} className="w-12 text-center text-muted-foreground">
                      <Checkbox checked={selectedIds.has(wf.id)} onCheckedChange={() => toggleSelection(wf.id)} />
                    </TableCell>
                    {columnOrder.filter(key => visibleColumns[key]).map(key => {
                      switch (key) {
                        case 'name': return (
                          <TableCell key="name">
                            <p className="font-medium truncate">{wf.name}</p>
                            {wf.description && <p className="text-xs text-muted-foreground truncate">{wf.description}</p>}
                          </TableCell>
                        );
                        case 'trigger': return (
                          <TableCell key="trigger">
                            <div className="flex items-center gap-1.5 text-sm text-muted-foreground">
                              <Clock className="w-3.5 h-3.5 shrink-0" />
                              <span className="truncate">{t(TRIGGER_TYPE_KEYS[wf.trigger_type] || 'workflows.trigger_type.event')}</span>
                            </div>
                          </TableCell>
                        );
                        case 'status': return (
                          <TableCell key="status"><StatusBadge status={wf.status} /></TableCell>
                        );
                        case 'steps': return (
                          <TableCell key="steps" className="font-mono text-sm">{wf.steps?.length ?? '—'}</TableCell>
                        );
                        default: return null;
                      }
                    })}
                    <TableCell className="text-right" onClick={e => e.stopPropagation()}>
                      <div className="flex justify-end gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                        <Button variant="ghost" size="sm" className="h-8 px-2 text-red-500 hover:bg-red-50" onClick={() => {
                          if (confirm(t('workflows.actions.confirm_delete'))) deleteMutation.mutate(wf.id);
                        }}>
                          <Trash2 className="w-4 h-4" />
                        </Button>
                      </div>
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          </div>

          <TableFooterPagination
            shownCount={paginatedWorkflows.length}
            totalCount={filteredWorkflows.length}
            rowsPerPage={rowsPerPage}
            onRowsPerPageChange={setRowsPerPage}
            currentPage={currentPage}
            onPageChange={setCurrentPage}
            className="border-t border-border p-4"
          />
        </div>
      )}

      <WorkflowEditorSheet
        open={isEditorOpen}
        onOpenChange={setIsEditorOpen}
        workflowId={selectedWorkflowId}
        onSave={() => {
          setIsEditorOpen(false);
          refetch();
        }}
      />
    </AppLayout>
  );
};
